// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 굳건
// ==========================================
// 방패병 · 생존가 · 결계술사 · 외공 수련생 · 광부
// 굳건 — 피가 쇠를 녹이고 발소리가 물을 흔드는 곳에서, 제일 나중에 물러나는 사람들

// ── 방패병 (shield) · 무력
kJob('shield', 'S', [

{ at:'S', t:'복도 — 앞면을 타는 피',
  x:`죽인 것의 피가 방패 앞면에 튀었다. 피가 끓는다. 쇠가 하얀 김을 올리며 운다.<br><br>
    닦으면 손이 녹는다. 두면 방패가 녹는다. 앞면 가운데가 벌써 움푹하다.<br>
    복도 저쪽에서 발톱 소리가 또 온다. 하나가 아니다.<br><br>
    방패를 버릴 수는 없다. 방패 뒤에 넷이 있다.`,
  o:[
    { l:'① 방패를 기울여 피를 가장자리로 흘려보낸다.', k:'steady', dc:24, wake:1,
      ok:`방패를 비스듬히 기울였다. 끓는 피가 앞면을 타고 미끄러진다. 가장자리에서 바닥으로 떨어졌다. 바닥이 대신 운다.<br><br>기울인 채로 받는 법을 팔이 외웠다. 세운 방패는 피를 머금는다. 기울인 방패는 흘려보낸다. 각도 하나 차이다.<br><br>발톱 소리가 왔을 때 방패는 이미 비스듬했다. 부딪친 것의 피도 제 발 밑으로 떨어졌다. 그것이 제 피에 발을 데고 물러났다.`,
      ng:`기울이는 게 늦었다. 피가 앞면 가운데 고였다. 쇠가 뚫렸다. 구멍으로 피가 넘어와 팔뚝에 떨어졌다.<br><br>살이 끓는 소리를 처음 들었다. 제 살인데 남의 소리 같았다.<br><br>천으로 동여매고 방패를 다시 들었다. 구멍 난 방패는 가볍다. 그게 제일 싫었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 무력을 실어 방패를 바닥에 내리찍어 피를 털어 낸다.', k:'break', dc:25, cost:{ might:30 },
      ok:`방패를 머리 위로 들었다가 모서리로 바닥을 내리찍었다. 쇠가 울고 피가 덩어리째 튕겨 나갔다.<br><br>바닥 돌이 피 떨어진 자리마다 운다. 방패 앞면에는 얕은 자국만 남았다.<br><br>소리를 들은 발톱들이 멈칫했다. 쇠를 저렇게 치는 것과는 붙지 않겠다는 걸음으로, 벽 쪽으로 돌아 나갔다.`,
      ng:`내리찍는 순간 피가 사방으로 튀었다. 뒤에 선 동료 소매에 한 방울 앉았다.<br><br>소매가 타들어 간다. 동료가 비명을 물었다. 칼로 소매를 통째 잘라 냈다.<br><br>복도 끝에서 발톱 소리가 빨라졌다. 비명을 들은 것이다. 뛰면서 방패를 고쳐 들었다. 팔이 떨렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-18 } }
  ] },

{ at:'S', t:'어둠 — 바닥으로 오는 무게',
  x:`불이 닿지 않는 어둠이다. 발바닥으로 떨림이 온다. 쿵. 쿵. 네 발이 아니다. 두 발로 긴 것이 뛴다.<br><br>
    이쪽으로 곧장 온다. 눈은 소용없다. 발바닥과 방패 든 팔만 남았다.<br>
    맨 앞은 방패다. 늘 그랬다. 여기서도 그렇다.<br><br>
    떨림의 간격이 좁아진다. 셋. 둘.`,
  o:[
    { l:'① 자세를 낮추고 방패째 받아 낸다.', k:'steady', dc:25,
      doom:{ title:'어둠의 돌진', what:'방패째 물려 어둠 속으로 끌려갑니다', dc:19, sec:45,
        text:`받았다. 받은 줄 알았다. 충격이 팔을 지나 어깨를 꺾었다.<br><br>이빨이 방패 가장자리를 물었다. 쇠가 종잇장처럼 접힌다. 끈이 팔뚝을 문 채 같이 간다. 발이 바닥에서 떨어졌다.<br>끌려가면서 불빛이 점이 됐다. 그것의 숨이 목덜미에 닿는다. 뜨겁고 비리다. 달리는 박자가 흐트러지지 않는다. 제 집으로 가는 길을 아는 박자다.`,
        dieText:`아침에 복도 끝에서 방패가 나왔다. 반으로 접혀 있다.<br><br>접힌 틈에 끈이 끼어 있다. 팔뚝에 두 번 감는 그 끈이다. 매듭은 풀리지 않은 채다.<br>접힌 방패를 펴 보려던 동료가 손을 멈췄다. 안쪽에서 물이 흘러나왔다. 붉지 않았다. 그게 더 나빴다.` },
      ok:`무릎을 꺾고 방패 위 가장자리를 어깨에 붙였다. 뒷발을 벽 모서리에 걸었다.<br><br>충격이 왔다. 벽이 등을 받았다. 방패가 운다. 팔뼈까지 울린다. 그래도 섰다.<br>부딪친 것이 튕겨 나가 바닥을 굴렀다. 일어나는 소리, 머뭇대는 소리, 돌아가는 소리.<br><br>어둠 속에서 들이받은 쪽이 물러난 것이다. 받아 낸 쪽은 제자리다. 팔이 한동안 펴지지 않았다.`,
      win:{ exp:21, dream:3 } },
    { l:'② 마지막 반 박자에 옆으로 비켜선다.', k:'evade', dc:24,
      ok:`둘. 하나. 반. 거기서 몸을 접어 벽에 붙였다.<br><br>바람이 지나갔다. 비린 바람이다. 그것이 빈자리를 지나 뒤쪽 어둠에 부딪혔다. 벽이 울었다.<br><br>그것이 다시 달려오기 전에 일행은 옆 통로로 꺾었다. 등 뒤에서 벽을 긁는 소리가 오래 났다. 빈자리를 이해하지 못하는 소리였다.`,
      ng:`반 박자가 늦었다. 어깨를 스쳤다. 스친 것만으로 몸이 돌아 바닥에 꽂혔다.<br><br>그것이 멈추는 소리가 났다. 돌아서는 소리. 코로 바닥을 훑는 소리가 가까워진다.<br><br>방패를 몸 위에 덮고 숨을 죽였다. 쇠 위로 콧김이 두 번 지나갔다. 비렸다. 그것이 흥미를 잃고 간 뒤에도 한참 못 일어났다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'S', t:'좁은 통로 — 뒷걸음의 법',
  x:`물러나야 한다. 통로가 좁아 돌아설 수 없다. 돌아서면 등을 준다. 여기서 등을 주면 끝이다.<br><br>
    방패를 앞에 둔 채 뒷걸음으로 간다. 발뒤꿈치가 길을 읽어야 한다.<br>
    앞의 어둠에서 그것이 보조를 맞춘다. 이쪽이 한 걸음 물러나면 저쪽이 한 걸음 온다. 간격이 줄지도 늘지도 않는다.<br><br>
    재고 있는 것이다. 뒷걸음이 흐트러지는 순간을.`,
  o:[
    { l:'① 발뒤꿈치로 바닥을 읽으며 같은 박자로 물러난다.', k:'steady', dc:24, wake:1,
      ok:`뒤꿈치를 끌며 걸었다. 바닥의 턱, 파인 데, 미끄러운 데가 발바닥으로 올라온다.<br><br>박자를 한 번도 흘리지 않았다. 물러나는 걸음이 나아가는 걸음과 같아졌다. 방향만 다르다.<br>그것이 세 번 속도를 바꿨다. 세 번 다 맞춰 줬다. 네 번째에 그것이 멈췄다. 재는 걸 포기한 것이다.<br><br>통로 끝까지 마흔 걸음. 눈 없이 걸은 마흔 걸음이 몸에 남았다. 이제 뒤꿈치가 눈이다.`,
      ng:`서른 걸음째에 뒤꿈치가 파인 데를 짚었다. 반 박자 어긋났다.<br><br>그 반 박자에 그것이 들어왔다. 방패가 튕겨 오르고 등이 벽에 찍혔다. 발톱이 방패 위 가장자리를 긁고 지나갔다. 이마에 바람이 닿았다.<br><br>동료들이 뒤에서 허리끈을 잡아 끌어냈다. 통로를 빠져나와 보니 투구 앞이 세 줄로 깊게 긁혀 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 뒤의 동료에게 길을 부르게 한다.', k:'bond', dc:23,
      ok:`뒤의 동료가 낮게 길을 불렀다. 오른발 턱. 왼쪽 패임. 세 걸음 곧장.<br><br>부르는 대로 디뎠다. 눈은 앞의 어둠에, 발은 동료의 목소리에 맡겼다. 몸이 둘로 나뉘어도 걸음은 하나였다.<br><br>통로를 다 나와서 동료와 등을 맞댔다. 어느 쪽도 혼자서는 못 나왔을 길이다.`,
      ng:`동료 목소리가 떨렸다. 턱이라는 말과 패임이라는 말이 섞였다. 발이 멈칫했다.<br><br>멈칫한 자리로 그것이 왔다. 방패로 받았지만 무릎이 꺾여 모서리에 찍혔다.<br><br>동료가 미안하다는 말을 되풀이했다. 미안할 일이 아니라고 했다. 어둠에 대고 길을 부르는 일은 원래 사람이 할 일이 아니다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-29, spirit:-17 } }
  ] },

{ at:'S', t:'천장 — 위를 걷는 발',
  x:`천장에서 소리가 난다. 발톱이 쇠를 쥐는 소리. 네 번, 쉬고, 네 번.<br><br>
    위를 걷는 것이다. 거꾸로 매달려서. 이쪽 걸음을 따라온다.<br>
    방패는 앞을 막는 물건이다. 위는 막아 본 적이 없다.<br><br>
    소리가 바로 머리 위에서 멈췄다.`,
  o:[
    { l:'① 방패를 머리 위로 올려 지붕을 만들고 걷는다.', k:'steady', dc:24,
      ok:`방패를 수평으로 올렸다. 팔이 금방 무거워진다. 무게를 어깨뼈에 얹는 법을 찾았다.<br><br>위에서 침이 떨어졌다. 방패가 받았다. 쇠가 작게 운다. 산이다. 기울여 흘려보냈다.<br>그것이 세 번 떨어뜨리고 세 번 다 못 맞혔다. 네 번째에 천장을 긁으며 앞질러 갔다. 먼저 가서 기다릴 셈이다.<br><br>길을 꺾었다. 지붕은 이고 다니면 된다. 길은 바꾸면 된다.`,
      ng:`수평으로 든 팔이 떨렸다. 방패가 한 뼘 기울었다.<br><br>그 틈으로 침이 떨어져 어깨에 앉았다. 가죽이 타고 살이 끓는다. 이를 악물고 소리를 삼켰다.<br><br>동료가 물을 부었다. 어깨에 동전만 한 구멍이 남았다. 위에서 소리가 났다. 딱. 딱. 혀 차는 소리 같았다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 그 자리에 멈춰 방패 밑에 웅크린다.', k:'hide', dc:24,
      ok:`걸음을 끊고 방패를 비스듬히 세워 그 밑에 들어갔다. 숨을 길게, 얕게.<br><br>위의 것은 움직임을 따라온다. 움직임이 사라지면 길을 잃는다. 발톱 소리가 머리 위를 두 바퀴 돌았다.<br><br>세 바퀴째에 소리가 멀어졌다. 쇠 식는 소리만 남았다. 방패 밑은 좁고 어두웠다. 그 밑에서 처음으로 숨이 편했다.`,
      ng:`웅크리는 순간 방패 가장자리가 바닥을 긁었다. 쇳소리 한 번.<br><br>위의 것이 떨어져 내렸다. 방패 위로. 무게가 등을 눌렀다. 발톱이 가장자리를 쥐고 들추려 든다.<br><br>동료들이 창대로 쑤셔 쫓아냈다. 방패를 쥔 손가락이 한동안 펴지지 않았다. 들추려던 힘을 손가락이 기억했다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-27, spirit:-19 } }
  ] },

{ at:'S', t:'쉬는 자리 — 문이 된 방패',
  x:`벽이 움푹한 자리를 찾아 일행을 넣고 방패로 입구를 막았다. 방패가 문이다. 이쪽은 문 안쪽에 등을 대고 앉는다.<br><br>
    밤중에 문이 밀렸다. 한 번. 한참 뒤에 또 한 번.<br>
    두드리는 게 아니다. 지그시 민다. 문이 어느 만큼 버티는지 재는 힘이다.<br><br>
    미는 간격이 조금씩 짧아진다.`,
  o:[
    { l:'① 밀 때마다 같은 힘으로 되밀며 간격을 센다.', k:'steady', dc:24, wake:1,
      ok:`밀면 되밀었다. 더도 덜도 아니고 똑같이. 문은 열리지 않지만 부서지지도 않는 벽이라고 가르쳤다.<br><br>간격을 셌다. 백 숨에서 아흔 숨, 여든 숨. 줄어드는 폭이 일정하다. 폭이 그대로면 새벽까지 열두 번. 열두 번은 버틴다.<br>아홉 번째부터 간격이 도로 늘었다. 열 번째는 오지 않았다.<br><br>미는 힘을 세는 법이 생겼다. 힘에도 숨이 있다. 숨을 세면 끝이 보인다. 끝이 보이면 버티는 건 일이 아니다.`,
      ng:`일곱 번째에 되미는 손이 늦었다. 문이 한 뼘 열렸다.<br><br>틈으로 긴 것이 들어왔다. 팔이라기엔 가늘고 혀라기엔 단단했다. 안쪽을 더듬는다. 제일 가까운 동료의 발목을 쥐었다.<br><br>방패 모서리로 내리찍었다. 긴 것이 빠져나가며 문틈에 젖은 자국을 남겼다. 남은 밤 내내 문에 온몸을 대고 있었다. 눈을 감지 못했다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 무력을 모아 한 번에 문을 밀쳐 그것을 넘어뜨린다.', k:'break', dc:25, cost:{ might:32 },
      ok:`미는 힘이 실리는 순간을 기다렸다. 실렸을 때 어깨째 문을 밀쳤다.<br><br>문밖에서 무엇이 넘어가는 소리가 났다. 무겁고 길다. 일어나는 데 오래 걸리는 몸이다.<br>일어나기 전에 방패를 도로 세우고 틈을 벽돌로 괴었다.<br><br>그 뒤로 미는 힘이 오지 않았다. 문이 되민다는 걸 배운 것이다. 배운 것은 다시 안 온다. 여기 것들은 머리가 있다.`,
      ng:`밀쳤는데 밖이 비어 있었다. 헛힘에 몸이 문밖으로 반이나 쏟아졌다.<br><br>어둠 속에서 그것이 기다리고 있었다. 미는 척한 것이다. 발톱이 어깨를 긁고 지나갔다.<br><br>동료들이 허리를 잡아 끌어들였다. 문을 닫고 보니 어깨 가죽이 세 줄로 갈라져 있었다. 머리가 있다. 이쪽보다 참을성도 있다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-34, spirit:-16 } },
    { l:'③ 문틈으로 밖을 내다본다.', k:'luck', dc:25,
      doom:{ title:'문틈의 눈', what:'문틈으로 들어온 손에 끌려갑니다', dc:19, sec:40,
        text:`방패를 손가락 한 마디만 젖히고 내다봤다. 어둠뿐이다.<br><br>어둠이 눈을 떴다. 틈 바로 앞에 있었다. 틈으로 긴 손가락이 들어와 투구 테를 쥐었다.<br>문이 활짝 열리며 몸이 밖으로 뽑혀 나갔다. 바닥에 끌린다. 쥔 손은 바꿔 쥐지도 않는다. 뒤에서 동료들이 문을 넘는 소리가 들렸다. 멀어진다.`,
        dieText:`새벽에 방패가 제자리에 세워져 있었다. 바깥쪽에서 괴어 놓은 채였다.<br><br>문을 닫아 준 것이다. 안에 남은 사람들이 나오지 못하게.<br>방패 앞면 안쪽, 눈높이 자리에 손가락 자국이 하나 찍혀 있었다. 내다보던 눈이 있던 자리다.` },
      ok:`내다보기 전에 방패에 귀를 먼저 댔다. 쇠 너머 숨소리가 틈 바로 앞에 있다.<br><br>내다보지 않았다. 대신 벽돌 부스러기를 틈으로 던졌다. 밖에서 그것이 부스러기를 쫓아 움직이는 소리가 났다.<br><br>그 사이 귀로 거리를 쟀다. 다섯 걸음. 문 앞 다섯 걸음에서 밤을 새우는 것이다. 아는 것만으로 밤이 조금 짧아졌다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'S', t:'빈터 — 재는 것들',
  x:`무리다. 셋이 번갈아 온다. 하나가 방패를 치고 빠지면 다음이 온다.<br><br>
    칠 때마다 아프게 치지 않는다. 깊이 들어오지도 않는다. 치고, 보고, 빠진다.<br>
    재는 것이다. 방패가 어느 높이에서 늦는지. 어느 쪽 발이 먼저 꺾이는지.<br><br>
    다음번은 잰 대로 올 것이다.`,
  o:[
    { l:'① 받을 때마다 자세를 바꿔 셈을 흐트러뜨린다.', k:'steady', dc:25, wake:1,
      ok:`첫째는 높게 받았다. 둘째는 낮게. 셋째는 반 걸음 나가며 받았다.<br><br>같은 방패가 매번 다른 벽이 됐다. 셋이 세 번씩 재고도 셈이 서지 않는다. 넷째 바퀴에 셋이 멈춰 서서 서로를 봤다.<br>셈이 안 서는 먹이는 비싼 먹이다. 셋은 비싼 값을 안 치르기로 했다. 풀숲이 닫혔다.<br><br>버티는 자세가 하나일 필요가 없다는 걸 몸이 배웠다. 벽은 한 가지 모양이라서 벽이 아니다. 안 넘어가서 벽이다.`,
      ng:`셋째 바퀴에 버릇이 나왔다. 오른쪽을 받을 때 왼발이 반 뼘 물러나는 버릇.<br><br>넷째 바퀴 첫째가 그 반 뼘으로 들어왔다. 방패 아래로 발톱이 걸려 정강이를 그었다.<br><br>동료들이 창을 세워 바퀴를 끊었다. 셋은 잰 것을 가지고 물러났다. 다음에 만나면 그 반 뼘부터 올 것이다. 왼발에 그 생각이 박혔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 치고 빠지는 셋 중 보는 놈을 찾는다.', k:'gaze', dc:24,
      ok:`치는 둘은 번갈아 바뀐다. 안 바뀌는 하나가 있다. 빈터 가장자리에서 목을 세우고 보기만 하는 놈.<br><br>그놈이 셈하는 놈이다. 방패를 돌려 그놈을 정면으로 세웠다. 치던 둘이 박자를 잃었다. 셈하는 놈이 가려지자 셈이 멎은 것이다.<br><br>보는 놈이 먼저 돌아섰다. 둘이 따라갔다. 셋을 상대한 게 아니었다. 하나를 상대한 것이다.`,
      ng:`보는 놈을 찾느라 방패가 반 박자 늦었다. 그 박자에 둘이 한꺼번에 왔다.<br><br>처음 있는 일이다. 번갈아 오던 것들이. 방패가 한쪽을 받는 사이 다른 쪽이 허리를 스쳤다.<br><br>물러나면서 알았다. 보는 놈이 박자를 바꾼 것이다. 이쪽이 저를 찾는 걸 보고. 눈이 마주친 값이었다.`,
      win:{ exp:19, dream:3 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'구덩이 — 끊어진 끈',
  x:`발톱이 방패 끈을 끊었다. 팔뚝에 감는 두 겹 가죽끈이 한 번에 갈렸다.<br><br>
    끈 없는 방패는 손잡이 하나로 버틴다. 받는 힘이 다 손목으로 온다.<br>
    버리고 갈 수 있는 물건이 아니다. 방패 뒤에 넷이 있다.<br><br>
    구덩이 저쪽에서 흙 긁는 소리가 다시 시작됐다.`,
  o:[
    { l:'① 허리띠를 풀어 그 자리에서 끈을 다시 맨다.', k:'fix', dc:23,
      ok:`허리띠를 이로 물어 끊고 방패 고리에 꿰었다. 팔뚝에 두 번. 매듭은 눈 감고도 짓는 매듭이다.<br><br>가죽이 설어서 조이는 맛이 다르다. 그래도 끈은 끈이다. 받는 힘이 도로 팔뚝 전체로 퍼졌다.<br><br>흙 긁는 소리가 끝나기 전에 맸다. 바지가 흘러내리는 건 다음 문제다.`,
      ng:`띠를 꿰는 손이 급했다. 매듭이 설었다.<br><br>첫 충격에 매듭이 풀리며 방패가 돌았다. 모서리가 제 턱을 쳤다. 입안에서 피 맛이 났다.<br><br>두 번째 매듭은 제대로 지었다. 손이 떨릴수록 매듭은 천천히 짓는 것이다. 알면서도 급했다. 그 값이 턱에 멍으로 남았다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 끈 없이 손잡이만으로 받는 법을 찾는다.', k:'steady', dc:24, wake:1,
      ok:`손잡이를 쥐고 방패를 몸에 붙였다. 끈이 하던 일을 어깨와 가슴이 나눠 맡았다.<br><br>받을 때 손목으로 버티지 않고 몸통으로 밀었다. 방패가 팔의 연장이 아니라 몸의 앞면이 됐다.<br>흙을 긁던 것이 두 번 부딪고 두 번 튕겨 나갔다. 끈이 있을 때와 같은 벽인 줄 알 것이다.<br><br>끈은 나중에 다시 맸다. 그래도 그날 배운 쥠새는 남았다. 끈이 또 끊겨도 벽은 선다.`,
      ng:`첫 충격은 받았다. 두 번째에 손목이 꺾이며 방패가 뒤집혔다.<br><br>뒤집힌 방패 너머로 그것의 얼굴이 들어왔다. 턱이 생각보다 길었다. 동료의 창이 그 턱을 옆에서 찔러 밀어냈다.<br><br>손목이 부어올랐다. 방패를 왼팔로 옮겨 들었다. 왼팔은 서툴다. 서툰 벽이라도 벽은 세워야 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, spirit:-15 } }
  ] },

{ at:'S', t:'바위 틈 — 감긴 꼬리',
  x:`꼬리가 동료의 허리를 감았다. 뱀처럼 길고 채찍처럼 빠른 꼬리다. 몸통은 바위 틈 안에 있다.<br><br>
    감은 채 당긴다. 동료의 발이 바닥에 고랑을 판다. 틈은 사람 하나 들어갈 넓이다.<br>
    칼이 안 드는 가죽이다. 벌써 두 번 미끄러졌다.<br><br>
    틈 안에서 삼키는 소리가 미리 난다.`,
  o:[
    { l:'① 무력을 실어 방패 모서리를 꼬리 아래에 박아 지렛대로 튼다.', k:'break', dc:25, cost:{ might:34 },
      ok:`방패 모서리를 꼬리와 동료 허리 사이에 박았다. 손잡이를 두 손으로 쥐고 몸무게째 틀었다.<br><br>감긴 것은 베는 게 아니라 벌리는 것이다. 쇠가 가죽 비늘 밑으로 파고들자 꼬리가 움찔 풀렸다.<br>동료를 뒤로 던지듯 밀고 방패를 뽑았다. 꼬리가 빈 바닥을 한 번 치고 틈으로 사라졌다.<br><br>동료 허리에 비늘 자국이 띠처럼 남았다. 숨은 쉰다. 그거면 됐다.`,
      ng:`모서리가 비늘에 미끄러졌다. 꼬리가 방패째 한 바퀴 더 감았다.<br><br>이제 방패도 저당 잡혔다. 동료와 방패와 이쪽 팔이 한 묶음으로 틈 쪽에 끌렸다.<br><br>동료들이 셋이 매달려서야 묶음이 풀렸다. 방패 앞면에 감긴 자국이 나선으로 남았다. 허리를 감겼던 동료는 그날 밤 꿈에서 틈 안을 봤다고 했다. 묻지 않았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-33, mind:-15 } },
    { l:'② 동료를 끌어안고 같이 버틴다.', k:'steady', dc:25,
      doom:{ title:'틈으로 가는 줄', what:'동료를 안은 채 바위 틈으로 끌려갑니다', dc:19, sec:45,
        text:`동료를 안고 발을 박았다. 둘 무게면 못 끌 줄 알았다.<br><br>끌렸다. 바닥 고랑이 두 줄이 됐다. 꼬리는 둘 무게를 처음부터 알고 있었다는 힘이다.<br>틈이 가까워진다. 틈 가장자리에 긁힌 자국이 많다. 다 손톱 자국이다. 다 바깥쪽을 향해 있다.<br>동료가 품 안에서 말했다. 놓으라고. 대답하지 않았다. 대답할 숨도 버티는 데 썼다.`,
        dieText:`바위 틈 앞에 방패가 남아 있었다. 세로로 세워진 채. 틈을 반쯤 가리고 있다.<br><br>마지막에 방패를 틈에 끼운 것이다. 문처럼. 들어가는 길을 제 몸으로 다 막지 못해서.<br>틈 안쪽은 조용했다. 방패를 치울 수 있는 사람이 없었다.` },
      ok:`동료를 안고 무게를 뒤로 실었다. 끌려가는 속도가 반으로 줄었다.<br><br>반이면 된다. 동료들이 달려올 시간이다. 창 둘이 틈 안쪽을 찔렀다. 안에서 바람 빠지는 소리가 나며 꼬리가 풀렸다.<br><br>둘이 한 덩어리로 뒤로 굴렀다. 버티는 건 이기는 게 아니다. 시간을 사는 것이다. 산 시간은 동료들이 썼다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'S', t:'모닥불 가 — 자국이 말하는 것',
  x:`불가에서 방패를 눕혀 놓고 봤다. 하루치 자국이 앞면에 쌓였다.<br><br>
    위쪽에 긴 세 줄. 가운데에 둥글게 움푹한 데. 아래 가장자리에 잘게 씹힌 자국.<br>
    자국마다 임자가 다르다. 셋이 다른 높이에서, 다른 때에 쳤다.<br><br>
    방패는 하루 종일 맞으면서 적는다. 읽는 건 사람 몫이다.`,
  o:[
    { l:'① 자국의 높이와 깊이로 그것들의 몸을 그려 본다.', k:'gaze', dc:24, wake:1,
      ok:`세 줄은 어깨 높이, 비스듬히 아래로. 선 키가 이쪽보다 머리 하나 크고 오른발잡이다.<br><br>움푹한 데는 가슴 높이 정면. 들이받는 놈이다. 돌진 길이가 길다. 씹힌 자국은 무릎 아래. 작고 많은 것들이 낮게 온다.<br>셋의 몸이 어둠 속에서 그려졌다. 내일 그 셋을 만나면 방패가 먼저 가 있을 것이다. 맞기 전에.<br><br>방패를 읽는 눈이 생겼다. 맞은 자리가 다음에 설 자리를 가르친다. 방패는 기록이고, 기록은 무기다.`,
      ng:`자국을 읽다가 아래 가장자리의 씹힌 자국에서 손이 멈췄다. 이빨 자국 간격이 어린애 턱이다.<br><br>그런데 깊이가 쇠를 문 깊이다. 그 두 가지가 한 턱에서 나온다는 게 그려지지 않았다. 그리다 말았다.<br><br>그날 밤 꿈에 그 턱이 나왔다. 그려지다 만 채로. 덜 그린 그림이 다 그린 그림보다 오래갔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 움푹한 데를 불에 달궈 두드려 편다.', k:'fix', dc:23,
      ok:`움푹한 자리를 숯불에 묻었다가 돌 위에 놓고 돌망치로 폈다. 광산에서 배운 어깨너머 솜씨다.<br><br>완전히 펴지지는 않는다. 그래도 다음 충격이 한 자리로 몰리지 않을 만큼은 됐다.<br><br>두드리는 소리가 밤의 소리들을 잠깐 멈추게 했다. 쇠를 다루는 소리를 아는 것이다. 아는 만큼 거리를 뒀다.`,
      ng:`너무 달궜다. 두드리는 자리가 얇아졌다.<br><br>얇아진 건 두드려 보면 소리로 안다. 알았을 때는 늦었다. 방패 가운데에 손바닥만 한 약한 자리가 생겼다.<br><br>다음 날부터 받을 때마다 그 자리를 피해 받아야 했다. 제 방패의 약점을 제 손으로 만들었다. 그 생각이 받을 때마다 같이 왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S', t:'갈림목 — 비린 바람',
  x:`갈림목에서 바람이 바뀌었다. 비린내가 실려 온다. 짐승 우리 냄새, 그 밑에 쇠 녹는 냄새.<br><br>
    여기 것들은 눈보다 코가 먼저다. 바람이 이쪽 냄새를 그것들 쪽으로 나른다.<br>
    달리면 냄새가 퍼진다. 숨으면 냄새가 고인다.<br><br>
    바람 속에서 무엇이 코를 들었다. 공기 빨리는 소리가 들렸다.`,
  o:[
    { l:'① 방패를 벽 삼아 일행을 바람 그늘에 세우고 선다.', k:'steady', dc:24,
      ok:`바람이 꺾이는 모퉁이에 방패를 세우고 일행을 그 뒤에 몰았다. 방패와 벽 사이, 바람이 죽는 자리다.<br><br>냄새가 제자리에 고였다. 흐르지 않는 냄새는 멀리 못 간다.<br>그것이 갈림목까지 와서 코를 들었다. 냄새의 길이 끊긴 자리에서 두 바퀴 돌았다. 그리고 바람 부는 쪽으로 갔다. 냄새는 바람을 거슬러 나지 않는다고 아는 것이다.<br><br>그것의 앎을 이쪽이 먼저 알았다. 그 차이가 전부였다.`,
      ng:`바람이 한 번 뒤집혔다. 고였던 냄새가 한꺼번에 갈림목으로 쏟아졌다.<br><br>그것이 곧장 왔다. 방패를 돌려 세울 틈이 반 숨이었다. 첫 충격에 방패 위로 넘어온 발톱이 투구를 벗겨 갔다.<br><br>맨머리로 두 번을 더 받았다. 동료들 창이 옆구리를 찔러 쫓았다. 투구는 저만치서 씹힌 채 나왔다. 머리가 아직 붙어 있다는 게 그날의 전부였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-35, mind:-15 } },
    { l:'② 바람을 등지고 옆길로 내닫는다.', k:'evade', dc:25,
      doom:{ title:'바람 속의 코', what:'달리는 등을 물려 바람 위쪽으로 끌려갑니다', dc:19, sec:40,
        text:`내달렸다. 바람을 등지면 냄새가 앞서간다는 걸 뛰면서 알았다.<br><br>냄새가 앞서가서 길목에 먼저 닿았다. 길목에서 그것이 기다리고 있었다.<br>어깨 가죽끈째 물렸다. 발이 땅에서 떴다. 그것은 물고 달린다. 바람 위쪽으로, 제 냄새가 쌓인 곳으로. 방패가 바닥에 끌리며 불꽃을 긋는다. 그 불꽃이 동료들에게 길을 그려 주고 있다는 것만 생각했다.`,
        dieText:`불꽃 자국은 바위 둔덕에서 끊겼다. 둔덕 너머는 뼈 무더기였다.<br><br>방패가 무더기 맨 위에 얹혀 있었다. 앞면이 하늘을 보고. 바람이 그 위를 지나며 쇳내를 실어 날랐다.<br>그 쇳내를 맡고 다른 것들이 모여들기 전에, 일행은 방패를 가지고 돌아섰다. 돌아서는 것 말고 할 수 있는 일이 없었다.` },
      ok:`내달리되 곧장 가지 않았다. 세 걸음마다 꺾었다. 냄새가 길을 그리기 전에 길을 버렸다.<br><br>마지막 모퉁이에서 물웅덩이를 밟았다. 일부러 밟았다. 젖은 냄새가 마른 냄새를 덮는다.<br><br>그것이 웅덩이 앞에서 코를 박고 오래 서 있는 소리를 들으며 일행은 빠져나갔다.`,
      win:{ exp:19, dream:2 } }
  ] },

{ at:'S', t:'무너진 문 — 마지막에 서는 자리',
  x:`나가는 문이 반쯤 무너져 사람 하나 지날 틈만 남았다. 하나씩 빠져나가야 한다.<br><br>
    빠져나가는 동안 등 뒤는 비는 자리다. 그 자리는 방패의 자리다.<br>
    어둠 저쪽에서 발소리들이 모이고 있다. 하나가 아니고, 급하지도 않다. 다 알고 오는 걸음이다.<br><br>
    넷이 지나가는 데 스무 숨. 그 스무 숨을 사야 한다.`,
  o:[
    { l:'① 틈을 등지고 서서 어깨 짚는 수를 세며 받는다.', k:'steady', dc:26, wake:1,
      ok:`틈을 등지고 방패를 세웠다. 나가는 동료가 어깨를 짚고 지난다. 하나. 둘.<br><br>셋째가 짚을 때 첫 놈이 왔다. 받았다. 넷째가 짚을 때 둘이 같이 왔다. 받고, 밀고, 버텼다. 어깨에 손이 닿을 때마다 등 뒤의 숫자가 줄었다.<br>마지막 손이 짚고 넘어갔다. 그 순간 방패째 몸을 틈에 던져 뒷걸음으로 빠졌다.<br><br>맨 마지막은 수를 세는 자리다. 세는 동안은 무섭지 않다. 숫자가 방패보다 단단할 때가 있다.`,
      ng:`셋째까지는 셌다. 넷째 손이 안 왔다. 돌아볼 수 없어 소리쳤다. 대답 대신 틈 안쪽에서 끙끙대는 소리. 넷째가 틈에 끼인 것이다.<br><br>그 사이 둘이 한꺼번에 왔다. 하나는 받고 하나는 못 받았다. 못 받은 쪽 발톱이 허벅지를 열었다.<br><br>넷째를 발로 밀어 넣고 제 몸을 틈에 쑤셔 넣었다. 틈 밖에서 방패를 당기는 힘과 틈 안에서 동료들이 끄는 힘 사이에서 몸이 한 번 삐걱였다. 안쪽 힘이 이겼다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-36, mind:-16 } },
    { l:'② 무력을 다해 문 위 돌무더기를 쳐서 틈을 마저 무너뜨린다.', k:'break', dc:25, cost:{ might:36 },
      ok:`마지막 동료가 빠지는 순간 몸을 던져 틈을 지나며, 방패 모서리로 문 위 괸 돌을 후려쳤다.<br><br>무너졌다. 틈이 닫혔다. 돌 너머에서 발톱들이 돌을 긁는 소리가 났다.<br><br>긁는 소리는 오래가지 않았다. 여기 것들은 셈이 빠르다. 돌을 파는 값과 다른 먹이를 찾는 값을 바로 비교한다. 이쪽은 비싼 먹이가 됐다. 그거면 됐다.`,
      ng:`돌을 쳤는데 엉뚱한 쪽이 먼저 내려앉았다. 이쪽 발등 쪽이다.<br><br>발이 돌 틈에 물렸다. 틈 밖에서 발소리들이 뛰기 시작했다.<br><br>동료 둘이 돌을 들치고 발을 뽑았다. 장화가 벗겨진 채 맨발로 뛰었다. 등 뒤에서 문이 마저 무너지는 소리가 났다. 운이 반, 동료가 반이었다. 이쪽 몫은 없었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-34, spirit:-15 } },
    { l:'③ 동료들에게 밧줄을 맡기고 가장 먼저 틈을 넘는다.', k:'bond', dc:24,
      ok:`순서를 바꿨다. 이쪽이 먼저 넘어가 틈 안쪽에 방패를 세우고, 밧줄을 밖의 동료들에게 던졌다.<br><br>당겨 주는 손이 있으면 틈은 반 숨에 지난다. 스무 숨이 열 숨이 됐다.<br>마지막 동료가 밧줄을 쥐었을 때 첫 놈이 그 등 뒤에 닿았다. 당겼다. 동료가 쑥 빠지고 발톱은 빈 데를 긁었다.<br><br>맨 앞에 서는 것도 지키는 자리일 수 있다. 자리가 아니라 일이 방패를 정한다.`,
      ng:`먼저 넘다가 방패가 틈에 걸렸다. 몸이 반 박자 늦게 빠졌다.<br><br>그 반 박자 동안 밖의 넷이 등을 비운 채 서 있었다. 제일 뒤의 동료 어깨에 발톱이 닿았다 떨어졌다.<br><br>간격이 조금만 좁았어도 사람이 상했다. 순서를 바꾸는 건 셈을 다시 하는 일이다. 셈이 설기 전에 바꾸면 이렇게 된다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S1', t:'에어록 — 둘이 든 방',
  x:`에어록 안쪽 문이 안 열린다. 바깥 문은 등 뒤에서 벌써 닫혔다. 쇠 방 하나에 일행이 다 들어 있다.<br><br>
    천장 환풍구 덮개가 달그락거린다. 나사가 하나뿐이다.<br>
    문 손잡이 바퀴는 돌아가다 만다. 안쪽에서 무엇이 바퀴를 마주 쥐고 있는 느낌이다.<br><br>
    덮개가 한 번 더 들렸다. 이 방에 든 게 일행만이 아니게 될 참이다.`,
  o:[
    { l:'① 바퀴를 두 손으로 쥐고 마주 쥔 힘과 버틴다.', k:'steady', dc:25,
      doom:{ title:'문 너머의 손', what:'문틈으로 나온 것에 에어록 밖으로 끌려갑니다', dc:20, sec:40,
        text:`바퀴를 쥐고 틀었다. 저쪽도 튼다. 힘이 팽팽해진 순간 저쪽이 갑자기 놓았다.<br><br>문이 활짝 열리며 몸이 앞으로 쏟아졌다. 문 너머 어둠에서 긴 팔이 나와 방패 끈을 쥐었다.<br>복도로 끌려 나간다. 바닥이 미끈하다. 끌려가는 길에 빈 허물이 줄지어 있다. 사람 모양이다. 뒤에서 에어록 문이 닫히는 소리가 났다. 동료들이 두드리는 소리가 쇠 너머로 작아진다.`,
        dieText:`문이 다시 열렸을 때 복도는 비어 있었다.<br><br>바닥에 방패가 미끈한 것에 덮여 놓여 있었다. 앞면에 손자국이 많았다. 쇠를 쥐어 본 적 없는 손들이 쥐는 법을 배운 자국이다.<br>복도 끝 어둠에서 바퀴 도는 소리가 났다. 어디선가 다른 문이 열리고 있었다.` },
      ok:`바퀴를 쥐고 저쪽 힘을 읽었다. 당기면 당기고 멈추면 멈춘다. 힘이 아니라 장단이다.<br><br>장단을 거꾸로 탔다. 저쪽이 당길 때 놓고, 놓을 때 당겼다. 세 번째에 저쪽 손이 미끄러지는 느낌이 바퀴를 타고 왔다.<br><br>바퀴가 끝까지 돌았다. 문이 열리고, 문 너머는 비어 있었다. 복도 저쪽에서 무엇이 급하게 기는 소리만 멀어졌다.`,
      win:{ exp:21, dream:3 } },
    { l:'② 조작반을 뜯어 문 여는 순서를 바꾼다.', k:'fix', dc:24,
      ok:`조작반 덮개를 방패 모서리로 비틀어 열었다. 선이 두 묶음이다. 안문, 바깥문.<br><br>안문 묶음을 끊고 바깥문 묶음에 이었다. 바퀴를 틀자 이번엔 끝까지 돌았다.<br>문이 열렸다. 마주 쥐고 있던 것은 안문 바퀴에 매달린 채였다. 열리는 건 이쪽 문인 줄 모르고.<br><br>일행이 빠져나간 뒤 선을 도로 끊었다. 그것이 문 여는 법을 배우게 둘 수는 없다.`,
      ng:`선을 잘못 이었다. 천장 환풍구 덮개가 철컥 열렸다.<br><br>덮개에서 작은 것이 떨어졌다. 다리가 많고 꼬리가 길다. 제일 가까운 동료 투구에 달라붙었다.<br><br>방패로 쳐서 떨어뜨리고 장화로 밟았다. 터진 자리에서 신 냄새가 났다. 바닥 쇠가 얕게 녹았다. 작은 것도 피는 같은 피다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S1', t:'숙소 구역 — 환풍구와 밤',
  x:`숙소 구역에서 밤을 나기로 했다. 방은 잠기는데 환풍구가 셋이다. 벽에 둘, 천장에 하나.<br><br>
    여기 것들은 문으로 안 다닌다. 관으로 다닌다. 벽 속에서 긁는 소리가 이따금 지나간다.<br>
    방패는 하나고 구멍은 셋이다.<br><br>
    어느 구멍을 막을지는 방패 든 사람이 정한다.`,
  o:[
    { l:'① 숨이 나오는 구멍을 찾아 그 하나를 방패로 막고 등을 댄다.', k:'steady', dc:24, wake:1,
      ok:`구멍마다 손바닥을 대 봤다. 둘은 바람이 일정하다. 기계 숨이다. 벽 아래 하나는 바람이 들쭉날쭉하다. 숨 쉬는 게 관 속에 있다.<br><br>그 구멍에 방패를 대고 등으로 눌렀다. 밤중에 등으로 세 번 밀림이 왔다. 세 번 다 되밀었다.<br>네 번째는 긁는 소리가 옆으로 돌아 천장 구멍 쪽으로 갔다. 천장 덮개 앞에서 멈췄다가, 그냥 갔다. 기계 숨 구멍으로는 저도 안 다니는 것이다.<br><br>구멍 셋이 다 같은 구멍이 아니다. 숨을 짚어 보면 문이 몇 개인지 나온다. 그 짚는 손이 이제 방패만큼 미덥다.`,
      ng:`숨을 잘못 짚었다. 막은 구멍은 기계 숨이었다.<br><br>밤중에 천장 덮개가 소리 없이 들렸다. 동료의 숨소리가 바뀌는 걸 듣고야 알았다. 긴 꼬리가 덮개 틈으로 내려와 침낭 위를 더듬고 있었다.<br><br>방패를 던지듯 올려 덮개를 쳤다. 꼬리가 관 속으로 빨려 들어갔다. 남은 밤은 천장 밑에서 방패를 이고 앉아 보냈다. 팔보다 자존심이 더 아팠다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 관 속 소리의 길을 귀로 그려 본다.', k:'sense', dc:24,
      ok:`벽에 귀를 대고 긁는 소리를 따라갔다. 소리가 꺾이는 데마다 손가락으로 벽에 금을 그었다.<br><br>그린 금이 방을 한 바퀴 돌고 바닥 쪽으로 내려갔다. 관이 방 밑을 지나는 것이다. 벽 구멍들은 곁가지다.<br><br>침낭을 방 가운데서 벽 쪽으로 옮겼다. 방 가운데가 관 바로 위였다. 밤새 바닥 밑으로 두 번, 무엇이 지나갔다. 바로 밑을. 옮긴 자리에서는 숨소리만 한 거리였다.`,
      ng:`소리를 따라가는데 소리가 멈췄다. 귀를 뗀 순간 벽 너머에서 마주 긁었다. 귀가 있던 자리를. 정확히.<br><br>저쪽도 듣고 있던 것이다. 벽 하나를 사이에 두고 서로 귀를 대고 있었다.<br><br>그 벽에서 제일 먼 구석으로 일행을 옮겼다. 잠은 오지 않았다. 벽 너머에서 밤새 한 자리를 긁는 소리가 났다. 문을 파는 소리였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'표본실 — 병과 뚜껑',
  x:`표본실이다. 벽장마다 유리병이 줄지어 있다. 병 속에 뜬 것들이 불빛에 흔들린다.<br><br>
    바닥에 깨진 유리가 밟힌다. 병은 세었는데 뚜껑이 남는다. 빈 병이 있다는 뜻이다.<br>
    병마다 적힌 글씨는 반쯤 지워졌다. 숫자만 남은 것도 있다.<br><br>
    벽장 맨 아래 칸, 제일 큰 병이 비어 있다. 뚜껑은 안쪽에서 밀려 깨진 모양새다.`,
  o:[
    { l:'① 병과 뚜껑을 맞춰 몇 마리가 나갔는지 센다.', k:'gaze', dc:24,
      ok:`병을 세고 뚜껑을 셌다. 병 서른둘, 성한 뚜껑 스물아홉. 깨진 뚜껑 둘. 하나가 빈다.<br><br>빈 병은 셋. 둘은 작은 병, 하나는 큰 병이다. 작은 것 둘, 큰 것 하나가 이 건물 어딘가에 있다.<br>큰 병 안쪽에 긁힌 자국이 있다. 자국 간격이 문에서 본 발톱 자국과 같다. 복도의 그것이 여기서 나간 것이다.<br><br>세어 보면 어둠에 수가 생긴다. 수가 생기면 어둠이 조금 좁아진다. 셋. 넷도 다섯도 아니고 셋.`,
      ng:`세는 중에 병 하나가 흔들렸다. 속에 뜬 것이 돌아섰다. 뜬 것들은 다 눈을 감고 있었다. 그것만 눈이 없었다. 눈이 있던 자리가 이쪽을 향했다.<br><br>병을 놓칠 뻔해 벽장을 쳤다. 벽장 전체가 흔들리며 병들이 일제히 부딪쳤다.<br><br>복도 저쪽에서 대답처럼 긁는 소리가 났다. 수를 세다 수에 들킨 셈이다. 서둘러 표본실을 나왔다. 몇이 나갔는지는 끝내 못 셌다.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-18, spirit:-15 } },
    { l:'② 벽장 서랍을 뒤진다.', k:'luck', dc:25,
      ok:`벽장 아래 서랍들을 당겼다. 셋째 서랍에 마른 풀 묶음이 종이에 싸여 있다. 연구자들이 쓰던 압착 표본인데 약초다. 쓸 수 있는 것만 골라 묶었다.<br><br>맨 아래 서랍에는 밀봉된 물통이 둘. 유리 긁힌 자국 하나 없이 멀쩡하다.<br><br>표본실은 터는 곳이 아니라 읽는 곳이지만, 읽다 보면 가끔 이런 줄도 나온다.`,
      ng:`서랍을 당기는데 안에서 무게가 쏠렸다. 작은 것이 서랍 안에 웅크리고 있었다.<br><br>튀어나와 손등을 긋고 벽장 뒤로 사라졌다. 손등이 금세 부어오른다. 독은 아니다. 독이면 벌써 쓰러졌다.<br><br>동료가 손등을 짜고 싸맸다. 서랍은 발로 밀어 닫았다. 남은 서랍은 열지 않았다. 운을 시험하는 건 하루 한 번이면 된다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S1', t:'식당 구역 — 가슴이 우는 사람',
  x:`식당 구역에서 사람을 만났다. 연구복 차림이다. 살아 있다. 말도 한다. 며칠을 숨어 지냈다고 한다.<br><br>
    방패 뒤에 들어오게 해 달라고 한다. 지켜 달라고. 같이 나가자고.<br>
    그가 숨을 들이쉴 때마다 가슴께 연구복이 조금 늦게 부푼다. 숨과 가슴이 박자가 안 맞는다.<br><br>
    안에서 다른 것이 제 숨을 쉬는 것이다.`,
  o:[
    { l:'① 방패 길이만큼 거리를 두고 같이 걷는다.', k:'steady', dc:25,
      doom:{ title:'벌어진 가슴', what:'가슴에서 나온 것에 관 속으로 끌려갑니다', dc:20, sec:35,
        text:`방패 하나 거리를 두고 걸었다. 그가 자꾸 거리를 좁힌다. 춥다고. 무섭다고.<br><br>모퉁이에서 그가 비틀거렸다. 반사로 팔을 뻗어 받쳤다. 거리가 사라진 그 순간 그의 가슴이 안쪽부터 열렸다.<br>나온 것은 작지만 빨랐다. 방패 안쪽으로 파고들어 목덜미에 감겼다. 차고 축축하다. 그대로 바닥을 끌고 환풍구 쪽으로 간다. 힘이 몸집의 열 배다. 그가 바닥에 앉아 꺼진 가슴으로 이쪽을 보고 있었다. 미안하다는 입 모양이었다.`,
        dieText:`환풍구 안쪽에서 방패가 걸려 나오지 않았다. 덮개에 비스듬히 낀 채였다.<br><br>며칠 뒤 다른 길에서 연구복 입은 사람이 일행 앞에 나타났다. 처음 보는 얼굴이다. 가슴 박자가 숨과 안 맞았다.<br>그는 방패 뒤에 들어오게 해 달라고 했다. 아는 목소리로. 아는 말버릇으로.` },
      ok:`방패 하나 거리. 그가 좁히면 이쪽이 물러나 되벌렸다. 서운해해도 벌렸다.<br><br>식당을 반쯤 질렀을 때 그의 가슴이 열렸다. 나온 것이 허공을 갈랐다. 방패 하나 거리만큼 모자랐다. 앞면에 부딪혀 떨어진 것을 동료들이 창으로 눌렀다.<br><br>그는 숨을 두 번 쉬고 멎었다. 끝까지 사람의 눈이었다. 거리는 그를 위한 것이기도 했다. 덜 미안한 자리에서 보내 줄 수 있었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 가슴의 박자를 그에게 묻는다.', k:'gaze', dc:24,
      ok:`숨과 가슴이 안 맞는다고, 본 대로 말했다. 그가 멈춰 서서 제 가슴을 내려다봤다.<br><br>알고 있었다고 했다. 사흘 됐다고. 같이 가면 안 되는 것도 안다고. 그는 통로 끝 냉동고를 가리켰다. 저 안이면 늦출 수 있다고. 문을 밖에서 잠가 달라고 했다.<br><br>잠갔다. 문 너머에서 고맙다는 말이 났다. 방패는 때로 문이다. 문은 때로 닫아 주는 게 지키는 것이다.`,
      ng:`말을 꺼내자 그의 눈빛이 바뀌었다. 아니라고, 아니라고 소리치며 물러난다.<br><br>소리가 식당에 울렸다. 천장 관들이 일제히 긁는 소리로 대답했다. 그는 겁에 질려 어둠 속으로 뛰어 들어갔다.<br><br>쫓아갈 수 없었다. 관 소리가 다 그쪽으로 몰리고 있었다. 밤에 멀리서 가슴 열리는 소리를 들었다. 들은 사람은 다 못 들은 척했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-19, spirit:-20 } }
  ] },

{ at:'S1', t:'중앙 복도 — 천장이 삭는 길',
  x:`중앙 복도 천장이 삭았다. 위층에서 산성 피가 밴 것이다. 방울이 느리게 맺혀 떨어진다.<br><br>
    떨어진 자리마다 바닥이 얽었다. 얽은 자국이 복도 끝까지 이어진다. 돌아가는 길은 없다.<br>
    방울은 한 줄로 안 떨어진다. 천장 가득 맺혀 있다.<br><br>
    우산이 필요한 길이다. 쇠 우산이.`,
  o:[
    { l:'① 무력을 다해 방패를 이고 일행을 밑에 모아 건넌다.', k:'steady', dc:25, cost:{ might:38 },
      ok:`방패를 머리 위로 수평으로 들고 일행을 방패 그늘에 모았다. 다섯이 한 덩어리로 걸었다.<br><br>방울이 앞면에 앉을 때마다 쇠가 운다. 기울여 흘리고, 받고, 또 흘렸다. 팔이 타는 것 같았다. 산이 아니라 무게로.<br>복도 끝에서 방패를 내렸다. 앞면이 얽을 대로 얽었다. 다섯 명분의 얽음이다.<br><br>동료 하나가 방패의 얽은 데를 손끝으로 짚어 보고 아무 말 없이 어깨만 두드렸다. 그걸로 됐다.`,
      ng:`복도 가운데서 팔이 한 번 꺾였다. 방패가 기울며 고였던 방울들이 한쪽으로 쏟아졌다.<br><br>맨 가장자리 동료의 어깨에 떨어졌다. 천이 타고 비명이 났다. 비명에 복도 끝 어둠이 움직였다.<br><br>남은 길을 반은 뛰다시피 건넜다. 어깨 데인 동료를 부축한 채였다. 방패는 끝까지 들고 있었다. 팔이 제 것 같지 않았다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-35, mind:-14 } },
    { l:'② 방울 듣는 박자를 재서 틈새로 지난다.', k:'sense', dc:24,
      ok:`방울은 제멋대로 듣지 않는다. 맺히는 데 걸리는 시간이 있다. 자리마다 박자를 쟀다.<br><br>박자가 긴 자리만 이어 길을 그렸다. 지그재그로 복도를 건너는 길이다. 하나씩, 박자 사이로 보냈다.<br><br>다 건너고 돌아보니 길이 안 보였다. 바닥 얽은 자국만 보였다. 길은 바닥이 아니라 박자에 있었다.`,
      ng:`박자를 쟀는데 천장이 셈을 어겼다. 삭은 판 하나가 통째로 내려앉았다.<br><br>판에 고였던 것이 비처럼 쏟아졌다. 방패를 펴 막았지만 튄 방울이 장갑 틈으로 들어왔다.<br><br>손가락 두 개의 감각이 밤까지 돌아오지 않았다. 박자는 맞았다. 천장이 삭는 속도까지는 박자에 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S1', t:'배양동 — 굳는 벽',
  x:`배양동 벽이 이상하다. 쇠 위에 검은 것이 겹겹이 발려 있다. 만지면 미지근하다.<br><br>
    그것들이 바르는 집이다. 벽이 안쪽으로 좁아지며 굴이 된다.<br>
    지나가려면 굴을 지나야 한다. 방패 가장자리가 벽에 스쳤다. 떨어지지 않는다.<br><br>
    검은 것이 쇠를 쥐고 굳는 중이다.`,
  o:[
    { l:'① 숨을 고르며 조금씩 흔들어 소리 없이 뗀다.', k:'steady', dc:24, wake:1,
      ok:`당기지 않았다. 당기면 뜯는 소리가 난다. 이 집에서 뜯는 소리는 초인종이다.<br><br>손목만 써서 좌우로 가늘게 흔들었다. 숨 한 번에 한 번. 검은 것이 조금씩 늘어나다 소리 없이 놓았다.<br>방패를 몸에 바싹 붙이고 굴을 지났다. 벽에 아무것도 더 주지 않았다.<br><br>급한 손이 내는 소리를 급하지 않은 손은 안 낸다. 그 손이 생겼다. 쇠를 다루는 손이 아니라 집을 존중하는 손이다. 집주인을 깨우지 않는.`,
      ng:`거의 뗐을 때 어깨가 벽을 스쳤다. 어깨받이가 붙었다.<br><br>몸째 흔들 수는 없다. 끈을 풀고 어깨받이를 벽에 두고 나왔다. 검은 것이 어깨받이를 천천히 삼키는 걸 굴 끝에서 봤다.<br><br>집은 바친 것을 받고 조용했다. 어깨 한쪽이 밤새 시렸다. 바친 값이라기엔 쌌다고, 억지로 생각했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-25, spirit:-16 } },
    { l:'② 무력으로 단숨에 뜯고 내닫는다.', k:'break', dc:25, cost:{ might:33 },
      ok:`한 번에 뜯었다. 젖은 천 찢는 소리가 배양동에 울렸다.<br><br>울림이 끝나기 전에 굴을 내달렸다. 벽 속에서 깨는 소리들이 따라왔지만 굴은 이미 등 뒤였다.<br><br>소리를 내는 게 늘 지는 수는 아니다. 소리와 다리가 같이 빠르면 수가 된다. 다만 두 번 쓸 수는 없는 수다.`,
      ng:`뜯었는데 방패에 검은 것이 길게 딸려 왔다. 끈처럼 늘어나며 안 끊어진다.<br><br>끈 끝이 벽 속 깊이 이어져 있고, 벽 속에서 그 끈을 당기는 힘이 왔다. 낚싯줄에 걸린 쪽은 이쪽이었다.<br><br>칼 든 동료가 세 번을 그어서야 끊었다. 방패에 검은 토막이 붙은 채 내달렸다. 토막은 밤까지 꿈틀거렸다. 불에 던지자 비명 같은 김을 냈다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'S1', t:'심부 격벽 — 숨 쉬는 문',
  x:`심부로 가는 격벽이 부풀었다 꺼진다. 쇠문이 숨을 쉰다. 문 너머에 아주 큰 것이 있고, 그 숨이 문을 밀고 당기는 것이다.<br><br>
    여왕이라고, 표본실 기록은 그렇게 불렀다.<br>
    지나가려면 이 격벽 앞 복도를 질러야 한다. 문이 부풀 때 복도가 좁아진다.<br><br>
    숨소리에 귀가 먹먹하다. 숨 하나하나가 공기를 다 쓴다.`,
  o:[
    { l:'① 문이 꺼지는 숨에 맞춰 한 사람씩 통과시킨다.', k:'steady', dc:26, wake:1,
      ok:`문의 숨을 셌다. 부풀고, 멎고, 꺼진다. 꺼지는 동안이 여섯 걸음. 복도는 다섯 걸음.<br><br>방패를 격벽 쪽으로 세우고 복도 가운데 섰다. 숨이 꺼질 때마다 손짓으로 하나씩 보냈다. 하나. 둘. 부풀 때는 이쪽 팔로 막아 세웠다.<br>마지막은 이쪽이다. 숨이 꺼지는 순간 다섯 걸음을 디뎠다. 등 뒤에서 격벽이 다시 부풀었다.<br><br>아주 큰 숨 곁에서는 제 숨을 그 숨에 맞추는 수밖에 없다. 맞추고 나면 큰 숨도 길이가 있는 숨일 뿐이다.`,
      ng:`넷째를 보내는데 문 숨이 당겨졌다. 박자가 바뀐 것이다. 잠든 숨에서 깬 숨으로.<br><br>부푼 격벽이 넷째의 등을 밀어 벽에 붙였다. 방패를 격벽과 동료 사이에 쑤셔 넣고 버텼다. 쇠와 쇠 사이에서 방패가 울었다.<br><br>숨이 꺼질 때 동료를 뽑아냈다. 갈비뼈에 금이 간 것 같다고 했다. 문 너머에서, 웃음처럼 긴 숨이 한 번 지나갔다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-33, mind:-16 } },
    { l:'② 격벽 옆 좁은 배관 틈으로 돌아간다.', k:'hide', dc:25,
      doom:{ title:'곁길의 임자', what:'배관 틈에서 나온 꼬리에 둥지로 끌려갑니다', dc:20, sec:35,
        text:`배관 틈은 몸 하나 간신히 지나는 폭이다. 방패를 앞세워 모로 끼어 들었다.<br><br>반쯤 지났을 때 알았다. 틈이 좁은 게 아니라 안이 차 있는 것이다. 검은 것이 벽을 바르고 있었다. 곁길은 길이 아니라 둥지의 처마였다.<br>어둠 속에서 꼬리가 나와 발목을 감았다. 당긴다. 안쪽으로. 방패가 틈에 걸려 몸만 끌려간다. 끈이 팔에서 찢겨 나갔다. 숨 쉬는 문 소리가 점점 가까워졌다. 문 너머 쪽에서.`,
        dieText:`배관 틈 입구에 방패만 끼어 있었다. 틈 폭에 꽉 맞게. 마개처럼.<br><br>며칠 뒤에도 방패는 그대로였다. 안쪽에서 검은 것이 방패를 반쯤 삼켰다.<br>둥지가 방패를 벽으로 썼다. 지키던 물건이 지키는 일을 계속하고 있었다. 주인만 바뀐 채.` },
      ok:`틈에 들기 전에 방패를 먼저 밀어 넣어 봤다. 반 길쯤에서 걸렸다. 걸린 게 아니라 잡혔다. 쇠를 쥐는 느낌이 손잡이로 왔다.<br><br>방패를 도로 당겼다. 저쪽도 당긴다. 힘을 겨루지 않고 놓는 척하다 홱 뽑았다.<br><br>틈은 길이 아니었다. 길이 아닌 걸 방패가 먼저 알았다. 몸이 먼저 알 뻔했다. 격벽 숨에 맞춰 건너는 쪽으로 돌아섰다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'울타리 — 빈 칸을 채우는 것',
  x:`정원을 두른 옛 울타리다. 쇠기둥에 가로대가 걸렸는데 한 칸이 부서져 비었다.<br><br>
    저녁마다 그것들이 울타리를 시험하러 온다. 머리로 밀어 보고, 발톱으로 당겨 보고, 간다.<br>
    오늘 밤 그것들이 빈 칸을 찾아낼 것이다. 고칠 시간은 없고 버릴 수도 없다. 빈 칸 너머가 잘 자리다.<br><br>
    빈 칸은 방패 하나 폭이다.`,
  o:[
    { l:'① 빈 칸에 방패를 세우고 그 뒤에 선다.', k:'steady', dc:25,
      ok:`방패를 빈 칸에 맞춰 세우고 어깨로 받쳤다. 울타리의 한 칸이 됐다.<br><br>어스름에 그것들이 왔다. 차례로 밀어 보고 간다. 빈 칸 차례가 왔다. 콧김이 쇠에 닿는다. 밀었다. 되밀었다. 울타리 쇠기둥과 같은 만큼만.<br>세 번 밀고 세 번 같은 답을 받자 그것은 다음 칸으로 갔다. 울타리는 밀어도 되미는 물건. 그 답이 맞으면 그것들은 간다.<br><br>밤새 두 바퀴를 돌고 그것들은 물러났다. 울타리가 된 어깨가 아침에야 풀렸다.`,
      ng:`두 번째 밀기에 발이 반 뼘 밀렸다. 쇠기둥은 반 뼘 안 밀린다.<br><br>그것이 알았다. 콧김이 급해지고 머리가 거푸 부딪쳐 왔다. 다른 것들이 모여들었다.<br><br>동료들이 불붙은 가지를 던져 쫓을 때까지 일곱 번을 받았다. 어깨가 한쪽으로 내려앉았다. 울타리 노릇은 반 뼘이 전부다. 그 반 뼘을 뼈로 배웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-36, mind:-14 } },
    { l:'② 부서진 가로대를 덩굴로 얽어 다시 건다.', k:'fix', dc:24,
      ok:`부러진 가로대를 주워 맞추고 덩굴로 열십자로 얽었다. 광에서 본 울짱 매듭이다.<br><br>얽은 위에 가시덩굴을 한 겹 더 감았다. 밀면 찔리게.<br>저녁에 그것이 와서 밀었다. 찔렸다. 콧김을 불며 물러나 다른 칸으로 갔다.<br><br>고친 칸은 성한 칸보다 세 배로 시험받는다. 그걸 알고 세 배로 감았다. 셈이 맞았다.`,
      ng:`덩굴이 밤이슬에 늘어졌다. 가로대가 처졌다.<br><br>그것이 처진 데를 단박에 알아봤다. 머리를 넣고 비틀자 매듭이 풀렸다. 뿔 돋은 머리가 울타리 안으로 들어왔다.<br><br>자던 일행이 뛰어 일어나 창대로 때려 쫓았다. 새벽까지 아무도 다시 눕지 못했다. 매듭은 젖을 것까지 셈해서 지어야 했다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S2', t:'물에 잠긴 양치밭 — 밀려오는 물',
  x:`허리까지 잠기는 양치밭을 건넌다. 물풀이 다리를 쓴다.<br><br>
    멀리서 쿵, 하고 물 전체가 한 번 울렁였다. 큰 것이 걷는 것이다. 걸음마다 물살이 밀려온다.<br>
    물살에 넘어지면 물풀 밑으로 들어간다. 물풀 밑에는 작은 것들이 산다. 이빨이 잔 것들이.<br><br>
    다음 물살이 수면 저쪽에서 줄을 그으며 온다.`,
  o:[
    { l:'① 방패를 물살에 비껴 세우고 일행을 뒤에 줄 세운다.', k:'steady', dc:25,
      ok:`방패 아래를 물에 박고 물살이 오는 쪽으로 비스듬히 세웠다. 물이 앞면을 타고 갈라졌다.<br><br>뒤에 선 일행은 허리띠를 서로 쥐고 줄이 됐다. 물살이 지나갈 때마다 줄이 출렁이고, 방패가 반을 갈라 냈다.<br>걸음 쿵, 물살, 버팀. 그 장단으로 밭을 건넜다. 큰 것은 끝내 보이지 않았다. 물살로만 왔다.<br><br>보이지 않는 것도 막아진다. 오는 방향만 알면 방패는 선다.`,
      ng:`세 번째 물살이 두 겹으로 왔다. 큰 것이 돌아선 것이다.<br><br>겹물살에 방패가 들리고 몸이 떴다. 물풀 밑으로 반쯤 잠겼다. 잔 이빨들이 장딴지를 몇 군데 긋고 지나갔다.<br><br>허리띠 줄이 이쪽을 건졌다. 세운 방패가 아니라 쥐고 있던 줄이. 물에서는 줄이 벽보다 세다는 걸 적셔서 배웠다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-34, mind:-15 } },
    { l:'② 물살 사이에 둔덕까지 내닫는다.', k:'evade', dc:24,
      doom:{ title:'물풀 아래', what:'물풀 밑으로 잡아채여 가라앉습니다', dc:19, sec:40,
        text:`물살과 물살 사이, 잔잔한 틈에 내달렸다. 둔덕까지 열 걸음.<br><br>여섯 걸음째에 발목이 잡혔다. 물풀이 아니다. 물풀 흉내를 내는 손이다.<br>무릎, 허리, 가슴. 물이 차오르는 게 아니라 몸이 내려간다. 방패로 수면을 쳤지만 물은 칠 수 없는 벽이다. 물속에서 눈을 떴다. 잔 이빨들이 반짝이며 모여들고 있었다. 수면 위에서 동료들 발소리가 물을 울리며 왔다. 멀다.`,
        dieText:`둔덕 쪽 수면에 방패가 떠올랐다. 앞면을 하늘로 하고. 거북 등처럼.<br><br>방패는 느리게 맴돌며 떠 있었다. 아래에서 무엇이 그걸 이고 노는 것처럼.<br>해 질 녘에 방패가 한 번에 쑥 가라앉았다. 노는 시간이 끝난 것이다.` },
      ok:`물살 틈에 내달리되 발을 높이 들어 디뎠다. 물풀에 발목을 주지 않는 걸음이다.<br><br>일곱 걸음째에 무엇이 장화 뒤축을 스쳤다. 여덟, 아홉, 둔덕.<br><br>뒤돌아 방패를 세우고 일행을 하나씩 받아 올렸다. 마지막 동료 뒤로 물풀이 길게 일렁였다. 아쉬워하는 일렁임이었다.`,
      win:{ exp:19, dream:2 } }
  ] },

{ at:'S2', t:'마른 개울 — 셋이 오는 법',
  x:`마른 개울 바닥을 걷는데 앞에 하나가 나섰다. 발톱 긴 것. 몸을 낮추고 이쪽을 본다.<br><br>
    너무 당당하다. 저 몸집이 정면에 서는 건 셈이 따로 있다는 뜻이다.<br>
    개울 양쪽 둔덕의 풀이 바람 없이 흔들렸다. 왼쪽 하나, 오른쪽 하나.<br><br>
    앞의 것은 미끼다. 진짜는 옆에서 온다.`,
  o:[
    { l:'① 정면을 버리고 방패를 옆으로 돌려 세운다.', k:'steady', dc:25, wake:1,
      ok:`앞의 것을 눈으로만 잡아 두고 방패를 왼쪽 둔덕으로 돌렸다. 풀 흔들림이 더 가까운 쪽이다.<br><br>왼쪽 것이 풀을 가르고 날아들었다. 방패 복판에 정통으로 부딪혀 개울 바닥에 떨어졌다. 셈이 깨진 것이다.<br>정면의 것이 주춤하고, 오른쪽 것은 뛰다 말았다. 미끼 노릇이 끝난 정면이 제일 먼저 돌아섰다.<br><br>정면이 늘 앞은 아니다. 방패가 볼 곳은 눈이 가는 곳이 아니라 셈이 가는 곳이다. 그 셈이 이제 등골로 온다. 풀 흔들림 하나에.`,
      ng:`왼쪽으로 돌렸는데 왼쪽이 늦고 오른쪽이 빨랐다. 흔들림의 크기가 아니라 순서를 읽었어야 했다.<br><br>오른쪽 것이 빈 옆구리로 들어왔다. 갈비를 발톱이 긁었다. 방패를 되돌리는 반 바퀴가 그렇게 길 수 없었다.<br><br>동료들 창이 울타리처럼 서서야 셋이 물러났다. 옆구리 천이 피에 붙었다. 셋의 셈은 둘보다 한 겹 깊었다. 다음엔 순서까지 읽는다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-37, mind:-15 } },
    { l:'② 조용한 놈을 찾는다 — 소리 내는 쪽은 미끼다.', k:'gaze', dc:24,
      ok:`왼쪽 풀은 흔들리며 소리가 난다. 오른쪽 풀은 흔들림이 잘고 소리가 없다.<br><br>소리 내는 쪽이 미끼의 미끼다. 진짜는 오른쪽. 방패를 오른쪽에 두고 창든 동료를 왼쪽에 세웠다.<br>덮침은 오른쪽에서 왔고 방패가 받았다. 왼쪽은 시늉만 하고 빠졌다.<br><br>미끼 뒤에 미끼를 두는 사냥을 하는 것들이다. 이쪽도 셈을 한 겹 더 깊게 놓는 수밖에 없다.`,
      ng:`읽는 사이에 정면의 것이 걸음을 옮겼다. 시선이 따라갔다. 그게 신호였다.<br><br>양쪽이 동시에 왔다. 방패는 하나고 옆구리는 둘이다. 왼쪽은 받았고 오른쪽은 동료의 창대가 겨우 걷어 냈다.<br><br>창대가 부러졌다. 부러진 반쪽을 쥔 동료 손이 떨렸다. 읽는 동안에도 방패는 어딘가를 향해 있어야 했다.`,
      win:{ exp:19, dream:3 }, lose:{ hp:-31, spirit:-16 } },
    { l:'③ 무력을 다해 정면의 미끼를 먼저 들이친다.', k:'break', dc:26, cost:{ might:40 },
      ok:`셈을 거꾸로 뒤집었다. 기다리는 대신 방패째 정면으로 내달렸다.<br><br>미끼는 받는 법만 알지 받히는 법은 모른다. 방패 복판으로 들이받자 미끼가 둔덕까지 굴렀다.<br>옆의 둘은 셈이 뒤집힌 자리에서 뛰지 못했다. 덮치는 쪽이 덮쳐지는 그림은 저들 셈에 없다.<br><br>굴러간 미끼가 일어나 절뚝이며 물러났다. 둘이 따라갔다. 무리는 셈이 깨지면 사냥을 접는다. 오늘 셈은 이쪽이 이겼다.`,
      ng:`내달리는 반 걸음에 미끼가 물러섰다. 받히는 법을 아는 미끼였다.<br><br>빈 데를 친 방패가 무거웠다. 돌아서는 등으로 양쪽이 덮쳤다. 하나는 방패 테두리로 걷어 냈지만 하나가 어깨를 물었다 놓았다.<br><br>문 자국이 얕았다. 간을 본 것이다. 다음에 깊이 물 자리를. 물린 어깨보다 그 생각이 무거웠다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-38, mind:-16 } }
  ] },

{ at:'S2', t:'진흙 벌 — 큰 것의 걸음',
  x:`진흙 벌 한가운데서 땅이 울렸다. 쿵. 물웅덩이마다 동그라미가 번진다.<br><br>
    큰 것이 온다. 나무 위 새들이 소리를 끊었다. 숨을 데가 없는 벌판이다.<br>
    저것의 눈은 움직임을 잡는다고, 울타리 기둥의 긁힌 높이가 말해 줬었다. 저 높이에서 보면 서 있는 사람은 그루터기다.<br><br>
    쿵. 동그라미가 커졌다.`,
  o:[
    { l:'① 방패에 진흙을 바르고 일행을 그 뒤에 세워 그루터기가 된다.', k:'steady', dc:26,
      ok:`방패에 진흙을 처바르고 비스듬히 세웠다. 일행은 그 뒤에 포개 앉았다. 숨만 쉬었다.<br><br>걸음이 왔다. 쿵. 쿵. 다리 하나가 방패 열 걸음 앞을 디뎠다. 디딘 자리의 진흙이 이쪽 발목까지 튀었다.<br>큰 것이 벌판을 질러갔다. 그루터기 하나를 끝내 돌아보지 않았다.<br><br>움직이지 않는 것은 저것의 세상에 없다. 없는 것이 되는 게 제일 단단한 방패일 때가 있다.`,
      ng:`다리가 코앞을 디딜 때 맨 뒤 동료의 다리가 풀렸다. 진흙에 손을 짚는 철퍽 소리.<br><br>큰 것이 멈췄다. 목이 돌아오는 그림자가 방패 위로 덮였다. 콧김이 진흙을 말리며 지나갔다. 한 번. 두 번.<br><br>새 한 마리가 벌판 끝에서 날아올랐다. 그림자가 그쪽으로 돌았다. 걸음이 멀어진 뒤에도 아무도 일어서지 못했다. 바지가 다 젖어 있었다. 진흙만은 아니었다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 떨리는 동료의 어깨를 눌러 같이 숨을 센다.', k:'bond', dc:24,
      ok:`옆 동료의 어깨가 떨렸다. 어깨에 손을 얹고 귓가에 숫자를 셌다. 하나에 들이쉬고 둘에 참고 셋에 내쉬고.<br><br>떨림이 숫자에 묶였다. 걸음이 지나가는 동안 다섯 사람 숨이 한 숨이 됐다.<br><br>큰 것이 지나간 뒤 동료가 말했다. 숫자만 들렸다고. 그거면 됐다. 무서움은 없앨 수 없다. 묶어 둘 수는 있다.`,
      ng:`숫자를 세는데 이쪽 목소리가 먼저 갈라졌다. 동료가 그걸 들었다.<br><br>둘의 떨림이 서로를 키웠다. 방패 테가 갑옷 무릎에 닿아 딱딱 소리를 냈다.<br><br>큰 것이 그 소리에 한 박자 멈췄다 갔다. 지나간 뒤 서로 아무 말 안 했다. 센 사람이 떨면 센 숫자도 떤다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-17, spirit:-17 } }
  ] },

{ at:'S2', t:'비탈길 — 뿔 돋친 돌진',
  x:`비탈 아래서 뿔 돋친 것이 땅을 긁는다. 머리가 바위만 하고 뿔이 셋이다.<br><br>
    초식이다. 초식이라서 더 거침없다. 잡아먹으려는 게 아니라 치우려는 것이다. 제 길에서.<br>
    비탈이라 피할 자리가 없다. 왼쪽은 절벽, 오른쪽은 가시덤불.<br><br>
    땅 긁기가 끝났다. 온다.`,
  o:[
    { l:'① 무력을 다해 방패를 비탈에 박고 비스듬히 흘려보낸다.', k:'steady', dc:25, cost:{ might:37 },
      ok:`방패 아래를 흙에 박고 윗가장자리를 비탈 위쪽으로 눕혔다. 벽이 아니라 미끄럼틀이다.<br><br>뿔이 앞면에 닿는 순간 충격이 비스듬히 흘렀다. 머리가 방패를 타고 위로 떠올랐다. 제 무게에 제가 들린 것이다.<br>그것이 비탈에 모로 넘어져 미끄러졌다. 한참 아래서 일어나 어리둥절 서 있었다.<br><br>받는 것과 흘리는 것은 다른 일이다. 산 같은 무게는 받지 않는다. 길을 바꿔 준다.`,
      ng:`박은 각이 섰다. 흘리지 못하고 정통으로 받았다.<br><br>방패째 몸이 떠서 가시덤불에 떨어졌다. 가시가 등 전체에 박혔다. 방패는 비탈 아래까지 굴러갔다.<br><br>그것은 제 길이 치워졌으므로 유유히 지나갔다. 동료들이 가시를 뽑는 동안 방패를 주워 왔다. 앞면에 뿔 자국 세 개가 나란했다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-39, mind:-14 } },
    { l:'② 마지막 순간 절벽 쪽으로 반 걸음 꺼진다.', k:'evade', dc:25,
      ok:`절벽 쪽 반 걸음. 발 하나는 허공 턱에 걸쳤다. 그것의 눈은 큰 움직임만 좇는다.<br><br>뿔이 옷깃을 스치고 지나갔다. 바람이 사람을 미는 무게였다.<br><br>그것은 비탈 위까지 달려 올라가서야 멈췄다. 치울 것이 없어진 길을 한 번 둘러보고, 돌아서 내려갔다. 이쪽은 그동안 절벽 턱에서 발을 거두지 못했다.`,
      ng:`반 걸음이 컸다. 절벽 턱이 부서지며 다리가 빠졌다.<br><br>가슴으로 턱에 매달렸다. 아래는 안개다. 뿔 돋친 것의 발소리가 머리 위를 지나갔다.<br><br>동료들이 끌어올렸다. 갑옷 가슴판이 턱에 갈려 반질반질했다. 피하는 자리에도 바닥은 있어야 했다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-32, spirit:-15 } }
  ] },

{ at:'S2', t:'둥지 벌판 — 내리꽂히는 것들',
  x:`흙무더기 둥지들이 벌판 가득하다. 알 냄새가 비리다. 지나는 길은 둥지 사이뿐이다.<br><br>
    하늘에서 그림자가 돈다. 날개가 가죽인 것들. 셋, 넷.<br>
    둥지 벌판 위에서는 걷는 것이 다 알도둑이다. 저들 법으로는.<br><br>
    첫 그림자가 돌기를 멈추고 기울었다. 내리꽂히는 각이다.`,
  o:[
    { l:'① 방패를 지붕 삼아 일행 머리 위를 맡는다.', k:'steady', dc:24,
      ok:`방패를 머리 위 비스듬히 들고 일행을 처마 밑에 모았다. 한 덩어리로 걸었다.<br><br>첫째가 꽂혔다. 앞면에 발톱이 긁히며 튕겨 올랐다. 둘째는 더 낮게 왔다. 각을 틀어 받아 냈다.<br>셋째부터는 꽂히지 않고 돌기만 했다. 꽂힐 자리가 없는 먹이는 먹이가 아니다.<br><br>벌판 끝까지 그림자들이 따라왔다. 지붕은 끝까지 지붕이었다.`,
      ng:`둘째를 받을 때 각이 어긋났다. 발톱이 방패를 긁고 내려와 동료의 짐을 채 갔다.<br><br>짐이 공중에서 뜯겼다. 사흘치 먹을 것이 벌판에 흩어졌다.<br>주우러 갈 수 없다. 흩어진 자리가 다 둥지 사이다.<br><br>빈 등으로 벌판을 나왔다. 하늘의 것들이 흩어진 것을 주워 먹는 소리가 등 뒤에서 났다. 지붕이 짐까지는 못 덮었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 둥지 하나를 골라 그 그늘에 바싹 붙어 지난다.', k:'luck', dc:25,
      ok:`제일 큰 둥지의 그늘에 붙어 걸었다. 제 둥지 바로 곁은 저들도 함부로 꽂히지 못한다. 알이 다칠까 봐.<br><br>그림자들이 머리 위를 돌며 끓었지만 내려오지 못했다.<br>둥지 가장자리 물웅덩이에 손가락만 한 민물고기들이 갇혀 있었다. 알 지키는 것들이 물을 안 건드려 살이 올랐다. 몇 마리를 조용히 건졌다.<br><br>둥지 끝에서 벌판 끝까지는 뛰었다. 염치는 거기까지였다.`,
      ng:`그늘에 붙어 걷다 발이 둥지 자락을 밟았다. 흙이 조금 무너졌다.<br><br>하늘이 뒤집혔다. 도는 것들이 한꺼번에 울며 내리꽂혔다. 알을 건드린 것에게는 법이 없다.<br><br>방패를 이고 구르다시피 벌판을 벗어났다. 등판 갑옷이 발톱 자국으로 밭이 됐다. 둥지 그늘은 길이 아니라 외상이었다. 값은 발끝이 치렀다.`,
      win:{ exp:17, dream:2, item:'민물고기' }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S2', t:'낡은 엘리베이터 — 닫히는 창살',
  x:`정원 끝, 바위 벽에 낡은 엘리베이터가 있다. 창살문 달린 쇠 바구니. 위로 올라가는 유일한 길이다.<br><br>
    바구니는 다섯이 타면 꽉 찬다. 권양기가 녹슬어 올라가는 데 오래 걸릴 것이다.<br>
    벌판 쪽에서 발톱 긴 것들이 온다. 쇠 냄새와 사람 냄새를 한꺼번에 맡은 걸음이다.<br><br>
    창살문은 밖에서 밀면 열리는 문이다. 안에서 잡아 줘야 닫혀 있는다.`,
  o:[
    { l:'① 맨 마지막에 타며 창살문을 방패로 눌러 막는다.', k:'steady', dc:26,
      doom:{ title:'창살 너머의 발톱', what:'창살문째 뜯겨 바구니 밖으로 끌려갑니다', dc:20, sec:40,
        text:`넷을 태우고 마지막에 올라 창살문에 방패를 대고 눌렀다. 바구니가 삐걱대며 떠올랐다.<br><br>한 길도 못 올라가서 첫 놈이 뛰어올라 창살을 쥐었다. 둘째가 그 등을 밟고 더 높이 쥐었다.<br>창살문이 경첩째 뜯겼다. 문과 방패와 이쪽 팔이 한 묶음으로 바구니 밖에 매달렸다. 발톱이 발목을 쥐었다. 바구니는 올라가고 발목은 내려간다. 동료들 손이 어깨끈을 쥐는 게 느껴졌다. 끈이 운다.`,
        dieText:`바구니는 올라갔다. 창살문 없이. 넷을 태우고.<br><br>바닥 틈으로 내려다본 벌판에서 방패가 이리저리 끌려다니고 있었다. 그것들이 나눠 무는 중이었다.<br>방패는 끝내 부서지지 않았다. 부서지지 않는다는 게 그렇게 나쁜 일인 줄 그날 알았다.` },
      ok:`방패를 창살문 안쪽에 대고 몸무게로 눌렀다. 첫 놈이 뛰어올라 창살을 쥐고 흔들었다.<br><br>문이 아니라 방패가 받았다. 쇠와 쇠 사이에서 발톱이 미끄러졌다. 둘째가 매달리기 전에 바구니가 그놈들 뛰는 높이를 벗어났다.<br><br>아래에서 그것들이 바구니 그림자를 따라 돌았다. 돌다가 멈춰 서서 올려다봤다. 오래. 배웅이 아니라 배움의 눈이었다. 다음 바구니는 더 어려울 것이다.`,
      win:{ exp:23, dream:4 } },
    { l:'② 권양기 걸쇠를 손봐서 바구니를 빨리 올린다.', k:'fix', dc:24,
      ok:`권양기 걸쇠가 녹으로 반쯤 물려 있었다. 걸쇠를 젖히고 기름때를 긁어낸 뒤 추 줄을 고쳐 걸었다.<br><br>바구니가 두 배 속도로 올랐다. 첫 놈이 뛰어오른 높이보다 바구니 바닥이 먼저 높아졌다.<br><br>발톱이 허공을 긁는 소리를 들으며 올라갔다. 기계는 거짓말을 안 한다. 손봐 준 만큼 올려 준다.`,
      ng:`걸쇠를 너무 젖혔다. 바구니가 덜컥 반 길 떨어졌다가 멈췄다.<br><br>그 반 길이면 닿는다. 첫 놈 발톱이 바구니 바닥 창살에 걸렸다. 매달린 채 같이 올라간다.<br><br>창대로 발톱 마디를 내리쳐 떨어뜨렸다. 바구니가 흔들릴 때마다 추 줄이 벽을 쳤다. 다 올라와서 보니 바닥 창살 하나가 엿가락처럼 휘어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-14 } },
    { l:'③ 타는 순서를 정해 준다 — 다친 이부터, 방패는 맨 끝.', k:'bond', dc:24, wake:1,
      ok:`순서를 불렀다. 발목 다친 이, 짐 무거운 이, 창 든 이 둘, 맨 끝이 방패.<br><br>순서가 서자 서두름이 사라졌다. 서두름이 사라지자 바구니가 흔들리지 않았다.<br>맨 끝 자리는 춥다. 등 뒤가 다 벌판이다. 그래도 그 자리가 이쪽 자리다. 문을 등지는 사람이 정해져 있으면 나머지는 뛰지 않고 걷는다.<br><br>바구니가 떠오를 때 벌판을 봤다. 그것들이 막 벌판 어귀에 들어서고 있었다. 순서가 산 시간이었다. 맨 끝 자리가 어떤 자리인지, 거기 설 때마다 조금씩 더 알게 된다.`,
      ng:`순서를 부르는데 짐 무거운 이가 먼저 바구니에 뛰어올랐다. 바구니가 크게 기울었다.<br><br>추 줄이 벽에서 벗겨질 뻔했다. 고쳐 거는 데 스무 숨을 썼다. 벌판 어귀의 발소리가 그 스무 숨만큼 가까워졌다.<br><br>마지막에 오르는 이쪽 등을 발톱 바람이 스쳤다. 순서는 부르는 게 아니라 평소에 심어 두는 것이다. 급할 때 심으면 늦다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ hp:-27, spirit:-16 } }
  ] }

]);

// ── 생존가 (survivor) · 자원 없음
kJob('survivor', 'S', [

{ at:'S', t:'고인 물 — 세 번 묻는 법',
  x:`고인 물을 찾았다. 수통이 다 말랐으니 반가워야 하는데, 생존가는 물을 보면 먼저 묻는다.<br><br>
    둘레에 짐승 발자국이 있는가. 물속에 산 것이 있는가. 물가에 뼈가 있는가.<br>
    발자국이 없다. 벌레도 없다. 뼈는… 있다. 물가에 잔뼈가 반원으로 흩어져 있다.<br><br>
    목마른 동료들이 벌써 수통을 꺼내 들었다.`,
  o:[
    { l:'① 세 물음의 답을 맞춰 보고 마실지 정한다.', k:'steady', dc:24, wake:1,
      ok:`발자국 없음, 산 것 없음, 뼈 있음. 셋 다 같은 답이다. 이 물은 짐승도 안 마신다.<br><br>물가의 뼈는 마신 것들의 뼈다. 수통을 거두게 했다. 대신 물가에서 위로 거슬러 올랐다. 고이기 전의 물은 바위 틈에서 가늘게 흘렀다. 흐르는 물에 손가락을 담그고 한 식경 기다렸다. 저리지 않는다. 그 물을 받았다.<br><br>목마를수록 물음이 느는 것, 그게 이 일이다. 세 물음이 몸에 붙어 이제 물을 보면 묻기부터 한다. 목보다 먼저.`,
      ng:`물음까지는 맞게 했다. 거슬러 오르다 바위 이끼를 밟았다.<br><br>미끄러지며 고인 물에 한쪽 발이 빠졌다. 장화 속까지 젖었다. 발등이 금세 가렵더니 저녁엔 발목까지 부었다.<br><br>마시지도 않은 물에 당했다. 씻고 싸매고 하루를 절었다. 그 물은 닿는 것도 마시는 축이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 짐승 길을 되짚어 그것들이 마시는 물을 찾는다.', k:'sense', dc:24,
      ok:`물은 짐승에게 물으면 된다. 벌판 쪽 발자국들을 되짚었다. 여러 길이 한 줄로 모이는 곳, 거기 물이 있다.<br><br>바위 아래 맑은 샘이었다. 둘레 발자국이 어지럽지만 뼈는 없다. 다들 마시고 돌아간 물이다.<br><br>수통을 다 채우고 마른 고기 씹을 물까지 얻었다. 마시는 자리 곁에는 오래 머물지 않았다. 물가는 마시러 오는 것들의 길목이기도 하다.`,
      ng:`길을 되짚는데 발자국이 점점 커졌다. 모이는 자리는 샘이 아니라 진창이었다.<br><br>진창 가운데 큰 것의 발자국이 웅덩이가 돼 있었다. 그 웅덩이에 고인 물을 작은 것들이 마시러 왔다. 지금도 오는 중이었다.<br><br>덤불에 엎드려 반나절을 보냈다. 물은 결국 빗물받이 천막으로 모았다. 한나절 늦었고 반 통뿐이었다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ hp:-25, spirit:-15 } }
  ] },

{ at:'S', t:'밤 식사 — 겁이 먹는 양',
  x:`짐을 풀고 저녁을 나눈다. 남은 식량은 사흘치. 길은 얼마나 남았는지 모른다.<br><br>
    겁먹은 사람은 많이 먹는다. 입이 바쁘면 생각이 조용해지니까. 오늘 낮에 험한 걸 본 동료가 제 몫을 다 먹고 자루 쪽을 본다.<br>
    사흘치가 이틀치 되는 건 금방이다.<br><br>
    굶는 밤보다 나쁜 건 굶는 걸 아는 밤이다.`,
  o:[
    { l:'① 몫을 미리 갈라 보이는 곳에 걸어 둔다.', k:'steady', dc:23,
      ok:`자루를 풀어 여섯 끼로 갈랐다. 천에 하나씩 싸서 나뭇가지에 줄지어 걸었다. 다 보이게.<br><br>오늘 밤 몫, 내일 아침 몫. 눈에 보이는 끝은 겁을 줄인다. 끝없는 자루가 겁을 키운다.<br>자루 쪽을 보던 동료가 걸린 꾸러미들을 세어 보더니 제 침낭으로 갔다.<br><br>배곯는 셈이 서면 사람은 견딘다. 안 서는 셈이 사람을 먹는다.`,
      ng:`갈라 걸었는데 밤에 꾸러미 하나가 사라졌다. 사람 소행이 아니다. 가지가 할퀴어져 있다.<br><br>걸어 둔 게 광고가 됐다. 밤새 작은 것들이 캠프 둘레를 돌았다. 남은 꾸러미를 도로 품에 안고 자야 했다.<br><br>보이게 거는 건 사람에게만 통하는 수였다. 여기선 냄새가 눈보다 멀리 간다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-15, spirit:-15 } },
    { l:'② 많이 먹는 동료에게 내일 몫을 맡긴다.', k:'bond', dc:24,
      ok:`그 동료에게 내일치 자루를 통째 맡겼다. 네가 제일 튼튼하니 짊어지라고.<br><br>맡은 사람은 축내지 않는다. 지키는 쪽이 되면 입이 아니라 눈이 바빠진다.<br>밤새 자루를 끌어안고 잤다. 아침에 그대로였다. 본인 얼굴이 제일 개운했다.<br><br>겁은 뺏는다고 안 없어진다. 일을 주면 자리를 비킨다.`,
      ng:`맡겼더니 밤에 자루를 열어 세고 또 셌다. 세는 소리에 다른 동료가 깼다. 훔치는 줄 안 것이다.<br><br>말다툼이 났다. 어두운 데서 언성이 높아지는 것만큼 나쁜 게 없다. 바깥 어둠이 조용해졌다. 듣는 조용함이었다.<br><br>둘을 떼어 앉히고 자루는 도로 이쪽이 맸다. 밤은 짧아졌고 화해는 아침에야 왔다.`,
      win:{ exp:16, dream:2, spirit:5 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 제 몫에서 반을 덜어 그 동료에게 준다.', k:'heal', dc:23,
      ok:`제 몫 반을 덜어 건넸다. 배고파 보여서라고만 했다.<br><br>동료가 받아 들고 한참 있다가 반의 반을 도로 줬다. 배부르면 잠이 안 온다고.<br>그 말이 거짓인 걸 둘 다 알았다. 그래도 그 거짓말로 저녁이 따뜻해졌다.<br><br>생존은 셈이지만, 셈이 전부면 못 버틴다. 가끔은 셈을 져 주는 것도 수다.`,
      ng:`반을 덜어 주는 걸 다른 동료가 봤다. 왜 쟤만 주냐는 눈이 됐다.<br><br>몫의 셈이 흐트러지면 다 흐트러진다. 결국 제 몫을 넷으로 갈라 다 돌렸다. 이쪽 저녁은 물로 때웠다.<br><br>밤에 배에서 소리가 났다. 어둠 속에서 그 소리가 유난히 컸다. 선심은 셈 안에서 써야 선심이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S', t:'어스름 — 불을 못 피우는 밤',
  x:`해가 진다. 춥다. 젖은 사람도 있다. 불을 피우고 싶은 밤이다.<br><br>
    낮에 본 발자국들이 문제다. 눈보다 코가 밝은 것들. 연기는 십 리를 간다.<br>
    불 없는 밤은 춥고 길다. 불 있는 밤은 따뜻하고, 어쩌면 짧다. 영영.<br><br>
    동료들이 이쪽 입을 본다. 불 피울지 말지는 생존가가 정하는 일이다.`,
  o:[
    { l:'① 불 대신 몸을 포개고 마른 풀을 두른다.', k:'steady', dc:24, wake:1,
      ok:`불은 없다고 선언했다. 대신 바람 그늘 바위 밑에 마른 풀을 두껍게 깔고 다섯이 등을 포갰다.<br><br>겉옷을 제일 젖은 사람 쪽으로 몰았다. 체온은 돌려 쓰는 불이다.<br>밤중에 코 밝은 것들이 둘레를 지나갔다. 연기도 불빛도 없는 캠프를 두 번 지나치고 못 찾았다. 쌔근대는 숨소리 위로 발소리가 지나가는 동안 모두 깨 있었다. 아무도 떨지 않았다. 춥지 않아서가 아니라 셈이 서 있어서.<br><br>불을 끄는 결정이 불을 피우는 결정보다 어렵다. 그 어려운 쪽을 고르는 게 버릇이 됐다.`,
      ng:`풀이 모자랐다. 새벽에 젖은 동료 이가 딱딱 부딪쳤다.<br><br>그 소리가 어둠 속에서 또렷했다. 둘레를 돌던 것이 소리에 멈췄다. 한참을 서 있다 갔다.<br><br>아침에 동료 입술이 파랬다. 몸을 주무르고 마른 고기를 씹였다. 추위도 짐승만큼 문다. 양쪽을 다 셈에 넣었어야 했다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 불을 피우되 바위 틈에 숯불만 묻는다.', k:'fix', dc:24,
      ok:`불꽃은 안 된다. 숯은 된다. 바위 틈에 구덩이를 파고 마른 가지를 태워 숯만 남긴 뒤 돌판을 덮었다.<br><br>연기는 바위 틈으로 가늘게 빠져 흩어졌다. 돌판이 데워지자 그 위에 젖은 옷을 널고 발을 올렸다.<br><br>불빛 한 점 없는 온기였다. 밤새 돌이 식지 않았다. 불은 꼭 보여야 따뜻한 게 아니다.`,
      ng:`숯을 묻다가 덜 마른 가지가 섞였다. 흰 연기가 한 줄 올랐다.<br><br>바로 껐지만 한 줄이면 족했다. 밤중에 코 고는 소리 같은 숨이 캠프 가장자리까지 왔다.<br><br>다들 무기를 쥔 채 엎드려 새벽을 기다렸다. 그것은 식은 숯 구덩이를 파헤쳐 보고 갔다. 연기 한 줄 값으로 잠을 다 냈다.`,
      win:{ exp:17, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'짐승 길 — 너무 좋은 길',
  x:`수풀에 길이 나 있다. 넓고 평탄하고 가시도 없다. 가려는 방향으로 곧게 뻗었다.<br><br>
    생존가는 좋은 길을 의심한다. 길은 누가 내는 것이다. 이 수풀에서 길을 낼 만한 것들을 떠올리면 답이 안 좋다.<br>
    길섶 나뭇가지가 어깨 높이에서 다 꺾여 있다. 이쪽 어깨보다 높은 어깨가 지나다닌다는 뜻이다.<br><br>
    돌아가는 덤불길은 한나절이 더 걸린다.`,
  o:[
    { l:'① 좋은 길로 간다 — 빨리 끝내면 된다.', k:'evade', dc:25,
      doom:{ title:'길의 임자', what:'길목에서 기다리던 것에 수풀 속으로 끌려갑니다', dc:19, sec:45,
        text:`길은 과연 빨랐다. 반나절 거리를 한 식경에 질렀다.<br><br>길이 꺾이는 목에서 그것이 기다리고 있었다. 길 임자는 제 길의 목을 안다. 지나다니는 것들이 어디서 한눈을 파는지도.<br>덮친 것은 소리도 없었다. 뒷덜미 옷깃째 물려 수풀로 끌려 들어간다. 수풀 바닥에 뼈가 많았다. 다 이 길로 다니던 것들이다. 길은 임자의 밥상으로 나 있었다.`,
        dieText:`길섶 수풀에서 배낭이 나왔다. 어깨끈이 이빨 모양으로 끊겨 있다.<br><br>배낭 속 꾸러미들은 그대로였다. 그것이 원한 건 꾸러미가 아니었다.<br>일행은 그 좋은 길을 버리고 가시덤불로 들어갔다. 한나절이 아니라 하루가 걸렸다. 아무도 불평하지 않았다.` },
      ok:`길로 가되 길처럼 안 갔다. 길섶에 바싹 붙어, 꺾이는 목마다 멈춰 귀를 줬다.<br><br>세 번째 목에서 숨소리가 났다. 길 가운데로 갔으면 코앞이었을 자리다. 수풀로 꺾어 목 하나를 통째 돌아 다시 길에 붙었다.<br><br>빠른 길의 값은 목마다 치르는 경계였다. 치를 수 있는 값이었다. 한나절을 벌었다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 덤불로 돌아간다 — 느린 길이 내 길이다.', k:'steady', dc:24,
      ok:`좋은 길에 등을 돌렸다. 동료들이 아쉬운 눈을 했지만 길게 설명하지 않았다. 어깨 높이 꺾인 가지만 보여 줬다.<br><br>덤불을 손도끼로 열며 갔다. 느리지만 이 길의 임자는 이쪽이다.<br>해 질 녘에 그 좋은 길과 덤불길이 다시 만나는 자리를 지났다. 좋은 길 쪽 흙에 끌린 자국과 어두운 얼룩이 길게 나 있었다. 누가 치른 값인지는 알 수 없었다.<br><br>아무도 더는 아쉬운 눈을 하지 않았다.`,
      ng:`덤불이 셈보다 깊었다. 한나절이 아니라 하루 거리다. 해가 덤불 속에서 졌다.<br><br>어둠 속 가시밭은 낮의 배는 느리다. 다들 팔다리가 긁혀 너덜해졌다.<br>밤중에야 겨우 바위 그늘을 찾아 쓰러졌다.<br><br>느린 길도 길이는 재고 들어가야 했다. 의심만으로는 반쪽 생존가다. 셈이 마저 있어야 한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'한밤 — 숨 세는 당번',
  x:`불침번을 선다. 생존가의 불침번은 어둠을 보는 게 아니다. 숨을 센다.<br><br>
    다섯 숨. 넷은 자고 하나는 깨 있는 숨. 그게 정상이다.<br>
    방금, 숨이 여섯이 됐다.<br><br>
    늘어난 하나는 아주 느리다. 자는 숨보다도 느리다. 캠프 가장자리, 침낭들 발치 쪽에서.`,
  o:[
    { l:'① 숨 하나하나에 이름을 붙여 늘어난 것을 가려낸다.', k:'steady', dc:25, wake:1,
      ok:`눈 감고 셌다. 코 고는 숨은 창잡이. 얕고 빠른 숨은 막내. 하나씩 이름을 붙이니 임자 없는 숨이 남는다.<br><br>발치 쪽, 바위 그늘. 임자 없는 숨에 맞춰 이쪽 숨을 바꿨다. 자는 숨으로. 그 숨이 조금 가까워졌다. 자는 줄 아는 것이다.<br>손 닿는 데 둔 돌을 그쪽으로 던지고 동시에 불씨를 걷어 불꽃을 올렸다. 그늘에서 긴 것이 튀어 물러났다. 다들 깼고, 그것은 불빛 밖에서 한참 서성이다 갔다.<br><br>숨에 이름을 붙이는 버릇이 생겼다. 머릿수는 눈으로만 세는 게 아니다.`,
      ng:`세는 사이 여섯째 숨이 사라졌다. 숨을 참은 것이다. 저쪽이 더 잘 참았다.<br><br>어디 있는지 모르는 채로 새벽까지 버텼다. 제일 긴 밤이었다.<br>동틀 녘 발치 바위에 긴 것이 웅크렸던 자국만 남아 있었다. 침낭 발치에서 두 걸음이었다.<br><br>막내 침낭 끝이 젖어 있었다. 코를 댄 자국이라고, 아무도 소리 내어 말하지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 소리 없이 동료들을 깨워 등을 맞댄다.', k:'bond', dc:24,
      ok:`옆 동료 발바닥을 꾹 눌렀다. 깨우는 신호다. 깬 동료가 다음 동료를 눌렀다.<br><br>다섯이 소리 없이 등을 맞대고 둥글게 앉았다. 눈 다섯 쌍이 다섯 방향을 본다.<br>여섯째 숨이 멀어졌다. 둥글게 깬 무리는 발치가 없다. 발치가 없으면 저것들은 셈을 못 한다.<br><br>그대로 등을 맞댄 채 번갈아 졸며 아침을 맞았다. 등이 따뜻하면 어둠도 견딜 만하다.`,
      ng:`발바닥을 눌렀는데 동료가 잠결에 소리를 질렀다. 누구냐고.<br><br>캠프가 뒤집어졌다. 여섯째 숨은 그 북새통에 사라졌다.<br>사라진 건 숨만이 아니었다. 발치에 뒀던 수통 두 개가 없어졌다. 물이 든 쪽으로만.<br><br>물 냄새를 아는 것이다. 다음부터 수통은 품에 안고 자기로 했다. 깨우는 신호도 다시 정했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'③ 늘어난 숨 쪽으로 마른 고기 한 점을 던져 본다.', k:'luck', dc:25,
      ok:`마른 고기 한 점을 그 숨 쪽에 던졌다. 씹는 소리가 났다. 긴 침묵.<br><br>그리고 숨이 멀어졌다. 먹을 걸 주는 것과는 안 싸운다는 셈인지, 간만 보고 간 것인지.<br>바위 그늘에 가 보니 고기는 없고 대신 그 자리에 반질한 돌멩이가 하나 놓여 있었다.<br><br>바꿔 간 것이다. 셈을 아는 짐승이다. 돌멩이는 주머니에 넣었다. 왠지 버리면 안 될 것 같았다.`,
      ng:`고기를 던지자 숨이 빨라졌다. 하나가 아니라 셋으로.<br><br>먹이를 던지는 캠프는 먹이가 나오는 캠프다. 밤새 셋이 둘레를 돌며 보챘다. 돌 던지고 불씨 올리고를 새벽까지 했다.<br><br>아침에 보니 던진 고기는 그대로 있었다. 고기가 아니라 던지는 손을 기다린 것이다. 먹이 주는 손부터 무는 게 저들 법이다.`,
      win:{ exp:17, dream:3 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S', t:'달음박질 — 버릴 것의 순서',
  x:`쫓긴다. 뒤에서 수풀 넘어지는 소리가 가까워진다. 짐을 지고는 못 벗어난다.<br><br>
    생존가는 달리면서 셈한다. 버릴 것의 순서는 정해져 있다. 무겁고 안 급한 것부터. 천막, 모탕, 여벌 옷.<br>
    물과 불씨와 칼은 맨 끝이다. 그건 버리면 쫓기다 살아도 죽는다.<br><br>
    등 뒤 소리가 수풀을 다 넘었다.`,
  o:[
    { l:'① 달리며 끈을 끊어 순서대로 흘린다.', k:'steady', dc:24, wake:1,
      ok:`허리칼로 천막 끈부터 끊었다. 털썩. 다음 모탕. 여벌 옷 꾸러미.<br><br>하나 흘릴 때마다 등이 가벼워지고, 뒤의 소리가 한 번씩 멈칫했다. 떨어진 것마다 냄새를 보는 것이다.<br>물과 불씨와 칼만 남았을 때 걸음이 바람이 됐다. 바위 비탈을 치고 올라 소리를 뗐다.<br><br>버리는 순서가 손에 붙어 있으면 달리면서도 셈이 안 흔들린다. 짐을 쌀 때부터 버릴 순서로 싸는 것, 그게 이 일의 속이다.`,
      ng:`급한 손이 순서를 어겼다. 끊은 게 물주머니 끈이었다.<br><br>등이 가벼워진 값으로 물이 수풀에 쏟아졌다. 소리는 뗐는데 물이 없다.<br><br>이틀을 이슬 핥고 풀뿌리 씹으며 걸었다. 혀가 입천장에 붙었다. 버리는 순서는 손이 외워야 한다. 머리는 달릴 때 못 믿는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 짐을 통째 벗어 던지고 나무 위로 오른다.', k:'evade', dc:25,
      ok:`짐을 통째 던지고 제일 가까운 굵은 나무를 탔다. 동료들도 따라 올랐다.<br><br>쫓던 것이 짐에 코를 박았다. 뒤지고, 찢고, 흩었다. 그동안 나무 위에서 숨을 골랐다.<br>그것은 나무 밑을 세 바퀴 돌고 갔다. 오르는 법을 모르는 몸이었다. 운이 좋았다.<br><br>내려와 흩어진 짐을 주웠다. 반은 못 쓰게 됐지만 목숨 값으로는 쌌다.`,
      ng:`나무를 탔는데 그것도 탔다. 반쯤은. 앞발이 둥치를 긁으며 올라왔다.<br><br>제일 낮게 매달린 동료의 장화 뒤축을 발톱이 벗겨 갔다. 다들 더 위로, 가지가 휘는 데까지 몰렸다.<br><br>그것은 밤이 깊어서야 갔다. 새벽까지 아무도 안 내려왔다. 가지에 묶은 허리끈 자국이 손바닥에 밤새 박혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'갈림길 — 옮겨진 표시',
  x:`갈림길마다 돌 세 개를 포개 표시를 해 뒀다. 돌아올 때 길을 잃지 않으려고.<br><br>
    지금 그 표시가 이상하다. 돌 세 개가 포개져 있긴 한데, 아까와 다른 쪽 길 어귀에 있다.<br>
    바람이 옮길 수 있는 물건이 아니다.<br><br>
    누가 표시를 읽었고, 옮겼다. 옮긴 쪽 길은 이쪽이 가려던 길이 아니다.`,
  o:[
    { l:'① 표시를 겉과 속 두 겹으로 바꾼다.', k:'steady', dc:25, wake:1,
      ok:`돌 포개기는 이제 미끼다. 눈에 띄는 표시는 옮기라고 두고, 진짜 표시는 따로 숨겼다.<br><br>길 어귀 셋째 나무, 어깨 높이 껍질 안쪽에 손톱 금 하나. 보려는 눈에만 보이는 표시다.<br>다음 갈림길에서 돌 포개기는 또 옮겨져 있었다. 나무 금은 그대로였다. 옮긴 그것은 돌만 알지 나무는 모른다.<br><br>표시는 남 읽으라고 하는 게 아니다. 나만 읽자고 하는 것이다. 그 생각이 서자 길 잃을 걱정이 줄었다. 거짓 표시가 되레 그것의 자리를 알려 준다. 돌이 옮겨진 길목마다 그것이 다녀간 것이니까.`,
      ng:`나무 금을 새기는데 등 뒤 수풀이 흔들렸다. 보고 있는 것이다. 숨기는 것까지.<br><br>자리를 옮겨 다시 숨겼다. 또 흔들렸다. 어디 숨기든 보는 눈이 있으면 소용없다.<br><br>결국 표시 없이 가기로 했다. 걸음 수와 해 방향을 입으로 외며 걸었다. 머리가 지도가 되는 수밖에 없었다. 밤이 되자 왼 숫자들이 헷갈리기 시작했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 옮겨진 쪽 길을 조금만 들어가 본다.', k:'sense', dc:25,
      ok:`옮겨진 표시가 가리키는 길을 스무 걸음만 들어갔다. 알고 싶었다. 뭐가 기다리는지.<br><br>스무 걸음 끝에 비탈이 꺼진 함정 지형이 있었다. 미끄러지면 못 올라오는 흙벽 구덩이. 바닥에 뼈가 보였다.<br>돌을 옮긴 것은 길을 아는 것이다. 사람 표시의 뜻도 안다.<br><br>스무 걸음을 되짚어 나왔다. 등 뒤 어딘가에서 기다리다 허탕 친 숨이 길게 났다.`,
      ng:`스무 걸음이 서른 걸음이 됐다. 알고 싶은 게 사람을 끈다.<br><br>흙이 꺼졌다. 비탈을 반쯤 미끄러지다 나무뿌리를 쥐고 멈췄다. 구덩이 바닥에서 비린 바람이 올라왔다.<br><br>동료들이 허리끈을 이어 내려 줬다. 올라와 보니 손바닥이 다 까져 있었다. 알고 싶은 값으로는 과했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'부러진 발목 — 업을 것인가 멈출 것인가',
  x:`동료가 발목을 접질렸다. 붓는 속도를 보니 금 갔을 수도 있다. 걷게 하면 못 쓰게 된다.<br><br>
    업으면 걸음이 반으로 준다. 쫓기는 몸으로 반걸음은 큰 셈이다.<br>
    여기 멈춰 하루 쉬면 발목은 낫는 쪽으로 간다. 대신 하루치 식량과, 하루치 어둠을 더 쓴다.<br><br>
    동료는 버리고 가라는 말을 벌써 두 번 했다. 생존가 앞에서 할 말이 아니다.`,
  o:[
    { l:'① 부목을 대고 하루 묵을 자리를 판다.', k:'steady', dc:24,
      ok:`버리는 셈은 셈에 없다고 한 번만 말했다. 곧은 가지 둘에 천을 감아 부목을 대고, 바위 틈에 하루 숨을 자리를 골랐다.<br><br>입구 좁고 안 넓은 틈. 물이 가깝고 바람이 등진 자리. 하루를 꼬박 쉬었다.<br>발목 부기가 반으로 내렸다. 하루치 식량은 썼지만 걸음을 되샀다.<br><br>이튿날 그 동료가 제일 앞서 걸었다. 미안해서 내는 속도였다. 그 속도가 하루치를 도로 벌었다.`,
      ng:`자리는 좋았는데 밤에 비가 들이쳤다. 바위 틈이 물길이 되는 자리였다.<br><br>한밤에 짐을 안고 틈을 빠져나와 비를 그대로 맞았다. 부목이 젖어 늘어졌다.<br><br>아침에 부목을 다시 댔다. 발목은 낫는 쪽이지만 다들 한기가 들었다. 자리는 하늘까지 셈해서 골라야 했다.`,
      win:{ exp:20, dream:2, hp:6 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 번갈아 업고 간다 — 멈추는 쪽이 더 위험한 땅이다.', k:'bond', dc:24,
      ok:`여기는 묵을 땅이 아니다. 낮에 본 발자국이 너무 많았다. 업는 순서를 짰다. 백 걸음씩, 넷이 돌아가며.<br><br>업힌 동료는 뒤를 보는 눈이 됐다. 등 뒤 경계는 업힌 사람이 제일 잘한다.<br>반걸음 속도로도 해 지기 전에 바위 지대에 닿았다. 발자국 없는 땅이다.<br><br>업은 등마다 땀이 뱄지만 아무도 셈을 입에 올리지 않았다. 사람을 업는 셈은 소리 내어 하는 게 아니다.`,
      ng:`세 번째 교대에서 업은 동료가 돌부리에 걸렸다. 둘이 같이 굴렀다.<br><br>접질린 발목이 땅에 찍혔다. 비명이 골짜기에 울렸다. 멀리서 대답 같은 울음소리가 왔다.<br><br>남은 길을 거의 뛰다시피 했다. 바위 지대에 닿았을 때 발목은 처음보다 배로 부어 있었다. 업는 길도 길은 골라 가며 업어야 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, spirit:-16 } }
  ] },

{ at:'S', t:'능선 — 바람의 아래위',
  x:`능선을 넘어야 한다. 넘는 길은 둘. 바람 위쪽 안부와 바람 아래쪽 벼랑길.<br><br>
    골짜기 건너에 그것들의 둥지 터가 보인다. 코로 사는 것들의 터.<br>
    바람 위로 가면 이쪽 냄새가 둥지로 곧장 흘러든다. 길은 좋다.<br>
    바람 아래로 가면 냄새는 등 뒤로 빠진다. 대신 벼랑길이다.<br><br>
    생존가의 길 고르기엔 코도 들어간다. 제 코가 아니라 남의 코가.`,
  o:[
    { l:'① 바람 아래 벼랑길로 간다.', k:'steady', dc:25,
      ok:`벼랑길을 골랐다. 한 사람 폭, 아래는 안개. 허리끈을 이어 묶고 바위에 손자국 나게 쥐며 건넜다.<br><br>바람이 등 뒤에서 냄새를 걷어 갔다. 둥지 터의 것들은 코를 들지 않았다.<br>제일 좁은 목에서 막내 발이 반쯤 미끄러졌지만 이은 끈이 잡았다.<br><br>능선을 넘고 보니 손바닥이 하얬다. 쥐는 힘으로 건넌 길이다. 코에게 들키는 것보다 손이 아픈 쪽이 싸다.`,
      ng:`벼랑 중간에서 바람이 뒤집혔다. 골바람은 한나절에 한 번 방향을 바꾼다. 그 셈을 빼먹었다.<br><br>냄새가 둥지 쪽으로 쏟아졌다. 골짜기 건너에서 울음이 올라오고, 벼랑 끝까지 마중 나온 그림자들이 보였다.<br><br>벼랑길 남은 반을 경주하듯 건넜다. 건너고 나서 보니 무릎이 다 까져 있었다. 바람도 시간표가 있다. 외웠어야 했다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 바람 위 안부로 가되 냄새를 지우고 간다.', k:'hide', dc:25,
      doom:{ title:'코 밝은 마중', what:'능선 안부에서 둥지의 것들에게 끌려갑니다', dc:19, sec:45,
        text:`진흙을 몸에 바르고 쑥 풀을 비벼 옷에 문질렀다. 사람 냄새 위에 땅 냄새를 덮은 것이다.<br><br>안부 중간까지는 통했다. 중간에서 땀이 났다. 땀은 안에서 나는 냄새다. 덮은 냄새가 안 덮인다.<br>안부 양쪽에서 그것들이 올라왔다. 마중 나온 걸음이었다. 제일 뒤에 섰던 이쪽이 제일 먼저 잡혔다. 발목을 물려 질질, 둥지 터 쪽 비탈로 끌려 내려간다. 바람이 위에서 동료들의 고함을 실어 왔다. 바람 위라서, 소리만은 잘 들렸다.`,
        dieText:`둥지 터에서 밤새 울음소리가 났다. 잔치 소리 같기도 했다.<br><br>이튿날 바람 아래 벼랑길로 돌아간 일행이 능선 너머에서 배낭을 찾았다. 진흙과 쑥 냄새가 아직 남아 있었다.<br>그 냄새 위에 다른 냄새가 덮여 있었다. 아무도 그 냄새의 이름을 입에 올리지 않았다.` },
      ok:`진흙과 쑥으로 냄새를 덮고, 거기서 멈추지 않았다. 안부를 건너는 시간을 골랐다. 한낮, 그것들이 그늘에 늘어지는 시간.<br><br>바람 위로 냄새가 흘러도 코가 쉬는 시간이면 늦게 닿는다.<br>안부를 다 건널 때까지 둥지 터는 조용했다. 건너고 반 식경 뒤에야 울음이 났다. 늦은 울음이었다.<br><br>냄새는 못 없앤다. 닿는 시간을 늦출 뿐이다. 그 시간 안에 지나가면 된다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'풀숲의 식탁 — 남이 잡은 것',
  x:`풀숲에 큰 짐승이 쓰러져 있다. 반쯤 먹혔다. 아직 김이 난다.<br><br>
    생존가에게 이건 식량이다. 동시에 경고판이다. 잡은 임자가 있고, 임자는 멀리 안 간다.<br>
    남은 살은 이틀치는 된다. 굶주린 배가 셈을 재촉한다.<br><br>
    물린 자국의 폭을 봤다. 이쪽 손 두 뼘이다.`,
  o:[
    { l:'① 임자가 돌아올 때까지의 틈을 재고 그 안에만 벤다.', k:'steady', dc:25,
      ok:`물린 자국에 고인 피가 아직 흐른다. 떠난 지 얼마 안 됐다. 배부른 임자는 물가로 간다. 제일 가까운 물까지 왕복이면 반 식경.<br><br>반 식경만 쓰기로 했다. 칼 둘이 뒷다리 살만 발랐다. 욕심은 등심까지라고 했지만 자르는 결이 시간을 넘긴다.<br>반 식경 끝에 미련 없이 물러났다. 수풀에 숨어 보니 임자가 돌아와 제 사냥감을 살폈다. 뒷다리 빈 자리를 오래 봤지만, 쫓을 냄새는 벌써 바람 아래로 뺐다.<br><br>남의 식탁에서는 시간을 먼저 베는 것이다. 고기는 그다음이다.`,
      ng:`살을 바르는 손이 반 식경을 넘겼다. 조금만 더, 가 길었다.<br><br>풀숲 너머에서 숨이 들렸다. 돌아온 것이다. 고기를 안은 채 넷이 흩어져 기었다.<br>임자는 제 사냥감 곁에서 오래 으르렁댔다. 도둑의 냄새를 외우는 소리였다.<br><br>그날 밤 캠프 둘레를 그 숨이 한 바퀴 돌고 갔다. 고기는 얻었지만 빚으로 얻었다. 갚는 날이 안 오길 빌 뿐이다.`,
      win:{ exp:21, dream:3, item:'짐승 고기' }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 발자국과 뜯긴 결로 임자의 정체부터 읽는다.', k:'gaze', dc:24,
      ok:`발자국은 세 발가락, 뒤꿈치 깊다. 무게가 뒤에 실리는 몸. 뜯긴 결은 아래서 위로, 혀가 아니라 이빨로만 먹는 입.<br><br>그림이 그려졌다. 목 긴 것들 중 혼자 다니는 큰 놈. 혼자면 제 몫을 지키러 꼭 돌아온다. 곧.<br>살 바르기를 관두고 자리를 떴다. 대신 임자가 안 먹는 부위만 챙겼다. 골수 든 정강이뼈 둘.<br><br>읽고 나니 욕심이 저절로 줄었다. 아는 만큼만 가져가는 것, 그게 남의 식탁 예절이다.`,
      ng:`읽는 데 시간을 썼다. 발자국, 뜯긴 결, 부러진 풀대. 다 읽었을 때 등 뒤 풀이 눕는 소리가 났다.<br><br>읽은 그대로의 것이 서 있었다. 읽기만 하고 뜨는 셈은 안 했던 것이다.<br><br>고기도 뼈도 없이 내뺐다. 넷이 네 방향으로 흩어졌다 바위에서 다시 모였다. 하나가 신발 한 짝을 잃었다. 읽기는 걸으면서도 된다. 서서 읽은 게 잘못이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } },
    { l:'③ 욕심껏 다 바른다 — 이런 횡재는 다시 없다.', k:'luck', dc:26,
      doom:{ title:'식탁의 임자', what:'사냥감 임자에게 물려 풀숲으로 끌려갑니다', dc:20, sec:40,
        text:`이틀치가 아니라 나흘치다. 칼 셋이 달라붙어 바르고 싸고 날랐다.<br><br>마지막 꾸러미를 묶을 때 풀숲이 통째로 일어섰다. 임자는 돌아온 게 아니었다. 안 떠났던 것이다. 그늘에서 제 식탁에 꼬이는 것들을 보고 있었다.<br>제일 많이 진 이쪽이 제일 느렸다. 어깨째 물렸다. 끌려가며 꾸러미들이 하나씩 떨어졌다. 그걸 세는 저 자신이 끝까지 생존가라서, 웃음이 났다.`,
        dieText:`꾸러미들은 사냥감 곁에 가지런히 놓여 있었다. 임자는 고기를 되찾고 도둑만 데려갔다.<br><br>일행은 꾸러미에 손대지 않았다. 그 식탁의 법을 이제 알았으니까.<br>빈손으로 물러나는 등 뒤에서, 풀숲이 오래 조용했다. 배부른 조용함이었다.` },
      ok:`나흘치 욕심을 부리되 머리는 차게 뒀다. 한 사람은 바르고 한 사람은 싸고 둘은 사방 풀숲만 봤다.<br><br>마지막 꾸러미까지 묶고 떴다. 떠나며 사냥감 배 속에 돌을 채워 뒀다. 무게가 그대로면 임자의 셈이 늦게 선다.<br><br>그날 저녁 넷이 고기를 구웠다. 불침번은 배로 세웠다. 횡재한 날일수록 밤이 길다는 걸 다들 알고 있었다.`,
      win:{ exp:19, dream:3, item:'짐승 고기' } }
  ] },

{ at:'S', t:'막다른 골 — 세 번째 출구',
  x:`골짜기가 막혔다. 들어온 입구는 하나, 나갈 데가 없다. 그리고 입구 쪽에서 그것들의 소리가 들어온다.<br><br>
    생존가의 철칙은 출구 둘이다. 들어올 때 세어 둔 둘째 출구는 벼랑 중턱의 바위 턱이었다.<br>
    지금 보니 그 턱은 비에 젖어 미끄럽다. 못 쓴다.<br><br>
    철칙이 깨졌으면 셋째를 만들 차례다.`,
  o:[
    { l:'① 골짜기를 다시 읽는다 — 물이 나간 길이 있을 것이다.', k:'steady', dc:25, wake:1,
      ok:`막힌 골짜기는 없다. 물이 드나든 흔적이 있으면 길이 있다. 바닥의 자갈 결을 읽었다. 자갈이 굵어지는 쪽, 막힌 벽 왼쪽 아래.<br><br>덤불을 걷어 내니 물이 뚫은 배수굴이 있다. 사람 하나 길 폭. 들어가 보니 스무 걸음 만에 골 바깥 개울로 났다.<br>하나씩 내보내고 마지막에 덤불을 도로 세워 입을 가렸다.<br><br>출구는 세는 게 아니라 읽는 것이다. 땅은 어디든 드나든 자국이 있다. 그 자국이 보이기 시작하면 막다른 데가 없어진다.`,
      ng:`자갈 결을 읽고 덤불을 걷었다. 배수굴은 있었다. 반쯤 무너진 채.<br><br>기어 들어간 막내가 중간에 끼었다. 어깨가 걸려 오도 가도 못한다. 입구 쪽 소리는 점점 들어온다.<br>겉옷을 벗기고 흙을 파서 겨우 뽑았다.<br><br>전원이 빠져나갔을 때 입구 쪽에서 그것들이 골 안으로 드는 소리가 났다. 반 식경만 늦었어도. 그 반 식경이 어깨 폭 하나였다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 바위 턱으로 간다 — 젖은 길도 길이다.', k:'evade', dc:26,
      ok:`젖은 턱을 그냥은 못 쓴다. 쓸 수 있게 만들었다. 겉옷을 찢어 발에 감았다. 젖은 바위에는 맨 가죽보다 천이 문다.<br><br>허리끈을 이어 위에서 당겨 주며 하나씩 올렸다. 마지막 이쪽 차례엔 당겨 줄 사람이 다 위에 있었다.<br>끈 하나에 매달려 턱을 넘는데 입구 쪽 그림자들이 골 안으로 들어서는 게 보였다.<br><br>턱 위에서 내려다보니 그것들이 빈 골짜기를 뒤지고 있었다. 길은 만들면 생긴다. 천 쪼가리 하나로도.`,
      ng:`천을 감아도 미끄러운 건 미끄러웠다. 셋째로 오르던 동료가 반쯤에서 흘러내렸다.<br><br>받아 내다 둘이 같이 바닥에 굴렀다. 허리끈이 바위 모서리에 쓸려 반이 끊어졌다.<br><br>남은 반 끈으로 다시 올렸다. 다 오르고 나니 손바닥들이 끈 자국으로 벌겋다. 입구의 소리는 코앞까지 와 있었다. 어떤 셈이든 두 번은 안 통하는 날이 있다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-32, spirit:-15 } }
  ] },

{ at:'S1', t:'보급 창고 — 뜯긴 상자와 성한 상자',
  x:`보급 창고다. 상자가 선반 가득하다. 생존가에게는 금광이고, 금광은 늘 임자가 있다.<br><br>
    상자 반은 뜯겼다. 밖에서 뜯긴 게 아니다. 못이 바깥으로 휘었다. 안에서 밀어 연 것이다.<br>
    식량 상자에 밖에서 들어갈 것은 쥐새끼뿐인데, 쥐는 못을 못 민다.<br><br>
    성한 상자들이 안쪽 선반에 줄지어 있다.`,
  o:[
    { l:'① 봉인 밀랍이 성한 것만 골라 소리 없이 내린다.', k:'steady', dc:24,
      ok:`상자마다 봉인 밀랍부터 봤다. 금 간 밀랍은 지나치고 성한 것만 셋 골랐다.<br><br>내릴 때 선반이 울지 않게 둘이 받치고 하나가 당겼다. 열어 보니 기름종이에 싼 마른 고기가 켜켜이 들었다.<br>뜯긴 상자들은 들여다보지도 않았다. 안에서 민 것이 어디로 갔는지 모르는 동안은, 빈 상자도 덫이다.<br><br>창고를 나올 때까지 발소리를 죽였다. 금광에서는 곡괭이 소리가 제일 위험하다.`,
      ng:`셋째 상자를 내리다 모서리가 선반을 쳤다. 쇠 선반이 종처럼 울렸다.<br><br>창고 안쪽 어둠에서 상자 무너지는 소리가 대답했다. 쌓인 상자 뒤에 있던 것이 일어선 것이다.<br><br>상자 하나만 안고 뛰었다. 문을 닫고 빗장을 걸 때까지 등 뒤에서 선반 넘어지는 소리가 따라왔다. 하나라도 건진 게 다행인 날이었다.`,
      win:{ exp:21, dream:3, item:'말린 고기' }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 제일 큰 상자를 연다 — 뜯긴 자국이 없다.', k:'luck', dc:26,
      doom:{ title:'상자 속의 숨', what:'상자에서 나온 것에 창고 안쪽으로 끌려갑니다', dc:20, sec:35,
        text:`제일 큰 상자는 밀랍도 성하고 무게도 묵직했다. 뚜껑을 들었다.<br><br>안에 식량은 없었다. 둥글게 말린 것이 있었다. 밀랍이 성한 건 안에서 다시 봉했기 때문이었다. 저 자는 동안 문 잠근 것이다.<br>그것이 펴졌다. 긴 팔이 이쪽 멱살을 감고 상자에서 쏟아져 나왔다. 그대로 창고 안쪽, 선반 뒤 어둠으로 끌고 간다. 바닥에 끌리며 보니 그 어둠에 뜯긴 상자들이 둥글게 쌓여 있었다. 집이었다. 식량 창고에 집을 지은 것이다. 먹을 게 배달되는 집.`,
        dieText:`큰 상자는 도로 닫혀 있었다. 밀랍까지 도로 녹여 봉한 채.<br><br>일행은 상자에 손대지 않고 창고를 나왔다. 문을 잠그고 빗장에 쇠막대를 덧댔다.<br>문 너머에서 밀랍 긁는 소리가 났다. 안에서 또 봉하는 소리인지, 여는 소리인지는 알 수 없었다.` },
      ok:`뚜껑에 손을 대기 전에 상자를 한 바퀴 돌았다. 밑판 구석에 바늘구멍만 한 숨구멍이 줄지어 있다.<br><br>식량 상자에 숨구멍은 없다. 뚜껑 대신 선반 지렛대를 상자 밑에 괴고, 멀찍이서 밀어 떨어뜨렸다.<br>상자가 엎어지며 안의 것이 쏟아졌다. 잠이 덜 깬 채로. 창 둘이 그 위에 꽂혔다.<br><br>치우고 보니 상자 안쪽에 먹다 남긴 것들이 쌓여 있었다. 기름종이에 싼 것도 몇 개 성했다. 집세는 받았다.`,
      win:{ exp:19, dream:3, item:'말린 고기' } }
  ] },

{ at:'S1', t:'환기 교차로 — 공기의 맛',
  x:`복도가 교차하는 자리다. 네 방향에서 공기가 섞인다. 생존가는 갈림길에서 공기부터 맛본다.<br><br>
    왼쪽 공기는 쇳내와 기름내. 기계가 사는 쪽이다.<br>
    오른쪽 공기는 달큰하다. 꽃 없는 건물에서 달큰한 냄새는 썩는 냄새 아니면 꾀는 냄새다.<br>
    정면 공기는 미지근하고 축축하다. 숨이 많이 모인 데서 오는 공기다.<br><br>
    어느 쪽도 좋은 답은 아니다. 덜 나쁜 답이 있을 뿐.`,
  o:[
    { l:'① 혀와 코로 세 길의 셈을 매겨 쇳내 쪽을 고른다.', k:'steady', dc:25, wake:1,
      ok:`달큰한 쪽은 꾀는 냄새다. 꾀는 것은 기다리는 것이 있다는 뜻. 축축한 쪽은 숨들의 안방이다. 쇳내 쪽만 남는다.<br><br>기계 사는 데는 시끄럽고, 시끄러운 데는 저것들도 꺼린다. 귀로 사는 것들에게 기계 소리는 눈가리개니까.<br>쇳내 복도는 과연 비어 있었다. 돌아가는 환풍기 밑을 지나며 일행 발소리가 기계 소리에 묻혔다.<br><br>공기에 셈을 매기는 버릇이 자리 잡았다. 눈은 속아도 코는 늦게 속는다. 혀는 더 늦게 속는다.`,
      ng:`쇳내를 골랐는데 쇳내가 둘이었다. 기계 기름내와, 산에 삭은 쇠 냄새.<br><br>복도 중간부터 벽이 얽어 있었다. 산성 피가 밴 길이다. 삭은 바닥이 막내 발밑에서 꺼졌다.<br>아래층으로 반 길 빠진 막내를 끌어올렸다. 정강이가 긁혀 피가 뱄다.<br><br>같은 쇳내도 갈래가 있다. 혀끝에 그 차이를 새겼다. 다음엔 안 속을 차이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 종이 재를 날려 바람의 길부터 그린다.', k:'sense', dc:24,
      ok:`수첩 한 장을 태워 재를 손바닥에 놓고 교차로 가운데서 불었다. 재가 흘러가는 길이 공기의 길이다.<br><br>재는 왼쪽으로 흐르다 천장 구멍으로 빨려 올라갔다. 왼쪽 길이 숨구멍 쪽, 곧 바깥쪽이라는 뜻이다.<br><br>재 한 줌이 지도 한 장이었다. 왼쪽 복도 끝에서 과연 바깥 공기 맛이 났다.`,
      ng:`재를 불자 재가 곧장 바닥에 가라앉았다. 공기가 안 움직이는 것이다. 사방이 다 막혔다는 뜻.<br><br>그때 정면 복도에서만 공기가 훅 밀려왔다. 무엇이 이쪽으로 오면서 공기를 미는 것이다.<br><br>넷이 왼쪽 복도로 몰려 들어가 기계 뒤에 엎드렸다. 교차로를 큰 그림자가 지나갔다. 재는 바닥에 그대로 있었다. 지도가 아니라 경보였다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-15 } }
  ] },

{ at:'S1', t:'물탱크실 — 출렁이는 소리',
  x:`물탱크실이다. 사람 키 세 배 높이 쇠 탱크에 물이 반쯤 차 있다. 수통을 다 채울 기회다.<br><br>
    탱크 위 점검구가 열려 있다. 열린 지 오래된 녹 자국이다.<br>
    물 받는 꼭지는 탱크 아래에 있다. 녹슬어 뻑뻑하다.<br><br>
    탱크 속에서 이따금 출렁, 소리가 난다. 바람 없는 방에서.`,
  o:[
    { l:'① 탱크는 두고 벽의 가는 송수관을 딴다.', k:'gaze', dc:24,
      ok:`출렁이는 건 물만이 아니라는 눈으로 탱크를 봤다. 수면에 기름막 같은 띠가 돈다. 뭔가 산다. 저 물은 우물이 아니라 못이다.<br><br>벽을 훑으니 탱크를 거치지 않는 가는 송수관이 있다. 위층에서 바로 내려오는 관이다.<br>이음매를 조금 풀자 맑은 물이 실처럼 나왔다. 느리지만 수통 다섯을 다 채웠다.<br><br>채우는 동안 탱크가 두 번 출렁였다. 못의 임자가 뒤척이는 소리였다. 깨우지 않고 나왔다.`,
      ng:`송수관 이음매를 너무 풀었다. 물이 실이 아니라 줄기로 터졌다.<br><br>물소리가 방에 울리자 탱크가 크게 출렁였다. 점검구 밖으로 긴 것이 넘겨다봤다.<br><br>이음매를 되감을 틈이 없어 수통만 안고 나왔다. 물은 반밖에 못 채웠고, 방바닥에 물길이 남았다. 물길은 문밖까지 이쪽을 따라왔다. 젖은 발자국으로.`,
      win:{ exp:19, dream:2, item:'맑은 물' }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 점검구로 올라가 두레박질을 한다.', k:'steady', dc:26,
      doom:{ title:'탱크 속으로', what:'물속에서 나온 것에 탱크 안으로 끌려 들어갑니다', dc:20, sec:35,
        text:`사다리를 타고 점검구에 엎드려 수통을 끈에 묶어 내렸다. 한 통. 두 통.<br><br>세 통째에 끈이 무거워졌다. 물 무게가 아니다. 끈을 타고 올라오는 무게다.<br>젖은 손이 손목을 감았다. 차고 미끄럽고, 억세다. 탱크 안으로 끌려 들어가며 마지막으로 본 것은 점검구 테두리의 녹 자국이었다. 오래된 녹. 이 짓을 당한 게 처음이 아니라는 녹이었다.`,
        dieText:`탱크는 다시 조용해졌다. 수면에 수통 하나가 떠 있었다.<br><br>일행은 꼭지를 억지로 틀어 물을 뺐다. 탱크를 비우는 데 한나절이 걸렸다.<br>바닥이 드러났을 때, 거기 아무것도 없었다. 탱크 안쪽 벽에 위로 기어오른 긁힘 자국만 있었다. 점검구는 그날부터 쇠막대로 질러 놓았다.` },
      ok:`점검구에 엎드리기 전에 돌 하나를 먼저 떨어뜨렸다. 퐁당 소리에 물이 크게 뒤집혔다. 큰 것이 돌을 쫓아 수면을 쳤다.<br><br>사는 놈의 크기와 버릇을 보고 나서 두레박질을 했다. 물이 뒤집힌 반대쪽 구석에서, 빠르게 세 통.<br>네 통째 욕심은 접었다. 그것이 돌이 가짜인 걸 알아챌 때쯤이었다.<br><br>내려와 꼭지 쪽에 귀를 댔다. 탱크 벽을 긁는 소리가 따라 내려왔다. 수통 셋 값으로는 충분한 긴장이었다.`,
      win:{ exp:20, dream:3, item:'맑은 물' } }
  ] },

{ at:'S1', t:'관측실 — 먼저 버틴 사람',
  x:`관측실 구석에 누가 살았던 자리가 있다. 담요, 빈 통조림 깡통, 벽에 그은 날짜 금.<br><br>
    금이 마흔하나다. 여기서 마흔하루를 버텼다.<br>
    깡통은 차곡차곡 포개져 있고 바닥엔 부스러기 하나 없다. 아는 사람의 솜씨다. 같은 일을 하는 사람.<br><br>
    마흔한 줄 끝에, 마지막 금 하나만 빗금으로 길게 그어져 있다. 그리고 자리는 비었다.`,
  o:[
    { l:'① 그가 남긴 것을 읽는다 — 수첩이 있을 것이다.', k:'gaze', dc:24,
      ok:`아는 사람은 기록을 남긴다. 담요 밑도 깡통 속도 아니다. 바닥 환기 살대 안, 기름종이에 싼 수첩이 있었다.<br><br>물 받는 자리, 조용한 시간대, 다니면 안 되는 복도가 깨알같이 적혔다. 마지막 장에는 한 줄. 천장을 믿지 말 것.<br>그 줄을 읽는데 다들 약속한 듯 위를 봤다. 천장 판 하나가 비뚤게 닫혀 있었다.<br><br>조용히 관측실을 나왔다. 수첩은 품에 넣었다. 마흔하루치 목숨값이 적힌 책이다.`,
      ng:`수첩은 찾았는데 마지막 장들이 뜯겨 있었다. 뜯긴 자리에 마른 얼룩.<br><br>남은 장을 뒤지는 사이 천장에서 먼지가 떨어졌다. 비뚤게 닫힌 판이 소리 없이 더 벌어지고 있었다.<br><br>읽기를 관두고 뛰었다. 복도에 나와서야 수첩을 폈다. 반쪽짜리 지도라도 지도는 지도다. 다만 천장 얘기가 뜯긴 쪽에 있었을 것이다. 그건 이제 몸으로 배워야 한다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 그의 마흔하루를 이어 쓴다 — 자리를 물려받는다.', k:'steady', dc:25, wake:1,
      ok:`자리를 뜯어보며 그의 하루를 되살았다. 담요 각도는 문을 보는 각. 깡통 탑은 넘어지면 울리는 종. 날짜 금 옆의 작은 점들은 그것들이 지나간 밤의 수.<br><br>마흔하루 동안 스물여섯 밤을 그것들이 지나갔고 그는 버텼다. 이 자리는 버텨지는 자리다.<br>하룻밤을 그 법대로 났다. 깡통 종을 세우고, 담요 각을 맞추고. 밤에 두 번 긁는 소리가 지나갔지만 자리는 조용했다.<br><br>남의 마흔하루를 하룻밤에 물려받았다. 생존은 이어 쓰는 글이다. 먼저 쓴 사람 덕을 입었으면, 다음 쓸 사람 몫도 남겨 둘 것. 떠나며 깡통 탑을 도로 세워 놓았다.`,
      ng:`그의 법대로 자리를 폈는데 하나를 놓쳤다. 날짜 금 옆의 점. 그건 밤의 수가 아니라 시간이 갈수록 잦아지는 간격이었다.<br><br>마흔한 줄 쪽으로 갈수록 점이 촘촘했다. 그것들이 점점 자주 왔다는 뜻. 이 자리는 버텨지는 자리였다가, 더는 아니게 된 자리다.<br>한밤에 긁는 소리가 관측실 문 앞에서 멈췄다. 숨죽인 반 식경이 하루 같았다.<br><br>새벽에 바로 자리를 떴다. 빗금의 뜻을 이제 알겠다. 그건 날짜가 아니라 끝맺음이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-19, spirit:-17 } }
  ] },

{ at:'S1', t:'아래층 복도 — 더운 바닥',
  x:`복도 바닥이 미지근하다. 쇠 건물의 바닥은 원래 차다. 열은 어디서든 올라오는 데가 있다.<br><br>
    걸을수록 더워진다. 장화 바닥으로 느껴질 만큼.<br>
    따뜻한 건 좋은 것이었다. 바깥세상에서는. 여기서 온기는 모여 사는 것들의 체온이다.<br><br>
    복도는 곧고, 끝은 어둡고, 바닥은 점점 덥다.`,
  o:[
    { l:'① 찬 바닥을 따라 되짚어 돌아간다.', k:'steady', dc:24, wake:1,
      ok:`발바닥을 온도계로 썼다. 더운 쪽이 아니라 찬 쪽으로. 갈림마다 장화를 벗고 맨발바닥으로 쟀다.<br><br>찬 길은 돌아가는 길이었다. 반나절을 둘렀다.<br>둘러 가는 길 창문에서 아래층이 내려다보였다. 가려던 그 곧은 복도의 끝, 넓은 방에 그것들이 융단처럼 깔려 있었다. 포개 자며 바닥을 덥히고 있었다.<br><br>발바닥이 재는 온도에 목숨이 달릴 수 있다. 장화 밑창 너머의 반 도 차이. 그걸 읽는 발이 됐다.`,
      ng:`찬 쪽을 짚어 가는데 중간에 바닥 온도가 뒤집혔다. 그것들이 자리를 옮기는 중이었다. 온기가 이쪽으로 번져 온다.<br><br>갈림 하나를 급히 꺾었다. 꺾은 복도에서 마주 오던 척후 한 마리와 마주쳤다.<br>창이 먼저 나갔기에 망정이지, 서로 놀란 반 숨이 승부였다.<br><br>죽인 것을 끌어다 찬 쪽 구석에 숨기고 내달렸다. 온기는 움직인다. 지도가 아니라 날씨로 읽어야 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 벽의 배관을 짚어 열의 근원을 가늠한다.', k:'sense', dc:25,
      ok:`벽 배관을 하나씩 짚었다. 온수관이면 기계 열이고, 벽 자체가 더우면 산 것들 열이다.<br><br>배관은 차고 벽이 덥다. 산 것들이다. 그리고 벽의 온기가 눈높이까지 올라와 있다. 바닥에 깔린 수가 아니라 벽 너머에 쌓인 수다.<br>이 복도는 둥지의 바깥담이었다.<br><br>소리 없이 물러났다. 담을 알았으니 둥지의 크기도 그려졌다. 생각보다 컸다. 많이.`,
      ng:`배관을 짚다가 뜨거운 관을 맨손으로 쥐었다. 김 빠지는 소리와 함께 손바닥이 익었다.<br><br>반사적으로 손을 떼며 배관을 쳤다. 쇳소리가 복도를 달렸다.<br>벽 너머의 온기가 일제히 움직이는 기척이 벽을 타고 왔다.<br><br>손바닥에 물집을 단 채 반나절 거리를 쉬지 않고 걸었다. 짚는 손에도 순서가 있다. 손등 먼저, 그다음 손바닥.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S1', t:'암등 복도 — 불빛의 장단',
  x:`비상등만 남은 복도다. 등이 성한 게 아니라 깜빡인다. 켜지고, 꺼지고. 장단이 있다.<br><br>
    켜진 동안 복도는 비어 보인다. 꺼진 동안 무슨 일이 벌어지는지는 모른다.<br>
    바닥에 긁힌 자국이 많다. 자국들은 다 등과 등 사이, 어두운 구간에 몰려 있다.<br><br>
    어둠에만 움직이는 것이 이 복도에 산다.`,
  o:[
    { l:'① 불의 장단을 외워 켜질 때만 걷는다.', k:'steady', dc:25,
      ok:`등의 장단을 셌다. 켜짐 여섯 숨, 꺼짐 네 숨. 어긋나는 법이 없는 기계 장단이다.<br><br>켜지면 여섯 숨 걷고, 꺼지기 반 숨 전에 멈춰 벽에 붙었다. 꺼진 네 숨은 숨도 반만 쉬었다.<br>세 번째 어둠에서 코앞을 무엇이 지나갔다. 바람과 비린내만 남기고. 움직이는 것만 좇는 몸이라, 멈춘 사람들을 못 봤다.<br><br>복도 끝까지 열한 장단. 불빛을 시계로 쓰는 법을 배웠다.`,
      ng:`아홉 번째 장단에서 막내가 반 숨 늦게 멈췄다. 꺼진 어둠 속에서 옷깃 스치는 소리.<br><br>다시 켜졌을 때 막내 소매가 어깨까지 찢어져 있었다. 본인은 뭐가 스쳤는지도 몰랐다.<br><br>남은 두 장단을 다섯이 한 덩어리로 붙어 건넜다. 복도를 나와서 막내가 주저앉았다. 소매는 꿰매면 된다. 반 숨은 꿰맬 수 없다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-25, spirit:-17 } },
    { l:'② 등 하나를 아예 꺼서 어둠 구간을 하나로 잇는다.', k:'fix', dc:25,
      ok:`거꾸로 갔다. 깜빡이는 등의 전선을 끊어 복도 전체를 어둠으로 만들었다.<br><br>어둠에 움직이는 것은 어둠과 빛의 경계로 사냥한다. 경계가 없어지면 저도 기준이 없다.<br>벽에 손을 대고 일렬로, 한 발씩 더듬어 건넜다. 그것이 복도를 두 번 오르내리는 기척이 났지만 끝내 못 찾았다. 다 같은 어둠에서는 멈춘 것과 벽이 같다.<br><br>복도 끝에서 뒤돌아보니 어둠만 있었다. 무서운 건 어둠이 아니라 어둠의 가장자리였다.`,
      ng:`전선을 끊자 복도 끝 등 하나만 남아 외로 깜빡였다. 어둠이 하나로 이어지는 대신 그 등 밑만 섬이 됐다.<br><br>그것이 섬 둘레를 돌기 시작했다. 하필 가야 할 문이 그 등 밑이다.<br><br>결국 등 꺼지는 네 숨마다 두 명씩 문을 넘었다. 마지막 조는 그것의 꼬리가 문틀을 치는 걸 등으로 느끼며 넘었다. 어둠을 잇는 셈은 좋았는데 등 하나를 빼먹었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S1', t:'탈피장 — 벗어 둔 것들',
  x:`넓은 방에 허물이 널렸다. 그것들이 벗은 껍질이다. 반투명하고, 사람 모양과 먼 모양.<br><br>
    생존가는 허물에서 숫자를 읽는다. 크기가 다 다르다. 작은 것, 중간 것, 큰 것.<br>
    제일 큰 허물이 문 하나만 하다.<br><br>
    허물은 벗은 자리 가까이에 임자가 있다는 뜻이기도 하다. 갓 벗은 몸은 무르니까, 안전한 데서 벗는다.`,
  o:[
    { l:'① 허물의 크기를 줄 세워 그것들의 자람 속도를 센다.', k:'gaze', dc:25,
      ok:`허물을 작은 것부터 줄 세워 봤다. 손바닥만 한 것에서 문짝만 한 것까지 다섯 치수.<br><br>치수 사이가 일정하다. 벗을 때마다 반씩 커진다. 그리고 제일 큰 허물의 안쪽이 아직 촉촉하다. 벗은 지 며칠 안 됐다.<br>문짝만 한 것이 벗었으면 지금은 문 둘 크기다. 그 몸이 다닐 수 있는 복도는 이 건물에 몇 없다. 넓은 복도만 피하면 마주칠 일도 없다는 뜻이다.<br><br>허물이 지도를 줬다. 큰길을 버리고 좁은 길로만 길을 다시 그렸다.`,
      ng:`치수를 재는데 셈이 안 맞았다. 제일 큰 허물과 그다음 사이가 비었다. 한 치수가 없다.<br><br>없는 게 아니라 아직 안 벗은 것이다. 그 치수의 것이 지금 어딘가에서 벗을 자리를 찾는 중이다. 무르고, 예민하고, 사나운 때.<br>그때 방 안쪽에서 젖은 천 벗는 소리가 났다.<br><br>세던 허물을 놓고 물러났다. 등 뒤의 소리가 끝까지 따라왔다. 벗는 소리인지 벗고 나온 소리인지 돌아보지 않았다.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 성한 허물 하나를 챙긴다 — 쓸모가 있을 것이다.', k:'steady', dc:24,
      ok:`중간 치수 허물 하나를 골라 둘둘 말았다. 질기고 가볍고 물이 안 샌다.<br><br>그날 밤부터 허물은 천막이 되고 물받이가 됐다. 비 오는 밤 그 아래서 넷이 말랐다.<br>덤으로 하나 더 알았다. 허물을 두른 쪽으로는 작은 것들이 안 온다. 저희 큰 것의 냄새가 나는 것이다.<br><br>버린 껍질에도 쓸모가 셋이다. 생존가 눈에는 이 방이 창고로 보였다.`,
      ng:`허물을 마는데 안쪽에 점액이 남아 있었다. 장갑에 묻자 가죽이 삭기 시작했다.<br><br>장갑을 벗어 던졌다. 늦게 벗어 손등이 얼얼하다. 갓 벗은 허물은 안감이 아직 살아 있다.<br><br>바싹 마른 허물로 다시 골라 챙겼다. 마른 것은 과연 순했다. 공짜 창고에도 값이 있었다. 손등으로 치렀다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S2', t:'잠긴 양치밭 — 소리 없는 낚시',
  x:`물에 잠긴 양치밭이다. 고사리 사이 물웅덩이마다 물고기가 다닌다. 등지느러미가 물을 가르는 게 보인다.<br><br>
    굶은 지 하루 반. 저걸 잡으면 오늘이 산다.<br>
    문제는 물소리다. 이 정원에서 물 때리는 소리는 종소리다. 큰 것의 걸음이 멀리서 이따금 물을 울린다.<br><br>
    낚시란 원래 기다리는 일이다. 여기선 더 그렇다.`,
  o:[
    { l:'① 큰 걸음이 물을 울릴 때만 손을 쓴다.', k:'steady', dc:24,
      ok:`옷 바늘을 굽혀 낚시를 만들고 물가에 엎드렸다. 손은 물속에, 몸은 돌처럼.<br><br>멀리서 쿵, 물이 울 때마다 그 울림에 숨겨 손을 썼다. 큰 소리가 작은 소리를 먹는다.<br>세 울림에 한 마리씩. 다섯 울림에 세 마리를 뭍에 올렸다. 물은 끝까지 이쪽 소리를 내지 않았다.<br><br>남의 발소리를 제 그물로 쓰는 낚시였다. 정원이 시끄러울수록 밥상이 쉬워진다. 셈이 하나 늘었다.`,
      ng:`네 마리째 욕심에 울림 없이 손을 챘다. 첨벙.<br><br>물소리가 양치밭에 퍼졌다. 고사리 숲 저쪽에서 답이 왔다. 물 가르며 오는 V자 물살. 그것도 물고기를 잡는 것이었다. 물소리 나는 데로 와서.<br><br>세 마리를 움켜쥐고 뭍으로 굴렀다. 물살이 방금 엎드렸던 자리를 치고 지나갔다. 고기는 건졌는데 밥맛은 반이 됐다.`,
      win:{ exp:20, dream:3, item:'민물고기' }, lose:{ hp:-25, mind:-14 } },
    { l:'② 물풀로 어살을 엮어 웅덩이 목을 막는다.', k:'fix', dc:24,
      ok:`웅덩이와 웅덩이를 잇는 좁은 물목을 찾았다. 물풀 줄기를 격자로 엮어 어살을 세웠다.<br><br>고기가 다니는 길목이라 기다릴 것도 없다. 반 식경에 어살 안이 퍼덕였다.<br>손도 안 적시고 네 마리를 건졌다. 어살은 걷어서 다음 물목에 또 쓰게 말아 뒀다.<br><br>도구는 소리를 안 낸다. 사람 손이 소리를 낸다. 손 대신 어살이 일하게 하는 것, 그게 조용한 사냥이다.`,
      ng:`어살을 엮는데 물풀 뿌리 쪽에서 잔 이빨들이 손가락을 쪼았다. 물풀 밑에 사는 것들이다.<br><br>손가락 두 개에 바늘땀 같은 잇자국이 줄로 났다. 피가 물에 번졌다.<br>피 냄새에 웅덩이가 끓기 시작했다. 작은 것들이 몰려드는 소리다.<br><br>어살이고 고기고 두고 물러났다. 피 흘리는 손은 물에 안 담그는 것. 기본을 배가 고파서 잊었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S2', t:'해 질 녘 — 잘 자리 고르기',
  x:`해가 기운다. 정원의 밤은 바깥 밤보다 빨리 오고 더 깜깜하다. 잘 자리를 정할 시간이다.<br><br>
    고사리 둔덕은 푹신하고 아늑해 보인다. 바위 턱은 딱딱하고 춥다. 덤불 속은 가시투성이다.<br>
    생존가는 아늑해 보이는 자리부터 의심한다. 아늑한 자리는 누구에게나 아늑하다.<br><br>
    둔덕 흙에 코를 대 봤다.`,
  o:[
    { l:'① 흙냄새와 눌린 풀로 자리의 전 주인을 읽는다.', k:'steady', dc:25, wake:1,
      ok:`둔덕 흙에서 노린내가 났다. 눌린 풀이 몸통 모양으로 둥글다. 누가 자던 자리다. 그것도 매일.<br><br>바위 턱 쪽은 흙냄새뿐이고 똥자국도 뼈도 없다. 아무도 안 쓰는 자리라는 뜻. 안 쓰는 데는 이유가 있지만, 그 이유가 춥고 딱딱한 것뿐이라면 사람에게는 상등 자리다.<br>바위 턱에서 잤다. 밤중에 둔덕 쪽에서 큰 숨소리가 밤새 들렸다. 주인이 돌아온 것이다.<br><br>자리를 고르는 코가 생겼다. 아늑함은 눈이 읽지만 임자는 코가 읽는다.`,
      ng:`냄새까지는 읽었는데 바람을 안 읽었다. 바위 턱이 바람길이었다.<br><br>밤새 골바람이 턱을 훑었다. 불을 못 피우는 밤이라 체온으로만 버텼다.<br>새벽에 막내 입술이 파랬다. 마른 고기를 씹이고 주물러 깨웠다.<br><br>임자 없는 자리에는 임자가 없는 값이 있다. 다음부턴 코 다음에 뺨을 쓰기로 했다. 바람은 뺨이 읽는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 가시덤불 속을 손도끼로 파서 방을 만든다.', k:'sense', dc:24,
      ok:`가시덤불 한가운데를 골랐다. 겉은 가시 벽, 속은 비었다. 손도끼로 드는 길만 한 사람 폭으로 텄다.<br><br>가시는 이쪽을 긁지만 저것들 가죽도 긁는다. 발톱 긴 것들이 밤에 두 번 둘레를 돌았지만 덤불 안으로는 코도 안 넣었다.<br><br>가시에 몇 군데 긁힌 값으로 성 하나를 얻었다. 정원이 만들어 둔 성이다. 쓸 줄 아는 사람에게만.`,
      ng:`덤불을 파는데 속에 먼저 든 것이 있었다. 가시 사이에 집 지은 작은 것들. 주먹만 하고 이빨은 바늘이다.<br><br>쫓겨 나오며 손등과 목덜미를 쪼였다. 부어오르는 게 벌 쏘인 것 같다.<br><br>결국 덤불 가장자리에 반쪽짜리 바람막이만 치고 잤다. 성에도 선주민이 있다. 문 두드리는 법부터 배워야 했다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S2', t:'트인 벌판 쪽으로 — 몰이',
  x:`뒤와 양옆에서 그것들이 따라온다. 급하지 않게. 이빨을 보이지도 않게. 그냥 따라온다.<br><br>
    가게 두는 방향이 하나뿐이다. 앞. 앞은 트인 벌판이다.<br>
    생존가는 이 걸음을 안다. 짐승 몰이다. 벌판 어딘가에 기다리는 입이 있다.<br><br>
    몰리는 줄 알면서 몰리는 것과 모르고 몰리는 것은 다른 일이다.`,
  o:[
    { l:'① 걸음을 뚝 멈추고 가시덤불 쪽으로 방향을 꺾는다.', k:'steady', dc:26,
      ok:`몰이의 약점은 몰리는 쪽이 멈추면 셈이 깨진다는 것이다. 뚝 멈췄다. 따라오던 걸음들도 멈췄다.<br><br>그대로 직각으로 꺾어 가시덤불에 몸을 밀어 넣었다. 가시가 옷과 살을 긁었지만 뚫고 나갔다.<br>덤불 너머에서 뒤돌아보니 그것들이 덤불 앞에 줄로 서 있었다. 몰이꾼은 가시를 안 뚫는다. 몰이가 안 되는 먹이는 셈에서 지운다.<br><br>벌판 쪽에서 긴 울음이 났다. 기다리던 입이 허탕을 문 소리였다.`,
      ng:`멈추고 꺾는 게 반 박자 늦었다. 왼쪽 몰이꾼이 덤불 어귀를 먼저 막았다.<br><br>몸을 던져 덤불 깊이 뚫었다. 발톱이 장딴지를 한 번 긁었다.<br>덤불 속을 피 흘리며 기었다. 가시가 상처를 자꾸 벌렸다.<br><br>빠져나와 싸매고 보니 장딴지가 세 줄로 갈라져 있었다. 몰이에서 빠지는 값이었다. 비싸지만 벌판 값보다는 쌌다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-34, mind:-15 } },
    { l:'② 벌판으로 내닫되 방향을 지그재그로 꺾는다.', k:'evade', dc:26,
      doom:{ title:'벌판의 입', what:'매복한 것에게 물려 풀숲으로 끌려갑니다', dc:20, sec:40,
        text:`벌판을 질렀다. 곧장 가지 않고 지그재그로. 몰이꾼들이 뒤에서 당황한 울음을 주고받았다.<br><br>그러나 기다리는 입은 벌판 가운데가 아니라 지그재그가 끝나는 자리에 있었다. 몰이는 이쪽 머리까지 몰았던 것이다. 꾀 많은 먹이가 꺾을 자리까지.<br>풀숲이 일어서며 입이 닫혔다. 어깨와 팔이 한입에 물렸다. 끌려가는 등 뒤로 몰이꾼들이 둘러앉는 그림자가 보였다. 상이 차려지기를 기다리는 그림자들이었다.`,
        dieText:`벌판 가운데 풀만 넓게 눕고 비어 있었다.<br><br>일행은 벌판을 크게 돌아 가시덤불 길로 빠졌다. 사흘 뒤 다른 무리의 생존가가 그 벌판에서 배낭 띠 하나를 주웠다.<br>띠에는 이로 문 자국이 하나뿐이었다. 한입이었다는 뜻이다. 그는 그걸 제 무리에게 보여 주며 말했다. 몰리면 벌판으로는 가지 마라.` },
      ok:`지그재그로 꺾으며 벌판 가운데가 아니라 가장자리 바위 무더기를 향해 뛰었다.<br><br>기다리는 입은 꺾임 끝을 노린다. 그래서 꺾임의 끝을 바위로 정했다. 입이 못 서는 자리로.<br>풀숲이 한 번 크게 일렁였지만 입은 끝내 안 나왔다. 바위 무더기에 올라서자 몰이 전체가 걸음을 접었다.<br><br>몰이꾼과 입이 흩어지는 걸 바위 위에서 다 셌다. 다섯. 다음에 또 만날 수다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'살수기의 비 — 움직일 시간',
  x:`천장 어딘가의 낡은 살수기가 돌기 시작했다. 정원 전체에 비가 온다. 한참 온다.<br><br>
    비는 냄새를 씻고 소리를 덮고 발자국을 지운다.<br>
    젖는 건 나쁘다. 하지만 비 오는 동안은 그것들의 코도 귀도 반쯤 먼다.<br><br>
    생존가에게 이 비는 날씨가 아니라 문이다. 열려 있는 동안만 지날 수 있는.`,
  o:[
    { l:'① 짐을 묶고 비가 긋기 전까지 최대한 거리를 번다.', k:'steady', dc:24, wake:1,
      ok:`비가 문이라고 외쳤다. 젖는 투정은 받지 않았다. 짐을 기름천으로 말아 묶고 곧장 떠났다.<br><br>빗소리에 발소리가 녹았다. 평소 피해 돌던 둥지 터 옆길을 곧장 질렀다. 그것들은 비를 피해 웅크린 채 코앞을 지나는 다섯을 몰랐다.<br>비가 긋기까지 한나절 거리를 벌었다.<br><br>날씨를 길로 읽는 눈이 생겼다. 비는 문, 안개는 담, 바람은 지도. 하늘이 주는 것은 다 쓰임이 있다.`,
      ng:`거리는 벌었는데 끝을 못 쟀다. 살수기는 기계라 비가 뚝 끊긴다. 하늘 비처럼 잦아들지 않고.<br><br>끊기는 순간 한가운데 트인 데 서 있었다. 냄새와 소리가 한꺼번에 돌아왔다. 사방에서 코 드는 기척도.<br><br>제일 가까운 바위까지 내달렸다. 등 뒤에서 울음들이 서로를 불렀다. 기계 비는 수도꼭지다. 잠기는 때를 셈에 넣었어야 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 비를 받아 두는 쪽을 고른다 — 물주머니부터 채운다.', k:'fix', dc:23,
      ok:`움직이는 대신 모으기로 했다. 넓은 잎을 꺾어 홈통을 만들고 물주머니와 수통을 줄 세웠다.<br><br>살수기 물은 받아 보니 맑았다. 오래된 관 치고는.<br>비 긋기 전에 전부 채우고 여분으로 기름천에도 한 자락 받았다.<br><br>길은 못 벌었지만 물 걱정이 사흘 치 사라졌다. 문이 열렸을 때 지나는 것만 수가 아니다. 문틈으로 들어오는 것을 받는 것도 수다.`,
      ng:`홈통을 대 놓고 보니 받히는 양이 영 시원찮다. 잎 홈통이 자꾸 넘어졌다.<br><br>반 통 채울 동안 비가 그쳤다. 길도 못 벌고 물도 반이다.<br>젖은 몸만 남았다. 밤에 한기가 들어 다들 떨었다.<br><br>두 마리 토끼 셈을 하다 양쪽 다 반쪽이 됐다. 문이 열리면 하나만 골라야 한다. 크게.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S2', t:'문지른 나무 — 금 긋는 냄새',
  x:`길목의 굵은 나무가 허리 높이까지 껍질이 벗겨져 반질하다. 큰 것이 몸을 문지른 자국이다.<br><br>
    조금 가니 또 한 그루. 그 너머에 또. 문지른 나무들이 줄을 선다.<br>
    이건 길이 아니라 금이다. 여기부터 내 땅이라는 금.<br><br>
    가려는 방향이 하필 그 금 안쪽이다.`,
  o:[
    { l:'① 금 안쪽을 지나되 한가운데 길로만 곧장 걷는다.', k:'steady', dc:25,
      ok:`영역 임자는 제 금 가장자리를 돈다. 가장자리가 남과 닿는 자리니까. 한가운데는 되레 비는 시간이 길다.<br><br>문지른 나무들에서 제일 먼 한가운데 길을 그어 곧장 걸었다. 멈추지 않고, 냄새 남길 것도 안 남기고.<br>반나절 만에 반대쪽 금을 넘었다. 멀리서 큰 것이 가장자리를 도는 소리만 두 번 들었다.<br><br>남의 땅은 가장자리가 제일 위험하다. 심장부가 아니라. 그 셈이 사람 사는 데서 온 셈이라 더 믿을 만했다.`,
      ng:`한가운데 길에서 막내가 돌에 걸려 넘어지며 물주머니가 터졌다. 물 냄새가 퍼졌다.<br><br>물 냄새는 곧 목마른 것들을 부른다. 임자의 땅 안에서.<br>걸음을 배로 올렸다. 등 뒤에서 작은 것들이 물 자국을 핥으러 모이는 소리, 그 소리에 큰 것이 돌아오는 소리.<br><br>금을 넘고 나서야 숨을 쉬었다. 남의 땅에서는 넘어지는 것도 죄가 된다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 금을 따라 돈다 — 멀어도 임자 눈 밖이 낫다.', k:'luck', dc:26,
      doom:{ title:'가장자리의 임자', what:'영역을 돌던 큰 것에게 밟혀 끌려갑니다', dc:20, sec:40,
        text:`금 바깥을 따라 돌았다. 한나절이 더 걸려도 임자 땅 밖이 낫다는 셈이었다.<br><br>셈이 하나 빠졌다. 임자도 그 가장자리를 돈다. 같은 길을, 반대 방향으로.<br>모퉁이 바위를 사이에 두고 마주쳤다. 피할 새도 없이 꼬리가 후려쳐 왔다. 몸이 떠서 문지른 나무에 부딪혔다. 큰 것이 목덜미 옷을 물어 들어 올렸다. 새끼 나르듯 물고 제 땅 안쪽으로 걸어 들어간다. 발밑에서 땅이 쿵, 쿵, 멀어졌다.`,
        dieText:`문지른 나무 밑에서 배낭이 나왔다. 터진 물주머니와 함께.<br><br>일행은 금 안쪽 한가운데 길로 건넜다. 반나절 걸렸고 아무 일 없었다.<br>그 뒤로 이 무리의 생존가 수첩에는 이렇게 적혔다. 남의 금은 밟고 지나가는 것보다 따라 걷는 게 더 나쁘다. 임자가 그 길로 다닌다.` },
      ok:`금 바깥을 돌되 금에서 돌 던질 거리만큼 더 떨어져 돌았다. 임자의 순찰길과 겹치지 않게.<br><br>반나절에 한 번씩 큰 것이 금을 따라 지나갔다. 지나가는 소리를 세며 그 사이사이에 움직였다.<br>한나절 반 걸려 금 반대편에 닿았다.<br><br>멀리 돌았지만 발 한 번 금 안에 안 넣었다. 느린 길의 값은 시간이고, 시간은 목숨보다 싸다.`,
      win:{ exp:19, dream:2 } }
  ] },

{ at:'S2', t:'풀그늘 — 먹어도 되는 것',
  x:`배낭이 가볍다. 정원에는 먹음직한 것이 많다. 통통한 버섯, 넓은 나물잎, 붉은 열매.<br><br>
    바깥 산의 눈으로 보면 반은 아는 것들이다. 그런데 여기는 바깥이 아니다. 아는 모양이라고 아는 속이 아니다.<br>
    생존가의 법은 하나다. 모르면 입에 안 넣는다. 그리고 하나 더. 모르면, 먹는 놈을 찾아본다.<br><br>
    풀그늘에서 작은 것들이 뭔가를 갉고 있다.`,
  o:[
    { l:'① 작은 것들이 먹는 것만 따라 거둔다.', k:'gaze', dc:24,
      ok:`풀그늘에 엎드려 반 식경을 봤다. 작은 것들이 갉는 건 넓은 나물잎과 둥근 버섯. 붉은 열매 쪽은 지나다니면서도 입을 안 댄다.<br><br>먹는 것만 따라 거뒀다. 나물은 데칠 것, 버섯은 구울 것으로 갈라 담았다.<br>붉은 열매 밑을 지나며 보니 열매 떨어진 자리마다 풀이 누렇게 죽어 있었다.<br><br>짐승 입이 책이다. 글은 못 읽어도 거짓말은 안 하는 책.`,
      ng:`따라 거두는 것까지는 좋았는데, 작은 것들의 밥그릇을 너무 비웠다.<br><br>해 질 녘부터 작은 것들이 캠프 둘레로 모여들었다. 수십 마리가 풀숲에서 눈만 반짝인다. 제 먹이 거둬 간 냄새를 따라온 것이다.<br>밤새 바스락 소리에 시달리다 거둔 것의 반을 풀숲에 도로 내놓았다.<br><br>그제야 눈들이 사라졌다. 남의 책을 베끼면 베낀 값을 치른다.`,
      win:{ exp:19, dream:2, item:'산나물' }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 버섯 둔덕을 턴다 — 양으로 승부한다.', k:'luck', dc:25,
      ok:`쓰러진 나무둥치에 버섯이 밭을 이뤘다. 작은 것들이 갉은 자국 있는 종류만 골라 쓸어 담았다.<br><br>두 자루 가득. 며칠 치 국거리다.<br>둥치 밑동에서 소금기 밴 돌덩이도 하나 나왔다. 짐승들이 핥으러 오는 소금돌이다. 모서리를 쪼개 챙겼다.<br><br>정원이 차린 장을 본 셈이다. 물론 장 주인 몰래.`,
      ng:`쓸어 담는데 둥치 속이 비어 있었고, 빈 속에서 자던 것이 깼다.<br><br>길고 다리 많은 것이 자루 위로 쏟아져 나왔다. 버섯이고 뭐고 자루 하나를 버리고 물러났다.<br><br>남은 자루 하나로 만족하기로 했다. 장을 볼 땐 진열대 뒤를 먼저 볼 것. 장 보는 법이 하나 늘었다.`,
      win:{ exp:17, dream:2, item:'야생 버섯' }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S2', t:'엘리베이터 앞 — 기름 냄새의 길',
  x:`바람에 실려 온 냄새 중에 처음으로 반가운 것이 있다. 기계 기름 냄새다.<br><br>
    낡은 엘리베이터. 올라가는 길. 기름 냄새는 그 권양기에서 온다.<br>
    냄새의 길을 거슬러 가면 된다. 문제는 그 길이 정원의 한가운데, 짐승 길들이 얽힌 매듭을 지난다는 것.<br><br>
    마지막 길일수록 서두르다 끝나는 법이다. 생존가는 그런 끝을 많이 안다.`,
  o:[
    { l:'① 기름 냄새가 짙어지는 쪽을 바람 볼 때마다 다시 잡으며 간다.', k:'steady', dc:25, wake:1,
      ok:`바람이 바뀔 때마다 멈춰 코를 들었다. 기름내가 짙어지는 쪽으로만 한 매듭씩.<br><br>짐승 길과 겹치는 자리마다 돌아서 코를 다시 잡았다. 곧장 가면 한 식경, 돌며 가면 세 식경 길이다. 세 식경을 골랐다.<br>엘리베이터 창살이 보였을 때 아무도 뛰지 않았다. 마지막 백 걸음을 제일 천천히 걸었다.<br><br>냄새 하나로 정원을 꿰어 나온 길이었다. 코가 눈보다 먼 데를 본다. 그 믿음이 이제 흔들리지 않는다.`,
      ng:`두 식경째에 바람이 죽었다. 냄새가 끊겼다. 끊긴 자리가 하필 짐승 길 매듭 한가운데였다.<br><br>길을 반으로 줄이려 곧장 질렀다. 매듭에서 발톱 긴 것 둘과 마주쳤다. 쫓고 쫓기며 반 바퀴를 돌아 겨우 뗐다.<br><br>엘리베이터에 닿았을 때 하나가 다리를 절었다. 바람이 죽으면 걸음도 죽였어야 했다. 냄새 없는 길은 길이 아니다.`,
      win:{ exp:23, dream:4 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 높은 바위에 올라 권양기 지붕부터 눈으로 찍는다.', k:'sense', dc:25,
      ok:`냄새는 길을 주지만 거리를 안 준다. 제일 높은 바위에 올라 정원을 훑었다.<br><br>북쪽 벼랑 밑, 녹슨 지붕이 반짝였다. 권양기 집이다. 지붕과 바위 사이 짐승 길이 두 줄, 비는 시간은 물 마시러 가는 한낮.<br>한낮에 맞춰 두 줄을 건넜다.<br><br>눈으로 찍고 코로 가는 길은 흔들림이 없었다. 마지막 길이 제일 깔끔한 길이 됐다.`,
      ng:`바위에 오르다 미끄러져 정강이를 찧었다. 그리고 바위 위는 이쪽만 좋은 자리가 아니었다.<br><br>날개 가죽인 것이 홰 치듯 바위 꼭대기에서 날아올랐다. 제 자리를 뺏겼다고 머리 위를 돌며 울었다.<br>그 울음이 정원에 이쪽 자리를 광고했다.<br><br>서둘러 내려와 반대쪽으로 한 바퀴 돌아 빠졌다. 높은 자리는 잘 보이는 자리고, 잘 보이는 자리는 잘 보여지는 자리다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-15 } },
    { l:'③ 다 같이 손을 묶듯 줄지어 마지막 길을 간다.', k:'bond', dc:24,
      ok:`마지막 길은 들뜬다. 들뜨면 흩어진다. 흩어지면 하나씩 없어진다. 그게 마지막 길의 법이다.<br><br>허리끈을 서로 이어 다섯을 한 줄로 묶었다. 제일 느린 사람의 걸음이 전체의 걸음이 되게.<br>묶인 줄은 뛰지 못한다. 뛰지 못하니 끝까지 조용했다.<br><br>창살 앞에서 끈을 풀며 세어 보니 다섯. 들어올 때와 같은 수다. 생존가의 일은 이 숫자 하나 지키는 일이었다.`,
      ng:`줄로 묶고 가는데 중간에서 하나가 발을 헛디뎠다. 묶인 줄이라 둘이 같이 넘어졌다.<br><br>넘어지는 소리가 매듭 길에 퍼졌다. 남은 길 반을 묶인 채로 뛰었다. 묶인 뜀박질은 세 배로 힘들다.<br><br>창살 안에 들어가 문을 닫고서야 끈을 풀었다. 손목마다 끈 자국이 붉었다. 묶는 수는 조용할 때 수다. 소리 난 뒤엔 족쇄다.`,
      win:{ exp:19, dream:3, spirit:5 }, lose:{ hp:-27, spirit:-16 } }
  ] }

]);

// ── 결계술사 (warder) · 마력
kJob('warder', 'S', [

{ at:'S', t:'첫 야영 — 선을 시험하는 발',
  x:`야영 자리에 가루로 원을 그렸다. 늘 긋던 결계다. 어둠의 것들은 이 선을 넘지 못한다.<br><br>
    한밤에 선 밖에서 발소리가 왔다. 선 앞에서 멈춘다. 넘지 못해서가 아니다. 안 넘고 있다.<br>
    발 하나가 선을 꾹 밟았다 뗀다. 저쪽으로 갔다가 거기서 또 밟는다.<br><br>
    유령은 선을 밟지 않는다. 이건 선을 울타리로 아는 발이다. 시험하는 발.`,
  o:[
    { l:'① 밟는 자리마다 선을 겹으로 덧그어 답을 준다.', k:'steady', dc:24, wake:1,
      ok:`밟은 자리를 따라가며 안쪽에 둘째 선을 그었다. 밟힌 만큼 두꺼워지는 울타리라고 답한 것이다.<br><br>그것은 원을 한 바퀴 돌며 열한 번 밟았고, 열한 군데가 다 겹줄이 됐다.<br>열두 번째 발은 오지 않았다. 시험한 만큼 단단해지는 울타리는 시험할 값이 없다.<br><br>어둠에 긋던 선과 짐승에 긋는 선은 다른 선이다. 짐승의 선은 대답을 해야 선다. 그 이치가 손에 들어왔다.`,
      ng:`덧긋는 사이 그것이 수를 바꿨다. 밟는 척하다가 가루를 발로 쓸어 흩었다.<br><br>한 뼘이 터졌다. 터진 데로 주둥이가 들어와 제일 가까운 배낭을 물고 나갔다.<br>배낭이 선 밖에서 갈가리 찢기는 소리를 다 들었다.<br><br>새벽까지 터진 뼘을 몸으로 막고 앉아 있었다. 선은 긋는 것보다 지키는 게 일이라는 걸, 여기 와서 배운다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 선에 마력을 올려 밟는 발바닥을 지진다.', k:'break', dc:25, cost:{ mana:30 },
      ok:`다음 발이 선을 밟는 순간 선 전체에 마력을 흘렸다. 가루가 하얗게 일어서며 발바닥을 지졌다.<br><br>살 타는 냄새와 함께 그것이 튀어 물러났다. 어둠 속에서 제 발을 핥는 소리.<br>그 뒤로 발소리는 원을 멀찍이 돌기만 했다. 아픈 울타리는 아픈 값을 기억하게 한다.<br><br>아침에 보니 선 밖에 발자국이 수없이 많았다. 밤새 돌았던 것이다. 아프고도 포기는 안 한 수다. 다음 밤은 다른 수로 올 것이다.`,
      ng:`마력을 올리는 반 숨 사이에 그것이 발을 뗐다. 빈 선만 하얗게 탔다.<br><br>가루가 타서 끊겼다. 제 손으로 제 울타리에 구멍을 낸 셈이다.<br>그것이 끊긴 자리로 곧장 들어왔다. 창든 동료들이 막는 사이 가루 주머니를 털어 선을 다시 이었다.<br><br>주머니가 반이 됐다. 지지는 수는 맞는 순간에만 수다. 빗나가면 제 울타리 값으로 치른다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S', t:'긴 복도 — 틀 없는 자리',
  x:`결계는 틀을 탄다. 문지방, 문틀, 기둥 사이. 틀이 있으면 반 품으로 서고, 없으면 세 품을 먹는다.<br><br>
    이 복도는 밋밋하다. 문도 기둥도 없이 스무 길. 그 끝에서 그것들이 오고 있다.<br>
    선 하나는 긋겠는데 틀이 없으니 금방 샐 것이다.<br><br>
    동료들이 복도 가운데서 이쪽 손끝만 보고 있다.`,
  o:[
    { l:'① 창 두 자루를 벽에 기대 세워 틀부터 만든다.', k:'fix', dc:24,
      ok:`창 두 자루를 복도 양벽에 비스듬히 세우고 꼭대기를 맞대 세모 틀을 만들었다. 문이다. 급조한 문.<br><br>그 틀에 선을 걸었다. 틀을 탄 결계는 단숨에 섰다.<br>달려온 것들이 세모 앞에서 콱 멈췄다. 없던 문이 생긴 복도를 이해 못 하는 걸음이었다.<br><br>틀은 꼭 나무틀 돌틀이 아니어도 된다. 기대 세운 창 두 자루면 충분하다. 세상 모든 것이 문설주가 될 수 있다.`,
      ng:`틀은 섰는데 창 한 자루가 바닥 물기에 미끄러졌다. 세모가 무너지며 결계가 꺼졌다.<br><br>맨 앞의 것이 그 순간을 놓치지 않았다. 무너진 창을 뛰어넘어 들어왔다.<br>동료들이 막는 사이 창을 다시 세우고 선을 다시 걸었다. 두 번째 틀은 창 밑동을 벽 틈에 박아 세웠다.<br><br>둘은 막았지만 하나가 들어온 뒤였다. 틀은 세우는 것보다 버티게 하는 게 일이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 틀 없이 세 품을 다 들여 맨 선을 세운다.', k:'steady', dc:25, cost:{ mana:36 },
      ok:`틀 없는 선은 술사가 틀이 되는 선이다. 복도 가운데 서서 양팔을 벌리고, 마력을 바닥 선에서 천장까지 끌어올렸다.<br><br>공기가 벽이 됐다. 달려온 것들이 보이지 않는 벽에 코를 박고 튕겼다.<br>세 품이 아니라 네 품이 나갔다. 팔이 떨리고 코피가 났다. 그래도 벽은 섰고, 그것들이 물러날 때까지 섰다.<br><br>틀이 없으면 몸이 틀이다. 그 값이 얼마인지도 함께 배웠다. 자주 쓸 수는 없는 수다.`,
      ng:`천장까지 올리다 마력이 중간에서 출렁였다. 벽의 윗단이 설었다.<br><br>그것들 중 뛰는 놈이 그 윗단을 넘었다. 결계 안쪽으로 떨어져 내렸다.<br>안에서 난장이 났다. 창 셋이 달라붙어 겨우 눕혔다.<br><br>선 벽은 아래보다 위가 어렵다. 눈에 안 보이는 높이는 마력도 못 미더워한다. 코피를 닦으며 그 높이를 외웠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-29, spirit:-17 } }
  ] },

{ at:'S', t:'잠자리 원 — 밤새 세는 수',
  x:`잘 자리에 원을 치고 다섯이 안에 들었다. 술사는 선 안쪽에 앉아 선을 지킨다.<br><br>
    밤이 깊자 건드림이 시작됐다. 톡. 선이 울린다. 반대쪽에서 톡. 가루 한 알이 튄다.<br>
    건드림마다 선의 힘이 티끌만큼 줄어든다. 아침까지 견디면 되는 줄다리기다.<br><br>
    문제는 건드리는 것이 하나가 아니라는 것. 울림의 결이 셋이다.`,
  o:[
    { l:'① 울림을 세며 줄어드는 힘만큼만 마력을 흘려 채운다.', k:'steady', dc:25,
      ok:`톡. 티끌만큼 샌다. 티끌만큼 채웠다. 톡. 또 채웠다.<br><br>많이 채우면 마력이 동나고 안 채우면 선이 삭는다. 새는 만큼만, 밤새 아흔두 번.<br>셋은 번갈아 건드리며 선이 마르기를 기다렸고, 선은 끝내 마르지 않았다. 동트기 전에 건드림이 끊겼다.<br><br>아침에 보니 선 둘레로 발자국이 세 겹 원을 그리고 있었다. 밤새 셋이 돈 것이다. 아흔두 번의 톡을 다 받아 낸 선은, 긋던 날보다 단단해 보였다.`,
      ng:`여든 번쯤에서 졸았다. 톡, 톡이 자장가가 됐다.<br><br>깨 보니 선 한 자락이 종잇장처럼 말라 있었다. 셋 중 하나가 마른 자락을 이빨로 물어 걷는 중이었다.<br>마력을 급히 쏟아 자락을 살렸다. 그것이 입에 가루를 묻힌 채 물러났다.<br><br>남은 밤은 혀를 깨물며 지켰다. 줄다리기에서 조는 쪽이 끌려간다. 선을 사이에 둔 줄다리기도 같다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 건드리는 셋 중 우두머리의 결을 찾는다.', k:'gaze', dc:24,
      ok:`울림 셋의 결을 갈랐다. 둘은 가볍고 잦다. 하나는 드물고 무겁다. 무거운 쪽이 어른이다.<br><br>어른 울림이 오는 자리만 지켜봤다. 어둠 속에 앉은 윤곽이 잡혔다. 다른 둘을 턱짓으로 부리고 있었다.<br>그 윤곽을 정면으로 마주 보고 앉았다. 보인다는 뜻으로. 한참 뒤 어른이 일어나 어둠으로 물러났다. 둘이 따랐다.<br><br>선 너머에도 자리가 있고 차례가 있다. 그걸 읽으면 셋이 아니라 하나만 상대하면 된다.`,
      ng:`결을 가르느라 선 채우기가 늦었다. 가벼운 둘이 그 틈에 한 자리를 집중해서 두드렸다.<br><br>그 자리가 뚫렸다. 머리 하나가 쑥 들어와 제일 가까운 동료의 담요를 물고 나갔다.<br>담요는 선 밖에서 갈가리 났다. 시위처럼.<br><br>남은 밤은 둘이 번갈아 선을 채웠다. 읽는 눈과 채우는 손은 같은 사람 몫이 아니어야 했다.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-17, spirit:-17 } },
    { l:'③ 선 밖으로 나가 건드리는 것을 쫓아 본다.', k:'luck', dc:26,
      doom:{ title:'선 밖은 저들의 땅', what:'선 밖에서 덮친 것들에게 끌려갑니다', dc:20, sec:40,
        text:`건드림이 뜸한 틈에 선을 열고 나섰다. 쫓아 버리면 밤이 편하다는 셈이었다.<br><br>선 밖 세 걸음에서 알았다. 뜸한 게 아니라 기다린 것이다. 톡, 톡은 꾀는 소리였다.<br>양옆에서 둘이 덮쳤다. 어깨와 다리를 하나씩 물려 어둠으로 끌려간다. 돌아보니 세 번째가 열린 선 앞에 서 있었다. 들어가지는 않고, 선이 닫히나 안 닫히나 보고만 있었다. 술사 없는 선이 어찌 되나 아는 눈이었다.`,
        dieText:`선은 새벽까지 버텼다. 긋고 간 사람 없이, 저 혼자.<br><br>동이 트자 가루가 바람에 날리기 시작했다. 동료들은 마르는 선 안에서 짐을 쌌다.<br>선 밖 어둠에 끌려간 자리는 찾지 못했다. 가루 주머니만 세 걸음 밖에 떨어져 있었다. 선을 긋는 손과 함께 갔어야 할 주머니였다.` },
      ok:`나가되 선을 닫고 나갔다. 등 뒤가 열린 채로는 한 걸음도 안 나간다.<br><br>횃불을 크게 돌리며 소리 질렀다. 숨고 재는 것들에게 제일 낯선 건 저보다 큰 소리다.<br>셋이 주춤 물러난 틈에 도로 선 안에 들었다. 쫓지는 못했다. 그래도 밤의 주도권이 반은 넘어왔다. 저쪽도 이쪽이 나올 수 있다는 걸 알았으니까.<br><br>남은 밤의 건드림은 눈에 띄게 뜸해졌다.`,
      win:{ exp:18, dream:3 } }
  ] },

{ at:'S', t:'빈 주머니 — 가루의 끝',
  x:`가루 주머니가 바닥을 보였다. 남은 건 두 원 치. 갈 길은 사흘이다.<br><br>
    결계 가루는 아무 데서나 안 나온다. 뼛가루, 소금, 말린 꽃. 다 떨어졌다.<br>
    여기는 여기의 재료가 있을 것이다. 결계란 본디 땅의 것을 빌려 긋는 금이니까.<br><br>
    어제 태운 그것의 뼈가 모닥불 자리에 하얗게 남아 있다.`,
  o:[
    { l:'① 그것들의 뼈를 갈아 가루에 섞어 본다.', k:'steady', dc:25, wake:1,
      ok:`태운 뼈를 돌로 갈아 남은 가루에 반씩 섞었다. 떨리는 손으로 시험 원을 긋고 마력을 흘렸다.<br><br>섰다. 서기만 한 게 아니다. 밤에 온 것들이 그 선 앞에서 유난히 멀리 돌았다. 저희 죽은 것의 냄새가 나는 선이다.<br>여기 것들에게는 여기 것들의 뼈가 제일 큰 금지였다.<br><br>사냥터의 결계는 사냥터에서 얻는다. 가루가 아니라 그 이치가 이번 길의 소득이다. 주머니는 다시 불룩해졌다. 하얗게.`,
      ng:`갈아 섞은 첫 원은 섰다. 둘째 원에서 탈이 났다. 덜 탄 뼛조각이 섞인 자리가 마력을 안 받는다.<br><br>밤에 그 자리로 작은 것이 스며들었다. 식량 자루 하나가 선 안에서 사라졌다.<br>선이 뚫린 게 아니라 선이 설었던 것이다.<br><br>아침에 뼈를 다시 골라 태우고 다시 갈았다. 빌리는 재료일수록 손질이 반이다. 설익은 결계가 제일 나쁜 결계다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 남은 두 원 치로 사흘을 나눠 쓰는 셈을 짠다.', k:'fix', dc:24,
      ok:`원을 포기했다. 원은 가루를 제일 많이 먹는 모양이다.<br><br>등 뒤가 바위면 반원, 바위 틈이면 입구에 한 줄. 자리를 가려 가루를 아끼는 셈을 짰다.<br>사흘 밤을 반원 하나, 줄 둘로 났다. 가루는 오히려 반의 반이 남았다.<br><br>결계는 가루가 긋는 게 아니라 자리가 긋는 것이었다. 좋은 자리는 반 줌으로도 성이 되고, 나쁜 자리는 한 주머니로도 모자란다.`,
      ng:`셈은 좋았는데 둘째 밤 자리가 글렀다. 바위인 줄 알았던 등 뒤에 위로 도는 길이 있었다.<br><br>그것이 바위를 돌아 위에서 내려왔다. 반원은 등 뒤를 못 막는다.<br>동료 창이 받아 내는 사이 급히 가루를 뿌려 머리 위를 막았다. 아껴 둔 가루가 거기서 다 나갔다.<br><br>아낀 셈이 하룻밤에 무너졌다. 자리 보는 눈이 셈보다 먼저여야 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'이동 결계 — 걷는 원',
  x:`트인 땅을 지나야 한다. 숨을 데가 없고, 그것들의 땅이다. 멈춰서 긋는 원은 여기선 과녁이다.<br><br>
    스승이 말로만 가르친 수가 있다. 걷는 원. 일행의 걸음에 맞춰 원이 함께 걷는 결계.<br>
    마력이 밑 빠진 독처럼 나가서 아무도 안 쓰는 수라고 했다.<br><br>
    트인 땅 저쪽에서 코 드는 소리들이 났다. 독을 채울 때다.`,
  o:[
    { l:'① 걷는 원을 편다 — 밑 빠진 독에 마력을 붓는다.', k:'steady', dc:26, cost:{ mana:38 }, wake:1,
      ok:`가루를 원으로 뿌리고 그 원을 마력으로 들었다. 일행 발에 맞춰 원이 끌려온다. 걸음마다 마력이 줄줄 샌다.<br><br>반쯤 건넜을 때 그것들이 왔다. 와서, 걷는 원 둘레를 따라 걸었다. 넘을 수 없는 울타리가 먹이와 같은 속도로 움직이는 것을 저들 머리로는 셈할 수 없었다.<br>트인 땅 끝까지 울타리와 짐승 떼가 나란히 걸었다. 기괴한 행렬이었다.<br><br>건너편 바위에 닿아 원을 접었다. 무릎이 꺾였다. 밑 빠진 독이 맞다. 그래도 독은 독이다. 물을 길어 부을 수 있는 동안은 성이다.`,
      ng:`반을 건너기 전에 마력이 바닥을 긁었다. 원이 걸음을 못 따라오고 뒤로 처졌다.<br><br>원과 일행 사이가 벌어진 그 틈을 한 놈이 파고들었다. 맨 뒤의 동료가 등을 긁혔다.<br>원을 버리고 전력으로 뛰었다. 바위까지 백 걸음이 십 리 같았다.<br><br>걷는 원은 거리를 반으로 접고 시작해야 하는 수였다. 독의 깊이를 재고 물을 길었어야 했다.`,
      win:{ exp:23, dream:4 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 원 대신 뒤만 막는 호를 끌며 간다.', k:'evade', dc:25, cost:{ mana:28 },
      ok:`온 원은 못 끌어도 반달 호는 끌 만하다. 일행 등 뒤에만 호를 걸고 트인 땅을 내달렸다.<br><br>쫓는 것들은 뒤에서 온다. 뒤가 막혀 있으면 옆으로 돌아야 하고, 도는 동안 거리가 벌어진다.<br>세 번 돌림을 당한 그것들이 네 번째에 쫓기를 접었다.<br><br>다 막을 수 없으면 올 길만 막는다. 마력은 반, 효과는 그때그때. 오늘은 그걸로 충분했다.`,
      ng:`호를 끌며 뛰는데 땅이 꺼진 데서 호가 걸렸다. 마력 줄이 당겨지며 이쪽 걸음도 같이 꺾였다.<br><br>넘어진 사이 호가 흩어졌다. 맨몸으로 남은 거리를 뛰었다.<br>제일 빠른 놈이 바위 바로 앞까지 따라붙었다. 동료가 바위 위에서 던진 돌이 그 콧등을 때려 줬다.<br><br>끄는 결계는 땅을 가린다. 땅부터 읽고 걸었어야 했다. 결계술사도 발밑은 눈으로 봐야 한다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S', t:'소리 그릇 — 비명을 담다',
  x:`동료가 덫 가시에 허벅지를 꿰였다. 뽑아야 산다. 뽑으면 비명이 난다.<br><br>
    여기서 비명은 종소리다. 사방 어둠이 다 듣는다.<br>
    재갈을 물려도 새는 소리는 샌다. 생살에서 가시를 뽑는 소리는 이 사이로 나온다.<br><br>
    결계는 본디 막는 재주다. 들어오는 것만 막으라는 법은 없다.`,
  o:[
    { l:'① 소리를 가두는 반구를 치고 그 안에서 뽑는다.', k:'steady', dc:25, cost:{ mana:30 },
      ok:`둘레에 좁은 원을 긋고 마력을 안쪽으로 접었다. 밖을 막는 결이 아니라 안을 담는 결. 소리의 그릇이다.<br><br>그릇 안에서 가시를 뽑았다. 동료는 실컷 비명을 질렀다. 지르라고 했다. 참는 힘까지 아픈 데 쓰라고.<br>그릇 밖은 바람 소리뿐이었다. 어둠은 아무것도 못 들었다.<br><br>결계를 뒤집어 쓰는 법을 하나 얻었다. 막는 벽과 담는 그릇은 같은 선의 앞뒤다.`,
      ng:`그릇을 접는 손이 설었다. 뽑는 순간의 비명 한 가닥이 샜다.<br><br>짧은 한 가닥. 그래도 어둠은 들었다. 사방에서 걸음들이 모여드는 기척.<br>동료를 들쳐 업고 자리를 떴다. 뽑은 자리를 싸맬 틈도 없이 반 식경을 걸었다.<br><br>그릇은 소리가 제일 큰 순간에 제일 두꺼워야 했다. 거꾸로 했다. 다음엔 안 그럴 것이다.`,
      win:{ exp:21, dream:3, hp:5 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 멀리 미끼 소리를 만들어 귀를 그쪽에 판다.', k:'luck', dc:25,
      ok:`빈 수통에 마력 한 올을 묶어 바위 너머로 던졌다. 수통이 구르며 요란하게 울게.<br><br>어둠의 귀들이 일제히 그쪽으로 쏠렸다. 그 틈에 가시를 뽑았다. 비명은 수통 소리에 묻혔다.<br><br>소리로 소리를 덮는 수다. 결계 가루 한 톨 안 들었다. 스승이 들었으면 그게 무슨 결계냐 했겠지만, 산 사람이 이긴 셈이다.`,
      ng:`수통이 바위에 걸려 두 번 구르고 말았다. 미끼 소리가 너무 짧았다.<br><br>가시는 반만 뽑힌 채 비명이 났다. 귀들이 되돌아왔다. 이쪽으로.<br>업고 뛰면서 남은 반을 뽑았다. 제일 나쁜 방식으로.<br><br>미끼는 오래 울어야 미끼다. 던지기 전에 구를 길을 봤어야 했다. 운에 맡긴 미끼는 미끼가 아니라 소음이다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S', t:'두 개의 원 — 비어 있는 쪽',
  x:`밤마다 원 하나로 버티는 데도 한계가 있다. 그것들이 원을 외우기 시작했다. 어디가 이음매인지, 몇 번 건드리면 술사가 지치는지.<br><br>
    오늘은 원을 둘 그린다. 하나는 빈터 가운데, 환하게. 하나는 바위 그늘에, 어둡게.<br>
    환한 원 안에는 입다 벗은 겉옷들을 사람 모양으로 앉힌다.<br><br>
    외우는 머리에는 거짓을 먹이는 법이다.`,
  o:[
    { l:'① 빈 원에 마력을 절반 흘려 사람 기척을 입힌다.', k:'steady', dc:25, wake:1,
      ok:`빈 원에 마력을 흘리되 사람 숨 장단으로 흘렸다. 들숨 날숨. 다섯 명 치를.<br><br>그것들이 밤새 빈 원을 포위하고 건드리고 재고 두드렸다. 어두운 진짜 원은 거들떠도 안 봤다.<br>새벽에 그것들이 빈 원을 마침내 뚫었을 때, 안에는 겉옷 다섯 벌뿐이었다.<br><br>어리둥절한 울음을 들으며 일행은 이미 반 식경 밖을 걷고 있었다. 결계는 막는 재주인 줄만 알았다. 속이는 재주이기도 하다. 선 안에 무엇이 있다고 믿게 하는 것, 그것도 결계다.`,
      ng:`숨 장단이 중간에 흐트러졌다. 다섯 숨이 한 숨으로 겹친 순간이 있었다.<br><br>어른 격인 놈이 그 겹침을 알아챘다. 빈 원을 버리고 고개를 돌려 어두운 쪽을 봤다.<br>밤새 진짜 원이 시달렸다. 미끼에 쓴 마력이 아까운 밤이었다.<br><br>거짓 숨은 진짜 숨보다 어렵다. 제 숨부터 다섯으로 나누는 연습이 필요했다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-15 } },
    { l:'② 빈 원은 공으로 두고 진짜 원을 바위에 바싹 숨긴다.', k:'hide', dc:24,
      ok:`빈 원은 가루만 둥글게 치고 비워 뒀다. 마력 한 톨 없이. 대신 진짜 원을 바위 그늘에 바싹 붙이고 선을 숯으로 그어 어둠에 녹였다.<br><br>그것들은 빈 원을 반 바퀴 돌다 흥미를 잃었다. 냄새가 없는 원이라서.<br>대신 밤새 빈터를 헤집고 다녔다. 사람 냄새의 꼬리를 찾아서. 바위 그늘까지는 바람이 막아 줬다.<br><br>미끼에도 급이 있다. 공들인 미끼보다 나은 게 바람 읽고 둔 빈 미끼일 때가 있다.`,
      ng:`숯 선이 문제였다. 숯은 마력을 설게 탄다. 새벽녘에 선 한 자락이 저 혼자 식었다.<br><br>지나가던 작은 것이 그 자락을 밟고 들어왔다. 침낭 사이를 밟고 다니는 걸 막내가 느끼고 소리쳤다.<br>난리 통에 쫓아내긴 했다.<br><br>어둠에 녹는 선은 마력도 설게 받는다. 숨기는 값과 버티는 값, 둘을 같이 셈해야 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-25, mind:-16 } }
  ] },

{ at:'S', t:'보는 자리 — 외우는 눈',
  x:`한밤에 선 밖 바위에 그것이 앉았다. 건드리지 않는다. 보기만 한다.<br><br>
    눈이 선을 따라간다. 천천히, 한 자락씩. 이음매에서 오래 멈춘다.<br>
    외우는 것이다. 선을. 내일 밤이나 모레 밤을 위해서.<br><br>
    외우게 둘 것인가, 못 외우게 할 것인가.`,
  o:[
    { l:'① 그것이 보는 동안 선을 조금씩 계속 바꾼다.', k:'steady', dc:25,
      ok:`보는 눈앞에서 선을 고쳤다. 이음매를 옮기고, 두껍던 데를 얇게, 얇던 데를 두껍게.<br><br>외우는 족족 틀린 답이 되게. 그것은 밤새 보고 이쪽은 밤새 고쳤다.<br>새벽에 그것이 일어나며 바위를 발톱으로 한 번 긁었다. 짜증의 소리였다.<br><br>외우는 머리와는 바꾸는 손으로 겨룬다. 산 결계는 외워지지 않는다. 선은 긋고 끝나는 게 아니라 기르는 것이다.`,
      ng:`밤새 고치다 이쪽이 먼저 지쳤다. 새벽녘 손이 둔해진 때, 고친 자리들이 눈에 다 들어왔을 것이다.<br><br>이튿날 밤 그것들이 왔다. 고치던 버릇까지 외운 공격이었다. 이쪽이 선을 고치는 왼쪽부터 쳤다.<br>겨우 막았지만 가루를 평소 배로 썼다.<br><br>바꾸는 수도 버릇이 되면 외워진다. 버릇 없이 바꾸는 법은 아직 손에 없다. 숙제가 생겼다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-19, spirit:-16 } },
    { l:'② 선 한 자락을 일부러 얇게 틔워 그쪽으로 꾄다.', k:'gaze', dc:25,
      ok:`외우는 눈에 답을 하나 줬다. 동쪽 자락을 눈에 띄게 얇게 틔운 것이다.<br><br>모레 밤 그것들은 과연 동쪽으로 왔다. 외운 대로.<br>얇은 자락 안쪽에는 둘째 선이 기다리고 있었다. 두 선 사이에 낀 첫 놈이 불꽃에 그을려 내뺐고 나머지는 따라 돌아섰다.<br><br>외우는 적에게는 외울 것을 준다. 거짓 답안지를. 선생 노릇은 이쪽이 한다.`,
      ng:`얇은 자락을 너무 그럴듯하게 틔웠다. 모레가 아니라 그 밤에 바로 왔다.<br><br>둘째 선을 아직 안 깔았을 때였다. 얇은 자락이 진짜로 뚫렸다.<br>난전 끝에 몰아내긴 했지만 식량 자루 하나와 담요 둘을 잃었다.<br><br>덫은 완성되기 전엔 문이다. 파는 날과 여는 날을 따로 잡았어야 했다.`,
      win:{ exp:19, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'③ 나가서 보는 놈을 쫓는다 — 외우기 전에.', k:'break', dc:26,
      doom:{ title:'보는 놈의 셈', what:'바위 뒤에 숨어 있던 것들에게 끌려갑니다', dc:20, sec:40,
        text:`선을 열고 나가 바위를 향해 내달렸다. 보는 놈이 달아나지 않는다. 그게 이상하다는 생각은 반 걸음 늦었다.<br><br>보는 놈은 미끼이기도 했다. 바위 뒤 어둠에서 둘이 나왔다.<br>양팔을 하나씩 물렸다. 끌려가며 보니 보는 놈은 그대로 바위에 앉아 있었다. 이제 선이 아니라 선 안에 남은 동료들을 보고 있었다. 술사 없는 선이 몇 밤이나 가는지 외우려는 눈으로.`,
        dieText:`선은 이틀 밤을 버티고 사흘째에 말랐다.<br><br>동료들은 선이 마르기 전에 떠났다. 바위 위의 눈이 그 등을 배웅했다.<br>그 뒤 이 땅의 결계술사들 사이에 말이 하나 돈다. 보는 놈은 눈이 둘이 아니다. 뒤에 몇이 더 보고 있는지 세기 전엔 선을 열지 마라.` },
      ok:`나가되 곧장 안 갔다. 선 안에서 횃불 두 개에 마력을 실어 바위 양옆 어둠부터 밝혔다.<br><br>양옆에 둘이 웅크리고 있었다. 보는 놈까지 셋. 숨은 둘이 드러나자 보는 놈이 먼저 일어나 물러났다.<br>셋이 함께 어둠으로 꺼졌다.<br><br>쫓지 않고 선을 더 둘렀다. 외우는 눈 뒤에는 무는 이빨이 있다. 그 셈을 등불이 대신 치러 줬다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'옛 원 — 먼저 그은 사람',
  x:`바위 그늘에서 옛 결계 자국을 찾았다. 가루는 삭았지만 긋던 결은 남아 있다. 솜씨가 좋다. 이쪽보다 윗길이다.<br><br>
    원은 반만 남았다. 반은 긁혀 없어졌다.<br>
    긁힌 쪽에 가루가 쓸려 나간 방향이 보인다. 안에서 밖이 아니다. 밖에서 안으로.<br><br>
    윗길 솜씨도 뚫린 밤이 있었다는 뜻이다.`,
  o:[
    { l:'① 뚫린 쪽의 긁힘을 읽어 그날 밤을 되그린다.', k:'gaze', dc:25,
      ok:`긁힘은 세 겹이다. 먼저 잔 발톱이 가루를 흩고, 다음 큰 발이 결을 밟아 끊고, 마지막에 몸통이 쓸고 들어갔다.<br><br>작은 것들이 선을 허는 앞잡이다. 큰 것은 허문 데로만 온다.<br>그렇다면 선은 큰 것 기준이 아니라 작은 것 기준으로 촘촘해야 한다. 이쪽 원의 코가 너무 성겼다는 걸 남의 원에서 배웠다.<br><br>그날 밤부터 선을 잘게 겹쳐 그었다. 작은 것들이 몇 번 왔다가 코가 안 들어가는 선 앞에서 돌아갔다.`,
      ng:`긁힘을 읽느라 원 안쪽을 늦게 봤다. 안쪽 바위 틈에 그 밤의 임자가 아직 산다는 걸.<br><br>잔 것들이 틈에서 쏟아져 나왔다. 옛 원은 사냥터가 된 지 오래였고, 읽으러 온 이쪽이 오늘 사냥감이었다.<br>뿌리치고 나오며 팔뚝을 여럿 물렸다.<br><br>죽은 결계는 비석이 아니라 덫 자리다. 읽을 땐 등 뒤부터 세워 두고 읽어야 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 남은 반원을 살려 이어 쓴다.', k:'steady', dc:25,
      ok:`삭은 결 위에 새 가루를 겹쳐 긋고 마력을 흘렸다. 옛 결이 새 마력을 기억처럼 받아들였다.<br><br>반 품으로 온전한 원이 섰다. 윗길 솜씨의 결을 따라 긋는 동안 손이 그 결을 배웠다. 이음매를 바위 틈에 묻는 법, 선 굵기를 바람 따라 바꾸는 법.<br><br>얼굴도 모르는 선배의 원에서 하룻밤을 잤다. 결계술사의 유산은 책이 아니라 땅에 남는다. 이어 그은 원이 수업료 없는 수업이었다.`,
      ng:`옛 결이 새 마력을 받다가 중간에 퉁겼다. 삭은 결과 새 가루의 결이 안 맞는 자리가 있었다.<br><br>그 자리가 밤에 식었다. 식은 데로 바람처럼 작은 것이 들었다.<br>수통 하나를 물고 나가는 걸 쫓아내고, 식은 자리를 제 결로 다시 그었다.<br><br>남의 결은 빌리는 것이지 믿는 게 아니다. 이음새마다 제 손을 거쳐야 제 원이다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-17, spirit:-15 } }
  ] },

{ at:'S', t:'상처 둘레 — 제일 작은 원',
  x:`동료가 물렸다. 이빨 자국 둘레가 검게 번진다. 독인지 균인지 모르지만 번지는 건 분명하다.<br><br>
    치유사가 없는 조다. 약초는 번짐을 못 따라잡는다.<br>
    결계는 넘는 것을 막는 금이다. 살갗 위라고 못 그을 것 없다.<br><br>
    제일 작은 결계를 그릴 시간이다.`,
  o:[
    { l:'① 상처 둘레 살갗에 손가락으로 원을 그어 마력을 건다.', k:'heal', dc:25, cost:{ mana:26 },
      ok:`재를 갠 물에 손끝을 적셔 이빨 자국 둘레로 동전만 한 원을 그었다. 마력을 가늘게, 오래 걸었다.<br><br>검은 번짐이 원 안에서 맴돌았다. 금을 못 넘는다.<br>번짐이 갇힌 사이 약초 뭉치를 짓이겨 원 안에만 발랐다. 갇힌 적은 약도 빨리 잡는다.<br>사흘 뒤 원 안쪽 살이 아물며 원 자국도 흐려졌다.<br><br>성을 지키는 결계나 살 한 뼘을 지키는 결계나 이치는 하나였다. 금 안의 것을 지킨다.`,
      ng:`원은 섰는데 너무 바싹 그었다. 번짐이 원에 눌려 안으로 곪았다.<br><br>밤새 동료가 열에 떴다. 원을 반 치 넓혀 다시 긋고 곪은 것을 짜냈다.<br>동료는 이틀을 앓고야 일어났다.<br><br>가두는 금은 숨 쉴 틈을 두고 긋는 것이다. 성이든 살이든. 급한 손이 금을 너무 조였다.`,
      win:{ exp:21, dream:3, hp:6 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 입으로 빨고 불로 지지는 옛법을 쓴다.', k:'steady', dc:24,
      ok:`결계고 뭐고 번짐이 너무 빨랐다. 옛법대로 했다. 입으로 빨아 뱉고, 칼날을 달궈 짧게 지졌다.<br><br>동료가 이를 악물고 받았다. 번짐이 지진 자리에서 멎었다.<br>그 위에 그제야 작은 원을 걸었다. 멎은 것을 굳히는 원이다.<br><br>술보다 손이 먼저일 때가 있다. 술사의 자존심은 동료 살보다 가볍다.`,
      ng:`빨아 뱉는 사이 입술이 얼얼해졌다. 독 기운이 이쪽 입에도 옮은 것이다.<br><br>혀가 반나절 굳어 주문이 샜다. 결계 없는 반나절을 창병들이 배로 뛰며 메꿨다.<br><br>동료 번짐은 멎었으니 반은 성공이다. 다만 술사의 입은 연장이다. 연장을 거는 일은 마지막 수였어야 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'열리는 금 — 문지기의 손',
  x:`앞서 정찰 나간 동료가 쫓겨 돌아온다. 뒤에 그것들이 바싹 붙었다.<br><br>
    원은 닫혀 있다. 열어야 동료가 들어온다. 열면 뒤따르는 것들도 들어온다.<br>
    닫힌 채 두면 동료는 원 앞에서 잡힌다.<br><br>
    여는 때와 닫는 때. 그 사이는 반 숨이다. 문지기의 반 숨.`,
  o:[
    { l:'① 동료의 발이 금을 넘는 반 숨에 맞춰 열고 닫는다.', k:'steady', dc:26, wake:1,
      ok:`동료의 걸음을 셌다. 다섯 걸음 앞에서 금 한 자락의 마력을 거뒀다. 문이 열렸다.<br><br>동료 발이 금을 넘는 순간, 거뒀던 마력을 내리꽂았다. 문이 닫혔다.<br>코앞까지 따라붙었던 놈이 닫힌 금에 정면으로 부딪혔다. 하얀 불꽃이 일고 그것이 나동그라졌다.<br><br>여닫는 것이 결계의 꽃이라던 스승 말이 그제야 몸으로 왔다. 벽은 아무나 세운다. 문은 문지기라야 연다. 반 숨짜리 문을 쥔 손이 생겼다.`,
      ng:`반 숨이 길었다. 동료 뒤 반 걸음에 붙었던 놈의 머리가 같이 들어왔다.<br><br>닫히는 금이 그 목을 조였다. 몸통은 밖, 머리는 안. 그것이 발버둥 치며 금 전체가 출렁였다.<br>창이 두 번 내리꽂히고서야 조용해졌다. 금은 한참을 떨다 가라앉았다.<br><br>문지방에 낀 것만큼 문을 흔드는 게 없다. 여는 폭을 사람 하나 치로 좁히는 연습이 필요하다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 금 밖으로 마중 나가 등을 맡아 준다.', k:'bond', dc:25,
      ok:`문지기 자리를 둘째 술수 아는 동료에게 맡기고 금 밖으로 나섰다. 횃불 두 개를 양손에 들고.<br><br>쫓기는 동료와 어깨를 스치며 교차했다. 이쪽은 불을 크게 돌리며 뒤의 것들 앞을 한 번 막아섰다.<br>반 숨 멈칫한 사이 동료가 금을 넘었고, 이쪽도 뒷걸음으로 넘었다. 문은 둘째가 닫았다.<br><br>문지기가 꼭 문 안에 있어야 하는 건 아니다. 믿을 손이 안에 있다면.`,
      ng:`마중은 나갔는데 뒤의 것들이 둘로 갈라졌다. 하나는 동료를, 하나는 이쪽을 물었다.<br><br>횃불로 후려치며 물러나는데 금이 등에 닿았다. 둘째가 여닫는 때를 못 잡아 금이 닫힌 채였다.<br>금 밖에서 두 놈을 상대로 다섯 숨을 버텼다. 금이 열린 건 여섯 숨째였다.<br><br>어깨와 옆구리가 길게 긁혔다. 문 열 손을 밖에서 믿는 건 외줄이다. 다음엔 신호부터 정하고 나간다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-32, spirit:-16 } }
  ] },

{ at:'S1', t:'환풍구 여섯 — 막을 하나',
  x:`묵을 방에 환풍구가 여섯이다. 가루는 넉넉잖다. 여섯을 다 막으면 내일 밤이 빈다.<br><br>
    관으로 다니는 것들이라고 모든 관으로 다니는 건 아니다. 다니는 관은 정해져 있다.<br>
    덮개마다 들여다봤다. 다섯은 먼지가 소복하다. 하나만 먼지가 없다. 반질반질하다.<br><br>
    먼지는 거짓말을 안 한다.`,
  o:[
    { l:'① 반질한 구멍 하나에만 가루를 다 건다.', k:'steady', dc:24, wake:1,
      ok:`반질한 덮개 둘레에만 겹으로 금을 치고 마력을 걸었다. 나머지 다섯은 맨 덮개로 뒀다.<br><br>밤중에 관 속을 기어 온 것이 금 걸린 덮개 안쪽에서 멈췄다. 긁고, 밀고, 안 되니 돌아갔다.<br>다른 관으로 돌아올까 귀를 세웠지만 오지 않았다. 다니던 길이 막히면 그 밤은 접는 것들이다. 길눈이 밝은 대신 길을 바꾸는 데는 둔하다.<br><br>여섯 구멍이 다 문은 아니다. 쓰는 문 하나를 찾는 눈이 가루 다섯 몫을 아꼈다.`,
      ng:`반질한 구멍은 맞게 짚었다. 못 짚은 건 그 관이 두 갈래라는 것.<br><br>막힌 것이 관 속에서 갈래를 꺾어 옆방으로 나왔다. 옆방과 이 방 사이 문은 맨 문이었다.<br>문을 긁는 소리에 밤잠이 다 달아났다. 가구를 쌓아 막고 아침까지 버텼다.<br><br>관은 구멍이 아니라 길이다. 길은 갈래까지 세어야 막은 것이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 다섯 구멍에 재를 얇게 발라 덫 표식을 만든다.', k:'sense', dc:24,
      ok:`막는 대신 알게 만들었다. 다섯 덮개 안쪽 턱에 재를 얇게 발랐다. 지나가면 자국이 남게.<br><br>아침에 확인하니 재 밟은 자국이 둘째 구멍에 나 있었다. 들어오다 만 자국이다. 발 두 개 깊이.<br>이 방은 둘째 관과도 통한다는 걸 하룻밤 자며 배웠다.<br>다음 밤부터 가루는 반질한 것과 둘째, 두 구멍에 갈라 걸었다.<br><br>결계는 밤을 막고, 재는 다음 밤을 가르쳐 준다.`,
      ng:`재를 바르다 둘째 덮개를 건드렸다. 나사가 헐거웠던 덮개가 떨어져 쇳소리를 냈다.<br><br>관 저쪽에서 쇳소리의 메아리가 돌아왔다. 메아리가 아니라 대답이었다.<br>그 밤은 구멍 여섯을 다 등지고 방 한가운데 모여 새웠다. 가루는 바닥났고 재주는 소리에 묻혔다.<br><br>덫을 놓는 손은 덫보다 조용해야 한다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S1', t:'삭은 바닥 — 산이 먹는 금',
  x:`밤 자리를 치려는데 가루 금이 서질 않는다. 바닥이 산성 피에 삭은 자리다. 가루가 닿는 족족 부글거리며 녹는다.<br><br>
    방을 옮길 시간은 없다. 복도의 발소리가 점점 잦아진다.<br>
    삭은 바닥을 들여다봤다. 산이 지나간 자리가 골을 팠다. 얕은 도랑처럼.<br><br>
    금을 못 긋는 바닥이 금을 파 놓고 기다리고 있었다.`,
  o:[
    { l:'① 산이 판 골에 마력을 직접 부어 금으로 삼는다.', k:'steady', dc:25, wake:1,
      ok:`가루 없이 갔다. 산이 판 골을 손끝으로 따라가며 마력을 부었다. 골이 마력을 물처럼 받았다.<br><br>파인 금은 그어진 금보다 깊다. 바닥 자체가 결계가 됐다.<br>밤에 온 것들이 골 앞에서 멈췄다. 저희 피가 판 골이 저희를 막았다.<br><br>재료가 없으면 지형이 재료다. 산은 금을 지우는 게 아니라 파기도 한다는 것. 적의 피가 남긴 상처가 이쪽 성벽이 된 밤이었다.`,
      ng:`골에 마력을 붓는데 골이 중간에 끊겨 있었다. 끊긴 데를 마력만으로 잇자니 허공에 긋는 금이라 헐거웠다.<br><br>밤중에 그 헐거운 데가 뚫렸다. 작은 것 하나가 들어와 한바탕 소동이 났다.<br>쫓아낸 뒤 끊긴 골을 칼끝으로 마저 파서 이었다. 손가락 두 마디 깊이.<br><br>빌린 지형은 끝까지 걸어 봐야 한다. 끊긴 다리인 줄 모르고 건너는 수가 있다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 바닥을 버리고 벽과 천장에 금을 건다.', k:'fix', dc:25,
      ok:`바닥이 안 받으면 바닥을 안 쓴다. 벽 허리 높이에 수평으로 금을 두르고, 모서리마다 천장까지 기둥 금을 세웠다. 새장을 거꾸로 씌운 모양이다.<br><br>바닥으로 기는 것은 벽 금 아래로 머리를 들이밀다 턱이 걸렸다. 기는 몸은 바닥에서 머리 하나는 든다. 그 높이에 금이 있었다.<br><br>금은 꼭 땅에 긋는 것이라는 생각부터가 버릇이었다. 성은 바닥이 아니라 둘레다.`,
      ng:`벽 금은 섰는데 천장 기둥 금 하나가 배관에 가려 설었다.<br><br>관을 타고 온 것이 그 설은 기둥 틈으로 내려왔다. 천장에서 떨어지는 건 금이 아니라 창이 받았다.<br>동료 창대가 부러지고 이쪽 어깨가 긁혔다.<br><br>새장은 살 하나만 빠져도 새장이 아니다. 가린 자리일수록 손으로 더듬어 확인했어야 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S1', t:'격리 원 — 사람을 가두는 금',
  x:`일행이 구한 연구원의 가슴이 수상하다. 숨과 가슴의 박자가 어긋난다. 안에 든 것이 있다.<br><br>
    두고 갈 수는 없다고 동료들이 말한다. 데려갈 수도 없다. 터지는 때를 모르니까.<br>
    남은 수는 하나다. 가두는 금. 밖을 막던 재주로 안을 막는다.<br><br>
    연구원도 안다는 눈으로 원 한가운데 앉았다.`,
  o:[
    { l:'① 이중 원을 치고 그 곁에서 밤을 지킨다.', k:'steady', dc:26,
      doom:{ title:'터진 금', what:'원을 깨고 나온 것에 관 속으로 끌려갑니다', dc:20, sec:35,
        text:`원을 둘 겹치고 곁에 앉아 밤을 지켰다. 연구원이 고맙다고, 미안하다고 번갈아 말했다.<br><br>새벽에 그가 기침을 시작했다. 가슴이 안에서 열렸다. 나온 것이 첫 원에 부딪혀 튕겼다.<br>둘째 원을 믿고 다가간 것이 실수였다. 그것은 벽에 부딪히며 배우는 것이었다. 두 번째 몸부림이 두 원의 같은 자리를 꿰뚫었다.<br>목에 감긴 그것이 바닥을 끌고 관 쪽으로 간다. 뒤에서 빈 가슴의 연구원이 원 안에 고요히 앉아 있는 게 보였다. 금은 사람만 가뒀다.`,
        dieText:`이중 원은 가운데가 뚫린 채 남았다. 뚫린 모양이 작고 둥글었다.<br><br>동료들이 원 자국을 지우고 연구원을 묻었다. 가슴이 빈 채였지만 얼굴은 편안했다.<br>관 덮개는 쇠판을 덧대 박았다. 안에서 밤마다 덮개 두드리는 소리가 났다는 말은, 그 뒤에 온 조가 전했다.` },
      ok:`원을 둘 치되 사이를 세 걸음 벌렸다. 첫 원은 가두고 둘째 원은 받는 원이다.<br><br>새벽에 그의 가슴이 열렸다. 나온 것이 첫 원에 갇혀 튀고 부딪고 뒹굴었다.<br>부딪히며 배우는 것이라, 첫 원이 터지기는 했다. 그러나 둘째 원까지 세 걸음을 건너는 동안 창 둘이 기다리고 있었다.<br><br>연구원은 끝까지 원 안에 앉아 있었다. 마지막에 이쪽을 보고 고개를 끄덕였다. 금이 그를 가둔 게 아니라 지켜 준 것이라고, 그렇게 믿기로 했다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 가슴의 것이 자리 잡은 깊이를 응시로 가늠한다.', k:'gaze', dc:25,
      ok:`원을 긋기 전에 그를 오래 봤다. 숨이 어긋나는 깊이, 박동이 밀리는 자리.<br><br>아직 얕다. 뿌리가 덜 내렸다. 표본실 기록에 있던 냉동 처치가 통할 깊이다.<br>그를 냉동고로 데려가 재웠다. 금은 냉동고 문 둘레에 둘렀다. 가두는 금이 아니라 지키는 금을.<br><br>구하러 온 사람들이 언젠가 이 문을 열 것이다. 그때까지 버틸 금으로 세 겹을 둘렀다.`,
      ng:`들여다보는 이쪽 눈을 가슴속 것이 마주 봤다. 그런 느낌이 왔다. 보는 순간 그것이 빨라졌다.<br><br>응시가 재촉이 된 것이다. 연구원이 가슴을 쥐고 꺾였다.<br>급히 원을 둘렀다. 반 숨 차이로 금이 먼저 섰다.<br><br>원 안의 일은 원 밖에서 다 보였다. 밤새 아무도 그쪽을 안 보려 애썼다. 보는 재주가 늘 이로운 건 아니었다.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-19, spirit:-18 } }
  ] },

{ at:'S1', t:'에어록 — 겹문의 이치',
  x:`에어록을 통과해야 한다. 문이 둘, 그 사이에 작은 방. 겹문이다.<br><br>
    결계술사 눈에 에어록은 낯익다. 이중 원과 같은 이치다. 바깥 금이 뚫려도 안 금이 받는다.<br>
    문제는 안쪽 문이 고장이라 양쪽이 한꺼번에 열린다는 것. 겹문이 홑문이 된 상태다.<br><br>
    복도 끝에서 발톱 소리가 골랐다. 이쪽을 재는 소리다.`,
  o:[
    { l:'① 고장 난 안문 자리에 금의 문을 세운다.', k:'steady', dc:25, cost:{ mana:29 },
      ok:`안문 문틀에 가루를 두르고 마력을 걸었다. 쇠문이 섰던 자리에 금의 문이 섰다. 틀이 좋아 반 품에 섰다.<br><br>다섯이 바깥문을 열고 사이 방에 들자, 과연 그것이 따라 들어왔다. 바깥문이 닫히기 전에.<br>사이 방에서 그것과 다섯이 마주 섰다. 그것과 안쪽 사이에는 보이지 않는 문.<br>그것이 금의 문에 부딪히는 사이 바깥문을 다시 열어 줬다. 그것은 제가 온 어둠으로 뛰쳐 돌아갔다.<br><br>겹문의 이치는 쇠가 아니라 겹에 있다. 한 겹을 금으로 메우면 겹문은 겹문이다.`,
      ng:`금의 문은 섰는데 사이 방 천장을 안 봤다. 환풍구가 사이 방에도 있었다.<br><br>그것 말고 작은 것이 천장에서 사이 방으로 떨어졌다. 금의 문 안쪽으로.<br>좁은 방에서 다섯과 작은 것이 엉켰다. 겨우 밟아 잡았지만 둘이 물렸다.<br><br>문은 벽의 일부다. 벽에 구멍이 있으면 문이 아무리 좋아도 소용없다. 천장도 벽이다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 문 기계를 손봐 여닫는 순서를 되살린다.', k:'fix', dc:25,
      ok:`조작반을 열어 보니 선 하나가 녹아 붙어 양 문이 한 회로가 돼 있었다. 녹은 데를 끊고 따로 이었다.<br><br>바깥문, 닫힘. 안문, 열림. 쇠가 제 순서를 되찾았다.<br>겹문이 제 발로 서니 금 없이도 방이 하나 벌렸다. 가루와 마력이 고스란히 남았다.<br><br>술사의 일은 금을 긋는 게 아니라 겹을 지키는 것이다. 쇠가 해 줄 수 있으면 쇠에게 맡긴다. 마력은 쇠가 못 하는 데 쓰는 것.`,
      ng:`선을 잇다가 불꽃이 튀며 조작반이 아예 죽었다. 양 문이 다 반쯤 열린 채 멎었다.<br><br>겹문이 뻥 뚫린 관이 됐다. 할 수 없이 가루를 털어 두 문 자리에 금을 쳤다. 이중 원 치듯.<br>지나가는 데는 성공했지만 내일 몫의 가루까지 썼다.<br><br>기계는 고치든가 안 건드리든가다. 반만 고친 기계가 제일 나쁘다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'S1', t:'심부 — 숨에 맞춰 뛰는 금',
  x:`심부 복도에 금을 치는데 금이 저 혼자 뛴다. 마력이 일정하게 안 흐르고 출렁인다.<br><br>
    벽 너머에서 거대한 숨이 들려온다. 여왕이라 불리는 것의 숨. 들숨에 금이 눌리고 날숨에 금이 들뜬다.<br>
    이 구역 전체가 그 숨에 맞춰 쉬고 있다. 공기도, 마력도.<br><br>
    숨을 거스르는 금은 이 구역에서 못 선다.`,
  o:[
    { l:'① 금 긋는 손을 그 숨에 맞춘다.', k:'steady', dc:26, cost:{ mana:35 },
      ok:`거스르기를 관뒀다. 날숨에 긋고 들숨에 멈췄다. 숨에 맞춰 긋는 금은 출렁임을 타고 오히려 깊이 박혔다.<br><br>완성된 금이 그 숨에 맞춰 함께 뛰었다. 눌리고 들뜨며, 끊기지는 않고.<br>밤에 온 것들이 금 앞에서 어리둥절했다. 저희 어미 숨으로 뛰는 금이었다. 어미의 것을 넘는 법은 저들에게 없다.<br><br>큰 힘 곁에서는 큰 힘의 장단을 빌린다. 거스르면 부서지고, 타면 실린다.`,
      ng:`숨에 맞춘다는 게 반 박자씩 늦었다. 어긋난 장단으로 그어진 금이 밤새 삐걱댔다.<br><br>새벽에 숨이 한 번 길게 멎었다. 자다 뒤척인 것이리라. 멎은 숨에 기대던 금이 와르르 식었다.<br>급히 다시 긋는 손이 어둠 속에서 떨렸다.<br><br>남의 장단에 기댄 금은 남의 장단과 같이 무너진다. 빌린 힘에는 빌린 값이 있다.`,
      win:{ exp:23, dream:4 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 숨이 닿지 않는 자리를 찾아 금을 옮긴다.', k:'gaze', dc:25,
      ok:`복도를 훑으며 출렁임이 덜한 자리를 찾았다. 기둥 뒤, 격벽 모서리. 숨의 물결에도 그늘이 있다.<br><br>물결 그늘 자리로 야영을 옮기고 금을 쳤다. 금이 고요히 섰다.<br>벽 하나 차이로 금이 서고 안 서고가 갈렸다.<br><br>큰 숨에도 미치지 않는 구석은 있다. 그 구석을 보는 눈이 가루 반 주머니를 아꼈다.`,
      ng:`그늘 자리라고 잡은 데가 하필 숨의 길목이었다. 들숨 때마다 공기가 그 구석으로 쏠려 나갔다.<br><br>금이 숨에 빨려 밤새 야위었다. 새벽엔 실금만 남았다.<br>실금을 보고 들어온 작은 것을 창으로 쫓으며 아침을 맞았다.<br><br>고요한 자리와 빨아들이는 자리는 겉이 같다. 연기 한 올 띄워 보면 갈렸을 것을.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S1', t:'알 방 — 깨우지 않는 금',
  x:`지나야 하는 방이 알 방이다. 둥근 것들이 바닥 가득 줄지어 있다. 겉이 가죽 같고, 속에서 가끔 무엇이 돈다.<br><br>
    막는 금은 여기서 소용없다. 알은 다가오지 않는다. 깨어날 뿐이다.<br>
    열기, 소리, 떨림. 알을 깨우는 건 셋이다. 금으로 가둘 것은 그 셋, 즉 이쪽이다.<br><br>
    사람을 싸서 지나가는 금. 거꾸로 쓰는 금이다.`,
  o:[
    { l:'① 일행을 금으로 싸서 기척을 안에 가두고 지난다.', k:'hide', dc:26, cost:{ mana:32 },
      ok:`다섯을 바싹 모으고 둘레에 걷는 고치를 쳤다. 소리도 열기도 발의 떨림도 고치 안에 고였다.<br><br>알 사이를 한 줄로 지났다. 발꿈치를 들 필요도 없었다. 떨림이 바닥에 닿기 전에 금이 거뒀다.<br>방 한가운데서 알 하나가 뒤척였지만, 뒤척임으로 끝났다.<br><br>문을 나와 고치를 접자 갇혔던 발소리 수백 걸음이 한꺼번에 사라졌다. 들려줄 곳 없는 소리로.`,
      ng:`고치가 반 방을 지나서 얇아졌다. 마력이 바닥 쪽부터 샜다. 발 떨림 몇 걸음이 바닥에 닿았다.<br><br>닿은 자리 둘레 알 셋이 일제히 출렁였다. 하나는 겉가죽에 금이 갔다.<br>남은 반 방을 숨도 안 쉬고 건넜다. 문을 닫는 순간 등 뒤에서 젖은 것 찢어지는 소리가 났다.<br><br>닫힌 문이 소리를 끊었다. 그 뒤는 알고 싶지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-19, spirit:-17 } },
    { l:'② 알 사이 넓은 틈만 골라 맨몸으로 지난다.', k:'luck', dc:26,
      doom:{ title:'깨어난 줄', what:'알 틈에서 솟은 것들에게 바닥 밑으로 끌려갑니다', dc:20, sec:35,
        text:`가루를 아끼자고 맨몸을 골랐다. 넓은 틈만 밟으며 반은 지났다.<br><br>반을 지난 자리에서 알이 아닌 것을 밟았다. 알들 사이 바닥이 꺼지는 뚜껑이었다. 알 방의 바닥 밑에 지키는 것들이 산다.<br>솟아 나온 것들이 발목과 허리를 감았다. 바닥 밑으로 끌려 들어가며 마지막으로 본 것은, 조용히 줄지어 선 알들이었다. 하나도 안 깨어난 채. 깨어날 필요가 없었던 것이다. 지키는 것들이 있으니.`,
        dieText:`알 방 바닥의 뚜껑은 다시 닫혀 있었다.<br><br>동료들은 방을 빙 돌아 배관 위로 건넜다. 반나절이 더 걸렸다.<br>배관에서 내려다본 알 방은 평화로웠다. 그 바닥 밑은 보이지 않았다. 안 보이는 게 나았다.` },
      ok:`맨몸으로 가되 밟기 전에 봤다. 틈마다 바닥 빛깔이 다르다. 알 둘레는 검고 몇 군데만 잿빛이다.<br><br>잿빛이 수상했다. 작은 돌을 잿빛 위에 놓자 바닥이 꺼지며 돌이 사라졌다.<br>검은 바닥만 밟고 건넜다. 느리게, 돌을 앞세워 가며.<br><br>알 방의 덫은 알이 아니었다. 운이 좋았던 게 아니라 돌 하나가 좋았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'수지 복도 — 걸어 다니는 문',
  x:`검은 수지가 벽과 바닥을 다 덮은 복도다. 가루를 뿌리면 수지가 빨아 먹는다. 금이 설 자리가 없다.<br><br>
    둘러 갈 길도 없다. 이 복도가 심부에서 나가는 마지막 길이다.<br>
    벗은 망토를 봤다. 천에는 금이 그어진다.<br><br>
    바닥에 못 긋는 금은 들고 다니면 된다.`,
  o:[
    { l:'① 망토에 금을 그어 등 뒤에 문짝처럼 펼쳐 들고 간다.', k:'fix', dc:25,
      ok:`망토에 재와 가루로 금을 긋고 마력을 재웠다. 천이 금을 머금었다. 걸어 다니는 문짝이다.<br><br>둘이 망토 귀를 잡고 일행 맨 뒤에서 펼쳐 들고 걸었다. 수지 복도 중간에서 뒤쪽 어둠이 달려들었다.<br>어둠이 망토 금에 부딪혀 튕겼다. 두 번, 세 번. 천은 긋는 자리가 아니라 금을 나르는 자리였다.<br><br>복도를 다 나와 망토를 걷었다. 금 그어진 망토는 개지 않고 말아 뒀다. 이제 연장이 하나 늘었다.`,
      ng:`망토 금은 섰는데 드는 각이 흔들렸다. 천이 출렁일 때마다 금도 출렁였다.<br><br>세 번째 부딪힘에 그것의 발톱이 출렁인 틈을 찢었다. 망토가 반으로 갈라졌다.<br>남은 반쪽을 방패처럼 들고 뒷걸음으로 복도를 나왔다.<br><br>나르는 금은 나르는 손이 반이다. 귀를 잡는 둘의 손이 한 손처럼 굳어야 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 수지가 안 덮은 천장 배관에 금을 건다.', k:'steady', dc:25,
      ok:`바닥과 벽은 수지 차지지만 천장 배관은 맨 쇠다. 수지도 못 덮은 데가 있다.<br><br>배관을 따라 점점이 금을 걸었다. 바닥에 닿는 금이 아니라 머리 위에서 내리누르는 금이다.<br>수지 속에서 나온 것들이 그 아래를 못 지났다. 머리 위가 무거운 길은 짐승이 제일 꺼리는 길이다.<br><br>금은 꼭 가로막이일 필요가 없다. 지붕처럼 내리누르는 금도 금이다. 수지가 가르쳐 준 변칙이다.`,
      ng:`배관에 금을 거는데 배관 속이 비지 않았다. 관 안을 타고 다니는 작은 것들이 금 기운에 놀라 쏟아져 나왔다.<br><br>머리 위에서 비처럼 떨어지는 것들을 털고 밟으며 복도를 내달렸다.<br>물린 데가 여럿이지만 깊지는 않았다.<br><br>금을 걸 자리는 속까지 봐야 했다. 겉이 맨 쇠라고 속까지 빈 건 아니다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S2', t:'울타리 모서리 — 모가 난 금',
  x:`옛 울타리에 기대 야영한다. 울타리가 ㄱ자로 꺾인 모서리 안쪽이다. 두 면이 막혀 편하다.<br><br>
    가루 금은 울타리 트인 쪽에 ㄴ자로 쳤다. 울타리와 금이 만나 네모가 된다.<br>
    발톱 긴 것들이 어스름부터 울타리를 시험하고 다닌다. 밀고, 당기고, 외우고.<br><br>
    저것들이 제일 좋아하는 게 모서리다. 힘이 모이는 자리, 그리고 빠지는 자리.`,
  o:[
    { l:'① 금의 꺾인 데를 둥글려 모서리를 없앤다.', k:'steady', dc:25,
      ok:`ㄴ자 금을 지우고 다시 그었다. 호선으로, 울타리 두 끝을 둥글게 잇는 활꼴로.<br><br>밤에 그것들이 와서 모서리를 찾았다. 울타리의 모서리는 바깥쪽이라 소용없고, 금에는 모서리가 없다.<br>힘이 모일 자리를 못 찾은 발톱들이 금 위를 두어 번 헛디디고 돌아갔다.<br><br>짐승은 각을 노린다. 각이 없는 금은 노릴 데가 없는 금이다. 울타리에 기댈 때일수록 금은 둥글게. 수첩에 적듯 외웠다.`,
      ng:`둥글린 금이 울타리 기둥과 만나는 두 자리가 남았다. 금과 쇠의 이음매. 거기가 새 모서리였다.<br><br>그것들이 밤새 그 두 자리만 두드렸다. 한 자리가 새벽에 헐거워졌다.<br>헐거운 틈으로 들어온 머리를 창이 받았다.<br><br>각을 없애면 이음매가 각이 된다. 금과 세상이 만나는 자리, 결국 거기가 늘 숙제다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 울타리 위에 올라 시험하는 것들을 내려다본다.', k:'luck', dc:26,
      doom:{ title:'울타리 너머', what:'울타리 위에서 낚아채여 바깥 어둠으로 끌려갑니다', dc:20, sec:40,
        text:`울타리에 올라 그것들의 시험을 내려다봤다. 어느 놈이 우두머리인지 보려고.<br><br>보이는 건 셋이었다. 넷째는 안 보였다. 안 보이는 놈이 울타리 바깥쪽 바로 밑에 붙어 있었다.<br>발목이 낚였다. 울타리 바깥으로 거꾸로 떨어져 그대로 끌려간다. 안쪽에서 동료들이 금을 열고 나오는 소리가 들렸다. 금 너머가 아니라 울타리 너머는, 술사의 땅이 아니었다.`,
        dieText:`울타리 바깥 풀밭에 가루 주머니가 떨어져 있었다.<br><br>동료들은 주머니를 주워 와 금을 마저 지켰다. 그을 줄 아는 사람 없이, 남은 가루로 사흘.<br>사흘째 밤 그것들이 금을 넘었을 때, 일행은 이미 반나절 밖을 걷고 있었다. 금이 버텨 준 사흘이 산 사람들의 몫이 됐다.` },
      ok:`올라가기 전에 울타리 바깥쪽 밑부터 횃불로 비췄다. 바로 밑에 하나가 납작 붙어 있었다.<br><br>불빛에 들킨 그놈이 풀숲으로 빠졌다. 그 뒤에 올라서 셌다. 넷. 우두머리는 제일 뒤에서 구경만 하는 놈이었다.<br>우두머리 쪽 울타리에만 금을 한 겹 더 둘렀다.<br><br>그 밤 시험은 우두머리 쪽에서 왔고, 두 겹 금이 받았다. 보고 나서 올라가는 순서, 그게 전부였다.`,
      win:{ exp:19, dream:3 } }
  ] },

{ at:'S2', t:'물 위 — 뜨는 금',
  x:`물에 잠긴 양치밭 한가운데 섬 둔덕에서 밤을 나야 한다. 물이 사방이다.<br><br>
    가루는 물에 뜨자마자 흩어진다. 물 위에는 금이 안 선다.<br>
    그런데 오는 것들은 물로 온다. 물풀 밑으로, 소리 없이.<br><br>
    둔덕 가장자리, 물과 뭍이 만나는 금. 그 한 뼘이 오늘 밤의 성벽 자리다.`,
  o:[
    { l:'① 기름에 가루를 개어 물 위에 뜨는 금을 두른다.', k:'steady', dc:26, wake:1,
      ok:`등잔 기름에 가루를 갰다. 기름은 물에 뜨고 번지지 않는다. 둔덕을 한 바퀴, 물 위에 기름 금을 둘렀다.<br><br>마력을 걸자 금이 수면에서 낮게 빛났다. 물결에 출렁이면서도 끊기지 않는다.<br>밤에 물풀 밑으로 온 것들이 금 아래서 멈췄다. 수면의 금은 물속까지 그림자를 드리운다. 그 그림자 커튼을 뚫고 올라온 놈은 없었다.<br><br>물 위에 금을 띄워 본 술사가 몇이나 될까. 기름 한 종지가 길을 열었다. 재료는 창고가 아니라 머리에 있다.`,
      ng:`기름 금은 섰는데 밤중에 큰 것의 걸음이 물을 울렸다. 물결이 금을 한쪽으로 몰아붙였다.<br><br>몰린 금이 겹치고 반대쪽이 비었다. 빈 쪽 물가로 긴 주둥이가 올라와 침낭 하나를 물고 들어갔다.<br>침낭 임자는 다행히 그 안에 없었다.<br><br>뜨는 금은 물결 따라 사는 금이다. 밤새 몰리는 쪽을 되밀어 줘야 한다는 것까지가 이 수의 전부다.`,
      win:{ exp:23, dream:4 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 물가에 말뚝을 박고 물속에 치는 금을 시험한다.', k:'sense', dc:25,
      ok:`둔덕 물가에 한 걸음 간격으로 나뭇가지 말뚝을 박고, 말뚝 허리에 가루 반죽을 발랐다. 수면 아래 한 뼘 깊이다.<br><br>말뚝이 틀이 되니 물속에서도 금이 섰다. 물풀 밑으로 오던 것이 금에 코를 박고 물러나는 물살이 두 번 일었다.<br><br>물속 금은 물 밖에서 보이지 않는다. 보이지 않는 성벽이 제일 좋은 성벽이다. 적도 못 보고 외우지도 못하니까.`,
      ng:`말뚝 간격이 넓었다. 한 걸음은 물속 것들에게 넉넉한 틈이었다.<br><br>가는 것 하나가 말뚝 사이로 들어와 물가의 수통 끈을 물고 갔다.<br>간격을 반으로 줄여 다시 박느라 밤의 반을 물가에서 보냈다. 젖은 바지가 마르기 전에 아침이 왔다.<br><br>물속 자는 물 밖 자보다 촘촘해야 한다. 물에는 어깨가 없다. 가는 것들은 틈이 제 폭이면 다 지난다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S2', t:'좁은 길목 — 무리를 가르는 금',
  x:`무리가 따라붙었다. 발톱 긴 것 다섯. 트인 데서 다섯을 상대하면 진다.<br><br>
    앞에 바위 두 개가 좁은 길목을 만든 자리가 있다. 다섯이 한꺼번에는 못 드는 폭.<br>
    저기서 무리를 갈라야 한다. 하나씩 들어오게.<br><br>
    금은 막는 것만이 아니다. 세는 것이기도 하다.`,
  o:[
    { l:'① 길목에 한 놈 폭의 문만 남기고 금을 친다.', k:'steady', dc:26, cost:{ mana:40 },
      ok:`바위 사이에 금을 치되 가운데 한 놈 폭만 비웠다. 들어올 테면 하나씩 들어오라는 문이다.<br><br>다섯이 문 앞에서 엉켰다. 하나가 들어오면 창 둘이 받고, 다음이 들어오면 또 받고.<br>셋째가 문턱에서 제 차례의 뜻을 깨달았다. 차례로 죽는 차례라는 걸.<br>무리가 문 앞에서 흩어졌다. 다섯이 다섯인 채로는 못 들어오는 문. 그게 금의 셈이었다.<br><br>마력이 바닥까지 갔지만 다섯을 둘씩 셋씩으로 바꾼 값이다. 쌌다.`,
      ng:`문 폭이 반 뼘 넓었다. 둘째가 첫째 등에 붙어 같이 밀고 들어왔다.<br><br>둘을 한꺼번에 받느라 창 하나가 부러지고 동료 하나가 넘어졌다.<br>급히 문을 마저 닫아 셋째부터는 막았다. 들어온 둘은 반 식경을 싸워 눕혔다.<br><br>문은 한 놈 폭이라야 문이다. 반 뼘이 둘을 들였다. 금 긋는 자의 반 뼘은 남의 목숨 폭이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 길목 바닥에 밟으면 터지는 가루 묻이를 깐다.', k:'evade', dc:25,
      ok:`금을 세우는 대신 묻었다. 길목 바닥에 가루를 얇게 깔고 마력을 재워, 밟으면 일어나게.<br><br>첫째가 밟았다. 가루가 하얗게 일어서며 콧잔등을 지졌다. 첫째가 뒤로 물구나무를 섰다.<br>둘째 셋째가 첫째에 걸려 넘어졌다. 길목이 저희끼리 엉킨 마당이 됐다.<br><br>그 틈에 일행은 길목 너머로 거리를 벌렸다. 서는 금만 금이 아니다. 눕는 금도 금이다.`,
      ng:`묻은 가루가 축축한 바닥에 설익었다. 첫째가 밟았는데 반만 일어났다.<br><br>지져지다 만 첫째가 성이 나서 배로 빨라졌다. 길목을 금 없이 맨 창으로 막는 싸움이 됐다.<br>둘을 눕히고 셋을 쫓는 동안 다들 한 군데씩 긁혔다.<br><br>눕는 금은 바닥이 반이다. 젖은 바닥에 묻는 가루는 밑에 마른 재부터 깔았어야 했다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S2', t:'큰 것의 길 — 떨림을 지우는 진',
  x:`큰 것의 영역을 질러야 한다. 눈은 피할 수 있다. 바위 그늘로만 가면. 문제는 발걸음의 떨림이다.<br><br>
    저것은 발바닥으로 듣는다. 다섯 사람 걸음은 땅울림으로는 북소리다.<br>
    떨림을 지우는 진. 뜬 바닥을 만들어 그 위를 걷는 수가 있다.<br><br>
    책에서는 두 줄이었다. 여기서는 목숨이다.`,
  o:[
    { l:'① 걸음 밑에 마력 방석을 깔아 떨림을 걷어 낸다.', k:'steady', dc:26, cost:{ mana:34 }, wake:1,
      ok:`다섯 발밑에 손바닥만 한 마력 방석을 하나씩 물렸다. 디딜 때마다 방석이 받고, 땅에는 눌림만 가고 떨림은 안 간다.<br><br>큰 것의 영역 복판을 가로질렀다. 바위 그늘에서 그것의 옆구리가 숨 쉬는 게 보일 만큼 가까웠다.<br>발바닥으로 듣는 귀에 다섯 걸음은 끝내 들리지 않았다.<br><br>영역을 다 지나 방석을 거뒀다. 손이 덜덜 떨렸다. 다섯 명 걸음을 한 식경 받친 값이다. 그래도 북소리를 지운 북채가 됐다. 이 수는 이제 두 줄이 아니라 몸에 있다.`,
      ng:`네 발은 받쳤는데 다섯째 발이 자꾸 샜다. 제일 무거운 동료의 뒤꿈치가 방석을 뚫고 울렸다.<br><br>세 번째 울림에 큰 것의 머리가 돌아왔다. 콧김이 수풀을 갈랐다.<br>바위 틈에 다섯이 끼어 박혀 반나절을 숨죽였다. 그것은 바위 둘레를 두 바퀴 돌고야 갔다.<br><br>방석은 무게 따라 두께를 달리해야 했다. 한 치수로 다섯을 신기는 신발 가게는 없다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-19, spirit:-17 } },
    { l:'② 큰 것의 걸음에 맞춰 걷는다 — 북소리에 북소리를 숨긴다.', k:'hide', dc:25,
      ok:`그것이 걸을 때만 걸었다. 쿵, 하는 울림에 다섯 걸음을 포갰다. 큰 북소리가 작은 북소리를 삼킨다.<br><br>그것이 멈추면 멈추고, 걸으면 걸었다. 영역을 지나는 데 세 배의 시간이 들었다.<br>마지막엔 그것의 걸음을 기다리는 저 자신이 우스웠다. 적의 걸음이 아군의 장단이 된 셈이다.<br><br>마력 한 톨 안 쓴 날이었다. 술사의 제일 좋은 수는 가끔 술이 아니다.`,
      ng:`장단을 타다가 그것이 갑자기 방향을 꺾었다. 이쪽으로.<br><br>걸음을 포개던 수가 마주 걷는 수가 됐다. 황급히 바위 뒤로 흩어졌다.<br>그것은 바위 앞에서 한참 발바닥 소리를 듣다가 갔다. 심증은 있는데 물증이 없는 걸음이었다.<br><br>남의 장단은 남의 것이다. 언제 바뀔지 모르는. 다음엔 방석 한 벌 칠 마력은 남겨 두고 탄다.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S2', t:'엘리베이터 — 쇠 바구니에 거는 금',
  x:`낡은 엘리베이터에 다섯이 탔다. 창살 바구니가 삐걱대며 오른다. 결계술사 눈에 이 바구니는 완벽한 틀이다. 네 모서리, 지붕, 바닥.<br><br>
    금을 걸었다. 반 품에 상자 결계가 섰다.<br>
    다만 지붕 가운데 줄 구멍이 있다. 권양기 줄이 지나는 구멍. 막을 수 없는 구멍이다.<br><br>
    위쪽 어둠에서 가죽 날개 소리가 났다.`,
  o:[
    { l:'① 줄 구멍 둘레에 깔때기꼴 금을 세워 구멍을 지킨다.', k:'fix', dc:25,
      ok:`구멍은 못 막는다. 대신 구멍 둘레에 깔때기를 엎은 모양으로 금을 세웠다. 줄은 지나되 줄보다 굵은 것은 못 지나게.<br><br>날개 것이 지붕에 내려앉아 구멍에 발톱을 넣었다. 깔때기 금이 발목을 조였다.<br>비명을 지르며 날아오르는 통에 바구니가 한 번 크게 흔들렸다. 그뿐이었다.<br><br>막을 수 없는 구멍은 좁히면 된다. 지나야 할 것의 굵기만큼만 남기고. 결계는 늘 그 한 치의 셈이다.`,
      ng:`깔때기 금이 줄에 너무 바싹 섰다. 바구니가 흔들릴 때마다 줄이 금을 긁었다.<br><br>긁힌 금이 반쯤 올라가서 흐트러졌다. 날개 것이 그 틈에 구멍으로 긴 혀를 넣어 막내의 모자를 채 갔다.<br>모자뿐이라 다행이었다.<br><br>금과 줄 사이에도 숨 쉴 틈이 필요했다. 움직이는 틀에 거는 금은 움직임의 폭까지 재야 한다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 바구니 금을 믿고 지붕 위 것과 버틴다.', k:'steady', dc:26,
      doom:{ title:'지붕 위의 발톱', what:'줄 구멍으로 들어온 혀에 감겨 하늘로 끌려갑니다', dc:20, sec:35,
        text:`날개 것이 지붕에 앉아 창살을 뜯기 시작했다. 금이 받아 내는 걸 믿고 버텼다.<br><br>그것이 뜯기를 멈추고 구멍에 입을 댔다. 금은 몸을 막는다. 혀는 몸보다 가늘었다.<br>줄 구멍으로 들어온 혀가 목을 감았다. 금 안에서, 금이 멀쩡한 채로, 몸이 지붕 쪽으로 끌려 올라간다. 동료들이 다리를 붙잡았다. 바구니는 오르고, 혀는 당기고, 동료는 매달리고. 쇠 바구니가 저울처럼 흔들렸다.`,
        dieText:`바구니는 끝까지 올라갔다. 넷이 내렸다.<br><br>지붕 위에는 긴 혀 끝이 한 뼘 떨어져 있었다. 창이 끊어 낸 것이다. 끊고도 늦은 것이다.<br>하늘 쪽 어둠에서 날개 소리가 오래 돌았다. 넷은 쇠 문을 닫고야 그 소리를 등졌다.` },
      ok:`믿되 다 믿지는 않았다. 금이 못 막는 것부터 셌다. 혀, 침, 바람. 가는 것들.<br><br>구멍 바로 밑에 방패 든 동료를 세우고 그 위에 겉옷을 걸었다. 천 한 겹이 혀의 눈을 가린다.<br>혀가 두 번 들어와 두 번 겉옷만 감아 갔다.<br>그 사이 바구니가 어둠 위로 올라섰다.<br><br>금을 세운 자가 금의 구멍을 제일 잘 알아야 한다. 아는 만큼만 금이 미덥다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'둥지 벌판 — 냄새를 싸는 금',
  x:`알 둥지 벌판을 지난다. 어미들이 하늘을 돈다. 눈은 바위 그늘로 피하면 된다.<br><br>
    코가 문제다. 다섯 사람의 땀내가 바람을 탄다. 알 곁에서 나는 낯선 냄새, 어미들이 제일 미워하는 것.<br>
    기척을 가두는 고치 금은 배웠다. 냄새도 기척이다.<br><br>
    바람이 벌판 안쪽으로 분다. 서두를 일이다.`,
  o:[
    { l:'① 고치 금을 코끝 높이까지만 낮게 치고 건넌다.', k:'hide', dc:26, cost:{ mana:27 },
      ok:`온몸을 싸는 고치는 마력이 너무 든다. 냄새는 위로 뜬다. 그러니 금도 위만 막으면 된다.<br><br>다섯 머리 위로 뚜껑 모양 금을 치고 벌판을 건넜다. 땀내가 뚜껑에 눌려 발밑으로 깔렸다.<br>어미들이 머리 위를 세 번 지났다. 세 번 다 그냥 지났다. 코에 걸리는 게 없었으니.<br><br>냄새의 길을 알면 금은 반만 쳐도 된다. 반 금은 반 마력이다. 남은 반으로 돌아갈 길도 샀다.`,
      ng:`뚜껑 금이 벌판 중간에서 바람에 밀렸다. 센 맞바람이 금 아래로 파고들어 냄새를 긁어 갔다.<br><br>어미 하나가 급강하로 내려와 바위 그늘 바로 앞을 훑고 올라갔다.<br>남은 길을 바위 밑에 붙어 기었다. 무릎이 다 까졌다.<br><br>뚜껑은 바람 없는 날의 금이었다. 바람 부는 날은 바람맞이 쪽에 한 폭을 더 드리워야 한다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 둥지 흙을 발라 냄새를 둥지 것으로 바꾼다.', k:'gaze', dc:25,
      ok:`빈 둥지 가장자리 흙을 봤다. 어미들이 발로 다져 둔 흙, 저들 냄새가 밴 흙이다.<br><br>그 흙을 손과 목덜미, 장화에 발랐다. 사람 냄새 위에 둥지 냄새를 입힌 것이다.<br>벌판을 건너는 동안 어미 하나가 낮게 내려와 머리 위를 맴돌다 올라갔다. 코에 걸린 냄새가 제 집 냄새였던 것이다.<br><br>금 없이 건넌 벌판이었다. 술사의 눈은 재료를 보는 눈이다. 적의 집 흙도 재료다.`,
      ng:`흙을 바르는데 빈 둥지가 빈 게 아니었다. 흙 밑에 묻어 둔 알이 있었다.<br><br>손끝이 알을 건드리자 흙 전체가 꿈틀했다. 알을 지키는 작은 것들이 흙 속에서 쏟아져 나왔다.<br>손등과 팔뚝을 물리며 물러났다.<br><br>남의 집 흙을 꾸러 갈 때는 집이 빈 것부터 확인해야 했다. 겉이 빈 둥지가 속까지 빈 건 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S2', t:'마지막 금 — 올라가는 바구니 뒤에서',
  x:`엘리베이터는 한 번에 다섯을 못 올린다. 바구니가 삭아서 셋이 한계다. 두 번에 나눠 오른다.<br><br>
    첫 바구니가 올라가는 동안 남는 둘이 아래를 지킨다. 술사는 남는 쪽이다. 금을 그을 수 있으니까.<br>
    벌판 쪽에서 발톱 긴 것들이 쇠 삐걱대는 소리를 듣고 온다.<br><br>
    바구니가 내려오는 데 백 숨. 백 숨짜리 금이 필요하다.`,
  o:[
    { l:'① 승강구 앞에 백 숨짜리 반원을 긋고 둘이 등을 맞댄다.', k:'steady', dc:26, wake:1,
      ok:`승강구를 등지고 반원을 그었다. 마력을 아끼지 않았다. 백 숨만 버티면 되는 금이니 두께를 다 썼다.<br><br>쉰 숨째에 그것들이 왔다. 반원을 때리고, 긁고, 돌았다. 금이 울 때마다 남은 숨을 셌다. 여든. 아흔.<br>백 숨째에 등 뒤에서 쇠 바구니가 덜컹 내려앉았다. 금을 걷으며 뒷걸음으로 바구니에 올랐다.<br>걷히는 금을 그것들이 덮쳤지만 창살문이 먼저 닫혔다.<br><br>금에도 수명을 정해 주면 두께가 산다. 영원히 버틸 금은 없다. 백 숨짜리 금, 그걸 긋는 손이 이제 떨리지 않는다.`,
      ng:`금은 섰는데 백 숨이 아니라 백서른 숨이 걸렸다. 바구니가 중간에 한 번 걸린 것이다.<br><br>백 숨에 맞춰 얇아지던 금이 백열 숨부터 비명을 질렀다. 마지막 스무 숨은 창과 몸으로 메꿨다.<br>바구니에 오를 때 장딴지에 발톱이 하나 걸렸다.<br><br>금의 수명은 남의 기계에 걸지 말 것. 삭은 기계는 셈을 어긴다. 숨 서른은 여유로 얹었어야 했다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-33, mind:-15 } },
    { l:'② 둘이 아니라 혼자 남는다 — 금 안은 한 사람이 제일 가볍다.', k:'bond', dc:26,
      doom:{ title:'혼자 남은 금', what:'무너진 금 틈으로 물려 벌판으로 끌려갑니다', dc:20, sec:40,
        text:`동료까지 첫 바구니에 밀어 올렸다. 금은 좁을수록 세다. 혼자 두를 원이 제일 작고 제일 단단하다.<br><br>셈은 맞았다. 틀린 건 그것들의 수였다. 다섯이 아니라 여덟이었다.<br>여덟이 번갈아 때리는 금은 백 숨을 못 갔다. 일흔 숨에 금이 깨지고, 깨진 틈으로 들어온 이빨이 어깨를 물었다.<br>벌판으로 끌려가며 위를 봤다. 바구니가 내려오고 있었다. 서른 숨 거리였다. 서른 숨이 벌판처럼 넓었다.`,
        dieText:`내려온 바구니에는 아무도 타지 못했다.<br><br>동료들은 위에서 승강구를 지키며 아침까지 기다렸다. 벌판은 조용했다.<br>해 뜬 뒤 바구니를 내려 보니 반원 금 자국이 바닥에 그대로 남아 있었다. 안쪽을 지키던 모양 그대로. 금은 깨진 자리 한 뼘 말고는 온전했다. 한 뼘이면 충분했던 것이다.` },
      ok:`혼자 남겠다는 말에 창잡이가 고개를 저었다. 금이 깨지면 그때는 창이라고.<br><br>둘이 남았다. 금은 혼자 치고, 등은 창잡이가 맡았다.<br>금이 일흔 숨에 한 번 뚫렸다. 뚫린 한 뼘을 창이 받아 내는 사이 금을 기웠다.<br>백 숨째 바구니가 왔다. 둘이 같이 올랐다.<br><br>제일 작은 원이 제일 세다는 셈은 맞다. 다만 금은 뚫리라고 있는 것이고, 뚫린 뒤가 사람 몫이다. 그 몫은 둘이어야 한다.`,
      win:{ exp:21, dream:3 } },
    { l:'③ 금 대신 승강구 둘레에 가루를 아예 눈처럼 흩뿌려 둔다.', k:'luck', dc:25,
      ok:`긋지 않고 뿌렸다. 승강구 앞 열 걸음을 가루 밭으로 만들고 마력을 설렁설렁 걸었다.<br><br>금이 아니라 늪이다. 밟는 자리마다 가루가 일어나 들러붙게.<br>온 것들이 가루 밭에서 난리가 났다. 발바닥에 붙은 가루가 따끔거려 걷지를 못했다.<br>백 숨 내내 그것들은 제 발만 핥았다.<br><br>급할 때 나온 엉터리 수가 정석보다 나을 때가 있다. 수첩에 적어 두기로 했다. 이름은 가루눈.`,
      ng:`뿌린 가루가 승강구 바람에 반이 날렸다. 밭이 듬성듬성해졌다.<br><br>성한 자리만 밟고 오는 놈이 하나 있었다. 눈썰미 있는 놈이.<br>그놈 하나와 백 숨 내내 창으로 밀고 밀렸다. 바구니가 내려왔을 때 둘 다 숨이 턱에 닿아 있었다.<br><br>뿌리는 수는 바람 없는 날의 수였다. 엉터리 수는 역시 엉터리일 때가 더 많다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] }

]);

// ── 외공 수련생 (ironbody) · 내공
kJob('ironbody', 'S', [

{ at:'S', t:'첫 합 — 팔뚝으로 받은 발톱',
  x:`어둠에서 발톱이 나왔다. 피할 자리가 없다. 뒤에 동료가 있다.<br><br>
    외공은 받는 공부다. 수련장에서 몽둥이를 만 번 받았다. 여기 것의 발톱은 몽둥이보다 빠르고 무겁다.<br>
    숨을 아랫배에 가라앉히고 팔뚝을 세웠다.<br><br>
    만 번의 매가 진짜 매를 받는 순간이다.`,
  o:[
    { l:'① 내공을 살갗에 올려 팔뚝으로 정통으로 받는다.', k:'steady', dc:25, wake:1,
      ok:`발톱이 팔뚝에 떨어졌다. 쇠를 친 소리가 났다. 살갗이 한 겹 쇠가 된 소리.<br><br>세 줄 자국이 났지만 피는 안 났다. 발톱 쪽이 하나 부러져 바닥에 떨어졌다.<br>그것이 제 발을 들여다봤다. 먹이가 제 발톱을 부러뜨린 적이 없는 눈이었다. 그대로 물러났다.<br><br>받으면서 알았다. 몽둥이와 발톱의 차이는 무게가 아니라 끝이다. 끝이 닿는 한 점에 내공을 모으는 것. 만 번의 매가 그 한 점을 찾는 공부였다.`,
      ng:`내공이 반 숨 늦게 올랐다. 살갗이 쇠가 되기 전에 끝이 닿았다.<br><br>팔뚝이 세 줄로 열렸다. 피가 손목까지 내려왔다.<br>두 번째 발톱은 제대로 받았다. 쇠 소리에 그것이 물러났다.<br><br>천으로 동여매며 셈했다. 올리는 데 반 숨. 그 반 숨을 줄이는 게 남은 공부다. 여기는 반 숨에 피가 나는 수련장이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 받으며 반 걸음 물러나 힘을 흘린다.', k:'evade', dc:24,
      ok:`정통으로 받지 않았다. 닿는 순간 반 걸음 물러나며 팔뚝을 비스듬히 틀었다.<br><br>발톱이 살갗을 타고 미끄러졌다. 자국은 길지만 얕다.<br>힘을 다 받는 것만 외공이 아니다. 반을 흘리면 반만 받으면 된다.<br><br>그것이 두 번을 더 쳤고 두 번 다 미끄러졌다. 끝이 안 박히는 먹이에 흥미를 잃은 걸음으로 어둠에 돌아갔다.`,
      ng:`물러나는 반 걸음이 벽에 막혔다. 등이 벽에 닿으며 흘릴 자리가 없어졌다.<br><br>발톱을 어깨로 받았다. 어깨받이가 찢어지고 살이 한 줄 열렸다.<br>벽을 등지면 외공은 받는 수밖에 없다. 그 당연한 걸 벽에 닿고야 떠올렸다.<br><br>다음부턴 등 뒤 반 걸음을 늘 재 두기로 했다. 흘리는 공부는 자리 공부부터다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S', t:'튄 피 — 끓는 방울',
  x:`창잡이가 그것의 목을 꿰뚫었다. 피가 부챗살로 튀었다. 그 피가 끓는 피다.<br><br>
    바닥이 녹고 창대가 녹는다. 그리고 방울 몇 개가 이쪽으로 날아온다.<br>
    피할 시간은 없다. 닦을 것도 없다.<br><br>
    외공 수련생에게 살갗은 갑옷이다. 갑옷이 산에도 버티는지는 오늘 처음 시험한다.`,
  o:[
    { l:'① 내공을 끌어올려 살갗을 조이고 방울을 받는다.', k:'steady', dc:26, cost:{ qi:28 },
      ok:`숨을 멈추고 내공을 살갗 전체로 밀었다. 땀구멍까지 조여졌다.<br><br>방울이 뺨과 손등에 앉았다. 끓는 소리가 났다. 살갗 위에서. 속으로는 못 들어온다.<br>조인 살갗 위를 방울이 데굴데굴 굴러 떨어졌다. 자국은 발갛게 남았지만 파이지는 않았다.<br><br>조인 가죽에는 물이 안 스민다. 산도 물이다. 스미기 전에 굴려 떨어뜨리면 된다. 떨어진 방울이 바닥을 녹이는 걸 보며 숨을 다시 쉬었다.`,
      ng:`손등은 조였는데 뺨이 늦었다. 방울 하나가 광대뼈 위에서 끓었다.<br><br>이를 악물고 손바닥으로 쓸어 냈다. 손바닥과 뺨이 같이 데었다.<br>동전만 한 자국이 두 개 남았다. 평생 갈 자국이다.<br><br>얼굴은 늘 마지막에 조여진다. 눈 코 입이 있어서. 얼굴부터 조이는 연습이 필요하다. 여기서는 얼굴로 제일 많이 튄다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 겉옷 자락을 휘둘러 방울을 걷어 낸다.', k:'evade', dc:24,
      ok:`몸으로 받을 것 없는 건 안 받는다. 겉옷 자락을 채찍처럼 휘둘러 날아오는 방울들을 쳐 냈다.<br><br>자락이 방울을 받고 치익 탔다. 옷은 타라고 입는 날도 있다.<br>타들어 가는 자락을 그 자리에서 뜯어 버렸다.<br><br>갑옷은 살갗만이 아니다. 걸친 것 전부가 겹겹의 갑옷이다. 제일 바깥 겹부터 쓰고 버리는 것, 그것도 외공의 셈이다.`,
      ng:`자락을 휘두르는 게 반 박자 늦었다. 방울 하나가 자락을 뚫고 정강이에 앉았다.<br><br>가죽 각반이 끓으며 살에 붙었다. 각반째 뜯어냈다. 살갗이 한 겹 따라 일어났다.<br><br>절뚝이며 그날 길을 다 걸었다. 걷어 내는 수는 거리가 반이다. 방울이 자락보다 가까우면 몸이 받는 수밖에 없다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S', t:'돌진 — 뿌리내리는 법',
  x:`복도 저쪽에서 그것이 달려온다. 머리를 낮추고, 곧장. 들이받는 몸이다.<br><br>
    뒤는 다친 동료들이다. 비키면 받히는 건 그들이다.<br>
    수련장에서 배운 말이 있다. 받는 힘의 반은 다리가 아니라 바닥에서 온다.<br><br>
    바닥을 봤다. 쇠판. 이음매가 두 걸음 앞에 있다.`,
  o:[
    { l:'① 이음매 턱에 뒷발을 걸고 뿌리를 내린다.', k:'steady', dc:26,
      ok:`뒷발 뒤꿈치를 이음매 턱에 걸었다. 무릎을 접고 허리를 낮추고 내공을 발바닥으로 내렸다.<br><br>사람이 아니라 기둥이 되는 숨 한 번.<br>부딪혔다. 세상이 한 번 하얘졌다. 밀리는 몸을 이음매 턱이 받았다. 반 뼘 밀리고 멈췄다.<br>그것은 제 돌진을 제가 받고 주저앉았다. 기둥을 들이받은 짐승 꼴로.<br><br>다리로 버틴 게 아니다. 바닥을 빌렸다. 바닥 읽는 눈이 외공의 반이라는 걸 몸이 알았다.`,
      ng:`이음매에 발을 거는 사이 그것이 먼저 닿았다. 뿌리내리다 만 나무 꼴로 받았다.<br><br>세 걸음을 날아 벽에 부딪혔다. 갈비 어디서 금 가는 소리가 났다.<br>그래도 그것의 길은 꺾었다. 받다 만 몸에 걸려 그것도 비틀거렸고, 그 틈에 동료들이 창을 꽂았다.<br><br>숨 쉴 때마다 옆구리가 결렸다. 뿌리는 미리 내려 두는 것이다. 적이 보일 때는 늦다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-36, mind:-14 } },
    { l:'② 받는 척하다 마지막에 어깨로 비껴 민다.', k:'break', dc:25,
      ok:`정면으로 서 있다가 닿기 반 걸음 전에 몸을 틀었다. 어깨를 그것의 어깨에 비껴 대고 밀었다.<br><br>정면 힘이 빗면을 타고 흘렀다. 그것은 제 힘에 제가 밀려 벽으로 꽂혔다.<br>벽이 울리고 천장 먼지가 쏟아졌다.<br><br>받는 공부의 끝은 돌려주는 공부라던 스승 말이 여기서 통했다. 받을 힘이면 흘릴 수도 민다.`,
      ng:`트는 반 걸음이 빨랐다. 그것이 따라 틀었다.<br><br>빗면이 정면이 됐다. 어깨와 어깨가 정통으로 부딪혔다. 이쪽 어깨가 한 번 빠졌다 들어왔다.<br>구르며 떨어져 나와 두 번째 돌진은 동료 창들이 막았다.<br><br>팔이 한나절 안 올라갔다. 흘리는 수는 상대가 곧은 놈일 때 수다. 따라 트는 놈한테는 정직하게 받는 수밖에 없다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-34, spirit:-15 } }
  ] },

{ at:'S', t:'숨구멍 — 들키지 않는 숨',
  x:`천장 위를 그것이 지나간다. 걸음을 멈추고 벽에 붙었다. 문제는 숨이다.<br><br>
    뛴 뒤라 숨이 거칠다. 여기 것들은 숨소리를 듣는다. 들숨의 떨림까지.<br>
    외공의 첫 수업이 숨이었다. 매를 받는 순간 숨을 어디 둘 것인가.<br><br>
    지금은 매가 아니라 귀를 받는 중이다.`,
  o:[
    { l:'① 거친 숨을 아랫배로 눌러 실숨으로 바꾼다.', k:'steady', dc:25, wake:1,
      ok:`들숨을 반으로 접고 날숨을 길게 풀었다. 가슴이 아니라 아랫배로 쉬는 숨. 코털 하나 안 흔들리는 실숨.<br><br>심장은 뛰는데 숨은 고요했다. 천장의 걸음이 머리 위에서 한 번 멈췄다. 듣고 있다.<br>실숨 스무 번. 걸음이 다시 멀어졌다.<br><br>매 받을 때 쓰라고 배운 숨이 숨을 때도 쓰였다. 외공의 숨은 결국 하나다. 몸의 안과 밖 사이 문을 닫는 숨. 그 문이 이제 반 숨에 닫힌다.`,
      ng:`실숨으로 바꾸다 중간에 숨이 한 번 턱 막혔다. 막힌 숨이 터지며 작은 기침이 났다.<br><br>천장이 조용해졌다. 제일 나쁜 조용함이다.<br>천장 판 하나가 들리기 전에 넷이 복도를 꺾어 내달렸다. 등 뒤에서 판 떨어지는 소리와 발톱 소리가 쏟아졌다.<br><br>간신히 따돌리고 벽에 기대 그 못다 쉰 숨을 몰아쉬었다. 숨은 참는 게 아니라 바꾸는 것이다. 참은 숨은 꼭 이자를 붙여 터진다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 동료들의 숨까지 제 장단에 맞추게 한다.', k:'bond', dc:24,
      ok:`손가락 셋을 펴 보였다. 셋에 들이쉬고, 셋에 내쉬고. 수련장 장단이다.<br><br>다섯 숨이 한 숨이 됐다. 다섯 사람이 한 사람 크기의 기척이 됐다.<br>천장의 그것은 한 사람 기척을 다섯 걸음 어림으로 지났다. 수를 잘못 센 것이다.<br><br>숨 장단은 혼자 배우지만 쓸모는 여럿일 때 더 크다. 수련장에서 못 배운 걸 천장 밑에서 배웠다.`,
      ng:`장단을 맞추는데 막내 숨이 자꾸 어긋났다. 무서우면 숨이 먼저 달아난다.<br><br>어긋난 숨 둘이 겹치며 숨소리가 오히려 도드라졌다. 천장 걸음이 되돌아왔다.<br>막내 입을 손바닥으로 덮고 제 숨을 멈춘 채 버텼다. 걸음이 세 바퀴를 돌고 갔다.<br><br>남의 숨은 장단만으로 안 잡힌다. 어깨를 짚어 주는 손이 같이 가야 한다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'물린 동료 — 턱 사이에 넣는 팔',
  x:`그것의 턱이 동료의 어깨를 물었다. 창은 각이 안 나온다. 턱은 벌릴수록 깊이 문다.<br><br>
    수련장 문답이 떠올랐다. 물린 동료를 어찌 구하나. 답은 하나였다. 더 단단한 것을 물린다.<br>
    여기서 제일 단단한 것은 이쪽 팔뚝이다.<br><br>
    내공을 팔에 몰 시간, 두 숨.`,
  o:[
    { l:'① 내공을 몬 팔뚝을 턱 사이에 쑤셔 넣는다.', k:'steady', dc:26, cost:{ qi:35 },
      ok:`팔뚝을 세워 턱 구석에 쑤셔 넣고 비틀었다. 지렛대다.<br><br>이빨이 쇠가 된 살갗에서 미끄러졌다. 무는 힘이 동료 어깨에서 이쪽 팔뚝으로 옮겨 왔다.<br>동료가 빠져나가는 걸 눈가로 보며 팔을 마저 비틀었다. 턱이 벌어졌다.<br>그것은 입맛이 떨어진 얼굴로 물러났다. 씹히지 않는 먹이였다.<br><br>팔뚝에 잇자국이 두 줄 박혔다. 피는 안 났다. 수련장 문답의 답이 맞았다. 몸으로 검산했다.`,
      ng:`팔은 넣었는데 비트는 각이 어긋났다. 턱이 벌어지는 대신 더 물렸다. 동료 어깨와 이쪽 팔뚝을 한입에.<br><br>둘이 한 묶음으로 흔들렸다. 동료들 창이 그것의 눈을 노리고서야 턱이 열렸다.<br>동료 어깨는 깊고 이쪽 팔뚝은 얕았다. 반반의 성공이다.<br><br>지렛대는 넣는 자리가 아니라 비트는 각이 생명이다. 각을 몸에 새기는 데 팔뚝 하나 값을 치렀다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-35, mind:-15 } },
    { l:'② 턱 대신 목을 조른다 — 숨이 끊기면 턱도 풀린다.', k:'break', dc:26,
      doom:{ title:'놓지 않는 턱', what:'목에 매달린 채 둥지로 끌려갑니다', dc:20, sec:40,
        text:`등 뒤로 돌아 목을 감아 조였다. 팔에 내공을 다 몰았다.<br><br>조여도 턱이 안 풀렸다. 숨이 끊겨 가는데도 무는 것들이 있다. 죽을 때 더 꽉 무는 것들이.<br>그것이 동료를 문 채 달리기 시작했다. 목에 매달린 이쪽째. 벽에 긁히고 문틀에 부딪히며 둥지 쪽 어둠으로.<br>동료와 눈이 마주쳤다. 물린 사람과 매달린 사람. 어느 쪽도 놓으라는 말을 안 했다. 놓을 수 있는 쪽이 없었다.`,
        dieText:`복도 끝에서 동료만 돌아왔다. 어깨가 너덜한 채, 혼자.<br><br>목을 조르던 팔이 끝까지 안 풀려서, 그것이 둥지 앞에서 둘 중 하나만 떼어 냈다고 했다. 어느 쪽을 떼어 낼지는 그것이 골랐다.<br>동료는 그 말을 하고 오래 벽을 보고 서 있었다.` },
      ok:`목을 감아 조이되 숨을 끊자는 셈이 아니었다. 머리를 뒤로 꺾는 셈이다.<br><br>턱은 목이 꺾이면 힘이 빠진다. 뼈의 이치다.<br>내공을 몬 팔로 머리를 뒤로 당기자 턱이 벌어지며 동료가 빠졌다.<br>놓자마자 이쪽도 굴러 떨어져 나왔다. 그것의 뒷발톱이 허공을 긁었다.<br><br>조르는 것과 꺾는 것은 다른 수다. 숨은 길고 뼈는 짧다. 급할 때는 짧은 쪽이다.`,
      win:{ exp:21, dream:3 } },
    { l:'③ 동료의 어깨받이 끈을 끊어 몸만 뽑아낸다.', k:'fix', dc:24,
      ok:`물린 건 어깨받이 가죽이 반이었다. 끈 두 가닥을 칼로 끊었다.<br><br>동료 몸이 가죽을 벗고 빠졌다. 그것의 입에는 어깨받이만 남았다.<br>빈 가죽을 씹는 그것을 두고 물러났다.<br><br>단단해지는 공부만 하다 보면 벗는 수를 잊는다. 갑옷은 벗으라고도 있는 것이다. 목숨보다 비싼 가죽은 없다.`,
      ng:`끈 하나를 끊었는데 둘째 끈이 물린 살 밑에 깔려 있었다. 칼이 못 들어간다.<br><br>그 사이 턱이 한 번 고쳐 물었다. 동료 비명이 커졌다.<br>결국 팔뚝을 턱에 넣는 수로 돌아갔다. 처음부터 그랬어야 했다.<br><br>빠른 수부터 찾다가 아픈 시간만 늘였다. 벗기는 수는 깔끔할 때나 수다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S', t:'꼬리 후리기 — 낮게 받는 법',
  x:`그것의 꼬리가 온다. 허리 높이로, 쇠몽둥이처럼. 피하면 뒤의 동료가 받는다.<br><br>
    높은 매는 흘려도 낮은 매는 받으라 했다. 꼬리는 낮은 매다.<br>
    무릎을 꿇다시피 낮추고 어깨를 내밀었다.<br><br>
    어깨로 받으면 설 수 있다. 허리로 받으면 눕는다.`,
  o:[
    { l:'① 어깨를 세워 꼬리의 가운데 토막을 받는다.', k:'steady', dc:25,
      ok:`꼬리의 끝은 채찍이고 뿌리는 기둥이다. 받을 것은 가운데 토막이다.<br><br>반 걸음 파고들며 어깨를 세웠다. 가운데 토막이 어깨뼈에 맞고 꼬리 전체가 출렁했다.<br>끝 채찍은 등 뒤 허공을 쳤다. 동료 머리 위 한 뼘을.<br>그것이 꼬리를 거두며 돌아봤다. 후린 꼬리가 안 먹힌 적이 없는 눈치였다.<br><br>어깨가 한나절 뻐근했다. 매의 어디를 받을지 고르는 것, 그게 받는 공부의 속이다.`,
      ng:`파고드는 반 걸음이 모자랐다. 가운데가 아니라 끝 쪽을 받았다.<br><br>채찍 끝이 어깨를 감아 치고 목덜미까지 긁었다. 몸이 반 바퀴 돌아 바닥에 꽂혔다.<br>그래도 동료 앞은 막았다. 바닥에서 올려다본 꼬리가 다시 들렸고, 동료들 창이 그 밑동을 찔러 세웠다.<br><br>목덜미에 긴 지렁이 자국이 남았다. 매는 토막마다 다른 매다. 눈이 토막을 못 고르면 몸이 값을 치른다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 바닥에 납작 엎드려 꼬리 밑으로 흘린다.', k:'evade', dc:25,
      ok:`받는 대신 버렸다. 무릎 꿇던 자세 그대로 가슴까지 엎었다. 꼬리가 등 위 한 뼘을 지나갔다.<br><br>바람이 등을 쓸었다. 뒤의 동료도 소리에 맞춰 엎드렸다. 둘 다 밑으로 흘렸다.<br>꼬리가 벽을 치고 벽이 움푹했다. 저걸 어깨로 받겠다던 셈이 서늘했다.<br><br>받는 공부의 끝에 안 받는 눈이 생긴다. 받을 매와 버릴 매. 벽의 움푹한 자국이 그 눈금이다.`,
      ng:`이쪽은 엎드렸는데 뒤의 동료가 반 박자 늦었다. 꼬리 끝이 동료의 팔을 스쳤다.<br><br>스친 것만으로 팔이 돌아갔다. 빠진 어깨를 그 자리에서 맞춰 넣었다.<br>동료 입에 가죽끈을 물리고 셋을 세고 당겼다.<br><br>혼자 피하는 건 반쪽이다. 신호를 몸에 미리 심어 뒀어야 했다. 엎드려, 한마디를.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-31, spirit:-15 } }
  ] },

{ at:'S', t:'가시 비 — 조이는 순간',
  x:`그것이 몸을 떨자 등가죽에서 가시가 날았다. 화살비처럼. 바위 뒤는 멀다.<br><br>
    가시는 빠르지만 한 번에 다 날아온다. 활과 같다. 시위 소리가 있고, 닿는 때가 있다.<br>
    외공은 그 사이를 산다. 시위 소리에서 닿기까지, 한 숨의 반.<br><br>
    등을 보일 수는 없다. 등 뒤가 동료들이다.`,
  o:[
    { l:'① 날아오는 때에 맞춰 온몸을 조인다.', k:'steady', dc:26,
      ok:`몸 터는 소리가 시위 소리다. 그 소리에 맞춰 숨을 끊고 조였다.<br><br>가시 예닐곱이 가슴과 팔에 맞고 튕겼다. 조인 살갗은 생나무 판자다. 가시는 박히는 물건이지 뚫는 물건이 아니다.<br>바닥에 떨어진 가시를 주워 봤다. 끝이 다 뭉개져 있었다.<br><br>조임은 세기가 아니라 때다. 늘 조이고 다닐 수는 없다. 맞는 순간에만 판자가 되면 된다. 그 순간을 시위 소리가 가르쳐 준다.`,
      ng:`조임이 반 숨 빨랐다. 조인 숨이 다하고 풀리는 참에 가시가 닿았다.<br><br>둘이 박혔다. 가슴팍 하나, 허벅지 하나. 깊지는 않다. 풀린 살이라도 외공 살이다.<br>뽑고 쑥대로 지졌다.<br><br>빨리 조이는 건 늦는 것과 같다. 조임에는 길이가 있다. 시위 소리보다 몸 터는 준비 동작을 봐야 했다. 한 수 배운 값으로 구멍 두 개.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 동료들 앞에 서서 큰 것만 쳐 낸다.', k:'break', dc:25,
      ok:`다 받을 것 없다. 동료에게 갈 것만 받으면 된다. 앞에 서서 팔뚝으로 낯을 가리고, 굵은 가시만 손등으로 쳐 냈다.<br><br>잔 가시는 겉옷에 박히게 뒀다. 겉옷이 고슴도치가 됐다.<br>굵은 것 셋을 쳐 내고 보니 손등이 얼얼했다.<br>겉옷을 벗어 터니 가시가 우수수 떨어졌다.<br><br>갑옷은 벗을 수 있을 때 갑옷이다. 살로 다 받는 건 하수다. 그 말을 오늘 제 입으로 외웠다.`,
      ng:`굵은 것 둘은 쳐 냈는데 셋째가 꺾여 날았다. 꺾인 가시는 길이 안 읽힌다.<br><br>쇄골 밑에 박혔다. 숨 쉴 때마다 결렸다.<br>그 자리에 선 채로 남은 비를 다 받았다. 물러나면 뒤가 맞는다.<br><br>비가 끝나고 가시를 뽑았다. 꺾여 나는 것까지 읽는 눈은 아직 멀었다. 멀다는 걸 아는 데서 다시 시작이다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-35, spirit:-15 } }
  ] },

{ at:'S', t:'꺼진 바닥 — 떨어지며 하는 공부',
  x:`바닥이 꺼졌다. 삭은 쇠판이 발밑에서 입을 벌렸다. 아래층까지 두 길 반.<br><br>
    떨어지는 동안 생각은 사치다. 몸이 알아서 해야 한다.<br>
    수련장에서 담 높이에서 만 번을 떨어졌다. 턱을 당기고, 무릎을 접고, 구른다.<br><br>
    다른 점은 하나. 아래층에 뭐가 사는지 모른다는 것.`,
  o:[
    { l:'① 배운 대로 떨어진다 — 턱을 당기고 구른다.', k:'steady', dc:25, wake:1,
      ok:`턱을 가슴에 붙이고 무릎을 접었다. 발바닥, 장딴지, 어깨 순으로 바닥을 핥으며 굴렀다.<br><br>구르고 일어서는 데 한 숨. 손에는 벌써 칼이 나와 있었다.<br>아래층은 비어 있었다. 먼지가 사람 모양으로 일어났다 가라앉았다.<br>위에서 동료들이 내려다보는 얼굴에 대고 손을 들어 보였다.<br><br>만 번 떨어진 몸은 만한 번째도 그렇게 떨어진다. 생각 없이. 그 생각 없음이 공부의 끝물이다. 여기서는 일어설 때 칼이 같이 나와야 한다는 것 하나가 더 붙었다.`,
      ng:`구르는 바닥에 쇳조각이 널려 있었다. 어깨가 조각 하나를 깔고 굴렀다.<br><br>어깨죽지가 길게 찢어졌다. 그래도 일어서기는 한 숨에 했다.<br>일어선 자리 두 걸음 앞 어둠에서 숨소리가 났다. 찢어진 어깨로 칼을 들고 숨소리와 마주 섰다. 숨소리가 먼저 물러났다.<br><br>떨어지는 공부에 바닥 고르기는 없었다. 여기 바닥은 수련장 모래가 아니다. 구르기 전 반 숨, 바닥을 보는 눈이 필요하다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 떨어지며 벽을 차서 기세를 죽인다.', k:'evade', dc:25,
      ok:`꺼진 구멍 가장자리 벽이 손 뻗을 거리였다. 떨어지며 벽을 두 번 찼다.<br><br>두 길 반이 반 길 둘과 한 길 하나로 쪼개졌다. 마지막 한 길은 선 채로 받았다.<br>무릎이 한 번 울고 끝났다.<br><br>떨어짐은 통째로 받는 게 아니라 토막 내는 것이다. 벽이 있으면 벽이 토막 칼이다.`,
      ng:`첫 발은 찼는데 둘째 발이 삭은 벽을 뚫었다. 벽이 토막 칼이 아니라 종잇장이었다.<br><br>자세가 깨진 채 떨어졌다. 구르긴 했지만 팔꿈치가 먼저 닿았다.<br>팔이 저려 한동안 주먹이 안 쥐어졌다.<br><br>여기 벽은 차기 전에 눈으로 두드려야 한다. 삭은 쇠는 발을 받아 주지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S', t:'내려앉는 들보 — 어깨의 쓸모',
  x:`천장 들보가 내려앉는다. 동료 둘이 그 밑에 깔릴 자리다. 밀쳐 낼 시간은 없다.<br><br>
    받칠 시간은 있다. 한 걸음, 그리고 어깨.<br>
    외공 수련생의 어깨는 그러라고 있는 어깨다.<br><br>
    들보가 어깨에 닿기 전에 내공이 먼저 닿아야 한다.`,
  o:[
    { l:'① 내공을 등줄기로 몰아 들보를 어깨로 받친다.', k:'steady', dc:26, cost:{ qi:38 },
      ok:`들어가 섰다. 들보가 어깨에 앉았다. 무게가 등줄기를 타고 발바닥까지 꽂혔다.<br><br>무릎이 반 뼘 가라앉고 멈췄다. 이를 악물고 소리쳤다. 나가.<br>동료 둘이 기어 나가는 발소리. 하나. 둘.<br>빈 걸 확인하고 어깨를 빼며 몸을 던졌다. 들보가 등 뒤에서 바닥을 쳤다. 먼지가 해일로 일었다.<br><br>어깨가 불에 덴 듯했지만 부러진 데는 없었다. 기둥 노릇 다섯 숨. 외공 십 년이 그 다섯 숨에 다 들어 있었다.`,
      ng:`받치긴 받쳤는데 들보가 비스듬히 앉았다. 무게가 한쪽 어깨에만 쏠렸다.<br><br>쇄골이 우는 소리를 들으며 버텼다. 동료 둘이 나가고, 빠져나오는 마지막 반 걸음에서 들보 모서리가 등을 긁고 내려갔다.<br><br>등에 손바닥 두 개 폭 생채기가 났다. 쇄골은 금 갔는지 짚을 때마다 운다. 받침은 한가운데가 생명이다. 비뚠 무게는 받는 게 아니라 깔리는 것이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-38, mind:-15 } },
    { l:'② 들보 밑에 어깨 대신 쇠 사물함을 걷어차 넣는다.', k:'fix', dc:25,
      ok:`벽가의 쇠 사물함이 눈에 들어왔다. 어깨보다 나은 기둥이다.<br><br>걷어차 눕혀 들보 낙점에 밀어 넣었다. 들보가 사물함에 앉으며 멈췄다. 사물함이 반쯤 찌그러지고 버텼다.<br>동료 둘이 그 틈으로 나왔다.<br><br>몸이 마지막 연장이라던 스승 말은 순서 이야기였다. 마지막이라는 건 먼저 쓸 게 있으면 먼저 쓰라는 뜻이다.`,
      ng:`사물함이 모로 들어가다 걸렸다. 들보가 그 모서리를 치고 미끄러지며 각이 틀어졌다.<br><br>결국 그 틀어진 각 밑에 어깨를 넣었다. 처음부터 어깨였으면 바로 섰을 각이, 사물함이 버려 놓은 각이 됐다.<br>동료들은 나왔지만 이쪽 허리가 한 번 삐끗했다.<br><br>연장은 던져 넣는 게 아니라 앉혀 넣는 것이다. 급한 손은 연장도 망친다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-34, spirit:-15 } }
  ] },

{ at:'S', t:'모닥불 가 — 흉터 손질',
  x:`하루가 끝났다. 몸에 난 자국들을 불가에서 센다. 발톱 자국 셋, 긁힌 데 다섯, 멍은 세다 말았다.<br><br>
    외공 수련생의 저녁 일과다. 상처는 그냥 두면 흠이 되고 다스리면 굳은살이 된다.<br>
    쑥대 연기를 쐬고, 눌러 풀고, 숨으로 피를 돌린다.<br><br>
    오늘 자국들은 유난히 깊다. 여기 것들은 발톱도 공부가 돼 있다.`,
  o:[
    { l:'① 자국마다 내공을 돌려 굳은살로 눌러 앉힌다.', k:'heal', dc:25, wake:1,
      ok:`자국 하나하나에 손바닥을 얹고 내공을 가늘게 돌렸다. 피가 몰렸다 풀리며 욱신거림이 가라앉는다.<br><br>사흘이면 딱지가 앉고 이레면 굳은살이 된다. 굳은살 앉은 자리는 다음 발톱에 반 치 덜 들어간다.<br>그렇게 몸이 지도가 된다. 맞은 데가 단단해진 지도.<br><br>상처를 두려워하면 외공은 못 간다. 상처를 재산으로 바꾸는 손이 이 공부의 살림이다. 오늘 셋을 재산에 올렸다.`,
      ng:`내공을 돌리는데 발톱 자국 하나가 받질 않는다. 둘레가 푸르스름하다. 발톱에 뭐가 발려 있던 것이다.<br><br>밤새 그 자리가 지끈거렸다. 아침엔 팔이 뻣뻣했다.<br>약초 뭉치를 짓이겨 붙이고 하루를 더 묵었다.<br><br>여기 것들의 발톱은 쇠만이 아니라 독도 공부가 돼 있다. 자국마다 냄새부터 맡는 버릇이 생겼다.`,
      win:{ exp:21, dream:3, hp:7 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 제일 깊은 자국은 동료에게 꿰매 달라 한다.', k:'bond', dc:23,
      ok:`허벅지 자국은 내공으로 안 될 깊이였다. 바늘 잘 쓰는 동료에게 내밀었다.<br><br>동료가 꿰매는 동안 이를 악물 것도 없었다. 조인 살은 바늘도 더디 들어간다. 동료가 웃었다. 가죽이 아니라 장작을 꿰매는 것 같다고.<br>일곱 땀에 아물 길이 섰다.<br><br>제 몸은 제가 고치는 게 외공의 법이지만, 등과 허벅지 뒤는 남의 손이 더 바르다. 내미는 것도 공부다.`,
      ng:`꿰매는 중에 불가 밖에서 기척이 났다. 피 냄새를 맡고 온 것이다.<br><br>실이 반쯤 걸린 채로 일어나 칼을 들었다. 어둠과 한참 대치하다 그것이 물러갔다.<br>다시 앉았을 때 바늘 자리가 부어 있었다. 두 땀을 뜯고 다시 꿰맸다.<br><br>피 냄새 나는 저녁에는 꿰매는 자리부터 바람 아래로 옮길 것. 여기서는 바느질도 자리를 가린다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'빈 단전 — 맨살로 받는 밤',
  x:`내공이 바닥났다. 하루 종일 받고 버틴 값이다. 단전이 빈 우물이다.<br><br>
    하필 그 밤에 그것이 캠프를 덮쳤다. 동료들이 맞서는 사이 하나가 이쪽으로 빠졌다.<br>
    조일 내공이 없다. 지금 이 몸은 그냥 사람 몸이다.<br><br>
    수련 첫해의 몸. 그 몸으로도 받는 법은 배웠었다.`,
  o:[
    { l:'① 내공 없이 뼈의 각도로만 받는다.', k:'steady', dc:26, wake:1,
      ok:`첫해에 배운 것들이 돌아왔다. 내공이 없을 때는 뼈로 받는다. 팔뚝 두 대를 엇갈려 세우고, 팔꿈치를 가슴에 붙이고.<br><br>발톱이 떨어졌다. 아팠다. 정직하게, 사람 살의 아픔으로. 그래도 각이 힘을 갈랐다. 뼈는 상하지 않았다.<br>세 합을 그렇게 받자 동료들 창이 와 닿았다.<br><br>피 흐르는 팔을 보며 알았다. 외공의 바닥은 내공이 아니라 각이다. 내공은 그 각 위에 얹는 것. 바닥이 성하면 빈 우물로도 하룻밤은 산다.`,
      ng:`각은 세웠는데 사람 살은 사람 살이었다. 첫 합에 팔뚝이 열리고 둘째 합에 무릎이 꺾였다.<br><br>셋째 합은 엎드려 등으로 받았다. 등가죽이 길게 갈렸다.<br>동료들이 그것을 쫓아냈을 때 일어나지 못했다.<br><br>업혀서 하룻밤을 났다. 빈 우물인 채 맨 앞에 선 게 잘못이었다. 빈 날은 빈 날의 자리가 있다. 뒤쪽에.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-39, mind:-15 } },
    { l:'② 받지 않고 시간을 번다 — 불붙은 장작을 휘두른다.', k:'evade', dc:25,
      ok:`빈 몸으로 받는 건 만용이다. 모닥불에서 장작 하나를 뽑아 불붙은 쪽을 앞세웠다.<br><br>그것이 불 둘레를 돌았다. 이쪽도 돌았다. 받지 않고 버는 시간.<br>스무 숨을 벌자 창잡이가 옆에 와 섰다.<br><br>외공 수련생이 불막대기나 휘둘렀다고 웃을 사람은 수련장에나 있다. 여기서는 산 사람이 고수다.`,
      ng:`장작이 반에서 부러졌다. 불붙은 쪽이 바닥에 굴렀다.<br><br>맨 토막을 쥔 채 뒷걸음질 쳤다. 그것의 발톱이 가슴팍을 한 번 긁고 지나갔다.<br>동료들이 와서야 끊어 냈다.<br><br>연장 믿고 버는 시간은 연장 수명까지다. 다음부터는 장작도 굵기를 보고 뽑기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-35, spirit:-15 } }
  ] },

{ at:'S1', t:'표본실 앞 — 코앞의 처치',
  x:`복도가 좁아 창이 못 논다. 그것과의 거리가 두 걸음. 칼질 한 번의 거리다.<br><br>
    문제는 피다. 벤 자리에서 끓는 피가 뿜는다. 두 걸음이면 다 뒤집어쓰는 거리.<br>
    베고 물러날 수는 없다. 물러날 자리가 동료들 자리다.<br><br>
    베는 손보다 받는 몸이 먼저 서야 하는 칼질이다.`,
  o:[
    { l:'① 내공을 앞면에 두르고 베는 순간을 함께 받는다.', k:'break', dc:26, cost:{ qi:30 },
      ok:`숨 한 번에 두 가지를 했다. 내공을 얼굴과 가슴에 두르고, 칼을 밀었다.<br><br>목이 갈렸다. 끓는 피가 정면으로 쏟아졌다. 두른 살갗 위에서 피가 끓다 미끄러져 내렸다.<br>김이 눈앞을 덮었다 걷혔다. 그것이 무너져 있었다.<br>얼굴이 발갛게 익었지만 파인 데는 없다.<br><br>베는 공부와 받는 공부가 한 숨에 겹치는 자리. 외공 수련생의 칼질은 거기서 선다. 베기 전에 받을 준비가 끝나 있는 칼질.`,
      ng:`칼이 반 치 얕게 들어갔다. 피 대신 비명이 터졌고, 그것이 몸부림치며 피를 사방에 뿌렸다.<br><br>두른 데는 버텼는데 안 두른 손목에 한 방울이 앉았다. 가죽 토시가 끓으며 손목을 물었다.<br>토시를 이로 물어뜯어 버리고 두 번째 칼질로 끝냈다.<br><br>손목에 동전만 한 자국이 남았다. 두르는 범위는 칼 쥔 손까지다. 베는 손이 제일 가까운 손이라는 걸 잊었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 벤 뒤 반 숨에 동료 방패 뒤로 접어 든다.', k:'evade', dc:25,
      ok:`방패 든 동료와 미리 짰다. 벤다, 접는다, 막는다.<br><br>칼이 들어가는 순간 몸을 접어 방패 뒤로 굴렀다. 끓는 피가 방패 앞면을 때리는 소리를 등으로 들었다.<br>방패 가장자리로 김이 새어 올라왔다.<br><br>혼자 다 받는 건 외공이고, 나눠 받는 건 한 조의 외공이다. 방패와 살갗은 같은 일을 하는 사이였다.`,
      ng:`접는 길에 바닥의 끈적한 것을 밟았다. 반 숨이 한 숨이 됐다.<br><br>방패 뒤에 닿기 전에 피 한 줄기가 등을 긁고 지나갔다. 겉옷이 탔다.<br>동료가 물을 끼얹어 줬다.<br><br>등가죽이 화끈거렸다. 접는 길도 바닥을 보고 접어야 한다. 여기 바닥은 어디든 함정 반 걸음이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-15 } }
  ] },

{ at:'S1', t:'달라붙는 것 — 목을 노리는 입',
  x:`깨진 병들 사이에서 그것이 튀었다. 손바닥만 하고 다리가 많고, 노리는 데는 하나다. 얼굴.<br><br>
    저것들은 입과 목에 깃든다고 표본실 기록에 적혀 있었다.<br>
    쳐 내기엔 빠르고 피하기엔 가깝다.<br><br>
    남는 건 외공 수련생의 세 번째 길이다. 잠그기.`,
  o:[
    { l:'① 턱을 당기고 목과 입을 조여 잠근다.', k:'steady', dc:26,
      ok:`턱을 가슴에 박고 이를 악물고 목 전체를 조였다. 입술까지 쇠가 되게.<br><br>그것이 얼굴에 달라붙었다. 다리가 뺨을 감고 꼬리가 목을 감는다. 들어갈 틈을 찾는다.<br>틈이 없다. 입은 잠긴 문이고 목은 조인 관이다.<br>그것이 다리 사이로 보는 이쪽 눈과 마주쳤다. 눈은 못 들어가는 문이다.<br>동료 손이 그것을 뜯어 바닥에 메쳤다. 창이 꽂혔다.<br><br>숨을 다시 쉬며 알았다. 몸의 구멍이란 구멍이 다 문이다. 외공은 그 문들의 빗장이다.`,
      ng:`목은 잠갔는데 그것의 꼬리가 콧구멍을 파고들려 했다. 숨이 막혔다.<br><br>숨이 급해지면 입이 열린다. 열리려는 입을 악물고 버티는 사이 눈앞이 노래졌다.<br>동료가 뜯어낸 건 이쪽이 쓰러지기 반 숨 전이었다.<br><br>콧등과 입가에 다리 자국이 줄줄이 났다. 빗장도 숨은 쉬어야 빗장이다. 코로 가늘게 쉬는 조임을 따로 연습해야 한다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 달라붙기 전에 허공에서 맨손으로 잡는다.', k:'luck', dc:26,
      doom:{ title:'문을 찾은 것', what:'목에 감긴 것에 끌려 환풍구로 딸려 갑니다', dc:20, sec:35,
        text:`허공에서 잡았다. 잡았다고 생각했다. 그것의 몸이 손아귀에서 뼈 없이 접히며 빠져나갔다.<br><br>팔을 타고 어깨로, 어깨에서 목으로. 꼬리가 목을 감고 조였다.<br>숨이 끊기는 건 순간이었다. 무릎이 꺾이는데 그것이 목을 감은 채 끌기 시작했다. 벽 아래 환풍구 쪽으로. 제 집으로 가져가서 천천히 깃들 셈이다.<br>동료들의 손이 발목을 잡는 게 느껴졌다. 목은 저쪽이, 발목은 이쪽이. 몸이 밧줄이 됐다.`,
        dieText:`환풍구 덮개 앞에서 줄다리기는 끝났다. 어느 쪽이 이겼는지는 덮개 안쪽의 어둠만 안다.<br><br>동료들은 그 환풍구에 쇠판을 대고 못을 박았다.<br>그 방을 나설 때까지 아무도 제 목을 만지는 버릇을 멈추지 못했다.` },
      ok:`허공에서 잡되 손아귀로 쥐지 않았다. 손바닥 두 개로 벽에 몰아 때려 붙였다.<br><br>쥐면 빠져나가는 몸이다. 누르면 못 나간다. 벽과 손바닥 사이에서 그것이 버둥댔다.<br>동료가 칼끝으로 마무리했다.<br><br>손바닥이 한동안 저릿했다. 잡는 것과 누르는 것의 차이. 뼈 없는 것들에게는 면으로 싸워야 한다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'에어록 — 몸으로 받는 바람',
  x:`에어록 바깥문이 반쯤 열린 채 고장 났다. 안팎의 공기가 다른 모양이다. 문틈으로 바람이 칼처럼 분다.<br><br>
    건너편 조작반까지 다섯 걸음. 그 바람 속을 지나야 한다.<br>
    바람에 실려 오는 잔 파편들이 벽에 박힌다. 쇳조각, 유리.<br><br>
    바람은 매다. 그렇게 배웠다. 매면 받는 법이 있다.`,
  o:[
    { l:'① 바람을 비스듬히 가르며 한 걸음씩 박아 걷는다.', k:'steady', dc:26,
      ok:`몸을 바람 쪽으로 반쯤 틀어 어깨부터 넣었다. 정면으로 받으면 돛이고 비스듬히 서면 칼이다.<br><br>한 걸음마다 발을 바닥에 박았다. 파편이 어깨와 팔에 와 박히려다 조인 살갗에서 튕겼다.<br>다섯 걸음에 다섯 번 박고 조작반을 당겼다. 문이 닫히며 바람이 죽었다.<br><br>고요해진 방에서 몸에 박힌 것을 셌다. 없다. 튕긴 자국만 열몇. 바람도 결국 매였다. 토막 내서 받으면 걸을 수 있는 매.`,
      ng:`세 걸음째에 큰 파편이 날아왔다. 주먹만 한 쇳덩이. 조임으로 받을 크기가 아니다.<br><br>팔뚝으로 쳐 냈지만 팔이 저려 네 걸음째가 무너졌다. 바람이 몸을 문틈 쪽으로 끌었다.<br>문틀을 잡고 버텼다. 동료들이 허리에 밧줄을 걸어 당겨 줬다.<br>두 번째 시도에 조작반을 당겼다.<br><br>바람 속 파편은 크기를 가려 받아야 한다. 잔 것은 살갗, 큰 것은 피하기. 그 가림이 반 숨 안에 돼야 한다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 밧줄 없이 바람을 등지고 단숨에 내닫는다.', k:'evade', dc:26,
      doom:{ title:'문틈의 바람', what:'바람에 휩쓸려 문틈 밖 어둠으로 끌려 나갑니다', dc:20, sec:40,
        text:`바람을 등지면 바람이 밀어 준다는 셈이었다. 내달렸다.<br><br>바람은 밀어 줬다. 조작반을 지나쳐 문틈까지.<br>바닥이 미끄러워 설 수가 없다. 문틈이 몸을 빨아들인다. 문틀을 한 손으로 잡고 매달렸다. 틈 밖은 캄캄한 바깥 구역이다. 바람이 그 어둠으로 자꾸 몸을 접어 넣는다.<br>어둠 속에서 뭔가가 바람 소리에 섞여 우는 게 들렸다. 바람에 실려 오는 먹이를 기다리는 울음이었다.`,
        dieText:`동료들이 조작반을 당겨 문을 닫았다. 바람이 죽었다.<br><br>문틈에 가죽 토시 한 짝이 끼어 있었다. 바깥쪽을 향한 채.<br>닫힌 문 너머에서 한참, 쇠를 두드리는 소리가 났다. 안쪽에서 열어 줄 수 있는 문이 아니었다. 소리는 바람이 다시 불 때쯤 그쳤다.` },
      ok:`등지고 내닫되 조작반 세 걸음 앞에서 몸을 던져 바닥 고리를 잡았다. 미끄러지는 몸이 고리에 걸려 멈췄다.<br><br>바람이 등을 밀다 못해 때렸지만, 고리 잡은 팔이 버텼다.<br>팔 하나로 몸을 끌어 조작반을 당겼다.<br><br>바람을 빌려 타는 건 좋은데 내릴 정거장부터 보고 타는 것이다. 고리가 정거장이었다. 못 봤으면 종점은 문틈이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'전시 복도 — 조각상 서기',
  x:`긴 복도에 그것이 들어섰다. 숨을 데가 없다. 불빛도 못 끈다. 비상등이 손 안 닿는 높이다.<br><br>
    여기 것들의 눈은 움직임을 좇는다고 했다.<br>
    외공에 그런 공부가 있다. 조각상 서기. 바람 부는 벼랑에서 반나절을 미동 없이 서는 수련.<br><br>
    그때는 벌이었다. 지금은 목숨이다.`,
  o:[
    { l:'① 다섯 모두 조각상이 된다 — 숨도 조각의 숨으로.', k:'hide', dc:26, wake:1,
      ok:`벽가에 선 채로 굳었다. 동료들에게도 눈짓했다. 선 모양 그대로, 숨은 실로.<br><br>그것이 복도를 걸어왔다. 코가 어깨를 스칠 거리에서 멈췄다. 콧김이 목덜미에 닿는다. 눈동자도 안 굴렸다.<br>그것의 세상에서 멈춘 것은 벽이고 기둥이다. 다섯 개의 기둥 사이를 그것이 지나갔다.<br><br>복도 끝 문이 닫히고 다섯 조각상이 한꺼번에 숨을 토했다. 벼랑의 반나절이 이 복도의 쉰 숨을 위한 공부였다. 멈춤도 외공이다. 가장 어려운.`,
      ng:`마흔 숨까지는 조각이었다. 마흔한 숨에 막내의 무릎이 떨렸다. 겁이 아니라 쥐가 난 것이다.<br><br>그 떨림 하나에 그것의 머리가 홱 돌았다. 조각들 사이에서 떨리는 조각 하나.<br>이쪽이 먼저 움직였다. 벽의 소화전 함을 뜯어 그것에게 던지고 다 같이 내달렸다.<br><br>복도 끝 문을 닫고 빗장을 걸었다. 조각상 서기는 혼자 공부로는 모자랐다. 쥐 안 나는 서기부터 가르쳐야 한다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 비상등 아래 그림자 쪽에 다섯을 포개 세운다.', k:'fix', dc:25,
      ok:`불빛 바로 아래가 그림자다. 비상등 밑 벽에 다섯을 세로로 바싹 포갰다. 하나의 큰 그림자 모양으로.<br><br>그것은 밝은 복도 가운데로 걸었다. 불빛 아래 어둠은 들여다보지 않았다. 빛 속에서 사는 눈이 아니라서, 빛 바로 밑이 저의 맹점이다.<br><br>지나간 뒤 포갠 줄을 풀었다. 등잔 밑의 이치는 사람에게만 통하는 게 아니었다.`,
      ng:`포개 선 자세가 길어지자 맨 밑 동료의 다리가 저렸다. 살짝 고쳐 디딘 발이 바닥 유리 조각을 밟았다.<br><br>빠직. 그것이 돌아섰다.<br>포갠 줄이 와르르 풀리며 복도를 내달렸다. 등 뒤로 발톱 소리가 따라붙다 문에서 끊겼다.<br><br>포개 서는 건 반 식경이 한계다. 긴 기다림엔 교대 조각이 필요하다. 사람은 기둥이 아니니까.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'심부 문턱 — 뼛속을 치는 소리',
  x:`격벽 너머에서 여왕이라 불리는 것이 울었다. 소리가 아니라 떨림이다. 벽을 지나 살을 지나 뼈를 친다.<br><br>
    앞서 걷던 동료가 코피를 쏟으며 주저앉았다. 귀를 막아도 소용없다. 뼈로 들어오는 소리다.<br>
    외공 수련생의 몸은 두드려 만든 몸이다. 두드림이라면, 받아 본 적 있다.<br><br>
    다음 울음이 벽을 타고 온다.`,
  o:[
    { l:'① 내공을 뼈에 감아 떨림을 마디마디서 끊는다.', k:'steady', dc:26, cost:{ qi:33 },
      ok:`내공을 살갗이 아니라 뼈에 둘렀다. 관절 마디마다 매듭을 묶듯.<br><br>울음이 왔다. 정강이뼈로 들어온 떨림이 무릎 매듭에서 반으로 꺾이고, 고관절에서 또 반. 가슴에 닿을 때는 북소리가 빗소리가 돼 있었다.<br>주저앉은 동료를 들쳐 업고 격벽 구간을 건넜다. 업힌 동료에게도 떨림이 반만 갔다. 몸이 방패가 된 것이다.<br><br>떨림은 마디에서 꺾인다. 사람 몸에 마디가 그렇게 많다는 게 처음으로 고마웠다.`,
      ng:`뼈에 두르는 건 처음이라 매듭이 설었다. 울음 한 번에 무릎 매듭이 풀렸다.<br><br>떨림이 곧장 올라와 어금니가 서로 부딪쳤다. 혀를 깨물었다. 입안에 피 맛.<br>그래도 선 채로 받았다. 두 번째 울음 전에 매듭을 고쳐 묶고 동료를 끌고 건넜다.<br><br>혀가 부어 사흘을 어눌하게 말했다. 새 공부는 늘 몸 어딘가로 수업료를 걷는다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 울음의 사이를 재서 그 틈에만 뛴다.', k:'sense', dc:25,
      ok:`울음은 숨이다. 울고, 들이쉬고, 또 운다. 들이쉬는 사이가 스무 숨.<br><br>울음이 끝나는 꼬리를 잡고 뛰었다. 스무 숨에 스무 걸음. 다음 울음이 오기 전에 기둥 뒤에 들어 뼈를 조였다.<br>세 번 뛰고 세 번 숨어 격벽 구간을 났다.<br><br>제일 큰 소리에도 쉼표는 있다. 쉼표를 세는 귀가 뼈를 살렸다.`,
      ng:`두 번째 틈에서 울음이 셈보다 빨리 왔다. 변덕스러운 숨이었다.<br><br>복도 한가운데서 정통으로 받았다. 무릎이 꺾이고 시야가 흔들렸다.<br>기었다. 기둥까지 열 걸음을 손톱으로 바닥을 긁으며.<br><br>코피가 멎는 데 반 식경이 걸렸다. 숨은 장단이지만 산 것의 장단이다. 변덕까지 셈에 넣는 수밖에 없다.`,
      win:{ exp:19, dream:3 }, lose:{ hp:-29, mind:-17 } }
  ] },

{ at:'S1', t:'수지 바닥 — 굳는 덫',
  x:`어두운 방을 질렀다. 바닥이 물컹하더니 발이 안 떨어진다. 검은 수지다. 디딘 발부터 굳고 있다.<br><br>
    둘이 벌써 양발이 잡혔다. 수지는 버둥댈수록 번진다.<br>
    그리고 이 방의 임자가 굳는 소리를 들으러 올 것이다. 덫이란 그런 것이니까.<br><br>
    외공 수련생의 몸에는 덫이 모르는 것이 하나 있다. 몸은 굳힐 수도 있다는 것.`,
  o:[
    { l:'① 다리를 돌처럼 굳혔다가 한 번에 비틀어 깬다.', k:'break', dc:26,
      ok:`버둥대지 말라고 외쳤다. 수지가 다리를 감고 굳는 동안 이쪽도 다리를 굳혔다. 내공으로, 돌처럼.<br><br>수지는 무른 것을 감아 굳는 물건이다. 돌을 감은 수지는 돌의 겉옷일 뿐이다.<br>다 굳기를 기다려, 무릎부터 한 번에 비틀었다. 겉옷이 쩍 갈라졌다.<br>같은 법으로 동료 둘의 다리 둘레를 주먹으로 쳐 깨 줬다.<br><br>덫과 같이 굳어 주고, 덫보다 단단하면 이긴다. 수지가 가르쳐 준 외공이다.`,
      ng:`이쪽 다리는 깼는데 동료 쪽 수지가 더 두꺼웠다. 치는 주먹에 수지 대신 동료 정강이가 울렸다.<br><br>비명을 삼키는 동료 얼굴을 보며 각도를 바꿨다. 세로로 치던 것을 결 따라 비스듬히.<br>세 번 만에 갈라졌다.<br>그때 방 저쪽에서 임자가 들어서는 소리가 났다. 반쯤 깬 수지를 매단 채 넷이 내달렸다.<br><br>깨는 것도 결이 있다. 결을 못 보면 사람을 친다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-32, mind:-15 } },
    { l:'② 겉옷과 장화를 벗고 알몸의 발로 빠져나온다.', k:'evade', dc:25,
      ok:`수지가 잡은 건 발이 아니라 장화다. 끈을 끊고 발만 뽑았다. 맨발이 수지 위에 설 자리는, 굳은 수지 위다.<br><br>굳은 데만 골라 디디며 동료들도 벗겨 뽑았다. 장화 세 켤레와 겉옷 하나가 방바닥에 심어진 채 남았다.<br><br>맨발로 방을 나와 천으로 발을 감았다. 덫이 문 것을 덫에게 준다. 몸만 나오면 이긴 셈이다.`,
      ng:`장화는 벗었는데 맨발이 디딘 데가 덜 굳은 자리였다. 이번엔 발바닥이 잡혔다.<br><br>장화보다 나쁘다. 살은 벗을 수 없다.<br>동료가 칼로 발바닥 둘레 수지를 깎아 내는 동안 임자의 기척이 점점 가까워졌다. 마지막엔 수지째 발을 뜯다시피 뽑았다.<br><br>발바닥 살갗이 한 겹 남았다. 벗는 수는 디딜 곳을 보고 쓰는 수다. 급하면 덫 안에서 덫을 밟는다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S1', t:'냉각 구역 — 숨으로 데우는 밤',
  x:`밤을 날 자리가 하필 냉각 구역이다. 쇠벽이 얼음장이고 입김이 바로 서리가 된다.<br><br>
    불은 못 피운다. 연기가 환풍구를 타고 온 건물에 광고가 된다.<br>
    동료들 입술이 벌써 퍼렇다. 떨리는 몸은 떨림으로 들키고, 곱은 손은 창을 못 쥔다.<br><br>
    외공 수련생의 몸에는 화로가 하나 있다. 단전이라는 화로가.`,
  o:[
    { l:'① 내공을 돌려 제 몸을 데우고 동료들을 등에 붙인다.', k:'heal', dc:25,
      ok:`숨을 길게 돌려 단전의 불을 올렸다. 등과 가슴이 화롯가 돌처럼 덥혀졌다.<br><br>동료들을 등과 옆구리에 붙여 앉혔다. 사람 화로 하나에 넷이 둘러앉은 모양새다.<br>밤새 숨으로 불을 지폈다. 땔감은 아침에 먹을 몫의 반이었지만, 떨다 지친 몸보다 덜 먹은 몸이 낫다.<br><br>추위도 매다. 오래 치는 매. 그 매는 받는 게 아니라 안에서 데워 녹이는 것이다. 몸이 화로가 되는 밤, 외공의 쓸모가 하나 더 늘었다.`,
      ng:`반 밤까지는 화로 노릇을 했다. 반 밤을 넘기자 단전이 바닥을 보였다.<br><br>불이 잦아들며 이쪽 이가 먼저 딱딱 부딪쳤다. 화로가 식으니 둘러앉은 넷이 같이 떨었다.<br>결국 다섯이 한 덩어리로 뒤엉켜 남은 밤을 났다.<br><br>새벽에 손가락이 곱아 창을 두 번 떨어뜨렸다. 화로도 땔감 셈을 하고 때야 한다. 밤의 길이부터 재고 불을 올렸어야 했다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 쇠벽에서 몸을 떼는 잠자리를 짜서 냉기를 끊는다.', k:'fix', dc:24,
      ok:`추위는 쇠에서 온다. 바닥과 벽의 쇠에서. 선반 판자를 뜯어 바닥에 깔고, 배낭을 벽 쪽에 쌓아 냉기 길을 끊었다.<br><br>판자 위에 다섯이 모여 눕자 견딜 만해졌다. 쇠와 살이 닿는 자리를 없앤 것만으로.<br><br>몸으로 버티는 것만 공부가 아니다. 버틸 일을 줄이는 것도 공부다. 스승이 들으면 게으른 소리라 하겠지만, 아침에 손가락이 다 움직였다.`,
      ng:`판자를 뜯는 소리가 밤의 건물에 울렸다. 세 장째에서 멀리 환풍구 쪽이 덜컹였다.<br><br>판자 세 장으로는 다섯 자리가 안 나왔다. 번갈아 눕고 번갈아 앉아 밤을 났다.<br>앉은 차례의 몸은 쇠 냉기를 고스란히 받았다.<br><br>아침에 다들 관절이 녹슨 문처럼 삐걱댔다. 소리 셈과 자리 셈, 둘 다 반쪽이었던 밤이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S2', t:'첫 대면 — 간 보는 이빨',
  x:`발톱 긴 것들은 처음 보는 먹이를 바로 안 문다. 간을 본다. 한 놈이 나서서 슬쩍 물어 보고, 반응으로 값을 매긴다.<br><br>
    지금 그 한 놈이 다가온다. 몸을 낮추고, 장난처럼.<br>
    달아나면 먹이 값이 매겨진다. 맞서면 싸움 값이 매겨진다.<br><br>
    셋째 값이 있다. 못 먹는 것 값.`,
  o:[
    { l:'① 간 보는 이빨을 조인 팔뚝으로 받아 준다.', k:'steady', dc:26, wake:1,
      ok:`팔뚝을 내밀다시피 하고 섰다. 그놈이 슬쩍 물었다. 쇠를 문 턱이 덜컥 울렸다.<br><br>그놈이 고개를 갸웃하고 한 번 더 물었다. 더 세게. 같은 쇠.<br>뱉고, 뒤돌아 무리에게 갔다. 무리 전체가 먼 길로 돌아 사라졌다. 값이 매겨진 것이다. 못 먹는 것. 돌. 바위.<br><br>무리의 셈법을 몸으로 읽었다. 첫 물림의 답이 그 뒤 전부를 정한다. 그 한 입을 받아 주는 배짱, 그게 이 땅에서 외공의 쓸모다.`,
      ng:`첫 물림은 받았다. 문제는 그놈이 영리했다는 것. 두 번째는 팔뚝이 아니라 오금을 노렸다.<br><br>조이지 않은 오금이 긁혔다. 반응이 나왔다. 움찔.<br>값이 매겨졌다. 겉은 돌, 속은 먹이.<br>무리가 반원으로 퍼지는 걸 보며 뒷걸음으로 바위에 붙었다. 동료들 창이 울타리를 치고서야 무리가 물러났다.<br><br>간 보기는 한 군데서 안 끝난다. 온몸이 같은 답을 해야 한다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-15 } },
    { l:'② 간 보러 온 놈의 눈을 맞받아 노려본다.', k:'gaze', dc:25,
      ok:`몸이 아니라 눈으로 답했다. 물러서지도 덤비지도 않고, 그놈 눈을 똑바로.<br><br>짐승의 눈싸움은 셈이 빠르다. 피하는 눈은 먹이, 노려보는 눈은 값을 다시 매겨야 하는 것.<br>그놈이 먼저 눈을 돌렸다. 간 보기가 간 보이기가 된 것이다.<br><br>무리는 그날 이쪽을 건드리지 않았다. 외공은 살갗 공부인 줄 알았는데, 눈빛도 조여지는 것이었다.`,
      ng:`눈은 맞받았는데 숨이 받쳐 주질 못했다. 가쁜 숨이 눈빛의 값을 깎았다.<br><br>그놈이 눈싸움 중에 슬쩍 앞발을 뻗어 정강이를 긁었다. 시선과 몸이 따로 논 것이다.<br>물러나는 이쪽 등 뒤로 무리의 울음이 길게 따라왔다. 값이 반만 매겨진 울음이었다.<br><br>눈빛은 몸의 끝이다. 몸이 안 선 눈빛은 허세고, 저것들은 허세를 제일 빨리 읽는다.`,
      win:{ exp:19, dream:3 }, lose:{ hp:-31, spirit:-16 } }
  ] },

{ at:'S2', t:'물살 속 — 바닥을 쥐는 발',
  x:`잠긴 양치밭을 건너는데 멀리서 큰 것이 물로 들어섰다. 물살이 벽처럼 밀려온다.<br><br>
    헤엄은 답이 아니다. 쓸려 가면 물풀 밑 이빨들의 밥이다.<br>
    외공에 물 공부가 있다. 발가락으로 바닥을 쥐고 몸을 돌처럼 가라앉히는 것.<br><br>
    물살이 열 걸음 앞에서 물보라를 세웠다.`,
  o:[
    { l:'① 발가락으로 바닥을 쥐고 물속 바위가 된다.', k:'steady', dc:26,
      ok:`숨을 크게 물고 몸을 낮춰 어깨까지 잠겼다. 발가락이 바닥 돌 틈을 쥐고 내공이 몸을 눌렀다.<br><br>물살이 덮쳤다. 세상이 한 번 뒤집히는 소리. 몸 위로 강이 지나갔다.<br>쓸리지 않았다. 바위는 물살에 안 쓸린다.<br>물살 꼬리가 지나가고 고개를 들었다. 하류 쪽에 동료들이 바위틈에 매달려 있었다. 다 있었다.<br><br>물속에서 무거워지는 공부. 뜨는 법보다 가라앉는 법이 사람을 살리는 물도 있다.`,
      ng:`발가락은 쥐었는데 디딘 돌이 흔들돌이었다. 물살과 함께 돌째 뽑혔다.<br><br>두 바퀴를 구르며 쓸려 가다 물풀 뿌리를 움켜쥐고 멈췄다. 물풀 밑에서 잔 이빨들이 장딴지를 두 번 긋고 지나갔다.<br>기어 나와 보니 쥐었던 손안에 물풀이 한 움큼이었다.<br><br>바위가 되는 공부의 반은 디딜 바위 고르기였다. 제 몸만 믿다 바닥에 뒤통수를 맞았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 물살을 타고 하류의 둔덕까지 몸을 던진다.', k:'evade', dc:26,
      doom:{ title:'물살의 끝', what:'물살에 쓸려 물풀 밑으로 끌려 들어갑니다', dc:20, sec:40,
        text:`거스를 수 없으면 탄다. 물살이 닿는 순간 발을 떼고 몸을 맡겼다.<br><br>반은 탔다. 반쯤 갔을 때 물속의 손들이 발목을 잡았다. 물풀이 아니다. 물풀 밑에 사는 것들이 물살을 그물 삼아 기다리고 있었다.<br>쓸려 가는 것과 끌려가는 것이 물속에서 하나가 됐다. 수면이 멀어진다. 위로 뻗은 손끝에서 햇빛이 부서졌다. 물살을 탄 게 아니라 밥상에 올라탄 것이었다.`,
        dieText:`물살이 가라앉은 뒤 둔덕 쪽 수면에 장화 한 짝이 떠올랐다.<br><br>동료들은 물풀 지대를 크게 돌아 건넜다. 한나절이 더 걸렸다.<br>건너는 내내 아무도 물속을 내려다보지 않았다. 내려다보면 뭐가 올려다보고 있을 것 같아서.` },
      ok:`타되 맨몸으로 안 탔다. 떠내려온 통나무를 끌어안고 물살에 실렸다.<br><br>물풀 밑에서 뻗은 것들이 통나무를 두 번 쳤다. 사람 살 대신 나무껍질을 물었다.<br>둔덕 모래에 통나무째 처박혔다.<br><br>일어나 통나무를 봤다. 아래쪽에 잇자국이 쭉 돌아가며 나 있었다. 탈것이 대신 받은 매였다. 물살을 탈 때는 방패도 같이 태우는 것이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'가시 울짱 — 업고 뚫는 길',
  x:`뒤는 무리, 앞은 가시덤불. 덤불 너머가 바위 지대다. 발목 다친 동료는 가시를 헤칠 수가 없다.<br><br>
    가시는 손가락 길이에 낚싯바늘처럼 휘었다. 긁히면 찢어진다.<br>
    외공 수련생의 살갗이라면 이야기가 다르다.<br><br>
    등을 내밀었다. 업혀. 눈 감고.`,
  o:[
    { l:'① 동료를 업고 온몸을 조여 덤불을 정면으로 민다.', k:'steady', dc:26, wake:1,
      ok:`동료를 업고 그 위에 겉옷을 덮었다. 이쪽은 낯만 가리고 내공을 온몸에 둘렀다.<br><br>덤불을 어깨로 밀며 들어갔다. 가시들이 살갗을 긁고 휘고 부러졌다. 바늘이 가죽 북을 긁는 소리.<br>스무 걸음의 가시밭을 소처럼 밀고 나왔다. 등의 동료는 생채기 하나 없었다.<br>뒤쫓던 무리는 덤불 앞에서 멈춰 울기만 했다.<br><br>조인 살갗은 제 것만 지키라고 있는 게 아니었다. 업힌 숨이 등에 닿을 때, 이 공부의 쓸모를 다 배웠다.`,
      ng:`반쯤 밀고 나갔을 때 유난히 굵은 가시가 조임 틈을 찾았다. 겨드랑이 밑, 조임이 얇은 자리.<br><br>길게 찢어졌다. 업힌 동료가 내리겠다고 버둥댔다. 더 꽉 쥐고 마저 밀었다.<br>빠져나와 찢어진 데를 꿰맸다. 동료가 바늘을 쥔 손을 떨었다. 떨지 말라고, 가죽보다 질기다고 웃어 줬다.<br><br>조임에도 얇은 자리가 있다. 겨드랑이, 오금, 사타구니. 접히는 데는 다 얇다. 그 지도를 오늘 몸에 그렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-35, mind:-14 } },
    { l:'② 덤불 밑 짐승 굴로 긴다 — 낮은 길은 가시가 성글다.', k:'break', dc:26,
      doom:{ title:'굴의 임자', what:'덤불 밑 굴로 끌려 들어갑니다', dc:20, sec:35,
        text:`덤불 아래쪽은 가시가 성글었다. 작은 짐승들이 뚫어 둔 길이다. 동료를 앞세우고 기었다.<br><br>반쯤 기었을 때 굴이 넓어졌다. 넓어진 데는 넓힌 임자가 있다.<br>어둠 속에서 앞 동료의 비명이 났다. 동료 발목을 잡았는데 동료째 끌려간다. 굴이 아래로 꺾였다. 가시덤불 밑에 집을 짓고, 덤불에 쫓긴 것들이 기어들기를 기다리는 것. 덤불은 울타리가 아니라 그물이었다.`,
        dieText:`덤불 밑 굴 입구에 찢어진 겉옷 자락만 남았다.<br><br>남은 일행은 덤불을 정면으로 밀고 나갔다. 생채기투성이가 됐지만 넘었다.<br>바위 지대에서 돌아본 덤불은 고요했다. 그 밑에 집이 몇 채나 있는지는, 덤불만 안다.` },
      ok:`굴로 기되 먼저 창대부터 밀어 넣었다. 창대 끝에 겉옷을 감아서.<br><br>굴 중간에서 창대가 홱 당겨졌다. 임자가 있다.<br>창대를 놓고 굴을 버렸다. 빈 미끼를 문 임자가 알아챌 때쯤 일행은 정면 돌파로 돌아섰다.<br><br>낮은 길, 쉬운 길에는 먼저 지나간 것들의 셈이 깔려 있다. 미끼 하나 값으로 그 셈을 읽었으면 싸다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'큰 것의 발밑 — 떨림의 복판',
  x:`트인 벌판에서 큰 것과 길이 겹쳤다. 숨을 바위가 멀다. 그것의 걸음이 땅을 접으며 온다.<br><br>
    쿵. 쿵. 떨림이 복사뼈를 타고 올라온다.<br>
    저것의 눈은 움직임을 좇고, 발은 떨림을 듣는다. 뛰면 둘 다에게 들킨다.<br><br>
    남는 수는 떨림의 복판에 서는 것이다. 제일 큰 소리 옆이 제일 조용한 법이니까.`,
  o:[
    { l:'① 무릎을 접어 떨림을 받아 내며 그 자리에 선다.', k:'steady', dc:26, wake:1,
      ok:`무릎과 발목을 반쯤 접고 내공을 발바닥에 깔았다. 떨림이 올라오는 족족 무릎에서 꺾어 버렸다.<br><br>몸이 안 떨리면 땅에 되돌려 주는 떨림도 없다. 그것의 발바닥 귀에 이쪽은 돌덩이 하나다.<br>걸음이 왼쪽 열 걸음 밖을 지나갔다. 그늘이 몸을 덮었다 벗겨졌다.<br>꼬리 끝이 일으킨 바람에 옷자락만 펄럭였다.<br><br>떨림을 받는 무릎은 떨림을 돌려주지 않는 무릎이다. 땅과 몸 사이의 문도 닫을 수 있다는 것. 외공의 문단속에 하나가 더 늘었다.`,
      ng:`걸음 하나가 셈보다 가까이 떨어졌다. 다섯 걸음 안. 땅이 뛰어오르며 접은 무릎이 펴졌다.<br><br>펴진 몸이 비틀, 반걸음을 밟았다. 그 반걸음의 떨림.<br>그것이 멈췄다. 콧김이 벌판 풀을 갈랐다. 눈 감고 숨 끊고 버틴 스무 숨.<br>풀벌레 하나가 날아오르자 그쪽으로 머리가 돌았고, 걸음이 이어졌다.<br><br>주저앉듯 숨을 토했다. 반걸음이 이렇게 큰 줄 벌판 복판에서 배웠다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-19, spirit:-17 } },
    { l:'② 걸음 사이에 맞춰 바위까지 토막 달리기를 한다.', k:'hide', dc:26,
      doom:{ title:'벌판의 그늘', what:'큰 것의 입에 물려 하늘로 끌려 올라갑니다', dc:20, sec:35,
        text:`쿵, 소리에 맞춰 뛰고 사이에 멈추기를 반복했다. 바위까지 반을 갔다.<br><br>그때 걸음이 멎었다. 장단이 사라지면 토막 달리기도 장단을 잃는다. 멈춘 채 다음 쿵을 기다리는데, 그늘이 머리 위로 내려왔다.<br>걸음을 멈춘 건 이쪽을 봤기 때문이었다. 목이 내려오고, 입이 열리고, 옷과 어깻죽지가 한입에 물렸다. 땅이 쑥 멀어진다. 벌판이 작아진다. 동료들이 콩알만 해진다. 하늘로 끌려 올라가는 길은 생각보다 조용했다.`,
        dieText:`큰 것은 벌판을 느리게 가로질러 숲 너머로 사라졌다. 고개를 한 번도 숙이지 않은 채.<br><br>동료들은 해가 질 때까지 벌판 가장자리를 뒤졌다. 찾은 것은 장화 한 짝이었다. 높은 데서 떨어진 모양으로 바위 위에 놓여 있었다.<br>그 벌판에는 그 뒤로 아무도 발을 들이지 않았다.` },
      ok:`토막 달리기를 하되 장단을 귀가 아니라 발바닥에 맡겼다. 떨림이 오면 뛰고, 잦아들면 굳었다.<br><br>걸음이 한 번 멎었을 때 이쪽도 반 숨 먼저 굳어 있었다. 발바닥이 귀보다 빨랐다.<br>그늘이 벌판을 한 바퀴 훑고 지나갔다.<br>다시 쿵. 마지막 세 토막을 달려 바위 틈에 접혔다.<br><br>남의 장단을 탈 때는 장단이 끊기는 순간까지 타야 한다. 발바닥이 그걸 해냈다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'S2', t:'뿔 돋친 것 — 빗면의 공부',
  x:`뿔 돋친 것이 땅을 긁는다. 이번에는 피할 벽도 세울 방패도 없다. 맨몸과 돌진 사이에 빈 땅뿐이다.<br><br>
    정면으로 받으면 사람이 아니라 쇠도 접힌다.<br>
    남는 건 외공의 마지막 장. 힘을 꺾는 것이 아니라 힘의 길을 꺾는 것.<br><br>
    두 뿔 사이가 아니라 뿔 하나의 옆면. 거기가 문이다.`,
  o:[
    { l:'① 내공을 두 팔에 몰아 뿔 옆면을 쳐서 길을 꺾는다.', k:'break', dc:26, cost:{ qi:36 },
      ok:`닿기 직전 반 보 틀며 두 손바닥을 포개 뿔 옆면을 밀어 쳤다.<br><br>꺾으려는 게 아니다. 기울이는 것이다. 달리는 힘이 기운 뿔을 따라 비스듬히 흘렀다.<br>그것의 머리가 반 뼘 돌아가자 몸통이 통째로 따라 돌았다. 돌진이 이쪽 옆구리를 스쳐 빈 땅에 꽂혔다.<br>흙먼지 속에서 그것이 제 돌진에 제가 엉켜 넘어졌다.<br><br>손바닥이 한나절 울렸다. 산을 못 막으면 산의 길을 민다. 반 뼘이면 된다. 그 반 뼘에 외공 전부를 싣는 법을 배웠다.`,
      ng:`옆면을 쳤는데 그것이 머리를 흔드는 버릇이 있었다. 기울인 반 뼘이 도로 돌아왔다.<br><br>뿔 끝이 옆구리를 걸었다. 몸이 공중에서 한 바퀴 돌아 떨어졌다.<br>구르며 일어났다. 두 번째 돌진은 동료들이 양쪽에서 소리를 질러 흩어 줬다.<br><br>옆구리 가죽이 찢어졌다. 민 반 뼘은 맞았는데 상대의 반 뼘을 셈 못 했다. 산에도 버릇이 있다. 버릇까지 밀어야 다 민 것이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-37, mind:-14 } },
    { l:'② 돌진 선상에서 마지막 순간 땅에 납작 붙는다.', k:'evade', dc:26,
      ok:`뿔 돋친 것의 머리는 낮게 달리다 받는 순간 들린다. 들리는 그 밑이 빈다.<br><br>마지막 두 걸음에서 몸을 던져 납작 엎드렸다. 들린 머리 밑, 네 다리 사이로 세상이 지나갔다. 배 비늘이 등을 쓸고 갔다.<br>지나간 그것은 빈 땅에서 한참 두리번댔다.<br><br>일어나 흙을 털었다. 제일 위험한 자리가 제일 안전한 자리로 뒤집히는 게 한 숨이다. 그 한 숨을 믿는 게 배짱이고, 배짱도 공부다.`,
      ng:`엎드리는 게 반 박자 빨랐다. 그것이 달리면서 머리를 도로 낮췄다.<br><br>뿔 밑동이 등을 긁고 지나갔다. 갑옷 등판이 뜯겨 나갔다.<br>뒹굴어 일어났을 때 등이 화끈거렸다.<br><br>엎드리기는 상대 머리가 들린 다음이다. 먼저 엎드리면 밟으라고 까는 멍석이다. 반 박자를 등가죽으로 샀다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-36, spirit:-15 } }
  ] },

{ at:'S2', t:'엘리베이터 — 휘는 창살',
  x:`바구니가 오르는 중에 발톱 긴 것 하나가 매달렸다. 창살 두 대를 쥐고 벌리고 있다. 쇠가 엿가락처럼 운다.<br><br>
    벌어진 틈이 머리 하나 폭. 조금만 더 벌면 몸이 들어온다.<br>
    창으로 찌르기엔 각이 없다. 창살 사이는 외공 수련생의 팔뚝 자리다.<br><br>
    쇠와 쇠 사이에서 힘겨루기다.`,
  o:[
    { l:'① 창살 사이에 팔을 걸고 맞벌리며 버틴다.', k:'steady', dc:26,
      doom:{ title:'창살 밖으로', what:'창살 틈으로 뽑혀 바구니 밖으로 끌려 나갑니다', dc:20, sec:35,
        text:`벌어지는 창살 사이에 두 팔을 걸고 안쪽으로 당겼다. 그것의 벌리는 힘과 이쪽의 모으는 힘이 쇠 두 대 위에서 만났다.<br><br>버텼다. 버텨졌다. 그때 그것이 수를 바꿨다. 창살을 놓고 이쪽 팔목을 잡았다.<br>모으던 힘이 허공을 쥐고, 몸이 벌어진 틈으로 빨려 나간다. 어깨가 창살에 걸리고, 그것의 무게가 팔에 실렸다. 바구니 밖은 허공이고 아래는 벌판이다. 벌판에서 무리가 올려다보며 입을 벌리고 있었다. 받을 준비들을 하고.`,
        dieText:`바구니가 꼭대기에 닿았을 때 창살 두 대가 바깥으로 휘어 있었다.<br><br>틈에는 가죽 토시가 한 짝 걸려 있었다. 안쪽을 향한 손 모양으로.<br>동료들은 토시를 거두고 창살을 안에서 묶었다. 올라오는 내내 아무도 아래를 내려다보지 못했다.` },
      ok:`팔을 걸되 창살이 아니라 그것의 손가락 위로 걸었다. 쇠와 발톱을 한꺼번에 감아 쥐는 자리다.<br><br>내공을 몬 손아귀로 발톱 마디를 꺾어 눌렀다. 쇠를 벌리던 힘이 제 마디 아픈 데로 흩어졌다.<br>그것이 비명을 물며 손을 뺐다. 매달릴 데를 잃고 바구니 벽을 긁으며 떨어졌다.<br><br>힘겨루기는 힘 닿는 자리 고르기다. 쇠 두 대 말고 마디 두 개. 작은 자리가 이긴다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 휜 창살을 안쪽에서 발로 걷어차 도로 편다.', k:'fix', dc:25,
      ok:`벌리는 힘의 복판을 피해, 휜 창살의 허리를 안쪽에서 걷어찼다. 한 번, 두 번.<br><br>쇠는 벌린 쪽보다 편 쪽의 기억이 길다. 창살이 도로 서며 그것의 발톱이 틈에 물렸다.<br>물린 발톱을 빼내느라 그것이 매달림을 풀었다. 떨어지며 바구니가 가벼워졌다.<br><br>쇠도 몸이다. 어디를 치면 펴지는지, 외공이 제 몸에서 배운 것과 같은 자리였다.`,
      ng:`걷어찬 각이 어긋나 창살 대신 그것의 주둥이를 찼다. 성만 돋웠다.<br><br>그것이 흔드는 통에 바구니가 추처럼 흔들렸다. 다들 바닥에 붙어 창살을 쥐었다.<br>꼭대기 승강구 턱에 바구니가 닿아서야 그것이 뛰어내렸다.<br><br>발길질은 거리가 반이다. 흔들리는 바닥 위의 거리는 눈이 아니라 발이 재야 했다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-31, mind:-14 } }
  ] },

{ at:'S2', t:'진흙 벌 — 가벼워지는 공부',
  x:`진흙 벌이 길을 막는다. 돌아가면 한나절, 질러가면 한 식경.<br><br>
    맨 앞의 동료가 두 걸음에 무릎까지 빠졌다. 단단히 조인 외공의 몸은 더 나쁘다. 무거우니까.<br>
    단단해지는 공부만 십 년을 했다. 그 반대가 있다는 말만 들었다.<br><br>
    뼈를 비우고 숨으로 몸을 드는 것. 경공은 아니어도, 그 어귀까지는.`,
  o:[
    { l:'① 조임을 다 풀고 숨을 띄워 넓게 디디며 건넌다.', k:'evade', dc:26, wake:1,
      ok:`십 년 조인 것을 다 풀었다. 어깨에서 발끝까지. 숨을 가슴 위쪽에 띄우고, 발바닥을 넓게 폈다.<br><br>진흙이 발을 받았다. 빠지기 전에 다음 발. 눈 위를 걷는 짐승의 걸음으로.<br>한 식경 거리를 반 식경에 건넜다. 뒤따르는 동료들에게도 걸음법을 일러 줬다.<br><br>건너편에서 돌아보며 알았다. 단단함은 외공의 반쪽이다. 무거워지는 몸은 가벼워질 줄도 알아야 온전하다. 나머지 반쪽의 문이 오늘 열렸다.`,
      ng:`푼다고 풀었는데 허리의 조임이 안 풀렸다. 십 년 버릇이다.<br><br>반쯤 건너다 허리부터 가라앉았다. 가슴까지 빠져서야 몸이 급해져 저절로 풀렸다.<br>동료들이 창대를 이어 뻗어 끌어냈다.<br><br>진흙을 뒤집어쓴 채 건너편에 누웠다. 조이는 건 한 숨에 되는데 푸는 건 숨 열 개로도 덜 풀린다. 비우는 공부가 쌓는 공부보다 어렵다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 갈대 단을 베어 깔며 길을 놓는다.', k:'fix', dc:25,
      ok:`벌 가장자리 갈대를 베어 단으로 묶었다. 한 단 깔고 딛고, 다음 단 깔고.<br><br>발판이 무게를 넓게 편다. 조인 몸 그대로도 빠지지 않았다.<br>건너고 나서 단을 거둬 묶어 뒀다. 돌아올 때도 쓸 길이다.<br><br>몸을 못 바꾸면 땅을 바꾼다. 그것도 답이다. 다만 어귀까지 간 그 공부는 숙제로 남았다.`,
      ng:`갈대 단이 중간부터 모자랐다. 아껴 깔다 간격이 벌어졌다.<br><br>벌어진 데를 건너뛰다 한 발이 빠졌다. 단을 쥐고 버텨 겨우 뽑았다. 장화는 진흙이 가져갔다.<br><br>맨발 한 짝으로 남은 길을 건넜다. 길을 놓는 수는 자재 셈부터다. 반 길짜리 다리는 다리가 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, spirit:-15 } },
    { l:'③ 제일 가벼운 막내를 먼저 보내 길을 읽게 한다.', k:'bond', dc:25,
      ok:`막내가 제일 가볍다. 밧줄을 묶어 먼저 보냈다. 단단한 길을 밟아 찾으며 가라고.<br><br>막내가 찾은 길을 뒤따라 하나씩 건넜다. 막내 발자국이 꺼진 데는 피하고 선 데만 밟았다.<br>맨 뒤의 이쪽이 제일 무거우니 맨 나중. 밧줄 네 개가 앞에서 당겨 줬다.<br><br>무거운 사람의 길은 가벼운 사람이 먼저 그려 준다. 조의 걸음은 그렇게 서로를 빌린다.`,
      ng:`막내가 반쯤에서 길을 잃었다. 단단한 줄이 끊긴 것이다. 막내가 허리까지 빠지며 당황해 버둥댔다.<br><br>밧줄을 당기는데 버둥대는 무게는 선 무게의 배다.<br>결국 이쪽이 진흙으로 들어가 업어 날랐다. 조인 몸이 허벅지까지 빠지며 한 걸음에 한 숨씩 먹었다.<br><br>둘 다 진흙 귀신이 돼 나왔다. 앞세운 사람에게는 돌아오는 길부터 가르쳐야 했다. 길은 가는 줄만으론 반쪽이다.`,
      win:{ exp:19, dream:2, spirit:5 }, lose:{ hp:-28, spirit:-16 } }
  ] }

]);

// ── 광부 (miner) · 자원 없음
kJob('miner', 'S', [

{ at:'S', t:'막힌 벽 — 두드리고 옮기기',
  x:`길이 벽으로 끝났다. 광부는 벽을 믿지 않는다. 벽 너머에 길이 있는지는 두드려 보면 안다.<br><br>
    곡괭이 자루로 두드렸다. 꽉. 꽉. 텅. 왼쪽 아래가 비었다.<br>
    문제는 이 어둠에서 소리를 내는 값이다. 여기 것들은 소리로 사냥한다.<br><br>
    두드린 자리에 오래 서 있는 광부는 여기선 오래 못 산다.`,
  o:[
    { l:'① 두드리고 바로 자리를 옮기며 소리를 흘린다.', k:'steady', dc:25, wake:1,
      ok:`한 번 두드리고 다섯 걸음 옮겼다. 또 한 번, 또 다섯 걸음.<br><br>소리가 난 자리와 사람이 선 자리를 계속 어긋나게 했다.<br>과연 세 번째 소리 자리에 어둠이 덮쳤다. 빈자리였다. 그것이 허공을 할퀴는 사이 넷째 자리에서 마지막 타진을 끝냈다. 왼쪽 아래, 사람 하나 길이 분명했다.<br><br>갱에서 배운 타진에 여기 법 하나를 더했다. 소리는 두고 몸은 옮긴다. 두드리는 손과 서 있는 발이 따로 노는 광부가 여기서 사는 광부다.`,
      ng:`두 번째까지는 옮겼는데 세 번째에 급해서 같은 자리에서 두드렸다.<br><br>천장에서 그것이 떨어졌다. 곡괭이 자루를 방패 삼아 받았다. 자루가 반으로 꺾였다.<br>동료들 창이 그것을 벽으로 몰아내고서야 숨을 쉬었다.<br><br>자루 반쪽을 쥐고 알았다. 급한 두드림이 관 두드림 된다. 갱 속담이 여기서도 참말이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 멈추지 않고 벽을 마저 두드려 빈 데를 다 그린다.', k:'luck', dc:26,
      doom:{ title:'소리의 임자', what:'소리를 쫓아온 것에 물려 어둠으로 끌려갑니다', dc:20, sec:40,
        text:`빈 데의 윤곽이 반쯤 그려졌다. 조금만 더. 꽉, 텅, 텅.<br><br>마지막 텅, 소리의 메아리에 다른 소리가 겹쳤다. 네 발이 바닥을 접는 소리.<br>돌아보기 전에 어깨가 물렸다. 곡괭이가 손에서 떨어졌다. 끌려가며 벽의 그 빈 데를 계속 생각했다. 사람 하나 길이. 다 그리지 못한 문.<br>동료들의 불빛이 멀어지고, 어둠이 아래로 꺾였다. 여기 것들의 집은 늘 아래다. 광부처럼.`,
        dieText:`떨어진 곡괭이는 벽 밑에 그대로 있었다.<br><br>동료들이 그 곡괭이로 왼쪽 아래 빈 데를 뚫었다. 사람 하나 길이 나왔다.<br>길을 연 곡괭이의 임자는 그 길로 나가지 못했다. 일행은 곡괭이를 가지고 나갔다. 갱의 법이다. 연장은 남은 사람이 쓴다.` },
      ok:`멈추지 않되 두드림 사이에 귀를 꽂았다. 꽉, 텅. 쉬고 듣고. 텅.<br><br>세 번째 쉼에서 발소리를 잡았다. 멀리서 소리를 더듬어 오는 걸음.<br>윤곽은 칠 할이면 족하다. 남은 삼 할은 곡괭이가 들어가며 그린다. 바로 파기 시작해 사람 하나 틈을 열고 다섯이 빠졌다.<br><br>마지막 동료가 지난 뒤 틈에 돌을 괴어 막았다. 돌 너머에서 발톱이 벽을 긁는 소리가 한참 났다.`,
      win:{ exp:19, dream:3 } }
  ] },

{ at:'S', t:'등불 — 기우는 불꽃',
  x:`갈림길이 셋이다. 지도는 없다. 광부에게는 등불이 지도다.<br><br>
    불꽃은 공기가 흐르는 쪽으로 눕는다. 공기가 흐르는 길은 어딘가로 뚫린 길이다.<br>
    등불을 세 길 어귀에 차례로 세웠다.<br><br>
    왼길에서 불꽃이 가늘게 누웠다. 그런데 가운데 길에서는, 불꽃이 이쪽으로 누웠다. 무엇이 공기를 밀며 오는 것이다.`,
  o:[
    { l:'① 불꽃이 눕는 왼길로 서둘러 든다.', k:'sense', dc:25,
      ok:`왼길로 들며 등불을 맨 뒤로 돌렸다. 가운데 길의 것에게 불빛 꼬리를 안 보이려고.<br><br>왼길은 과연 바람길이었다. 불꽃이 끝까지 같은 쪽으로 누웠다.<br>등 뒤 가운데 길에서 공기 밀리는 소리가 갈림목을 지나 오른길로 빠졌다. 불꽃 하나 차이로 길이 갈렸다.<br><br>불꽃은 광부의 나침반이고, 여기서는 파수꾼이기도 했다. 눕는 쪽과 눕는 때를 같이 읽으면 길과 적이 한 불에 보인다.`,
      ng:`왼길로 드는데 등불을 앞세운 채였다. 불빛이 갈림목에 길게 꼬리를 남겼다.<br><br>가운데 길의 것이 그 꼬리를 따라 꺾어 들어왔다. 뒤에서 공기가 확 밀렸다.<br>등불을 끄고 벽에 붙어 그것이 지나가기를 빌었다. 그것은 다섯 걸음 앞에서 한참 코를 들고 서 있다 갔다.<br><br>어둠 속에서 다시 불을 켜는 손이 떨렸다. 불은 길도 그리고 미끼도 그린다. 쥔 사람이 가려 써야 한다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 불을 끄고 뺨으로 바람을 읽는다.', k:'steady', dc:25,
      ok:`불을 껐다. 어둠 속에서 뺨과 귓바퀴에 공기를 댔다. 광부는 불 없이도 바람을 읽을 줄 알아야 한다. 갱에서 불이 꺼지는 날은 오니까.<br><br>왼쪽 뺨이 서늘했다. 왼길이 숨구멍이다. 가운데서 오는 미지근한 밀림도 뺨이 먼저 알았다.<br>어둠인 채로 왼길에 들어 스무 걸음을 간 뒤에야 불을 켰다.<br><br>그것은 불 꺼진 갈림목에서 길을 잃었다. 빛으로 사냥 못 하는 밤눈도, 불꽃 꼬리는 좇을 줄 안다. 꼬리를 아예 지운 것이다.`,
      ng:`어둠 속에서 발밑 돌을 못 봤다. 돌이 구르며 갈림목에 소리가 울렸다.<br><br>가운데 길의 밀림이 곧장 빨라졌다. 불도 없이 왼길을 더듬어 뛰었다.<br>벽 모서리에 이마가 찍혔다.<br><br>뒤따르던 동료들이 겨우 손을 이어 줬다. 불 없는 걸음은 바람 읽기 전에 발밑 읽기부터였다. 순서를 피로 배웠다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S', t:'우는 천장 — 버팀목 세우기',
  x:`쉬어 갈 자리는 좋은데 천장이 운다. 끼익. 끼이익. 광부 귀에 저 소리는 자장가가 아니라 초읽기다.<br><br>
    바닥에 떨어진 돌가루가 한 줄로 쌓여 있다. 금 간 자리에서 떨어진 것이다.<br>
    버팀목감은 있다. 부러진 창대 둘, 짐 고정용 각목 하나.<br><br>
    다만 망치질 소리가 어둠에 어떻게 들릴지가 문제다.`,
  o:[
    { l:'① 망치 대신 어깨로 밀어 넣고 쐐기는 손으로 박는다.', k:'steady', dc:25,
      ok:`버팀목을 세울 자리를 돌가루 줄 바로 밑으로 잡았다. 각목을 어깨로 지그시 밀어 올려 끼우고, 쐐기는 손바닥으로 눌러 박았다. 망치 소리 한 번 없이.<br><br>천장 울음이 반으로 줄었다. 끼익이 끄응으로.<br>밤새 두 번 깨서 쐐기를 더 눌렀다. 아침까지 천장은 버텼고 어둠은 조용했다.<br><br>갱의 일은 원래 소리의 일이다. 소리를 뺀 갱일을 여기서 새로 배운다. 어깨가 망치가 되고 손바닥이 메가 되는.`,
      ng:`어깨로 미는데 각이 반 치 어긋났다. 각목이 미끄러지며 벽을 쳤다. 깡.<br><br>소리가 어둠을 깨웠다. 멀리서 긁는 소리가 대답했다.<br>버팀목을 마저 세우는 손이 급해졌다. 급한 쐐기는 설다. 밤중에 한 번 빠져서 다시 박았다.<br><br>그래도 천장은 버텼다. 소리 하나에 잠 하나. 여기 갱의 환율이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 버팀목 없이 금의 끝을 읽고 자리만 옮긴다.', k:'gaze', dc:24,
      ok:`금을 등불로 따라갔다. 금은 천장을 비스듬히 지르다 바위 결 단단한 데서 멈춰 있었다.<br><br>무너져도 금 안쪽 반이다. 잘 자리를 금 바깥쪽으로 옮기면 버팀목도 필요 없다.<br>옮긴 자리에서 다섯이 잤다. 밤중에 금 안쪽에서 주먹돌 몇 개가 떨어졌다. 옮기지 않았으면 머리맡이었다.<br><br>버티는 수만 수가 아니다. 무너질 자리를 읽고 비키는 것, 그게 광부의 첫 공부였다.`,
      ng:`금의 끝을 읽었는데 등불 그림자에 속았다. 금이 바위 결을 넘어 반 뼘 더 가 있었다.<br><br>밤중에 그 반 뼘이 내려앉았다. 발치에 주먹돌이 쏟아져 막내 정강이를 때렸다.<br>놀란 소리가 어둠에 퍼져 한 식경을 무기 쥐고 앉아 있었다.<br><br>금 읽기는 불을 두 자리에서 비춰 겹으로 읽어야 한다. 그림자 하나가 반 뼘을 숨겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'단내 — 혀에 닿는 공기',
  x:`걷다가 혀끝에 단맛이 스쳤다. 광부는 그 맛을 안다. 갱 깊은 데서 사람을 눕히는 공기. 단내 나는 공기는 숨을 데려간다.<br><br>
    등불 불꽃이 평소보다 길고 흐리다. 그것도 표식이다.<br>
    이 어둠의 낮은 데를 나쁜 공기가 채우고 있다.<br><br>
    뒤의 동료들은 아직 모른다. 단맛은 맨 앞 혀에 먼저 온다.`,
  o:[
    { l:'① 일행을 세우고 높은 턱 길로 올려 걷게 한다.', k:'steady', dc:25, wake:1,
      ok:`손을 들어 일행을 세웠다. 낮은 길을 버리고 벽가의 턱진 길로 올렸다. 나쁜 공기는 무겁다. 어깨 높이만 벌어도 다른 하늘이다.<br><br>턱길을 걷는 동안 등불을 가슴 높이로 들고 불꽃만 봤다. 불꽃이 살아나면 공기가 산 것이다.<br>낮은 길 쪽에서 짐승 하나가 비틀거리다 눕는 걸 봤다. 코로 사는 것들에게 저 공기는 덫 중의 덫이다.<br><br>혀끝 단맛 하나로 다섯 목숨이 턱 하나를 올랐다. 광부의 혀는 그러라고 있는 혀다.`,
      ng:`턱길로 올리는데 막내가 벌써 어지럽다고 주저앉았다. 낮은 데를 너무 오래 걸은 뒤였다.<br><br>둘이 양팔을 꿰어 턱으로 끌어올렸다. 끌어올리는 동안 이쪽도 단맛을 더 삼켰다.<br>턱 위에서 한참 둘이 나란히 토악질을 했다.<br><br>단맛은 느끼는 순간이 이미 반 박자 늦은 것이다. 다음부터는 불꽃 길이를 먼저 본다. 혀보다 불이 빠르다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 겉옷을 적셔 코와 입을 막고 낮은 길을 빨리 지난다.', k:'evade', dc:25,
      ok:`물에 적신 천으로 코와 입을 감고, 숨을 반으로 줄인 채 낮은 구간을 빠르게 질렀다.<br><br>쉰 걸음. 혀의 단맛이 사라지는 자리까지.<br>다 지나 천을 풀고 숨을 몰아쉬었다. 머리가 잠깐 띵했지만 그뿐이다.<br><br>젖은 천은 갱의 오랜 벗이다. 다만 이 수는 거리를 아는 길에서만 쓴다. 쉰 걸음이 백 걸음이었으면 반에서 누웠다.`,
      ng:`쉰 걸음인 줄 알았던 낮은 구간이 꺾여서 더 이어졌다. 여든 걸음째에 뒤의 동료가 휘청였다.<br><br>부축해 뛰었다. 눕기 전에 끌어내는 게 전부다.<br>구간을 나와 동료를 눕히고 가슴을 눌러 숨을 받았다. 한참 만에 긴 숨이 돌아왔다.<br><br>낮은 길의 길이는 눈으로 안 보인다. 어귀에서 돌을 굴려 소리로 재 보는 버릇, 그게 빠졌었다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-31, spirit:-15 } }
  ] },

{ at:'S', t:'좁은 틈 — 몸의 치수',
  x:`길이 무너져 남은 건 바위 사이 틈 하나다. 광부 눈대중으로 어깨 하나 반. 지나가진다. 간신히.<br><br>
    틈은 중간에서 한 번 꺾인다. 꺾이는 데가 제일 좁다.<br>
    갱에서 배운 틈의 법. 큰 사람 먼저, 숨은 내쉰 채, 짐은 끈으로 뒤에.<br><br>
    틈 너머에서 바람이 온다. 길이 있다는 바람이. 그리고 그 바람에 비린내가 섞여 있다.`,
  o:[
    { l:'① 틈의 법대로 순서를 세우고 하나씩 통과시킨다.', k:'steady', dc:25,
      ok:`제일 큰 창잡이부터 넣었다. 큰 사람이 지나면 다 지난다. 숨 내쉬고, 오른팔 먼저, 꺾임에서 고개 돌리고.<br><br>한 사람 지날 때마다 틈 너머의 비린내 쪽으로 귀를 세웠다. 짐은 끈에 묶어 맨 뒤에서 당겼다.<br>다섯이 다 지나는 데 백 숨. 비린내의 임자는 오지 않았다.<br><br>틈은 서두르는 사람부터 삼킨다. 순서와 숨, 갱의 두 글자가 여기서도 길을 열었다.`,
      ng:`셋째가 꺾임에서 끼었다. 숨을 들이쉰 채 들어간 것이다.<br><br>끼면 당황하고, 당황하면 숨이 차고, 숨이 차면 몸이 분다. 악순환을 끊는 건 목소리다. 내쉬어. 천천히. 어깨 내리고.<br>그 목소리를 비린내의 임자도 들었다. 틈 너머에서 긁는 소리가 다가왔다.<br>셋째가 빠지고 넷째 다섯째는 반 박자로 욱여넣다시피 했다.<br><br>마지막에 이쪽이 지날 때 틈 너머 어둠에서 콧김이 닿았다. 반 걸음 차이였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 비린내가 걱정이니 먼저 혼자 건너가 본다.', k:'hide', dc:26,
      doom:{ title:'틈 너머의 입', what:'틈을 나서는 순간 물려 굴속으로 끌려갑니다', dc:20, sec:35,
        text:`먼저 건너 살피는 게 광부 몫이다. 숨 내쉬고 틈에 들어 꺾임을 돌았다.<br><br>틈 끝에서 몸을 빼는 순간, 기다리던 것이 물었다. 비린내는 멀리 있는 게 아니라 틈 출구에 입을 대고 있던 것이다.<br>어깨째 물려 굴속으로 끌려간다. 틈에 대고 소리쳤다. 나오지 마라. 돌아가라.<br>그 소리가 틈을 타고 동료들에게 닿는 걸 들으며 어둠 아래로 꺾여 들어갔다. 틈의 법에 한 줄이 빠져 있었다. 바람에 비린내가 섞이면, 틈 너머는 길이 아니라 아가리다.`,
        dieText:`동료들은 틈을 건너지 않았다. 무너진 길을 사흘 걸려 파서 둘러 갔다.<br><br>파는 내내 틈 쪽에서 바람이 불어왔다. 비린내가 섞인 바람이.<br>새 길이 뚫린 날, 둘러 간 자리에서 곡괭이 한 자루를 틈 어귀에 세워 두고 떠났다. 갱에서 못 돌아온 사람에게 하는 방식 그대로.` },
      ok:`먼저 건너되 몸보다 등불을 먼저 내보냈다. 자루 끝에 등불을 걸어 틈 밖으로 천천히.<br><br>불빛이 틈을 나서는 순간 어둠이 등불을 쳤다. 자루가 울리고 등불이 날아갔다.<br>기다리는 입이 있다. 몸이 알기 전에 불이 알았다.<br>틈 안에서 창끝을 모아 출구를 고슴도치로 만들고, 그것이 물러난 기척 뒤에 하나씩 나갔다.<br><br>광부의 선두는 몸이 아니라 불이 선다. 불은 물려도 피가 안 난다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S', t:'뒤를 끊는 일 — 무너뜨림',
  x:`쫓긴다. 길은 좁은 갱도꼴이고 뒤의 것들은 빠르다. 달리기로는 셈이 안 선다.<br><br>
    광부는 길을 여는 사람이지만, 닫는 법도 안다. 여는 법을 거꾸로 하면 된다.<br>
    달리며 천장을 훑었다. 금 간 데, 돌가루 떨어진 데, 버팀이 삭은 데.<br><br>
    저기다. 머리 위가 우는 자리.`,
  o:[
    { l:'① 우는 자리 지나자마자 쐐기돌을 쳐서 천장을 내린다.', k:'break', dc:26,
      ok:`일행을 먼저 지나 보내고 쐐기처럼 박힌 돌 하나를 곡괭이로 후려쳤다.<br><br>천장이 한 숨 머뭇하더니 통째로 내려앉았다. 흙먼지가 벽처럼 섰다.<br>먼지 너머에서 발톱들이 돌무더기를 긁는 소리가 났다. 파는 소리는 아니다. 여기 것들은 셈이 빠르다.<br><br>길을 닫는 망치질은 여는 망치질보다 어렵다. 어디를 치면 무너지는지는, 어디를 치면 안 무너지는지를 아는 사람만 안다.`,
      ng:`쐐기돌을 쳤는데 천장이 반 박자 일찍 내려왔다. 이쪽 발뒤꿈치 위로.<br><br>장화 뒤축이 돌에 물렸다. 발을 뽑는데 벗겨진 장화가 돌 밑에 남았다.<br>그래도 길은 닫혔다. 맨발 한 짝으로 절뚝이며 일행을 따라갔다.<br><br>닫는 자리에서 제일 늦게 나오는 건 광부 몫이다. 몫은 치렀는데 장화 값이 아깝다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 무너뜨리는 대신 좁은 목에 짐수레 돌을 쌓는다.', k:'fix', dc:25,
      ok:`천장을 내리는 건 되돌릴 수 없다. 돌아올 길일지도 모르는데.<br><br>좁은 목에 큰 돌을 세 단으로 엇갈려 쌓았다. 갱 입구 막는 법이다. 사람 손으론 반 식경이면 트는 벽, 발톱으로는 밤새 긁어야 하는 벽.<br>쌓는 동안 동료들이 창을 들고 등을 봐 줬다.<br>돌벽 너머에서 긁는 소리가 나다 멎었다.<br><br>닫되 되돌릴 수 있게 닫는다. 광부의 벽은 문이기도 해야 한다.`,
      ng:`쌓는 반 식경이 길었다. 두 단째에서 첫 놈이 목에 닿았다.<br><br>쌓다 만 돌 틈으로 주둥이가 들어왔다. 곡괭이 자루로 콧등을 후려치고 마지막 단을 엉망으로 올렸다.<br>엇갈림이 설은 벽은 밤중에 한 귀퉁이가 헐렸다. 보초가 소리로 알아채 다시 괴었다.<br><br>쌓는 벽은 시간부터 쌓아야 한다. 시간이 모자라면 처음부터 천장을 내렸어야 했다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S', t:'꺼진 불 — 손줄의 법',
  x:`등불이 꺼졌다. 기름이 아니라 바람이다. 어디선가 큰 것이 지나가며 민 바람.<br><br>
    부싯돌은 있다. 그러나 방금 그 바람의 임자가 가까이 있다면, 불꽃은 저녁 종이다.<br>
    갱에서 불이 꺼지면 광부들은 손줄을 잡는다. 앞사람 허리끈에 손, 그 앞사람도 손.<br><br>
    어둠은 광부의 두 번째 고향이다. 무섭지만, 아는 무서움이다.`,
  o:[
    { l:'① 손줄을 엮어 어둠인 채로 벽을 타고 간다.', k:'bond', dc:25, wake:1,
      ok:`다섯이 손줄로 이어졌다. 맨 앞은 이쪽. 왼손은 벽, 오른손은 뒷사람에게.<br><br>벽을 더듬어 걸었다. 벽이 꺾이면 멈추고, 뒤로 신호를 쥐어 보냈다. 한 번 쥐면 간다, 두 번이면 선다.<br>어둠 속에서 다섯 몸이 한 몸이 됐다. 바람의 임자가 어디선가 숨 쉬는 소리를 들으며, 한 몸은 소리 없이 그 곁을 지났다.<br><br>갱의 손줄이 여기서도 목숨줄이다. 불빛보다 손아귀가 미더운 길이 있다. 그 길을 다섯이 함께 배웠다.`,
      ng:`손줄 중간이 한 번 끊겼다. 셋째가 돌부리에 걸려 넘어지며 놓친 것이다.<br><br>어둠 속에서 끊긴 줄만큼 무서운 게 없다. 이름을 부를 수도 없다.<br>벽을 치는 신호 세 번으로 겨우 다시 모였다. 모이는 데 백 숨이 걸렸고, 백 숨 내내 어딘가의 숨소리가 가까워졌다 멀어졌다.<br><br>손줄은 손만 엮는 게 아니라 발도 맞춰야 한다. 걸음 장단까지 엮는 연습이 필요하다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 몸을 가리고 부싯불을 한 번만 친다.', k:'luck', dc:25,
      ok:`겉옷으로 삼면을 가리고 바닥 쪽으로 부싯돌을 쳤다. 불꽃 한 번, 심지에 옮겨 붙이고 바로 등피를 닫아 빛을 실눈으로 줄였다.<br><br>실눈 빛이면 발밑과 벽만 보인다. 그거면 걷는다.<br>바람의 임자는 오지 않았다. 불꽃 한 번은 어둠 속에서 눈 깜빡임이다. 두 번부터가 신호다.<br><br>그래도 손바닥이 땀에 젖어 있었다. 한 번에 붙은 심지가 고마웠다.`,
      ng:`첫 부싯불에 심지가 안 붙었다. 두 번째도. 세 번째에 붙었다.<br><br>불꽃 세 번은 신호다. 어둠 저쪽에서 돌 구르는 소리가 났다.<br>등피를 줄일 새도 없이 내달렸다. 흔들리는 불빛이 벽에 저희 그림자를 괴물처럼 키웠다.<br>한참을 달려 따돌렸다.<br><br>부싯돌은 마른 데 간수하는 것부터가 광부 일이다. 눅은 부싯깃이 세 번을 만들었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S', t:'바위 귀 — 곡괭이로 듣기',
  x:`앞길이 두 갈래다. 어느 쪽에서든 이따금 긁는 소리가 울려오는데, 메아리가 섞여 방향을 못 잡겠다.<br><br>
    갱에서 쓰던 수가 있다. 곡괭이 날을 바위에 대고 자루 끝을 귀에 무는 것. 바위는 공기보다 소리를 똑바로 나른다.<br><br>
    날을 왼쪽 벽에 댔다. 그리고 오른쪽 벽에.`,
  o:[
    { l:'① 양쪽 벽의 소리를 견주어 긁는 놈의 자리를 잡는다.', k:'sense', dc:25,
      ok:`왼벽의 긁음은 멀고 겹이 많다. 여럿이 먼 데서. 오른벽의 긁음은 하나인데 가깝다.<br><br>멀리 여럿과 가까이 하나. 광부의 셈으로는 가까운 하나가 낫다. 자리를 아니까.<br>오른길로 들되 그 하나의 자리를 크게 돌아 지났다. 벽 너머에서 긁는 소리가 끝까지 제자리였다. 굴 파는 데 정신 팔린 놈이었다.<br><br>바위 귀는 거짓이 없다. 공기는 메아리로 속여도 돌은 곧이곧대로 나른다.`,
      ng:`오른벽 소리를 하나로 셌는데 둘이었다. 같은 장단으로 긁는 둘.<br><br>크게 돌아 지나는 길에서 둘째와 마주쳤다. 서로 놀란 반 숨.<br>이쪽 곡괭이가 먼저 나갔고, 그것이 피하며 벽을 차고 사라졌다. 어둠에 대고 한참 곡괭이를 겨눈 채 서 있었다.<br><br>같은 장단으로 둘이 긁으면 하나로 들린다. 짝으로 일하는 것들이 있다는 걸 바위 귀에 새로 가르쳤다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 곡괭이로 바위를 한 번 쳐서 대답을 들어 본다.', k:'steady', dc:26,
      ok:`듣기만 하는 귀는 반쪽이다. 딱, 한 번 치고 날을 문 채 기다렸다.<br><br>왼벽 너머의 긁음이 일제히 멎었다. 멎는 것들은 숨는 것들이다. 오른벽의 긁음은 그대로다. 못 들었거나 관심 없거나.<br>숨는 것들은 들은 것이다. 듣고 숨는 것들이 더 무섭다. 왼길을 버렸다.<br><br>어둠에 질문을 던지는 법을 배웠다. 답은 소리가 아니라 소리의 멎음으로도 온다.`,
      ng:`친 소리의 대답이 셋째 방향에서 왔다. 천장에서.<br><br>천장을 기어 오던 것이 바로 위에서 머리를 내렸다. 곡괭이를 휘두를 각도 안 나오는 거리.<br>뒤로 구르며 피했고 동료들 창이 천장을 쑤셨다. 그것은 천장 틈으로 사라졌다.<br><br>질문은 던지는 자리부터 비키고 던지는 것이다. 두드린 자리 위도 자리다. 벽만 보고 천장을 안 봤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S', t:'걸음 수첩 — 머릿속 갱도',
  x:`갈림을 여섯 번 지났다. 불빛은 좁고 길은 서로 닮았다. 돌아 나갈 길을 잃으면 여기서는 끝이다.<br><br>
    광부는 종이 지도를 안 믿는다. 갱도는 머리에 새긴다. 걸음 수와 꺾은 방향과 바닥의 기울기.<br>
    왼쪽 마흔둘, 오른쪽 열일곱, 내리막 백.<br><br>
    동료들이 길을 외우는 이쪽 입만 보고 걷는다.`,
  o:[
    { l:'① 걸음과 꺾음을 소리 없이 입에 새기며 간다.', k:'steady', dc:25, wake:1,
      ok:`입속으로 외며 걸었다. 왼 마흔둘, 오 열일곱, 내림 백, 물소리 스물.<br><br>돌아올 때 그 수첩을 거꾸로 폈다. 물소리 스물, 오름 백, 왼 열일곱, 오 마흔둘.<br>여섯 갈림을 거꾸로 다 맞췄다. 마지막 갈림에서 들어올 때 못 본 발톱 자국이 보였다. 들어온 뒤에 생긴 자국이다. 수첩 덕에 걸음을 안 늦추고 그대로 질러 나왔다.<br><br>머릿속 갱도는 종이와 달리 안 젖고 안 찢긴다. 어둠 속 걸음 하나하나가 글자가 되는 것, 그게 광부의 문자다.`,
      ng:`다섯째 갈림까지는 맞았다. 여섯째에서 수가 엉켰다. 쫓기며 지난 갈림이라 걸음이 수에 안 실렸던 것이다.<br><br>두 길 앞에서 반 식경을 섰다. 어둠 속의 반 식경은 밖의 한나절이다.<br>결국 바닥 기울기로 갈랐다. 들어올 때 내리막이었으니 나갈 땐 오르막. 맞았다.<br><br>쫓길 때일수록 수를 세야 한다. 겁이 수를 지운다는 걸 알았으니, 겁 위에 수를 쓰는 연습이 남았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 갈림마다 돌 세 개를 광부식으로 포개 둔다.', k:'fix', dc:24,
      ok:`갈림마다 돌 셋을 포갰다. 맨 위 돌의 뾰족한 끝이 나가는 길을 가리키게. 광부들끼리만 아는 포개기다.<br><br>돌아오는 길, 표식들이 차례로 길을 가리켰다.<br>다섯째 표식이 흐트러져 있었다. 무엇이 건드린 것이다. 그러나 흐트러진 돌들도 광부 눈에는 읽혔다. 구른 방향이 원래 자리를 말해 준다.<br><br>표식은 세울 때 흐트러질 것까지 셈해서 세운다. 그래서 돌이 셋이다. 하나는 남으라고.`,
      ng:`표식 돌을 포개는 소리가 문제였다. 넷째 갈림에서 돌 부딪는 소리에 어둠이 대답했다.<br><br>서두르느라 다섯째 여섯째 표식이 설었다. 돌아올 때 그 둘이 구분이 안 갔다.<br>잘못 든 길에서 반 식경을 버리고 뼈 무더기 하나를 만나고서야 되짚었다.<br><br>표식은 소리 없이, 설지 않게. 두 가지가 같이 돼야 표식이다. 하나만 되면 미끼다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'자루 끝 떨림 — 땅으로 듣는 수',
  x:`멀리서 무엇이 오는 것 같다. 공기는 조용한데 발바닥이 간지럽다.<br><br>
    곡괭이 날을 바닥에 박고 자루 끝을 손가락으로 물었다. 땅의 떨림이 자루를 타고 올라온다.<br>
    쿵. ……쿵. 느리고 무겁다. 네 발. 그리고 그 사이에 자잘한 떨림이 따로 있다.<br><br>
    큰 것 하나와 작은 것 여럿이 같은 쪽에서 온다.`,
  o:[
    { l:'① 떨림의 세기와 사이로 거리와 수를 잰다.', k:'sense', dc:26,
      ok:`큰 쿵은 사이가 여섯 숨, 세기는 아직 멀다. 작은 떨림은 사이가 잘고 점점 또렷하다. 작은 것들이 앞서 온다.<br><br>작은 것들 닿기까지 백 숨, 큰 것은 삼백 숨. 백 숨이면 옆 굴로 빠지고도 남는다.<br>일행을 옆 굴로 물리고 자루를 다시 물었다. 작은 떨림들이 본 길을 우르르 지나가고, 이어 큰 쿵이 따라갔다.<br>몰이꾼들과 몰이 주인의 행차였다.<br><br>땅은 광부의 귀다. 거리도 수도 순서도, 자루 하나로 다 들린다.`,
      ng:`수는 쟀는데 방향을 반대로 읽었다. 떨림은 오는 쪽이 아니라 굴이 꺾인 쪽에서 크게 울렸던 것이다.<br><br>피한다고 든 옆 굴이 그것들의 길목이었다. 작은 것들과 정통으로 마주쳤다.<br>좁은 굴에서 창과 곡괭이로 한바탕을 치르고 본 길로 도로 나왔다. 큰 쿵이 오기 전에.<br><br>떨림은 곧은 길에서만 곧다. 꺾인 굴에서는 소리처럼 꺾인다. 그 한 줄이 비쌌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 재기를 관두고 바로 제일 높은 턱으로 올린다.', k:'steady', dc:25,
      ok:`백 숨 삼백 숨 셈이 다 무슨 소용인가. 발바닥이 간지러우면 비키는 것이다.<br><br>일행을 바위 턱 위로 올리고 숨을 죽였다. 턱 아래로 작은 것들이 지나가고 큰 것이 따라갔다. 턱 밑 한 길 반에서.<br>큰 것의 등이 지나가는 걸 위에서 내려다봤다. 등에 오래된 곡괭이 자국 같은 흉터가 있었다.<br><br>재는 것은 피할 틈이 있을 때 재는 것이다. 간지러움이 셈보다 먼저인 날도 있다.`,
      ng:`턱으로 오르는데 마지막 동료 발이 돌을 굴렸다. 데구루루.<br><br>작은 것들 몇이 떨어져 나와 턱 밑을 맴돌았다. 뛰어오르려 발톱을 거는 놈도 있었다.<br>큰 쿵이 가까워지자 작은 것들이 아쉬운 듯 따라갔다. 주인 걸음에 못 처지는 것들이었다.<br><br>턱 위에서 다들 돌이 된 채 삼백 숨을 셌다. 오르는 발부터 조용해야 턱이 성이다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-17, spirit:-15 } }
  ] },

{ at:'S', t:'막장 — 우는 벽을 따는 법',
  x:`길이 끝났다. 막장이다. 되돌아가기엔 뒤가 멀고, 뒤쪽 어둠에는 아까부터 따라오는 기척이 있다.<br><br>
    막장 벽을 살폈다. 아래쪽 돌 틈에서 물이 가늘게 운다. 벽 너머에 물길이 있다는 뜻이고, 물길은 곧 빈 길이다.<br>
    물 우는 벽은 얇다. 광부라면 안다.<br><br>
    딸 수 있는 벽이다. 소리가 문제일 뿐.`,
  o:[
    { l:'① 물 우는 금을 따라 날을 넣고 지렛대로 소리 없이 딴다.', k:'fix', dc:26,
      ok:`치지 않고 땄다. 물 우는 금에 곡괭이 날을 넣고 몸무게로 지그시. 돌이 비명 대신 신음만 내며 떨어졌다.<br><br>두 장, 세 장. 사람 하나 구멍이 열리고 물내 나는 바람이 쏟아졌다. 너머는 물길이 말라붙은 옛 굴이었다.<br>고인 웅덩이에서 맑은 물도 떴다. 다섯이 빠져나가고 마지막에 떨어낸 돌로 구멍을 도로 괴었다.<br><br>뒤따르던 기척은 막장만 만났을 것이다. 광부에게 막장은 끝이 아니라 제일 얇은 벽이다.`,
      ng:`세 장째 돌이 지렛대에서 미끄러져 바닥을 쳤다. 꽝.<br><br>뒤쪽 기척이 곧장 달음질로 바뀌었다. 남은 돌을 발로 차 내고 구멍으로 하나씩 욱여넣었다.<br>마지막 이쪽이 빠질 때 어둠이 막장에 들어섰다. 구멍 너머로 굴러 들어와 돌을 괴었다. 돌 너머에서 발톱이 벽을 두드렸다. 광부처럼. 빈 데를 찾는 두드림이었다.<br><br>그 두드림 소리에 잠이 다 달아났다. 저것들도 벽을 읽는다. 다음 막장은 더 조용히 따야 한다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-27, mind:-16 } },
    { l:'② 물 틈에 쐐기를 박고 물이 벽을 열게 한다.', k:'luck', dc:26,
      ok:`물이 우는 틈에 나무 쐐기를 박고 물을 먹였다. 물 먹은 나무는 분다. 돌을 가르는 조용한 힘이다.<br><br>반 식경을 기다리자 금이 자라는 소리가 났다. 뿌지직. 벽이 스스로 입을 벌렸다.<br>망치질 한 번 없이 사람 하나 틈이 열렸다.<br><br>갱의 옛 수다. 급한 쫓김에 반 식경짜리 수를 거는 건 도박이었지만, 물과 나무는 약속을 지켰다.`,
      ng:`쐐기가 분기 전에 뒤쪽 기척이 먼저 닿았다. 반 식경은 도박이었고 졌다.<br><br>막장을 등지고 다섯이 창을 세웠다. 어둠과 대치한 백 숨. 그때 등 뒤에서 뿌지직, 벽이 열렸다.<br>뒷걸음으로 틈을 넘으며 창끝은 끝까지 어둠을 향했다.<br><br>수는 맞았는데 시간이 설었다. 느린 수를 걸 땐 버틸 벽부터 등에 세우고 걸어야 한다.`,
      win:{ exp:19, dream:3 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S1', t:'환풍구 — 쇠로 판 갱도',
  x:`벽에 뚫린 환풍구를 들여다봤다. 광부 눈에는 낯익다. 갱도다. 쇠로 판 갱도.<br><br>
    갱도에는 본줄기와 곁가지가 있다. 바람이 센 쪽이 본줄기, 바람이 죽은 쪽이 막장.<br>
    여기 것들이 이 쇠 갱도로 다닌다. 그렇다면 저것들의 길도 본줄기와 곁가지로 읽힌다.<br><br>
    덮개마다 손을 대고 바람을 쟀다.`,
  o:[
    { l:'① 바람 세기로 관의 본줄기를 그려 방 위치를 고른다.', k:'sense', dc:25, wake:1,
      ok:`덮개 아홉 개의 바람을 재서 머릿속에 관의 지도를 그렸다. 본줄기가 복도 천장을 지르고 곁가지가 방마다 내린다.<br><br>본줄기에서 제일 먼 곁가지 끝 방을 골라 묵었다. 막장 방이다. 다니는 길에서 먼.<br>밤새 본줄기 쪽에서 긁는 소리가 두 번 지나갔다. 곁가지 끝까지는 한 번도 안 왔다. 저것들도 막장까지는 안 들어온다. 먹을 게 없는 길이니까.<br><br>쇠 갱도도 갱도다. 갱도를 읽는 눈은 쇠 앞에서도 눈이다. 건물 전체가 광산 도면처럼 읽히기 시작했다.`,
      ng:`바람을 재는데 곁가지 하나의 바람이 중간에 변덕을 부렸다. 죽었다 살았다.<br><br>고장 난 바람개비 탓인 걸 모르고 그 가지를 본줄기로 읽었다. 고른 방이 하필 진짜 본줄기 바로 밑이었다.<br>밤새 머리 위로 긁는 소리가 오갔다. 눈을 못 붙이고 날을 샜다.<br><br>바람은 세기만이 아니라 결도 봐야 한다. 기계가 미는 바람과 길이 부르는 바람은 결이 다르다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 관 속에 등불을 넣어 그을음으로 길을 읽는다.', k:'steady', dc:25,
      ok:`덮개를 열고 등불을 관 안에 넣어 봤다. 불꽃이 눕는 쪽, 그을음이 흐르는 쪽.<br><br>관 천장에 묵은 그을음 자국이 있었다. 공장 돌던 시절의 기름 그을음. 그 자국이 굵은 쪽이 본줄기다.<br>바람은 오늘 것이지만 그을음은 십 년 치다. 십 년 치가 더 미덥다.<br><br>그을음 지도로 고른 방은 밤새 조용했다. 광부는 벽에 쓰인 세월을 읽는 사람이다. 쇠벽에도 세월은 쓰여 있다.`,
      ng:`등불을 너무 깊이 넣었다. 관 안쪽 어디선가 바람이 훅 밀려와 불이 꺼지며 등피가 관 바닥에 떨어졌다. 떼그르르.<br><br>쇠 관은 소리를 백 배로 나른다. 건물 어딘가의 귀들이 다 들었을 소리.<br>등피를 포기하고 덮개를 닫고 방을 두 번 옮겼다.<br><br>관에 넣는 건 손 닿는 깊이까지다. 광부가 제 등피를 갱에 바치고 배운 줄이다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S1', t:'벽 속의 소리 — 마주 대는 귀',
  x:`복도 벽 속에서 소리가 난다. 설설 기는 소리. 벽과 벽 사이 틈새 공간을 무엇이 다니는 것이다.<br><br>
    귀를 대면 소리가 멎는다. 떼면 다시 긴다. 벽 하나를 사이에 두고 서로 듣고 있다.<br>
    광부는 벽 너머 기척을 읽는 데 이골이 났다. 무너진 갱에서 동료 찾을 때 쓰던 귀다.<br><br>
    저쪽도 같은 재주가 있는 모양이다.`,
  o:[
    { l:'① 걸음 장단을 바꿔 가며 저쪽의 읽기를 헝클어뜨린다.', k:'steady', dc:26,
      ok:`저쪽은 이쪽 발소리를 읽고 따라온다. 그렇다면 읽을 것을 거짓으로 준다.<br><br>둘은 제자리걸음, 셋은 전진. 장단을 섞자 벽 속 소리가 갈팡질팡했다. 앞서 가다 돌아오고, 멈췄다 급해지고.<br>복도 끝에서 벽 속 소리는 한참 뒤처져 있었다. 거짓 걸음을 읽느라.<br><br>벽 너머 읽기는 광부가 선생이다. 읽는 법을 아는 사람이 속이는 법도 안다.`,
      ng:`장단을 섞는데 막내가 자꾸 진짜 걸음을 섞었다. 거짓 걸음은 생각보다 어렵다.<br><br>저쪽이 진짜만 골라 읽고 따라왔다. 복도 끝 덮개 앞에 먼저 도착해 기다리고 있었다.<br>덮개를 밀치고 나오는 머리를 곡괭이 자루로 후려쳐 도로 넣었다.<br><br>뛰다시피 그 구간을 벗어났다. 거짓 걸음도 연습이 필요하다. 다섯이 다 선생일 수는 없다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 점검 뚜껑을 열고 벽 속을 들여다본다.', k:'luck', dc:26,
      doom:{ title:'벽 사이의 손', what:'벽 틈새 공간으로 끌려 들어갑니다', dc:20, sec:35,
        text:`복도 중간의 점검 뚜껑을 찾아 살며시 열었다. 벽 속 공간이 생각보다 넓다. 사람도 기어 다닐 폭.<br><br>등불을 들이밀자 어둠 속에서 눈 네 개가 돌아봤다. 둘이었다. 서로 듣고 있던 게 아니라, 둘이 번갈아 들었던 것이다.<br>가까운 놈의 긴 팔이 뚜껑 틈으로 나와 멱살을 쥐었다. 좁은 틈으로 몸이 구겨져 들어간다. 광부가 벽 속으로 캐어 들어가는 꼴이 됐다. 벽과 벽 사이는 어두웠고, 바닥에는 먼저 읽힌 것들의 뼈가 깔려 있었다.`,
        dieText:`점검 뚜껑은 안쪽에서 닫혀 있었다.<br><br>동료들이 지렛대로 다시 열었을 때 벽 속은 비어 있었다. 틈새 공간은 건물 전체로 이어져 있었다.<br>그 벽에 귀를 대 본 동료가 아무 말 없이 물러났다. 무슨 소리를 들었는지는 끝내 말하지 않았다.` },
      ok:`뚜껑을 열되 몸은 옆벽에 붙이고 등불만 자루에 걸어 들이밀었다.<br><br>불빛 속에 둘이 있었다. 번갈아 듣던 둘.<br>놀란 둘이 틈새 안쪽으로 내빼는 발소리가 벽을 타고 멀어졌다.<br>뚜껑을 닫고 쇠막대를 질렀다. 이 복도 벽 속은 이제 빈 것이다.<br><br>들여다보기 전에 몸부터 치우는 것. 갱의 발파 버릇이 여기서도 목숨값을 했다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'얽은 바닥 — 밑이 빈 길',
  x:`복도 바닥이 군데군데 얽었다. 산성 피가 녹인 자국이다. 몇 군데는 아예 구멍이 뚫려 아래가 보인다.<br><br>
    아래층이 아니다. 바닥과 아래층 천장 사이의 배관층이다. 어둡고, 관이 엉켜 있고, 그리고 그 관 위에 무언가 지나다닌 기름 자국.<br><br>
    광부는 밑이 빈 바닥을 걸을 때의 법을 안다. 무게를 어디에 줄 것인가.`,
  o:[
    { l:'① 얽은 자국의 색으로 바닥의 남은 두께를 읽는다.', k:'gaze', dc:25,
      ok:`얽은 자국도 자국 나름이다. 겉만 얽은 데는 희끗하고, 깊이 삭은 데는 거뭇하고 테두리가 분처럼 인다.<br><br>희끗한 데만 이어 밟아 길을 그렸다. 보 위를 지나는 자리는 발소리가 달라서 거기도 표시했다.<br>다섯이 그 길대로 건넜다. 바닥은 한 번도 울지 않았다.<br><br>삭은 쇠 읽기는 삭은 바위 읽기와 같다. 색과 가루가 두께를 말해 준다. 광부의 눈은 재료를 안 가린다.`,
      ng:`색 읽기는 맞았는데 짐 무게를 셈에서 뺐다. 제일 짐 무거운 동료가 희끗한 데를 밟았는데도 바닥이 울었다.<br><br>한 발이 빠졌다. 배관층의 관을 밟고 걸려 다행히 허리까지는 안 갔다.<br>끌어올리는데 아래 어둠 속 기름 자국 위로 뭔가 미끄러지는 소리가 지나갔다.<br><br>두께는 밟는 무게와 같이 읽는 것이다. 사람마다 길이 달라야 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 아예 벽가의 보 위로만 외줄 걷기를 시킨다.', k:'fix', dc:25,
      ok:`바닥은 못 믿어도 보는 믿는다. 벽을 따라 지나는 보의 선을 발소리로 찾아 분필로 그었다.<br><br>그 선 위로만, 한 줄로 건넜다. 외줄이지만 폭이 한 뼘은 되는 외줄이다.<br>가운데쯤에서 바닥 성한 데가 꺼지는 소리를 들었다. 아무도 안 밟은 자리가 저 혼자 내려앉았다.<br>보 위의 다섯은 흔들리지도 않았다.<br><br>보 찾기는 광부의 밥줄 재주다. 쇠 건물의 뼈대도 결국 갱목과 같은 이치로 서 있다.`,
      ng:`보 선은 맞게 그었는데 보와 보 사이 이음에서 분필 선이 끊겼다. 이음새 한 뼘이 삭아 있던 것이다.<br><br>앞서가던 이쪽 발밑에서 이음이 부서졌다. 가랑이가 보에 걸려 매달렸다.<br>동료들이 끌어올렸다. 아래 배관층에서 기름 자국 주인이 올려다보는 기척이 났다.<br><br>보는 몸통보다 이음이 먼저 삭는다. 갱목이고 쇠보고 같다. 아는 것인데 급해서 건너뛰었다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S1', t:'녹은 수직굴 — 산이 판 샤프트',
  x:`아래층으로 내려갈 계단이 무너져 있다. 대신 산성 피가 녹여 뚫은 수직 구멍이 있다. 두 층을 지르는 비뚠 샤프트다.<br><br>
    광부는 수직굴을 안다. 내려가는 법도, 수직굴에서 죽는 법들도.<br>
    구멍 가장자리를 만져 봤다. 녹다 만 쇠가 엿처럼 흘러 굳었다.<br><br>
    디딜 데와 못 디딜 데가 섞여 있다.`,
  o:[
    { l:'① 가장자리를 두드려 삭은 데를 골라내고 디딤을 정한다.', k:'steady', dc:26,
      ok:`내려가기 전에 반 식경을 썼다. 자루로 가장자리를 돌아가며 두드려, 맑은 소리 나는 데만 분필로 찍었다.<br><br>찍은 자리만 디디며 내려갔다. 밧줄은 성한 보에 걸고.<br>중간에 분필 없는 데를 디디려던 막내를 소리로 세웠다. 그 자리는 둔탁한 소리가 났던 자리다. 자루로 치자 통째로 떨어져 나갔다.<br>다섯이 다 내려와 밧줄을 거뒀다.<br><br>수직굴의 법은 하나다. 내려가는 시간보다 고르는 시간이 길어야 한다.`,
      ng:`두드려 고른 자리가 하나 틀렸다. 소리는 맑았는데 속이 삭은 자리였다. 소리는 겉 한 겹만 말해 줬던 것.<br><br>그 자리를 디딘 동료가 미끄러졌다. 밧줄이 받았지만 벽에 쓸리며 팔꿈치가 까졌다.<br>나머지는 그 자리를 피해 내려왔다.<br><br>맑은 소리도 두 번 쳐야 한다. 첫 소리는 겉, 둘째 소리의 꼬리가 속을 말한다. 급해서 꼬리를 안 들었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 밧줄 하나로 바닥까지 단숨에 하강한다.', k:'evade', dc:25,
      ok:`디딤이고 뭐고 밧줄 하강이 제일 빠르다. 보에 줄을 걸고 허리에 감아 차례로 내렸다.<br><br>벽에 발이 닿을 때마다 삭은 가장자리가 부스러기를 떨궜지만, 디디는 게 아니라 스치는 발이라 버텼다.<br>다섯이 백 숨 만에 바닥을 밟았다.<br><br>빠른 길은 빠른 만큼 좋다. 줄과 보만 성하다면. 그 둘을 보는 눈이 광부 눈이라 가능한 속도였다.`,
      ng:`셋째가 내려갈 때 줄이 녹다 만 가장자리에 쓸렸다. 산기가 남은 쇠였다.<br><br>줄 겉가닥이 삭아 끊기며 셋째가 반 길을 떨어졌다. 발목을 접질렸다.<br>남은 둘은 줄을 반대쪽으로 옮겨 걸고 내려왔다.<br><br>산이 지나간 자리는 겉이 굳어도 이빨이 남는다. 줄 길은 줄이 닿는 자리까지 다 봐야 했다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S1', t:'굵은 관 — 쇳줄 광맥',
  x:`갈림마다 헤매는 대신 광부의 법을 쓰기로 했다. 광맥 따라가기. 여기의 광맥은 전선과 관이다.<br><br>
    가는 관은 곁가지, 굵은 관은 본맥. 본맥은 심장으로 통한다. 심장은 동력실이고, 동력실은 바깥벽에 붙어 있기 마련이다.<br><br>
    천장을 등불로 훑었다. 팔뚝 굵기 관 셋이 한 방향으로 간다.`,
  o:[
    { l:'① 굵은 관 셋이 모이는 쪽으로 길을 잡는다.', k:'fix', dc:25, wake:1,
      ok:`굵은 관을 따라 걸었다. 갈림마다 관이 답을 줬다. 관이 꺾으면 꺾고, 관이 내려가면 내려갔다.<br><br>관이 다른 관들과 합쳐질수록 굵어졌다. 광맥이 모이는 것이다.<br>이윽고 관 다발이 큰 문 하나로 빨려 들어갔다. 동력실. 그 옆에 바깥으로 통하는 비상구가 있었다. 광부의 셈대로.<br><br>길 잃은 건물에서 관은 광맥이고 광맥은 거짓말을 안 한다. 캐는 것만 광부 일이 아니다. 따라가는 것도 광부 일이다.`,
      ng:`관 셋 중 하나가 중간에 아래층으로 꺾였다. 굵기만 보고 그걸 따랐다.<br><br>닿은 곳은 동력실이 아니라 큰 물탱크실이었다. 굵은 관이 다 심장으로 가는 건 아니었다. 물로 가는 관도 굵다.<br>되짚어 나와 남은 두 관을 따랐다. 반 식경을 버렸고, 그 사이 뒤쪽 어둠에 기척이 하나 붙었다.<br><br>광맥에도 종류가 있다. 쇠 관은 전기, 무거운 관은 물. 두드려 보면 소리가 다르다. 다음부턴 두드리고 따른다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 관이 우는 소리로 산 관과 죽은 관을 가른다.', k:'sense', dc:25,
      ok:`관에 귀를 댔다. 산 관은 운다. 가늘게, 물이든 전기든 흐르는 소리로. 죽은 관은 벙어리다.<br><br>우는 관만 따랐다. 흐르는 것은 어딘가 산 데로 간다.<br>우는 관의 끝에 비상등이 살아 있는 구역이 나왔다. 불빛과 바깥 공기. 산 관이 산 길을 데려다줬다.<br><br>광산의 물소리 따라가기와 같은 수다. 흐름은 늘 출구를 안다.`,
      ng:`우는 관을 따라갔는데 울음의 임자가 물이 아니었다. 관 속을 무엇이 기어가는 소리였다.<br><br>울음이 멎은 자리 덮개가 들썩였다. 관을 따라온 게 아니라 관 속의 것과 나란히 걸어온 꼴이다.<br>덮개가 열리기 전에 그 구역을 떴다.<br><br>관의 울음도 결을 가려야 한다. 흐르는 울음은 고르고, 기는 울음은 끊겼다 이어진다. 귀에 그 결을 새겼다.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S1', t:'더운 바닥 — 밑이 빈 온기',
  x:`알 방을 돌아가는 좁은 복도다. 바닥이 미지근하다. 그리고 광부의 발바닥은 온기보다 먼저 다른 것을 읽었다.<br><br>
    울림이 무르다. 밑이 비었다.<br>
    더운 바닥에 밑이 빈 것. 갱이라면 온천 동굴 위를 걷는 셈이다. 여기서는 그 밑에 사는 게 온천이 아닐 것이다.<br><br>
    돌아가려면 알 방을 질러야 한다. 그건 더 나쁘다.`,
  o:[
    { l:'① 무게를 나눠 벽가로 붙어 한 사람씩 건너보낸다.', k:'steady', dc:26,
      doom:{ title:'꺼진 바닥', what:'무너진 바닥 밑 둥지로 떨어져 끌려갑니다', dc:20, sec:35,
        text:`벽가가 그나마 단단하다. 한 사람씩, 벽에 붙어, 발꿈치 들고.<br><br>넷이 건넜다. 마지막 이쪽 차례. 넷이 밟아 피로해진 바닥이 광부의 무게에서 셈을 끝냈다.<br>쇳판이 접시처럼 꺼지며 몸이 아래로 빠졌다. 떨어진 곳은 미지근하고 물컹한 어둠. 알들 사이였다. 바닥 밑이 둥지의 천장이었던 것이다.<br>일어서기 전에 어둠 속에서 지키는 것들이 다가왔다. 위에서 동료들이 뚫린 구멍으로 손을 뻗었다. 손과 손 사이가 한 길. 그 한 길이 갱 하나 깊이 같았다.`,
        dieText:`뚫린 구멍으로 등불을 내려 비췄지만 불빛이 닿는 데까지는 비어 있었다.<br><br>밧줄을 내려 반 식경을 불렀다. 대답 대신 알 방 쪽 벽 전체가 한 번 꿈틀했다.<br>동료들은 밧줄을 거두고 구멍에 철판을 끌어다 덮었다. 덮기 전에 각자 돌 하나씩을 내려놓았다. 광부의 장례였다.` },
      ok:`한 사람씩 보내되 순서를 광부 식으로 짰다. 가벼운 사람 먼저가 아니다. 무거운 사람 먼저다.<br><br>바닥은 밟을수록 피로해진다. 제일 무거운 무게는 바닥이 제일 성할 때 건너야 한다.<br>창잡이부터, 마지막에 제일 가벼운 막내. 바닥은 막내의 발밑에서 한 번 울고 말았다.<br><br>다 건너고 돌아보니 바닥 가운데가 눈에 띄게 처져 있었다. 순서 하나가 바닥의 수명을 다섯 몫으로 나눠 쓴 것이다.`,
      win:{ exp:23, dream:4 } },
    { l:'② 온기의 결을 읽어 밑 둥지의 넓이부터 그린다.', k:'gaze', dc:25,
      ok:`맨손바닥으로 바닥을 짚어 가며 온기의 가장자리를 그렸다. 더운 데가 둥지 위, 식은 데가 맨바닥 위다.<br><br>온기는 복도 가운데로 길쭉했다. 벽가 두 뼘은 끝까지 차가웠다.<br>그 두 뼘이 길이다. 차가운 두 뼘만 밟고 다섯이 건넜다.<br><br>열은 광부의 오랜 적이자 지도다. 갱의 불내도 이렇게 손바닥으로 그렸었다. 여기서는 둥지를 그렸을 뿐이다.`,
      ng:`온기 지도를 그리는 데 정신이 팔려 손바닥을 너무 오래 댔다. 바닥 밑에서 그 온기가 움직였다.<br><br>손바닥 밑으로 무엇이 지나가는 진동. 지키는 것들이 천장에 닿은 손의 열을 읽은 것이다.<br>바닥 밑에서 긁는 소리가 따라오기 시작했다. 차가운 두 뼘을 거의 뛰다시피 건넜다.<br><br>읽는 손도 읽힌다. 열 읽기는 짧게 짚고 길게 쉬는 것. 광부 수칙에 한 줄을 또 적었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'S1', t:'내려앉는 격벽 — 갱목 괴기',
  x:`지나야 할 문이 내려앉는 격벽이다. 동력이 죽어 가는지 격벽이 조금씩 흘러내린다. 하루면 다 닫힐 높이다.<br><br>
    닫히면 심부에 갇힌다. 다섯이 지나는 데는 문제없지만, 뒤에 올 다른 조가 있다.<br>
    광부는 길을 쓰고 나서 길을 남기는 사람이다. 갱목 괴기. 내려앉는 천장을 받치는 그 법.<br><br>
    마침 복도에 쇠 책장이 쓰러져 있다.`,
  o:[
    { l:'① 쇠 책장을 세로로 괴어 격벽을 받친다.', k:'fix', dc:26,
      ok:`책장을 뜯어 제일 두꺼운 판 두 장을 겹치고, 격벽 밑에 세로로 괴었다. 갱목은 세로가 법이다. 가로는 꺾이고 세로는 버틴다.<br><br>격벽이 책장 기둥에 내려앉아 멈췄다. 쇠가 쇠를 받는 신음이 한 번 나고 조용해졌다.<br>지나가며 기둥 옆 벽에 분필로 크게 적었다. 괴어 둠. 치우지 말 것.<br><br>광부가 지나간 길에는 버팀이 남는다. 뒤에 올 조가 누구든, 이 문은 그들의 문이기도 하다.`,
      ng:`괴는 각이 반 치 어긋났다. 격벽 무게가 실리자 책장 기둥이 삐딱하게 울었다.<br><br>버티기는 버틴다. 다만 얼마나 버틸지 광부 눈에도 안 보이는 각이다.<br>일행을 먼저 다 지나 보내고 마지막에 이쪽이 지나며 각을 다시 봤다. 고칠 수 없는 각이다. 건드리면 무너진다.<br><br>벽에 적었다. 괴어 둠. 오래 못 감. 빨리 지날 것. 거짓 없는 표지가 광부의 체면이다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 격벽의 흘러내리는 속도를 재서 닫히는 때를 적어 둔다.', k:'steady', dc:25,
      ok:`괼 것이 마땅찮으면 시간을 괸다. 격벽이 흘러내리는 속도를 쟀다. 한 식경에 손가락 한 마디.<br><br>남은 높이로 셈하면 내일 해 질 녘에 닫힌다.<br>문 옆 벽에 분필로 적었다. 이 문, 내일 저녁 닫힘. 오늘 지나갈 것. 날짜와 조 이름도.<br>돌아오는 길에 그 문을 세 식경 여유로 다시 지났다.<br><br>갱의 시간표는 종이에 없고 벽에 있다. 읽을 줄 아는 사람에게 벽은 늘 말을 해 준다.`,
      ng:`속도를 쟀는데 흘러내림이 일정하지 않았다. 밤사이 동력이 한 번 더 꺼지며 격벽이 한 뼘을 단숨에 흘렀다.<br><br>돌아오는 길, 셈보다 반나절 이른 문은 무릎 높이만 남아 있었다.<br>다섯이 기다시피 빠졌다. 마지막 동료의 배낭이 걸려 끈을 끊고 당겼다. 격벽이 등 뒤에서 바닥을 물었다.<br><br>기계의 속도는 바위의 속도가 아니다. 변덕까지 재는 법은 아직 광부 책에 없다. 여유를 배로 잡는 수뿐.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'물빠짐 — 낮은 데를 읽는 눈',
  x:`잠긴 양치밭이 끝없다. 허리 물을 헤치는 걸음은 한 시간에 반 리다. 이대로는 해가 진다.<br><br>
    광부는 물에 잠긴 갱을 빼 본 사람이다. 물은 반드시 낮은 데로 길을 내고, 그 길 바닥은 물살에 씻겨 단단하다.<br>
    수면을 봤다. 물풀이 눕는 방향, 거품이 흐르는 줄.<br><br>
    물밑에 물의 길이 있다.`,
  o:[
    { l:'① 거품 줄을 따라 물밑 물길 위로 걷는다.', k:'sense', dc:25, wake:1,
      ok:`거품이 가늘게 줄지어 흐르는 선을 따라 들어섰다. 발밑이 달라졌다. 뻘이 아니라 자갈. 물살이 다져 둔 길이다.<br><br>물길 위는 걸음이 배로 빨랐다. 물풀도 물길 위에는 성기다. 다리를 쓰는 것들이 숨을 데도 성기다는 뜻이다.<br>해 지기 전에 밭을 질렀다.<br><br>물은 광부의 오랜 동료다. 갱을 채울 때는 적이지만, 길을 다져 둘 때는 선배다. 물이 간 길을 읽는 눈이 여기서도 길을 냈다.`,
      ng:`거품 줄이 중간에 둘로 갈렸다. 굵은 쪽을 따랐는데 그쪽은 물길이 아니라 물이 빠지는 구멍 쪽이었다.<br><br>발밑이 갑자기 깊어져 가슴까지 빠졌다. 구멍이 빠는 물살에 다리가 끌렸다.<br>동료들이 창대를 뻗어 꺼내 줬다.<br><br>굵은 거품은 급한 물이고 급한 물은 구멍으로 간다. 가는 거품이 길이고 굵은 거품이 함정이다. 거꾸로 외우고 있었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 긴 자루로 바닥을 짚어 가며 단단한 데만 잇는다.', k:'steady', dc:25,
      ok:`곡괭이 자루를 지팡이 삼아 세 걸음 앞 바닥을 짚으며 걸었다. 푹 들어가면 뻘, 탁 서면 자갈.<br><br>느리지만 한 번도 안 빠졌다. 뒤의 넷은 이쪽 발자국만 밟았다.<br>중간에 자루 끝에 물컹한 것이 닿아 멈춘 적이 한 번. 비켜 돌았다. 그것이 무엇이었는지는 확인하지 않았다. 확인은 공짜가 아니다.<br><br>자루 하나가 다섯 사람 발이 됐다. 광부의 더듬이는 물속에서도 더듬이다.`,
      ng:`자루 짚기는 좋았는데 그 소리가 문제였다. 탁. 탁. 물속으로 울리는 장단.<br><br>물풀 저쪽에서 그 장단에 맞춰 다가오는 물살이 생겼다.<br>짚기를 관두고 뻘이고 뭐고 곧장 질렀다. 두 번 빠지고 한 번 구르며 둔덕에 닿았다.<br><br>물속 소리는 공기보다 멀리 간다. 갱에서 배운 걸 물에서 잊었다. 짚더라도 쉬엄쉬엄, 장단 없이 짚어야 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S2', t:'기운 울타리 — 말뚝의 법',
  x:`밤을 기댈 울타리가 절반은 기울어 있다. 발톱 긴 것들이 몇 밤이고 밀어 댄 탓이다.<br><br>
    울타리 기둥을 봤다. 얕게 박혔고, 곧게 박혔다. 그래서 넘어간다.<br>
    광부의 말뚝은 다르다. 갱목도 버팀도, 미는 힘을 아는 자리에 비스듬히 박는다.<br><br>
    해 지기 전에 반은 다시 세울 수 있다.`,
  o:[
    { l:'① 기둥을 뽑아 미는 쪽으로 비스듬히 다시 박는다.', k:'fix', dc:26,
      ok:`기둥 여섯을 뽑아 다시 박았다. 짐승이 미는 바깥쪽으로 비스듬히, 깊이는 전보다 배로.<br><br>비스듬한 기둥은 밀수록 땅을 문다. 미는 힘이 박는 힘이 되는 각이다.<br>밤에 그것들이 와서 밀었다. 울타리가 끄떡도 안 하자 당겨도 봤다. 당기면 이쪽 각이 버틴다.<br>세 번 밀고 두 번 당기고, 그것들은 셈을 접고 갔다.<br><br>말뚝은 힘과 싸우는 게 아니라 힘을 빌리는 것이다. 갱목 십 년이 울타리 하룻밤에 다 들어갔다.`,
      ng:`여섯 중 넷은 제대로 박았는데 둘은 땅속 바위에 걸려 얕게 섰다.<br><br>밤에 그것들이 귀신같이 그 둘만 골라 밀었다. 얕은 기둥 하나가 뽑히며 울타리 한 칸이 열렸다.<br>열린 칸은 창든 동료들이 밤새 번갈아 막았다.<br><br>박다 만 말뚝은 성한 말뚝보다 나쁘다. 어디가 약한지 광고하는 꼴이니까. 바위에 걸리면 자리를 옮겨 팠어야 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 뽑힌 기둥으로 안쪽에 두 번째 울타리 선을 친다.', k:'break', dc:25,
      ok:`바깥 울타리는 못 믿는다. 뽑히고 남은 기둥들을 안쪽 세 걸음에 둘러 박아 겹 울타리를 쳤다.<br><br>갱의 이중 버팀 법이다. 첫 겹은 희생양, 둘째 겹이 진짜.<br>밤에 그것들이 바깥 겹 한 칸을 기어이 넘었다. 넘고 보니 세 걸음 앞에 또 울타리. 두 울타리 사이 좁은 골에 갇힌 꼴이 됐다.<br>창 둘이 그 골을 위에서 찌르자 그것이 비명을 물고 되넘어 갔다.<br><br>겹은 막는 게 아니라 가두는 것이다. 그 골이 오늘 밤의 함정이었다.`,
      ng:`안쪽 겹을 치는 망치 소리가 어스름 벌판에 울렸다. 박기도 전에 그것들이 왔다.<br><br>반만 선 둘째 겹과 기운 첫 겹 사이에서 어수선한 밤을 났다. 뚫리지는 않았지만 아무도 못 잤다.<br><br>겹 울타리는 낮의 공사다. 소리가 나는 일은 해가 셈해 주는 시간 안에 끝내야 한다. 광부가 밤일을 벌인 게 잘못이었다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-17, spirit:-16 } }
  ] },

{ at:'S2', t:'물 울림 — 큰 것의 걸음 재기',
  x:`무릎 물을 건너는데 수면에 동그라미가 번졌다. 한 번. 또 한 번.<br><br>
    광부는 물그릇의 떨림으로 발파 거리를 쟀었다. 같은 눈으로 수면을 읽었다.<br>
    동그라미의 간격, 물결의 높이. 큰 것의 걸음이다.<br><br>
    문제는 오는지 가는지, 그리고 몇 걸음 밖인지다.`,
  o:[
    { l:'① 수면 물결의 높이 변화로 距離와 방향을 잰다.', k:'steady', dc:26, wake:1,
      ok:`물결 높이를 세 번 견줬다. 같은 걸음인데 물결이 조금씩 낮아진다. 멀어지는 것이다. 방향은 물결이 먼저 닿는 쪽의 반대.<br><br>멀어지는 등 뒤로 길을 잡았다. 큰 것의 꽁무니를 따라가는 길이 제일 안전한 길이다. 저 걸음 둘레의 것들은 다 피해 엎드리니까.<br>빈 길을 다섯이 조용히 걸었다.<br><br>발파 거리 재던 눈이 짐승 거리 재는 눈이 됐다. 떨림은 어디서나 같은 문법으로 말한다. 광부는 그 문법을 읽는 사람이다.`,
      ng:`물결을 읽는데 둘째 떨림이 섞여 들었다. 큰 것 말고 다른 것. 잘고 빠른 물결.<br><br>큰 것에 정신이 팔려 잔 물결을 늦게 봤다. 물풀 밑으로 오는 작은 것들이었다.<br>종아리를 하나 물리고서야 물 밖 둔덕으로 뛰어올랐다.<br><br>큰 소리가 작은 소리를 가린다. 갱에서도 발파 소리에 낙석 소리를 놓치면 죽는다. 같은 실수를 물에서 했다.`,
      win:{ exp:23, dream:4 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 물결이 멎을 때까지 바위 뒤에 몸을 가라앉힌다.', k:'hide', dc:25,
      ok:`재는 것도 일이고 숨는 것도 일이다. 오늘은 숨는 일을 골랐다. 바위 뒤에 턱까지 가라앉아 물결이 평평해지기를 기다렸다.<br><br>큰 것의 걸음이 한참 물을 울리다 멀어졌다.<br>수면이 거울이 되고 나서도 백 숨을 더 셌다. 광부는 갱이 조용해진 뒤의 백 숨을 안다. 무너짐은 꼭 조용한 뒤에 한 번 더 온다.<br>과연 뒤처진 새끼 한 마리가 그제야 지나갔다.<br><br>백 숨의 법은 물에서도 법이었다.`,
      ng:`가라앉아 기다리는데 바위 뒤가 하필 물고기 길이었다. 잔 이빨들이 종아리를 쪼기 시작했다.<br><br>물결은 아직 안 멎었는데 다리는 못 버틴다. 엉거주춤 자리를 옮기다 물소리를 냈다.<br>큰 것의 걸음이 멎었다. 제일 긴 스무 숨이 지나고, 걸음이 다시 멀어졌다.<br><br>숨는 자리도 광맥 보듯 골라야 한다. 물속에는 물속의 길들이 있고, 그 길 위는 숨는 자리가 아니다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S2', t:'바위 벼랑 — 하룻밤 벽감',
  x:`벌판에서 밤을 맞게 생겼다. 유일한 등 붙일 데가 바위 벼랑이다. 벼랑 밑은 그것들의 밤 길목이고.<br><br>
    광부에게 바위 벼랑은 벽이 아니라 재료다.<br>
    벼랑 중턱, 사람 키 하나 반 높이에 결 따라 파인 홈이 보인다. 반나절 공정이면 다섯이 깃들 벽감이 된다.<br><br>
    해가 손가락 네 개 남았다.`,
  o:[
    { l:'① 바위 결을 따라 벽감을 파고 입구를 좁게 남긴다.', k:'steady', dc:26, wake:1,
      ok:`결을 거스르면 반나절도 모자란다. 결을 따르면 바위가 반은 일해 준다.<br><br>파인 홈의 결을 읽고 결대로만 쳐 냈다. 큰 판이 결 따라 떨어질 때마다 공정이 성큼 줄었다.<br>해가 지기 전에 다섯이 모로 눕는 벽감이 났다. 입구는 어깨 하나 폭으로 남기고 안에서 돌로 반을 괴었다.<br>밤에 그것들이 벼랑 밑을 오가는 소리를 머리 위 반 길에서 들었다. 오르는 놈은 없었다. 발톱이 걸릴 결을 다 쳐 냈으니까.<br><br>바위는 광부의 집이다. 어디서든, 반나절이면.`,
      ng:`결 읽기가 반쯤 빗나갔다. 치는 족족 잔돌만 떨어지는 자리가 나왔다.<br><br>해가 지고도 벽감이 세 사람 폭이다. 둘은 입구에 앉아 밤을 났다.<br>앉은 둘 발밑으로 그것들이 밤새 오갔다. 발 하나 거리를 두고.<br><br>결은 겉결과 속결이 있다. 겉결만 읽고 삽을 댄 값이다. 속결은 첫 세 번의 울림으로 읽는 것인데, 해에 쫓겨 그 셋을 건너뛰었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 파는 대신 벼랑의 묵은 굴을 찾아본다.', k:'luck', dc:26,
      ok:`벼랑에 바람 드나드는 작은 구멍이 있었다. 넓혀 보니 안쪽에 묵은 굴이 있다. 물이 옛날에 파 둔 굴.<br><br>바닥에 마른 똥이 있지만 삭은 지 오래다. 전 주인은 이사 간 지 오래.<br>입구만 돌로 좁히고 다섯이 들었다. 반나절 공정을 공짜로 얻은 셈이다.<br>굴 안쪽 벽 틈에서 소금기 밴 돌 한 덩이도 캤다. 짐승들이 핥던 소금돌이다.<br><br>파기 전에 찾아보기. 광부의 게으름은 가끔 지혜와 같은 얼굴을 한다.`,
      ng:`묵은 굴은 찾았는데 전 주인이 이사를 안 갔다. 굴 안쪽 어둠에서 송곳니가 번들거렸다.<br><br>좁은 입구에서 그것과 한참을 대치했다. 굴 임자는 굴에서 안 나오고 이쪽은 못 들어가고.<br>결국 물러나 벼랑 밑에서 뜬눈 반, 쪽잠 반의 밤을 났다.<br><br>굴은 겉보다 속이 먼저다. 돌부터 던져 넣고 메아리와 기척을 듣는 것, 그 순서를 피곤이 잡아먹었다.`,
      win:{ exp:19, dream:2, item:'소금 덩이' }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'비탈 굴들 — 사는 굴과 빈 굴',
  x:`지나야 할 비탈에 굴이 여럿 뚫려 있다. 발톱 긴 것들의 집이다. 어느 굴에 지금 그것들이 들었는지가 문제다.<br><br>
    광부는 굴 입구만 보고도 산 굴과 죽은 굴을 가른다.<br>
    입구의 흙이 다져졌는가. 거미줄이 걸렸는가. 똥이 새것인가. 파리가 나는가.<br><br>
    굴 사이 길은 하나뿐이다.`,
  o:[
    { l:'① 입구마다 네 가지를 읽어 산 굴만 표시하고 돈다.', k:'gaze', dc:26,
      ok:`굴 일곱을 하나씩 읽었다. 다져진 흙과 새 똥과 파리, 산 굴이 셋. 거미줄 걸린 죽은 굴이 넷.<br><br>산 굴 셋을 크게 돌아 죽은 굴 쪽 비탈로 길을 그었다.<br>지나는 중에 산 굴 하나에서 코 고는 숨이 새어 나왔다. 낮잠 시간이었다. 읽은 대로였다.<br><br>갱 입구 읽는 눈이 짐승 굴에도 그대로 통한다. 산 구멍과 죽은 구멍은 재료가 뭐든 같은 표를 단다.`,
      ng:`여섯까지는 맞게 읽었다. 일곱째가 함정이었다. 거미줄이 걸렸는데 산 굴이었다. 입구를 안 쓰고 뒷구멍으로 드나드는 놈의 굴.<br><br>그 앞을 지날 때 뒷구멍으로 나온 놈과 비탈 위에서 마주쳤다.<br>구르다시피 비탈을 내려와 따돌렸다. 무릎이 다 까졌다.<br><br>거미줄은 하루면 쳐진다. 네 가지 표가 다 겹쳐야 죽은 굴이다. 하나만 보고 도장 찍은 게 잘못이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 제일 큰 굴을 들여다본다 — 큰 굴이 비면 다 빈 것이다.', k:'luck', dc:26,
      doom:{ title:'큰 굴의 임자', what:'굴 안으로 물려 끌려 들어갑니다', dc:20, sec:40,
        text:`우두머리 굴이 비면 무리가 사냥 나간 것이다. 제일 큰 굴 입구에 머리를 들이밀었다.<br><br>어둠이 눈을 떴다. 우두머리는 사냥을 안 나간다. 데려오게 시키는 자리다.<br>목덜미가 물렸다. 굴 안으로 끌려 들어가며 밖의 동료들 고함이 멀어졌다. 굴은 생각보다 깊고, 안쪽에 새끼들의 눈이 줄지어 반짝였다.<br>밥이 저 발로 문까지 왔다고, 우두머리의 턱이 말하고 있었다.`,
        dieText:`동료들은 굴에 불붙인 풀단을 던져 넣고 연기 속에서 외쳤다. 대답이 없었다.<br><br>무리가 사냥에서 돌아오는 울음이 비탈 아래서 올라왔다. 더 머물 수 없었다.<br>비탈을 벗어난 뒤 막내가 물었다. 광부들은 굴을 그렇게 잘 알면서 왜. 아무도 답하지 못했다. 아는 것과 급한 것이 싸우면 급한 것이 이기는 날이 있다.` },
      ok:`큰 굴을 보되 머리 대신 돌을 보냈다. 입구 안쪽으로 돌 하나를 굴려 넣고 귀를 줬다.<br><br>돌이 구르다 무엇에 막혔다. 그리고 낮은 그르렁거림.<br>우두머리는 집에 있다. 그럼 무리는 가까이 있다. 멀리 사냥 가는 날은 우두머리도 비운다.<br>비탈 전체를 버리고 능선으로 돌았다. 한나절 손해가 났다.<br><br>돌 하나가 머리 하나 값을 했다. 광부의 정찰은 늘 돌이 먼저 간다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S2', t:'낙반 길목 — 몰이의 함정',
  x:`쫓긴다. 그것들이 급하지 않게 몰아 온다. 열린 길은 하나, 바위 절벽 사이 좁은 목이다.<br><br>
    그 목 위를 광부의 눈이 먼저 읽었다. 돌출 바위가 금 간 채 얹혀 있다. 낙반 직전의 천장.<br>
    저것들은 먹이를 저 밑으로 몬다. 지나던 먹이가 깔리면 줍는 식이다.<br><br>
    갱에서라면 접근 금지 팻말이 붙을 자리다.`,
  o:[
    { l:'① 목 앞에서 멈춰 서서 돌아선다 — 낙반 밑은 안 지난다.', k:'steady', dc:26,
      ok:`몰리던 걸음을 목 앞에서 뚝 끊고 돌아섰다. 낙반 밑을 지나느니 이빨과 마주 서는 게 광부의 셈이다.<br><br>몰던 것들이 당황했다. 먹이가 함정 앞에서 돌아서는 그림은 저들 셈에 없다.<br>창을 세우고 뒷걸음으로 왔던 길 옆 바위 턱에 붙었다. 몰이가 흩어지고, 그것들은 빈 목만 한참 내려다봤다.<br><br>함정을 아는 자는 몰리지 않는다. 낙반을 읽는 눈이 몰이의 끈을 끊었다.`,
      ng:`돌아서기는 했는데 반 박자 늦었다. 맨 뒤의 동료가 이미 목 어귀에 들어서 있었다.<br><br>소리쳐 불러내는 사이 몰던 놈 하나가 덮쳤다. 창대로 빗겨 막고 동료를 끌어냈다.<br>그 북새통의 울림에 금 간 바위가 저 혼자 반쯤 내려앉았다. 흙먼지가 목을 메웠다.<br><br>먼지 덕에 빠져나오긴 했다. 돌아서는 결정은 맨 앞이 아니라 맨 뒤 기준으로 내려야 했다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 목 어귀에서 기다렸다가 그것들 위로 낙반을 떨군다.', k:'break', dc:26,
      doom:{ title:'무너진 목', what:'낙반에 깔린 채 그것들에게 끌려갑니다', dc:20, sec:35,
        text:`함정을 거꾸로 쓰기로 했다. 일행을 먼저 목 너머로 보내고, 이쪽은 어귀 턱에 붙어 그것들을 기다렸다.<br><br>그것들이 목에 들어선 순간 돌출 바위 금에 곡괭이를 걸어 당겼다.<br>바위는 떨어졌다. 셈보다 크게. 금이 천장 전체로 번지며 어귀 턱까지 무너졌다.<br>다리가 돌에 물렸다. 먼지 속에서 그것들 중 성한 놈들이 다가오는 소리가 났다. 깔린 먹이를 줍는 건 저들의 본업이다. 돌 밑에서 곡괭이만이라도 동료들 쪽으로 밀어 놓았다.`,
        dieText:`먼지가 가라앉은 목은 돌무더기로 막혀 있었다.<br><br>동료들이 밤새 돌을 들어냈다. 곡괭이가 먼저 나왔다. 자루가 동료들 쪽을 향한 채.<br>그 곡괭이로 마지막 돌을 들어냈을 때, 밑에는 아무도 없었다. 끌린 자국만 목 밖으로 이어져 있었다.<br>일행은 곡괭이를 지고 돌아섰다. 갱의 법대로, 연장은 남은 사람이 쓴다.` },
      ok:`거꾸로 쓰되 광부답게 썼다. 떨어질 범위부터 쟀다. 금의 길이, 바위의 결, 쏟아질 방향.<br><br>범위 밖 턱에 자리 잡고, 그것들이 목 한가운데 모인 순간 곡괭이를 걸어 당겼다.<br>돌출 바위가 잰 범위대로 떨어졌다. 두 놈이 깔리고 나머지는 흩어졌다.<br>무너짐은 어귀까지 오지 않았다. 잰 대로였다.<br><br>낙반은 광부의 적이자 연장이다. 범위를 재는 자에게만 연장이다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'S2', t:'권양기 집 — 광부의 기계',
  x:`낡은 엘리베이터의 권양기 집에 들어섰다. 녹슨 드럼, 늘어진 와이어, 손잡이 꺾인 수동 크랭크.<br><br>
    광산 수갱의 권양기와 같은 물건이다. 눈 감고도 만지던 기계.<br>
    바구니를 올리려면 브레이크 상태와 와이어와 추, 셋을 봐야 한다. 그리고 벌판 쪽에서는 벌써 발톱 긴 것들의 기척이 온다.<br><br>
    여기부터는 광부의 마당이다.`,
  o:[
    { l:'① 브레이크 디딤쇠부터 손봐 바구니를 제 속도로 올린다.', k:'fix', dc:26, wake:1,
      ok:`드럼보다 브레이크가 먼저다. 올라가다 미끄러지는 바구니가 제일 많은 사람을 데려갔다. 수갱에서나 여기서나.<br><br>디딤쇠의 녹을 긁고 기름때를 발라 밟아 봤다. 물리는 손맛이 돌아왔다.<br>다섯이 타고, 크랭크 대신 추를 썼다. 디딤쇠로 속도를 쥐며 바구니가 고르게 올랐다. 중간에 와이어가 한 번 튀었지만 디딤쇠 반 발로 눌러 잡았다.<br><br>기계는 광부의 둘째 몸이다. 낡은 기계일수록 브레이크부터. 그 순서 하나가 다섯을 올려 보냈다.`,
      ng:`브레이크는 잡았는데 드럼의 와이어 감김이 한 줄 엇갈려 있던 걸 놓쳤다.<br><br>반쯤 오르다 와이어가 드럼에서 삐걱이며 바구니가 한 뼘 떨어졌다. 비명을 디딤쇠로 눌렀다.<br>남은 반을 가다 서다로 올랐다. 승강구에 닿았을 때 다들 창살을 쥔 손이 하얬다.<br><br>와이어 감김은 눈으로 한 바퀴 다 돌려 봐야 한다. 서두름이 그 한 바퀴를 아꼈고, 그 값이 식은땀이었다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 크랭크를 혼자 맡고 일행을 먼저 올린다.', k:'steady', dc:26,
      doom:{ title:'크랭크 곁의 어둠', what:'권양기 집에서 물려 벌판으로 끌려갑니다', dc:20, sec:40,
        text:`수동 크랭크는 아래서 돌려야 한다. 넷을 태우고 크랭크를 잡았다. 광부의 팔은 이 일에 이골이 났다.<br><br>바구니가 반쯤 올랐을 때 권양기 집 문이 안쪽으로 터졌다. 기척은 벌판에서 오는 줄 알았는데, 한 놈은 벌써 집 뒤에 와 있던 것이다.<br>크랭크를 놓으면 바구니가 떨어진다. 놓지 않으면 이쪽이 물린다. 광부는 크랭크를 안 놓았다.<br>어깨가 물려 끌리면서도 디딤쇠에 돌을 괴어 놓은 것이 마지막 일이었다. 바구니는 멈춘 채로라도 떨어지지는 않을 것이다.`,
        dieText:`바구니는 중간에 걸린 채 밤을 났다. 디딤쇠에 괴인 돌 하나가 넷의 목숨을 쥐고 있었다.<br><br>아침에 위쪽 동료들이 와이어를 타고 내려와 크랭크를 마저 돌렸다.<br>권양기 집 바닥에 곡괭이와 돌 몇 개가 가지런했다. 급한 중에도 괸 돌은 광부의 돌이었다. 넷은 그 돌을 하나씩 나눠 지니고 올라갔다.` },
      ok:`크랭크를 잡기 전에 광부의 버릇대로 집부터 봤다. 문 둘, 창 하나. 뒷문을 선반으로 막고 앞문에 등을 지는 자리로 크랭크를 돌렸다.<br><br>반쯤 올렸을 때 뒷문 선반이 덜컹했다. 막아 둔 보람이 있었다. 덜컹이는 동안 마저 돌렸다.<br>바구니가 닿자 와이어를 타고 이쪽도 올랐다. 아래서 선반 무너지는 소리가 났지만 발은 이미 허공이었다.<br><br>기계 곁의 등 뒤부터 막는 것. 수갱의 수칙 일 번이 여기서도 일 번이었다.`,
      win:{ exp:23, dream:3 } },
    { l:'③ 와이어에 짐을 먼저 달아 올려 그것들의 눈을 시험한다.', k:'bond', dc:25,
      ok:`사람 전에 짐을 올렸다. 배낭 둘을 바구니에 싣고 반 길쯤 올렸다 세워 봤다.<br><br>벌판의 그것들이 움직이는 바구니에 어떻게 반응하는지 다 같이 지켜봤다. 두 놈이 바구니 그림자를 쫓아왔다. 뛰는 높이, 도는 길, 눈 두는 데.<br>그걸 보고 순서와 신호를 짰다. 누가 먼저 타고 누가 창을 들고 누가 어디를 보는지.<br>사람이 탈 때는 모두가 저 둘의 버릇을 알고 있었다.<br><br>기계 시험 운전은 광부의 철칙이다. 짐이 맞아 주는 매는 사람이 안 맞는다.`,
      ng:`짐을 단 바구니가 반 길에서 흔들리며 배낭 하나가 떨어졌다. 그것들이 떨어진 배낭에 몰려들어 찢었다.<br><br>사흘치 마른 고기가 반나절 만에 그것들 입으로 갔다.<br>덕에 그것들이 배낭에 정신 팔린 사이 사람은 다 올랐다. 셈이 아주 틀리진 않은 셈이다.<br><br>시험 운전에도 짐 고정은 철칙이었다. 철칙 하나를 빼먹으면 다른 철칙이 값을 치른다.`,
      win:{ exp:19, dream:3, spirit:5 }, lose:{ hp:-26, spirit:-15 } }
  ] }

]);
